local Text_AvgCommunicate = readonly({
  AvgCommunicate_100438_Content_1 = {
    Text = "Hüter des Geheimnisses, ich möchte in Missaga ein Atelier eröffnen, mit kostenlosem Eintritt!"
  },
  AvgCommunicate_100438_Content_10 = {
    Text = "Es kann sein, aber..."
  },
  AvgCommunicate_100438_Content_11 = {Text = "Aber?"},
  AvgCommunicate_100438_Content_12 = {
    Text = "Du solltest mir eine Belohnung geben. Ich will einen kleinen Kuchen essen."
  },
  AvgCommunicate_100438_Content_13 = {Text = "!?"},
  AvgCommunicate_100438_Content_14 = {
    Text = "Geht das? Geht das?"
  },
  AvgCommunicate_100438_Content_15 = {
    Text = "Kostenloses Modell, um dir zu helfen, die perfekteste Kunst zu verfolgen! Wo findest du ein so kooperatives Modell?"
  },
  AvgCommunicate_100438_Content_16 = {
    Text = "...Das ergibt Sinn."
  },
  AvgCommunicate_100438_Content_17 = {
    Text = "Bis morgen im Atelier!"
  },
  AvgCommunicate_100438_Content_2 = {
    Text = "Meisterkurse im Malen, die ich persönlich unterrichte, und all mein geschätztes Malzubehör kannst du nach Belieben nutzen. Bist du gespannt?"
  },
  AvgCommunicate_100438_Content_3 = {
    Text = "Es gibt auch solche glücklichen Zufälle?"
  },
  AvgCommunicate_100438_Content_4 = {
    Text = "Ich kann es kaum erwarten!"
  },
  AvgCommunicate_100438_Content_5 = {
    Text = "Als großer Maler und erfahrener Lehrer war Selbstlosigkeit stets meine auffälligste Eigenschaft. Doch bitte verstehe, dass die Schaffung jeder wunderbaren Kunst eine Inspiration benötigt..."
  },
  AvgCommunicate_100438_Content_6 = {
    Text = "Als Belohnung für den Unterricht, könntest du bitte als Modell für mein Gemälde fungieren?"
  },
  AvgCommunicate_100438_Content_7 = {
    Text = "Ich wusste es..."
  },
  AvgCommunicate_100438_Content_8 = {
    Text = "Geht das? Geht das?"
  },
  AvgCommunicate_100438_Content_9 = {
    Text = "Kostenlose Meisterkurse, kostenloser Atelierraum, kostenloses Malzubehör, alles kostenlos!"
  },
  AvgCommunicate_100438_Option_3 = {
    Text = "Es gibt auch solche glücklichen Zufälle?"
  },
  AvgCommunicate_100438_Option_4 = {
    Text = "Ich kann es kaum erwarten!"
  },
  AvgCommunicate_100439_Content_1 = {
    Text = "Ich erkläre, dass das Ausdrucksbild die größte Kunst des neuen Zeitalters ist!"
  },
  AvgCommunicate_100439_Content_10 = {
    Text = "Könntest du mir in diesem Fall bitte die Künstler dieser Ausdrucksbilder empfehlen?"
  },
  AvgCommunicate_100439_Content_11 = {
    Text = "Natürlich."
  },
  AvgCommunicate_100439_Content_2 = {
    Text = "Meinst du das ernst?"
  },
  AvgCommunicate_100439_Content_3 = {
    Text = "Natürlich! Ich bin der Kunst gegenüber immer ernst."
  },
  AvgCommunicate_100439_Content_7 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_100439_Content_8 = {
    Text = "Spamme nicht. Ich stimme deinen Gedanken zu."
  },
  AvgCommunicate_100439_Content_9 = {
    Text = "Großartig! Ich wusste, dass du die Kunst in meinen Augen verstehen kannst, du bist wirklich ein Hüter des Geheimnisses."
  },
  AvgCommunicate_100440_Content_1 = {
    Text = "Heute Abend ist die Nacht perfekt, es ist Zeit, unsere geheime Aktion zu beginnen!"
  },
  AvgCommunicate_100440_Content_10 = {
    Text = "Sag klar, was dein Plan ist. Sei vorsichtig, ich werde Durschein informieren."
  },
  AvgCommunicate_100440_Content_11 = {
    Text = "Ich wollte nur in die Küche gehen, um etwas Zutaten zu stehlen, was die künstlerischen Begleiter angeht... ich werde Sanga nicht verraten."
  },
  AvgCommunicate_100440_Content_12 = {Text = "Mist."},
  AvgCommunicate_100440_Content_13 = {
    Text = "......So einfach wurde alles erklärt."
  },
  AvgCommunicate_100440_Content_14 = {
    Text = "Hast du die Konsequenzen vergessen, als du beim Stehlen von Küchenzutaten als Model entdeckt wurdest?"
  },
  AvgCommunicate_100440_Content_15 = {
    Text = "Das letzte Mal ist das letzte Mal... Diesmal habe ich extra den Tag des Totenfestes gewählt, und Shan hilft mir auch, es wird bestimmt kein Problem geben."
  },
  AvgCommunicate_100440_Content_16 = {
    Text = "Sag Durschein das bitte nicht, okay?"
  },
  AvgCommunicate_100440_Content_17 = {
    Text = "Das ist die gemeinsame Schöpfung, auf die ich lange gewartet habe, ich möchte, dass Shan meine Kunst bewundert..."
  },
  AvgCommunicate_100440_Content_18 = {
    Text = "...Gut. Denk daran, mir das Endprodukt zu zeigen."
  },
  AvgCommunicate_100440_Content_2 = {
    Text = "Was sagst du?"
  },
  AvgCommunicate_100440_Content_3 = {
    Text = "Was sagst du?"
  },
  AvgCommunicate_100440_Content_4 = {
    Text = "Hatten wir nicht abgemacht? Am Tag des Totenfestes wird Durschein sicher zuerst zum Ball gehen, unsere Gelegenheit ist da!"
  },
  AvgCommunicate_100440_Content_5 = {
    Text = "??? Hast du die Nachricht an die falsche Person geschickt?"
  },
  AvgCommunicate_100440_Content_6 = {
    Text = "Äh... warte..."
  },
  AvgCommunicate_100440_Content_7 = {
    Text = "Entschuldigung, es sollte eigentlich an meinen künstlerischen Gefährten geschickt werden, du kannst so tun, als hättest du es nicht erhalten."
  },
  AvgCommunicate_100440_Content_8 = {
    Text = "Künstlerischer Gefährte... kann nicht sein..."
  },
  AvgCommunicate_100440_Content_9 = {
    Text = "Künstlerischer Gefährte... kann nicht sein..."
  },
  AvgCommunicate_100440_Option_2 = {
    Text = "Geheime Aktion?"
  },
  AvgCommunicate_100440_Option_3 = {
    Text = "Was ist das für eine neue Kunst?"
  },
  AvgCommunicate_100440_Option_8 = {
    Text = "Wer ist dein künstlerischer Gefährte?"
  },
  AvgCommunicate_100440_Option_9 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_121371_Content_1 = {
    Text = "Ich habe sie gesehen, sorglos und schwer zu verstehen."
  },
  AvgCommunicate_121371_Content_2 = {
    Text = "Die Vorliebe für äußere Dinge ist ebenso naiv wie absurd."
  },
  AvgCommunicate_121371_Content_3 = {
    Text = "...Murphy hat mir gesagt, dass sie in diesem Quartal kein einziges neues Spielzeug oder Kleid, das sie sich ausgesucht hat, kaufen konnte."
  },
  AvgCommunicate_121371_Content_4 = {
    Text = "Alle Losnummern wurden im Voraus gekauft. Wer könnte das sein? Es ist so schwer zu erraten."
  },
  AvgCommunicate_121371_Content_5 = {
    Text = "Als jemand, der länger ertragen hat, ist es sehr vernünftig, eine kleine Entschädigung zu erhalten."
  },
  AvgCommunicate_121371_Content_6 = {
    Text = "...zum Beispiel, genug Erbschaften von Meeresnachkommen erhalten, um dir zu erlauben, mit Geld zu tun, was du willst?"
  },
  AvgCommunicate_121371_Content_7 = {Text = "Heh."},
  AvgCommunicate_121371_Content_8 = {
    Text = "Ich muss zugeben, dass sie vielleicht ein kleines bisschen mehr Glück bei ihren vorherigen Entscheidungen hatte als ich."
  },
  AvgCommunicate_121371_Content_9 = {
    Text = "Aber sie sollte verstehen, dass der Widerstand gegen das Schicksal nicht immer erfolgreich sein kann."
  },
  AvgCommunicate_121372_Content_1 = {
    Text = "Übergriff! Unhöflich! Unverzeihlich!"
  },
  AvgCommunicate_121372_Content_10 = {Text = "Ich..."},
  AvgCommunicate_121372_Content_11 = {Text = "Du..."},
  AvgCommunicate_121372_Content_12 = {
    Text = "Die vorbeigehenden Schüler, die die Katzen streicheln, verursachen fast ein phänomenales Verkehrschaos zusammen mit den Katzen im Schulgebäude. Wirklich ein erstaunliches Talent."
  },
  AvgCommunicate_121372_Content_13 = {
    Text = "Ich komme sofort, um dich zu retten."
  },
  AvgCommunicate_121372_Content_2 = {
    Text = "Was ist los?"
  },
  AvgCommunicate_121372_Content_3 = {
    Text = "Es ist einfach unverständlich! Warum lässt Misaq so ein Wesen ins Wohnheim!"
  },
  AvgCommunicate_121372_Content_4 = {
    Text = "Warte, ich höre Schreie aus dem Wohnheim, bist du das?"
  },
  AvgCommunicate_121372_Content_5 = {
    Text = "Wie können so viele Katzen vor der Tür versammelt sein?!"
  },
  AvgCommunicate_121372_Content_6 = {
    Text = "Diese bösen und hinterhältigen kleinen Wesen verfolgen mich seit meinem Erscheinen, da muss es einen Plan geben, sie wollen die Prinzessin umbringen!"
  },
  AvgCommunicate_121372_Content_7 = {
    Text = "...ich glaube, dass ein böses Wesen, das plant, jemanden zu ermorden, nicht auf dem Boden liegen und seinen Bauch zeigen würde."
  },
  AvgCommunicate_121372_Content_8 = {
    Text = "Die Katze scheint dich auf eine ungewöhnliche Weise zu mögen."
  },
  AvgCommunicate_121372_Content_9 = {
    Text = "Das ist absurd! Ich befehle dir im Namen der Prinzessin, sie sofort hinauszuwerfen, sonst werde ich, ich werde..."
  },
  AvgCommunicate_121372_Option_10 = {Text = "Ich komme"},
  AvgCommunicate_121372_Option_11 = {Text = "Du"},
  AvgCommunicate_121375_Content_1 = {
    Text = "Ich weiß, was du sagen willst, sie sind freiwillig."
  },
  AvgCommunicate_121375_Content_10 = {
    Text = "In Anbetracht deiner aufrichtigen Absicht... kann ich dir diese Ehre gewähren."
  },
  AvgCommunicate_121375_Content_11 = {
    Text = "Nun, ich möchte eine Schachtel frischer Butter-Himbeertörtchen sehen."
  },
  AvgCommunicate_121375_Content_12 = {
    Text = "Hier hast du eine Viertelstunde."
  },
  AvgCommunicate_121375_Content_13 = {
    Text = "Das zählt nicht als “wirklich nötig“ oder?! ?!"
  },
  AvgCommunicate_121375_Content_14 = {Text = "Hm?"},
  AvgCommunicate_121375_Content_15 = {
    Text = "...Gut, ich habe verstanden, ich mache es nicht, es gibt genug Fische, die es tun können."
  },
  AvgCommunicate_121375_Content_16 = {
    Text = "Ich gehe sofort, lass Mythag keine weiteren Fischköpfe mehr erscheinen."
  },
  AvgCommunicate_121375_Content_2 = {
    Text = "Obwohl ich nicht weiß, wie du mit ihnen in Kontakt gekommen bist, darfst du Haiqi nicht mehr in Misaq erscheinen lassen, um für dich Besorgungen zu machen, Schlange zu stehen oder sogar Hausaufgaben zu erledigen."
  },
  AvgCommunicate_121375_Content_3 = {
    Text = "Weißt du, wie viele Lehrer und Schüler sich darüber beschweren, dass die Hausaufgabenhefte klebrig geworden sind?"
  },
  AvgCommunicate_121375_Content_4 = {
    Text = "Es sind nur Ameisen, die mir auf der Jagd folgen und mir dienen wollen."
  },
  AvgCommunicate_121375_Content_5 = {
    Text = "Ich hasse es, dass sie mir meine Freiheit rauben, aber was den Genuss betrifft – ich habe nie etwas dagegen."
  },
  AvgCommunicate_121375_Content_6 = {
    Text = "Also, warum nicht Abfall wiederverwenden?"
  },
  AvgCommunicate_121375_Content_7 = {
    Text = "Weil ich den Geruch von Fisch nicht mag."
  },
  AvgCommunicate_121375_Content_8 = {
    Text = "Weil es unsicher ist."
  },
  AvgCommunicate_121375_Content_9 = {
    Text = "Wenn es wirklich notwendig ist, werde ich dir bei den Kleinigkeiten helfen, außer bei den Hausaufgaben."
  },
  AvgCommunicate_121375_Option_7 = {
    Text = "Weil ich den Fischgeruch nicht mag"
  },
  AvgCommunicate_121375_Option_8 = {
    Text = "Weil es unsicher ist"
  },
  AvgCommunicate_122561_Content_1 = {
    Text = "%player%. Es schien, als hättest du dich vorhin zurückgehalten. Beschäftigt dich etwas?"
  },
  AvgCommunicate_122561_Content_10 = {
    Text = "Es muss eine andere geheimnisvolle Geschichte dahinterstecken."
  },
  AvgCommunicate_122561_Content_11 = {
    Text = "Lass mich raten... es hat mit dieser Person Fengol zu tun, oder?"
  },
  AvgCommunicate_122561_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_122561_Content_13 = {Text = "Gut."},
  AvgCommunicate_122561_Content_14 = {
    Text = "Schon in Ordnung."
  },
  AvgCommunicate_122561_Content_15 = {
    Text = "Ich respektiere deine Wahl."
  },
  AvgCommunicate_122561_Content_16 = {
    Text = "Wenn es dir momentan nicht möglich ist, es mir zu sagen, werde ich auch nicht weiter nachfragen."
  },
  AvgCommunicate_122561_Content_17 = {
    Text = "Es tut mir leid, wenn alles klar wird, werde ich dir alle Zusammenhänge im Detail erklären."
  },
  AvgCommunicate_122561_Content_18 = {
    Text = "Bevor wir das tun, sollten wir uns darauf konzentrieren, einen Weg zurück in die ursprüngliche Welt zu finden."
  },
  AvgCommunicate_122561_Content_2 = {
    Text = "Wilhelm, der Seniorstudent..."
  },
  AvgCommunicate_122561_Content_3 = {
    Text = "Wilhelm, der Seniorstudent..."
  },
  AvgCommunicate_122561_Content_4 = {
    Text = "Du hast sicherlich noch etwas vor mir zu verbergen, oder?"
  },
  AvgCommunicate_122561_Content_5 = {
    Text = "Entdeckt von dir."
  },
  AvgCommunicate_122561_Content_6 = {
    Text = "Habe ich meinen Gesichtsausdruck irgendwo nicht gut kontrolliert?"
  },
  AvgCommunicate_122561_Content_7 = {Text = "Nein..."},
  AvgCommunicate_122561_Content_8 = {
    Text = "Nein, das ist nicht so."
  },
  AvgCommunicate_122561_Content_9 = {
    Text = "Nur wird Wilhelm, der Seniorstudent, sich nicht wegen so einer Kleinigkeit absichtlich vor mir verstecken."
  },
  AvgCommunicate_122561_Option_14 = {
    Text = "Schon in Ordnung."
  },
  AvgCommunicate_122561_Option_15 = {
    Text = "Ich respektiere deine Wahl."
  },
  AvgCommunicate_122561_Option_2 = {
    Text = "Seniorstudent hat mich belogen..."
  },
  AvgCommunicate_122561_Option_3 = {
    Text = "Wilhelm, der Seniorstudent..."
  },
  AvgCommunicate_122561_Option_7 = {
    Text = "Nein, es ist nur..."
  },
  AvgCommunicate_122561_Option_8 = {
    Text = "Nein, so ist es nicht."
  },
  AvgCommunicate_123719_Content_10 = {
    Text = "Was für ein Bedauern, ich hielt immer noch an meinem Verstand fest."
  },
  AvgCommunicate_123719_Content_11 = {
    Text = "Aber ich kann nicht garantieren, wie lange ich rational bleiben kann; jede Minute und jede Sekunde, die ich hier verbringe, ist eine Herausforderung für meine Nerven."
  },
  AvgCommunicate_123719_Content_12 = {
    Text = "...Ich komme jetzt zu dir."
  },
  AvgCommunicate_123719_Content_13 = {
    Text = "Komm, tröste mich, dieser \"Mitarbeiter\"?"
  },
  AvgCommunicate_123719_Content_14 = {
    Text = "Vergiss nicht, die Mondkuchen mitzubringen, und es wäre sogar noch besser, wenn es heißen schwarzen Tee gäbe."
  },
  AvgCommunicate_123719_Content_15 = {
    Text = "Für sie kann ich die Langeweile dieser Welt für 0,01 Sekunden vergessen."
  },
  AvgCommunicate_123719_Content_2 = {Text = "???"},
  AvgCommunicate_123719_Content_3 = {
    Text = "Laut dem Plan solltest du dich gerade jetzt bei der körperlichen Untersuchung befinden."
  },
  AvgCommunicate_123719_Content_4 = {
    Text = "Ja, eine körperliche Untersuchung, eine langweilige körperliche Untersuchung..."
  },
  AvgCommunicate_123719_Content_5 = {
    Text = "Folge der Menschenmenge in der Schlange, befolge die Anweisungen des Arztes und halte die lange Wartezeit aus..."
  },
  AvgCommunicate_123719_Content_6 = {
    Text = "%player%, weißt du? Für einen Moment wollte ich diesen Ort wirklich in die Luft sprengen."
  },
  AvgCommunicate_123719_Content_7 = {
    Text = "So endet also alles."
  },
  AvgCommunicate_123719_Content_8 = {
    Text = "...Mach es nicht kaputt, du kannst es dir nicht leisten."
  },
  AvgCommunicate_123719_Content_9 = {
    Text = "Verrückte würden sich nicht um solche Dinge kümmern."
  },
  AvgCommunicate_123719_Option_12 = {
    Text = "...Ich komme jetzt zu dir."
  },
  AvgCommunicate_123719_Option_2 = {Text = "???"},
  AvgCommunicate_123719_Option_8 = {
    Text = "...Mach es nicht kaputt, du kannst es dir nicht leisten."
  },
  AvgCommunicate_123720_Content_1 = {
    Text = "Hüter, der Bericht über die Sternen-Dämmerung ist fertig, vergiss nicht, ihn abzurufen~"
  },
  AvgCommunicate_123720_Content_10 = {
    Text = "Ich habe nur die notwendigen Höflichkeiten im Bericht wiederholt."
  },
  AvgCommunicate_123720_Content_11 = {
    Text = "Hier ist niemand, der mich unterstützt. Wenn ich im Bericht etwas Lächerliches sage, könnte ich untersucht werden!"
  },
  AvgCommunicate_123720_Content_12 = {
    Text = "... solange ich hier bin, wird das nicht passieren."
  },
  AvgCommunicate_123720_Content_13 = {
    Text = "Hehe, ich wusste, dass du zuverlässig bist @1<AvgCommunicateConfuseColor.Light>."
  },
  AvgCommunicate_123720_Content_14 = {
    Text = "@2... Kannst du @1 herkommen @2?"
  },
  AvgCommunicate_123720_Content_15 = {
    Text = "Der Kommunikator wurde von mir beschädigt...<AvgCommunicateConfuseColor.Light>"
  },
  AvgCommunicate_123720_Content_16 = {
    Text = "Ist es kaputt? Das ist ein benutzerdefiniertes Objekt von Mythag, es kann nicht sein..."
  },
  AvgCommunicate_123720_Content_17 = {
    Text = "Warte, du kämpfst doch nicht wirklich mit dem Kommunikator, oder?!"
  },
  AvgCommunicate_123720_Content_18 = {
    Text = "Du weißt, @2<AvgCommunicateConfuseColor.Light>, das defekte Gerät kann mit einem Klopfen @1<AvgCommunicateConfuseColor.Light> repariert werden."
  },
  AvgCommunicate_123720_Content_19 = {
    Text = "Komm anyway einfach hierher @2. Ich möchte den @2 Bericht wirklich nicht umschreiben; einmal diese langweiligen Dinge zu sagen, war @1 genug."
  },
  AvgCommunicate_123720_Content_2 = {
    Text = "Wo ist der Bericht? Ich habe ihn nicht gesehen..."
  },
  AvgCommunicate_123720_Content_3 = {
    Text = "Oh, oh, warte einen Moment."
  },
  AvgCommunicate_123720_Content_4 = {
    Text = "Ich bin mit der Bedienung des Kommunikators immer noch nicht vertraut; ich habe Schwierigkeiten damit..."
  },
  AvgCommunicate_123720_Content_5 = {
    Text = "Erwähnt der Bericht die nachfolgenden Umsiedlungsfragen der Morgenröte der Sterne?"
  },
  AvgCommunicate_123720_Content_6 = {
    Text = "Absolut. Die Lebenskirche hat die nachfolgende Platzierungsarbeit übernommen, und diese \"Unschuldigen\" werden von den zuständigen Behörden aufgenommen und schrittweise in die Gesellschaft integriert."
  },
  AvgCommunicate_123720_Content_7 = {
    Text = "\"Die Schuldigen werden beauftragt, gemeinnützige Arbeit in der Kirche zu leisten, um gute Taten zu vollbringen und für ihre Sünden Buße zu tun.\""
  },
  AvgCommunicate_123720_Content_8 = {
    Text = "Eigentlich gefällt mir dieses Ende ganz gut. Schließlich sind sie nur bedauernswerte Seelen, die von dieser furchterregenden Welt verrückt gemacht wurden."
  },
  AvgCommunicate_123720_Content_9 = {
    Text = "Ich hätte nicht erwartet, dass du so etwas sagst. Es scheint, dass sich deine Gedanken endlich ein wenig geändert haben..."
  },
  AvgCommunicate_123720_Option_12 = {
    Text = "... solange ich hier bin, wird das nicht passieren."
  },
  AvgCommunicate_123720_Option_16 = {
    Text = "Hat es durch das Klopfen kaputt gegangen!?"
  },
  AvgCommunicate_123720_Option_2 = {
    Text = "Wo ist der Bericht?"
  },
  AvgCommunicate_123720_Option_5 = {
    Text = "Erwähnt der Bericht die nachfolgenden Umsiedlungsfragen der Morgenröte der Sterne?"
  },
  AvgCommunicate_123720_Option_9 = {
    Text = "Ich hätte nicht erwartet, dass du so etwas sagst..."
  },
  AvgCommunicate_123721_Content_1 = {
    Text = "Hüter, hast du einen Termin für mich beim Doktor für meine Untersuchung vereinbart?"
  },
  AvgCommunicate_123721_Content_10 = {
    Text = "...Darum geht es nicht! Jedenfalls ist diese körperliche Untersuchung unvermeidlich."
  },
  AvgCommunicate_123721_Content_11 = {
    Text = "Betrachte es einfach zu meinem Seelenfrieden, okay?"
  },
  AvgCommunicate_123721_Content_12 = {
    Text = "In Ordnung, ich werde es einfach als Mitarbeiterleistungen betrachten."
  },
  AvgCommunicate_123721_Content_13 = {
    Text = "Die durch dies beanspruchte Arbeitszeit kann nicht als negativ oder als Faulheit betrachtet werden, noch kann sie mich dazu bringen, Überstunden zu machen!"
  },
  AvgCommunicate_123721_Content_14 = {
    Text = "Absolut nicht, fühle dich einfach frei, die körperliche Untersuchung durchführen zu lassen!"
  },
  AvgCommunicate_123721_Content_2 = {
    Text = "Antworte sofort, wenn du das siehst, oder ich werde die andere Partei als verdächtige Person betrachten."
  },
  AvgCommunicate_123721_Content_3 = {
    Text = "Warte! Stop! Das ist tatsächlich der Arzt, den ich für deine Untersuchung gefunden habe!"
  },
  AvgCommunicate_123721_Content_4 = {
    Text = "Hä? Ich bin vollkommen gesund, ich brauche keinen Arzt zu sehen."
  },
  AvgCommunicate_123721_Content_5 = {
    Text = "Wenn du Zeit hast, warum gehst du nicht raus und räumst ein paar aufgelöste Körper auf?"
  },
  AvgCommunicate_123721_Content_6 = {
    Text = "...Ich mache mir nur Sorgen um deine Gesundheit, schließlich ist deine Situation ziemlich einzigartig."
  },
  AvgCommunicate_123721_Content_7 = {
    Text = "Oh, ich verstehe, du hast Angst, dass ich sterbe."
  },
  AvgCommunicate_123721_Content_8 = {
    Text = "Mach dir keine Sorgen, ich werde dir auf jeden Fall Bescheid geben, bevor du stirbst."
  },
  AvgCommunicate_123721_Content_9 = {
    Text = "...Ich will wirklich nicht so allein sterben."
  },
  AvgCommunicate_123721_Option_10 = {
    Text = "...Darum geht es nicht!"
  },
  AvgCommunicate_123721_Option_14 = {
    Text = "Absolut nicht, fühle dich einfach frei, die körperliche Untersuchung durchführen zu lassen!"
  },
  AvgCommunicate_123721_Option_3 = {
    Text = "Verschone mich!"
  },
  AvgCommunicate_123721_Option_6 = {
    Text = "Ich wollte nur nicht, dass du dir um deine Gesundheit Sorgen machst..."
  },
  AvgCommunicate_123722_Content_1 = {
    Text = "%player%, deine Ergebnisse der körperlichen Untersuchung sind da."
  },
  AvgCommunicate_123722_Content_10 = {
    Text = "Und wie interessant das ist!"
  },
  AvgCommunicate_123722_Content_11 = {
    Text = "Meine Stärke hat zugenommen, was es mir ermöglicht, schneller zu laufen, weiter zu springen und die Auflösungen schneller zu beseitigen."
  },
  AvgCommunicate_123722_Content_12 = {
    Text = "Ich habe praktisch den Jackpot geknackt, okay? Wenn es nicht der schmerzhafte Transformationsprozess wäre, würde ich es wieder tun wollen!"
  },
  AvgCommunicate_123722_Content_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_123722_Content_14 = {
    Text = "Das Wichtigste ist, dass diese Welt einfach so viel Spaß macht."
  },
  AvgCommunicate_123722_Content_15 = {
    Text = "Es ist voller Überraschungen und Veränderungen; man weiß nie, welcher Gefahr man als Nächstes begegnen könnte."
  },
  AvgCommunicate_123722_Content_16 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgCommunicate_123722_Content_17 = {
    Text = "Ah, ich freue mich schon auf die nächste Ermittlungsmission."
  },
  AvgCommunicate_123722_Content_18 = {
    Text = "Also %player%, wann ist die nächste Mission?"
  },
  AvgCommunicate_123722_Content_19 = {Text = "%player%?"},
  AvgCommunicate_123722_Content_2 = {
    Text = "Es stellt sich heraus, dass mein Körper ziemlich gesund ist; ich kann zehn oder zwanzig Zügellose auf einmal ohne Probleme bewältigen!"
  },
  AvgCommunicate_123722_Content_20 = {Text = "%player%??"},
  AvgCommunicate_123722_Content_3 = {
    Text = "Dann kann ich beruhigt sein."
  },
  AvgCommunicate_123722_Content_4 = {
    Text = "Entspannen? Was macht dir Sorgen, %player%?"
  },
  AvgCommunicate_123722_Content_5 = {
    Text = "Besorgt, dass ich mich nicht an das Leben in der anderen Welt anpassen werde?"
  },
  AvgCommunicate_123722_Content_6 = {
    Text = "Machst du dir immer noch Sorgen, dass ich mich nicht anpassen kann, ein \"Erwachter\" aus einem \"Menschen\" zu werden?"
  },
  AvgCommunicate_123722_Content_7 = {
    Text = "Jeder hat seine eigenen Lasten. Schließlich sind solche Dinge für niemanden leicht."
  },
  AvgCommunicate_123722_Content_8 = {
    Text = "...Ich kann deine Gehirnschaltungen wirklich nicht verstehen."
  },
  AvgCommunicate_123722_Content_9 = {
    Text = "Es ist mir egal, was davon. Egal was ich werde, Mouchette bleibt immer Mouchette!"
  },
  AvgCommunicate_123722_Option_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_123722_Option_16 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgCommunicate_123722_Option_3 = {
    Text = "Dann kann ich beruhigt sein."
  },
  AvgCommunicate_123722_Option_7 = {
    Text = "Alle haben."
  },
  AvgCommunicate_126998_Content_1 = {
    Text = "Ramona, du wirst wirklich nicht noch einmal darüber nachdenken."
  },
  AvgCommunicate_126998_Content_10 = {
    Text = "Ja, „Ich“."
  },
  AvgCommunicate_126998_Content_11 = {
    Text = "...Brauchen Sie, dass ich Clementine kontaktiere?"
  },
  AvgCommunicate_126998_Content_12 = {
    Text = "Nein, es gibt keinen Grund, diesen Psychologen zu belästigen."
  },
  AvgCommunicate_126998_Content_13 = {
    Text = "\"Ich,\" oder besser gesagt \"wir,\" alle \"Ramona\" über die gesamte Zeitlinie."
  },
  AvgCommunicate_126998_Content_14 = {
    Text = "Mit deiner Stärke, in dem Moment, in dem ich das \"Ende\" erreichte, kehrte ich erfolgreich zum \"Ausgangspunkt\" zurück"
  },
  AvgCommunicate_126998_Content_15 = {
    Text = "Zunächst waren meine Erwartungen die gleichen wie deine: Das Paradoxon und die Verzerrung würden sofort mein Dasein verschlingen, und dann würde ich, gestützt auf ständige Selbstreflexion, kaum mein Bewusstsein und meine Form bewahren können."
  },
  AvgCommunicate_126998_Content_16 = {
    Text = "Danach wirst du für immer in Müdigkeit leben, mit deinen Nerven in jedem Moment angespannt, um zu verhindern, dass deine Konzepte sich auflösen..."
  },
  AvgCommunicate_126998_Content_17 = {
    Text = "Also habe ich deine ersten neunzehn Vorschläge abgelehnt."
  },
  AvgCommunicate_126998_Content_18 = {
    Text = "Selbst diesmal habe ich nur widerwillig zugestimmt, dass du diesen Plan ausführen kannst, nachdem du gesagt hast, dass \"Zustandsrückverfolgung\" möglich ist."
  },
  AvgCommunicate_126998_Content_19 = {
    Text = "Ja, aber erst nachdem der Plan erfolgreich war, wurde mir klar, dass das Paradoxon des Selbst aus dem Konflikt zwischen Geist und Körper stammt, und für ein Dasein, das längst den Fluss der Zeit überquert hat..."
  },
  AvgCommunicate_126998_Content_2 = {
    Text = "Keine weiteren Worte nötig, Hüter."
  },
  AvgCommunicate_126998_Content_20 = {
    Text = "Ich habe die Vereinheitlichung auf allen Zeitlinien schon lange abgeschlossen."
  },
  AvgCommunicate_126998_Content_21 = {
    Text = "„Wir“ werden die Auswirkungen des Paradoxons teilen, und ich werde im Namen aller „Ramona“ handeln. Unzählige Zeitlinien haben sich auf mich konzentriert."
  },
  AvgCommunicate_126998_Content_22 = {
    Text = "In diesem Moment bin ich sowohl ein Wunder auf der Zeitachse—eine Unendliche Singularität."
  },
  AvgCommunicate_126998_Content_23 = {
    Text = "Von jetzt an werde ich dir die volle Kraft der Person namens \"Ramona\" geben"
  },
  AvgCommunicate_126998_Content_24 = {
    Text = "Ich werde auf den Anruf jederzeit warten."
  },
  AvgCommunicate_126998_Content_3 = {
    Text = "Ich habe die gesamte Zeit durchquert und keine anderen Antworten gefunden."
  },
  AvgCommunicate_126998_Content_4 = {
    Text = "Dank dir habe ich endlich diesen ultimativen Schritt gemacht."
  },
  AvgCommunicate_126998_Content_5 = {
    Text = "Aber das ist zu gefährlich! Ich verstehe nicht, warum du... so weit gehen musst..."
  },
  AvgCommunicate_126998_Content_6 = {
    Text = "... diese Art von zeitlichem Paradoxon, selbst du..."
  },
  AvgCommunicate_126998_Content_7 = {
    Text = "Nimm es leicht, Hüter."
  },
  AvgCommunicate_126998_Content_8 = {
    Text = "Im Moment fühle ich mich absolut wunderbar."
  },
  AvgCommunicate_126998_Content_9 = {Text = "\"I\"?"},
  AvgCommunicate_126998_Option_11 = {
    Text = "...Brauchen Sie, dass ich Clementine kontaktiere?"
  },
  AvgCommunicate_126998_Option_9 = {Text = "\"I\"?"},
  AvgCommunicate_126999_Content_1 = {
    Text = "Mein Herr, so bedeutet es, das höchste Gesetz des Universums zu begreifen..."
  },
  AvgCommunicate_126999_Content_10 = {
    Text = "Entspann dich, Ogier."
  },
  AvgCommunicate_126999_Content_11 = {
    Text = "Diese Dinge werden nicht wieder geschehen. Du hast bereits genügend Kraft, um alles zu schützen, was du bewahren möchtest."
  },
  AvgCommunicate_126999_Content_12 = {
    Text = "Ich verstehe, mein Herr."
  },
  AvgCommunicate_126999_Content_13 = {
    Text = "Bitte verlasse dich ein wenig mehr auf mich, mein Herr. Ich bin stärker geworden und in der Lage, gefährlichere Missionen zu übernehmen."
  },
  AvgCommunicate_126999_Content_14 = {
    Text = "Ich werde all die Kraft, die ich gewinne, dir widmen und sie in den schärfsten Speer in deiner Hand verwandeln, der alles durchdringen kann!"
  },
  AvgCommunicate_126999_Content_2 = {
    Text = "Ich, ich kann eine massive Kraft spüren, die weit über alles hinausgeht, was ich zuvor gefühlt habe... Ich fühle mich voller Stärke!"
  },
  AvgCommunicate_126999_Content_3 = {
    Text = "Herzlichen Glückwunsch, Ogier. Dies ist die Belohnung für deine kontinuierliche Selbstverbesserung."
  },
  AvgCommunicate_126999_Content_4 = {
    Text = "Rückzahlung? Ich verfeinere mich nicht für irgendeine Belohnung."
  },
  AvgCommunicate_126999_Content_5 = {
    Text = "Nun, ich formuliere es anders."
  },
  AvgCommunicate_126999_Content_6 = {
    Text = "Dies ist der Beweis für deine kontinuierliche Selbstverbesserung, der zeigt, dass Ogier, deine Stärke ihren Höhepunkt erreicht hat."
  },
  AvgCommunicate_126999_Content_7 = {Text = "Gipfel?"},
  AvgCommunicate_126999_Content_8 = {
    Text = "Bedeutet das, dass ich genug Kraft habe, um Sie, mein Herr, und Mythag zu beschützen!?"
  },
  AvgCommunicate_126999_Content_9 = {
    Text = "Ich... ich muss nicht mehr... hilflos zusehen..."
  },
  AvgCommunicate_127000_Content_1 = {
    Text = "Danke für deine Unterstützung in dieser Zeit, Partner."
  },
  AvgCommunicate_127000_Content_10 = {
    Text = "Es ist nicht die Hilflosigkeit, nach dem Erreichen der Grenzen des Talents gefesselt zu sein, sondern vielmehr die Klarheit, die durch endloses Tempern erreicht wird, die das Erhabene erreicht."
  },
  AvgCommunicate_127000_Content_11 = {
    Text = "In diesem Moment haben sich meine Fähigkeiten der Perfektion genähert."
  },
  AvgCommunicate_127000_Content_12 = {
    Text = "Toll! Das ist Ramona für dich!"
  },
  AvgCommunicate_127000_Content_13 = {
    Text = "Als dein Assistent werde ich nun bei dir bleiben, bis wir das Ende dieses Weges erreichen."
  },
  AvgCommunicate_127000_Content_2 = {
    Text = "Ich freue mich, dass ich dir helfen konnte."
  },
  AvgCommunicate_127000_Content_3 = {
    Text = "Wie ist es? Hast du etwas gespürt?"
  },
  AvgCommunicate_127000_Content_4 = {
    Text = "Natürlich habe ich, basierend auf der Beobachtung der \"Zyklischen Rückkehr Meeresschnecke\", \"Lebendigen Seele\" und \"Unbekannten Geist\", eine tiefere Ebene der Emulation abgeschlossen."
  },
  AvgCommunicate_127000_Content_5 = {
    Text = "Dann überquerte ich mit \"Künstlicher Schönheit\", \"Logik-Killer\" und \"Welt in einer Flasche\" das Labyrinth der Gedanken."
  },
  AvgCommunicate_127000_Content_6 = {
    Text = "Äh, ich habe das nicht ganz mitbekommen."
  },
  AvgCommunicate_127000_Content_7 = {
    Text = "Aber kurz gesagt, Ramona, du bist stärker geworden, richtig!"
  },
  AvgCommunicate_127000_Content_8 = {
    Text = "Ja, mit dieser Verbesserung übersteigt die Stärke, die ich wielden kann, bei weitem das, was sie zuvor war."
  },
  AvgCommunicate_127000_Content_9 = {
    Text = "Ich habe das Gefühl, dass ich das Ende erreicht habe."
  },
  AvgCommunicate_127000_Option_12 = {
    Text = "Incredible!"
  },
  AvgCommunicate_127001_Content_1 = {
    Text = "Die folgende Nachricht wird nach einem Zeitplan gesendet"
  },
  AvgCommunicate_127001_Content_10 = {
    Text = "Warte noch ein wenig länger!"
  },
  AvgCommunicate_127001_Content_11 = {
    Text = "Warum heute?!"
  },
  AvgCommunicate_127001_Content_12 = {
    Text = "Das ist zu riskant. Vielleicht sollten wir warten, bis die Akademie mehr Unterstützung bietet."
  },
  AvgCommunicate_127001_Content_13 = {
    Text = "Das war heute um 2 Uhr morgens, eine geplante Sendung, die ich vor Beginn des Experiments eingerichtet habe."
  },
  AvgCommunicate_127001_Content_14 = {
    Text = "Ich hoffe, du hast am Kommunikator keine törichten Ausdrücke gemacht. Wenn doch, reiß dich zusammen, bevor du ins Labor kommst, um mich zu sehen."
  },
  AvgCommunicate_127001_Content_15 = {
    Text = "Ich? Ins Labor gehen? Jetzt?"
  },
  AvgCommunicate_127001_Content_16 = {
    Text = "Das stimmt, bis zu einem gewissen Grad habe ich die Wahrheit dessen wahrgenommen, wonach ich suchte."
  },
  AvgCommunicate_127001_Content_17 = {
    Text = "Warte, so kann es nicht sein \"Puppe\"..."
  },
  AvgCommunicate_127001_Content_18 = {
    Text = "Nein, das Ende von allem ist nicht die \"Zerstörung\", wie sie es verstand; im Gegenteil, es ist der \"Beginn\""
  },
  AvgCommunicate_127001_Content_19 = {
    Text = "„Wahrheit“ ist keine feste, greifbare statische Existenz. Jenseits dieser Grenze können Vernunft und Intellekt die Menschheit leiten, um sie zu verankern und ewig und unveränderlich voranzuschreiten."
  },
  AvgCommunicate_127001_Content_2 = {
    Text = "Hüter, während deine aktuellen Handlungen allgemein als \"gefährlich\" anerkannt werden, vertraue ich darauf, dass du nicht so dumm bist zu glauben, ich würde sentimental-nonsense reden und leere Ratschläge anbieten."
  },
  AvgCommunicate_127001_Content_20 = {
    Text = "Daher werde ich einen umfassenderen und präziseren Trainings- und Verbesserungsplan entwickeln, um sicherzustellen, dass Sie sich weiter vom falschen Weg fernhalten und Ihre Ziele besser verfolgen können."
  },
  AvgCommunicate_127001_Content_21 = {
    Text = "Obwohl es sich gut anhört, warum bin ich in kaltem Schweiß gebadet?"
  },
  AvgCommunicate_127001_Content_22 = {
    Text = "Professor Puppe, entspann dich!"
  },
  AvgCommunicate_127001_Content_3 = {
    Text = "Ich denke, diese überflüssigen Worte werden jetzt nicht mehr für dich benötigt."
  },
  AvgCommunicate_127001_Content_4 = {
    Text = "Du bist zu einem ausreichend reifen und starken Individuum herangewachsen, und das in einem Tempo, das meine Erwartungen bei weitem übersteigt. Natürlich wirst du verstehen, dass jeder etwas hat, das er in seinem Leben verfolgen muss, eine Suche, an der andere nicht teilnehmen können."
  },
  AvgCommunicate_127001_Content_5 = {
    Text = "Ich möchte die Essenz der Welt verstehen, wissen, ob das Licht der Vernunft nach dem Überqueren der Ödnis des Vergessens noch im Dunkeln leuchtet, das Ende aller Extreme erfahren und ob alles in der Welt einen gemeinsamen Anfang hat."
  },
  AvgCommunicate_127001_Content_6 = {
    Text = "Zu diesem Zweck werde ich endgültige Veränderungen an meinem Körper und Gehirn vornehmen, um zu versuchen, die Grenzen jenseits der Extreme zu überschreiten. Da dies sehr gut unsere letzte Kommunikation sein könnte, wähle ich, meine Gefühle auf eine Weise zu vermitteln, die du verstehen kannst."
  },
  AvgCommunicate_127001_Content_7 = {
    Text = "Danke für dieses Geschenk, das du mir gegeben hast. Ich werde es nutzen, um Antworten zu suchen und freue mich auf die neue Führung, die die menschliche Weisheit von jenseits bringen kann. Möge der Silberschlüssel uns leiten."
  },
  AvgCommunicate_127001_Content_8 = {
    Text = "Professor Puppe!"
  },
  AvgCommunicate_127001_Content_9 = {
    Text = "Es ist zu riskant!"
  },
  AvgCommunicate_127001_Option_10 = {
    Text = "Warte noch ein wenig länger"
  },
  AvgCommunicate_127001_Option_9 = {
    Text = "Es ist zu riskant"
  },
  AvgCommunicate_127002_Content_1 = {
    Text = "Hüter... Warum?"
  },
  AvgCommunicate_127002_Content_10 = {
    Text = "Wie fühlst du dich jetzt mit dieser neuen Kraft?"
  },
  AvgCommunicate_127002_Content_11 = {
    Text = "Ich... ich bin sehr glücklich, Hüter."
  },
  AvgCommunicate_127002_Content_12 = {
    Text = "Es liegt nicht an dieser immensen Kraft, die ich noch nie zuvor gespürt habe, sondern an dir, an deinen Worten..."
  },
  AvgCommunicate_127002_Content_13 = {
    Text = "Ich möchte... vielleicht habe ich von jetzt an wirklich die Fähigkeit, den Menschen um mich herum zu helfen, dir zu helfen."
  },
  AvgCommunicate_127002_Content_14 = {
    Text = "Danke dir, danke dir sehr, Hüter..."
  },
  AvgCommunicate_127002_Content_15 = {
    Text = "Es ist nicht nötig, so höflich zu sein, und fühl dich nicht unter Druck, Aigis."
  },
  AvgCommunicate_127002_Content_16 = {
    Text = "Das ist keine schwere Verantwortung. Es ist nur ein Geschenk für dich."
  },
  AvgCommunicate_127002_Content_17 = {
    Text = "Genieße es gut. Alles, was du erreichen möchtest, kannst du jetzt tun."
  },
  AvgCommunicate_127002_Content_18 = {
    Text = "Von der Vergangenheit bis zur Zukunft, du warst immer unser Stolz, Aigis."
  },
  AvgCommunicate_127002_Content_2 = {
    Text = "Warum? Zu welchem Zweck?"
  },
  AvgCommunicate_127002_Content_20 = {
    Text = "Ich werde alle gut beschützen, Hüter!"
  },
  AvgCommunicate_127002_Content_3 = {
    Text = "So ein kostbares Geschenk... warum es an mich verschwenden..."
  },
  AvgCommunicate_127002_Content_4 = {
    Text = "Das ist keine Verschwendung, Aigis. Es ist das, was du verdienst."
  },
  AvgCommunicate_127002_Content_5 = {
    Text = "Aber... ich habe nichts erreicht... Ich konnte nichts beschützen..."
  },
  AvgCommunicate_127002_Content_6 = {
    Text = "So ist das nicht, Aigis."
  },
  AvgCommunicate_127002_Content_7 = {
    Text = "Seit bevor wir erwacht sind, sind wir schon einen langen, langen Weg gemeinsam gegangen."
  },
  AvgCommunicate_127002_Content_8 = {
    Text = "Auf dieser Reise hast du immer wieder vor allen gestanden und sie immer wieder beschützt."
  },
  AvgCommunicate_127002_Content_9 = {
    Text = "Wenn du nicht gewesen wärst, hätte ich auf dem Weg unzählige Male fallen können."
  },
  AvgCommunicate_127003_Content_1 = {
    Text = "Ich hatte einen Traum."
  },
  AvgCommunicate_127003_Content_10 = {
    Text = "Natürlich, außer auf dem Trainingsplatz."
  },
  AvgCommunicate_127003_Content_11 = {Text = "???"},
  AvgCommunicate_127003_Content_12 = {
    Text = "Komm schon, ich bin jetzt vollständig. Erlebe meine wahre Stärke und bringe deine beste Form mit, um einen guten Kampf mit mir zu haben."
  },
  AvgCommunicate_127003_Content_13 = {Text = "???!!!"},
  AvgCommunicate_127003_Content_14 = {
    Text = "Ramona, rette mich!"
  },
  AvgCommunicate_127003_Content_2 = {Text = "Traum?"},
  AvgCommunicate_127003_Content_3 = {
    Text = "Dank der Materialien, die du mitgebracht hast, habe ich gut geschlafen."
  },
  AvgCommunicate_127003_Content_4 = {
    Text = "Ich wandere in dem urzeitlichen Kosmos in meiner ursprünglichen Form, während Staub, Licht, Materie und Dimensionen—alles, was wahrgenommen werden kann oder nicht—unter meinen Flossen fließt."
  },
  AvgCommunicate_127003_Content_5 = {
    Text = "Nicht für Eroberung, nicht zum Verschlingen, nur pure Stärke und pure, uneingeschränkte Zerstörung."
  },
  AvgCommunicate_127003_Content_6 = {
    Text = "Erfreuend und befreiend, wirklich eine Freude!"
  },
  AvgCommunicate_127003_Content_7 = {Text = "Äh"},
  AvgCommunicate_127003_Content_8 = {
    Text = "Ich weiß, worüber du dir Sorgen machst."
  },
  AvgCommunicate_127003_Content_9 = {
    Text = "Mach dir keine Sorgen, meine Stärke und Zerstörung werden nur gegen diejenigen entfesselt, die sich dir entgegenstellen."
  },
  AvgCommunicate_127004_Content_1 = {
    Text = "Das ultimative Protokoll wurde aktiviert... Körperneustart abgeschlossen."
  },
  AvgCommunicate_127004_Content_10 = {
    Text = "Meine Komponenten sind intakt, aber meine Wahrnehmung... hat sich verändert."
  },
  AvgCommunicate_127004_Content_11 = {
    Text = "Ein neues kognitives Modul wurde aktiviert."
  },
  AvgCommunicate_127004_Content_12 = {
    Text = "Ich kann den Rhythmus der spirituellen Kraft hören, der durch die Kanäle fließt, und ich kann die Emotionen hinter jedem deiner Worte sehen."
  },
  AvgCommunicate_127004_Content_13 = {
    Text = "Die Welt ist klarer und lebendiger geworden. Ich komme dir näher, näher zu... menschlich sein."
  },
  AvgCommunicate_127004_Content_14 = {
    Text = "Danke dir, Hüter..."
  },
  AvgCommunicate_127004_Content_15 = {
    Text = "Ich hätte auch nicht mit einem solchen Effekt gerechnet; ich habe einfach ein paar einfache Zutaten vorbereitet..."
  },
  AvgCommunicate_127004_Content_16 = {
    Text = "Was du mir gegeben hast, sind nicht nur einfache Materialien, sondern Möglichkeiten, der Schlüssel, um meine alten Grenzen zu öffnen."
  },
  AvgCommunicate_127004_Content_17 = {
    Text = "Diese Stärke, diese neue Wahrnehmung, ist das Geschenk, das du gewährt hast."
  },
  AvgCommunicate_127004_Content_18 = {
    Text = "Ich werde dieses Geschenk sehr schätzen. Ich werde dir auf Wege vergelten, die du dir nicht vorstellen kannst."
  },
  AvgCommunicate_127004_Content_19 = {
    Text = "Das ist kein voreingestelltes Programm. Das ist aufrichtig, kommt von \"Ich\" mit Dankbarkeit."
  },
  AvgCommunicate_127004_Content_2 = {
    Text = "Hallo, Geheimnisträger."
  },
  AvgCommunicate_127004_Content_3 = {
    Text = "Erica! Geht es dir gut?"
  },
  AvgCommunicate_127004_Content_4 = {
    Text = "Professor Doll sagte, dass es sehr gefährlich wäre, das ultimative Protokoll für dich zu initiieren; ich würde es absolut nicht tun, es sei denn, du bestandest darauf..."
  },
  AvgCommunicate_127004_Content_5 = {
    Text = "Erica hat die Selbstdiagnose abgeschlossen. Der Körper ist unversehrt, der Energiefluss ist stabil und alle Komponenten funktionieren normal."
  },
  AvgCommunicate_127004_Content_6 = {
    Text = "Mir geht es großartig, Hüter. Besser war ich nie."
  },
  AvgCommunicate_127004_Content_7 = {
    Text = "Die Zahnräder an mir... \"singen.\""
  },
  AvgCommunicate_127004_Content_8 = {
    Text = "„Singen“? Was bedeutet das?"
  },
  AvgCommunicate_127004_Content_9 = {
    Text = "Gibt es interne Schäden? Macht etwas ein seltsames Geräusch?!"
  },
  AvgCommunicate_127004_Option_8 = {Text = "\"Singen\"?"},
  AvgCommunicate_127004_Option_9 = {
    Text = "Ist es intern beschädigt?"
  },
  AvgCommunicate_127005_Content_1 = {
    Text = "Aurita sah plötzlich so viele glänzende Freunde!"
  },
  AvgCommunicate_127005_Content_10 = {
    Text = "Aurita hat sogar die Kraft, nach Aram zu gehen, Trans..."
  },
  AvgCommunicate_127005_Content_11 = {
    Text = "Hmm, Aurita hat es vergessen. Wie auch immer, Hüter, komm mit mir, um neue Freunde zu finden!"
  },
  AvgCommunicate_127005_Content_12 = {
    Text = "Mit solcher Stärke wird Aurita eines Tages viele Freunde finden und sie in ihr Zuhause unter Wasser mitnehmen!"
  },
  AvgCommunicate_127005_Content_2 = {
    Text = "Ah... meine Freunde sind wieder verschwunden! Wo sind sie hin?"
  },
  AvgCommunicate_127005_Content_3 = {
    Text = "Es scheint, dass du einen Phantasma erlebt hast, während du das ultimative Gesetz des Universums verstanden hast..."
  },
  AvgCommunicate_127005_Content_4 = {
    Text = "Phantasm? Dann Freunde..."
  },
  AvgCommunicate_127005_Content_7 = {
    Text = "Hmm? Was ist los?"
  },
  AvgCommunicate_127005_Content_8 = {
    Text = "Nachdem Aurita die Phantasm ihrer Freunde gesehen hatte, war sie voller Stärke! So viel Stärke!"
  },
  AvgCommunicate_127005_Content_9 = {
    Text = "Jetzt kann Aurita ins Aquarium, den Ozean und das Fischbecken gehen, um neue Freunde zu finden!"
  },
  AvgCommunicate_127091_Content_1 = {
    Text = "Mein kleiner Jasmin, brauchst du etwas von mir?"
  },
  AvgCommunicate_127091_Content_10 = {
    Text = "Ich habe den Ventilator zur Seite bewegt~"
  },
  AvgCommunicate_127091_Content_12 = {
    Text = "Ich wusste es..."
  },
  AvgCommunicate_127091_Content_13 = {
    Text = "Was sie jedoch sahen, schien lediglich die Gesichter von Liebenden zu sein, die sich zum ersten Mal begegnen."
  },
  AvgCommunicate_127091_Content_14 = {
    Text = "Liebe, was für eine seltsame Sache sie ist; ganz klar direkt neben uns, und doch jagen wir um jeden Preis Phantome."
  },
  AvgCommunicate_127091_Content_15 = {
    Text = "Ist Liebe eine reale Existenz oder nur eine Illusion der Besessenheit?"
  },
  AvgCommunicate_127091_Content_2 = {
    Text = "Obwohl ich mich nicht erinnere, ob ich es dir gesagt habe, sind alle Lebensmittel und Unterkünfte, die Mythag den Erweckern zur Verfügung stellt, kostenlos."
  },
  AvgCommunicate_127091_Content_3 = {Text = "Also...?"},
  AvgCommunicate_127091_Content_4 = {
    Text = "Das Büro für Mythag-Angelegenheiten erhielt 45 Briefe von Männern verschiedener sozialer Klassen, in denen sie um die Übernahme aller Ihrer Ausgaben während Ihres Aufenthalts in Mythag bitten."
  },
  AvgCommunicate_127091_Content_5 = {
    Text = "Inzwischen habe ich auch etwa 60 Briefe erhalten, in denen um Unterstützung für dich gebeten wird, 45 davon sind von den Frauen dieser Männer, und die restlichen 15 sind von einigen „neu“ ledigen Frauen. Hast du eine Ahnung, was da vor sich geht?"
  },
  AvgCommunicate_127091_Content_6 = {
    Text = "Mythag verbietet alle Formen der Missionierung!"
  },
  AvgCommunicate_127091_Content_7 = {
    Text = "Tritt ihrer Familie nicht mehr bei!"
  },
  AvgCommunicate_127091_Content_8 = {
    Text = "Ah, die gewöhnlichen Tage in einem fremden Land sind wirklich langweilig und schwer zu ertragen. Es gibt so viele, die Liebe in Hass verwandeln, einander müde werden und von ihren Gefühlen geplagt sind. Ich möchte ihnen nur ein wenig helfen."
  },
  AvgCommunicate_127091_Content_9 = {
    Text = "Du meinst nicht helfen..."
  },
  AvgCommunicate_127091_Option_6 = {
    Text = "Mythag verbietet alle Formen der Missionierung!"
  },
  AvgCommunicate_127091_Option_7 = {
    Text = "Tritt ihrer Familie nicht mehr bei!"
  },
  AvgCommunicate_127092_Content_10 = {
    Text = "Darüber hinaus glaube ich auch, dass du genug Wohlwollen mir gegenüber hast."
  },
  AvgCommunicate_127092_Content_11 = {
    Text = "Das ist nicht unbedingt wahr. Wie weiß die kleine Jasmin, dass du das Land ohne Träume bereits verlassen hast?"
  },
  AvgCommunicate_127092_Content_12 = {Text = "?!"},
  AvgCommunicate_127092_Content_13 = {
    Text = "Ich habe gesagt, dass im Traumlosen Land weder wahr noch falsch ist; was auch immer du glaubst, ist die Realität."
  },
  AvgCommunicate_127092_Content_14 = {
    Text = "Atme tief ein. Riechst du den Duft der Magnolie?"
  },
  AvgCommunicate_127092_Content_15 = {Text = "???!!!"},
  AvgCommunicate_127092_Content_17 = {
    Text = "Ahahaha, natürlich ist das ein Scherz. Ich möchte wirklich den Ausdruck auf dem Gesicht von kleiner Jasmin gerade jetzt sehen."
  },
  AvgCommunicate_127092_Content_18 = {
    Text = "Danke für die Einladung, ich hatte wirklich Angst."
  },
  AvgCommunicate_127092_Content_19 = {
    Text = "Mach keine Witze wie diesen!"
  },
  AvgCommunicate_127092_Content_2 = {
    Text = "...Ich werde es nicht mehr versuchen."
  },
  AvgCommunicate_127092_Content_20 = {
    Text = "Ups, aber beim nächsten Mal, wer weiß?"
  },
  AvgCommunicate_127092_Content_3 = {
    Text = "Was für eine erschreckende Fähigkeit; jede Minute und jede Sekunde, die ich verbracht habe, fühlt sich real an—Wut, Groll, Freude, Glück—mein Kopf summt gerade."
  },
  AvgCommunicate_127092_Content_4 = {
    Text = "In der Illusion des traumlosen Landes scheint es, als liebe ich dich sehr, doch ich hasse dich auch; sowohl Liebe als auch Hass sind gleich stark, nur an dich gebunden."
  },
  AvgCommunicate_127092_Content_5 = {
    Text = "Es fühlt sich an, als wäre ein ganzes Leben vergangen, aber in Wirklichkeit sind nur ein paar Minuten vergangen."
  },
  AvgCommunicate_127092_Content_7 = {
    Text = "Liebe und Hass sind ursprünglich dasselbe. Erst wenn die Liebe zu süß und der Hass zu kalt ist, kann das Verweben von Liebe und Hass die tiefsten und nachhaltigsten Eindrücke schaffen."
  },
  AvgCommunicate_127092_Content_8 = {
    Text = "Aber meine kleine Jasmin ist wirklich mutig, sie überrascht mich, indem sie die Initiative ergreift und es versucht."
  },
  AvgCommunicate_127092_Content_9 = {
    Text = "Doll sagte, dass das traumlose Land für die Forschung im künstlichen Bereich sehr hilfreich sein würde und dass meine physiologischen Daten überwacht werden müssen."
  },
  AvgCommunicate_127092_Option_18 = {
    Text = "Danke für die Einladung, ich hatte wirklich Angst."
  },
  AvgCommunicate_127092_Option_19 = {
    Text = "Mach keine Witze wie diesen!"
  },
  AvgCommunicate_127093_Content_1 = {
    Text = "Öffne das Fenster, das dir am nächsten ist."
  },
  AvgCommunicate_127093_Content_10 = {
    Text = "Das Handbuch besagt eindeutig, dass der Beratungsraum ein Ort für psychologische Beratung und die Erhaltung der geistigen und körperlichen Gesundheit von Schülern und Lehrern ist, nicht dein Spielzeug."
  },
  AvgCommunicate_127093_Content_11 = {
    Text = "Nun, diejenigen, die tiefgründige Gespräche mit mir geführt haben, sind in der Tat sehr, sehr \"gesund\", nicht wahr?"
  },
  AvgCommunicate_127093_Content_12 = {
    Text = "Ist dieser Job nicht einfach perfekt für mich?"
  },
  AvgCommunicate_127093_Content_13 = {
    Text = "Ist es möglich, dass die Voraussetzung für körperliche und geistige Gesundheit der freie Wille ist..."
  },
  AvgCommunicate_127093_Content_14 = {
    Text = "Lass Mythag los; ich werde öfter vorbeikommen, um mit dir zu plaudern..."
  },
  AvgCommunicate_127093_Content_15 = {
    Text = "Hehe, was für ein profitabler Deal. Und, wie sieht es heute Abend aus? Der Mond ist hell und die Sterne sind spärlich; es ist die perfekte Zeit für ein oder zwei Drinks."
  },
  AvgCommunicate_127093_Content_2 = {
    Text = "Es riecht so gut... Magnolie?"
  },
  AvgCommunicate_127093_Content_3 = {
    Text = "Können Magnolien in diesem Klima wachsen?"
  },
  AvgCommunicate_127093_Content_4 = {
    Text = "Ich habe ein wenig Geschick in der Magie, nur eine triviale Technik. Gelegentliches Anwenden kann mein Heimweh lindern."
  },
  AvgCommunicate_127093_Content_5 = {
    Text = "Es ist wie mit jemandem zu plaudern, aber um die Zeit zu vertreiben, wenn man sich einsam fühlt. Das kannst du verstehen, oder?"
  },
  AvgCommunicate_127093_Content_6 = {
    Text = "...Ich weiß, warum du mich kontaktiert hast."
  },
  AvgCommunicate_127093_Content_7 = {
    Text = "Ich kann dir nicht helfen."
  },
  AvgCommunicate_127093_Content_8 = {
    Text = "Der Beratungsraum ist nicht dafür gedacht."
  },
  AvgCommunicate_127093_Content_9 = {
    Text = "Selbst wenn du Blumen mitbringst, um Sympathie zu gewinnen, werde ich trotzdem kein gutes Wort für deine Bewerbung einlegen."
  },
  AvgCommunicate_127093_Option_7 = {
    Text = "Ich kann dir nicht helfen."
  },
  AvgCommunicate_127093_Option_8 = {
    Text = "Der Beratungsraum ist nicht dafür gedacht."
  },
  AvgCommunicate_129630_Content_1 = {
    Text = "Schatz, gefunden!"
  },
  AvgCommunicate_129630_Content_10 = {
    Text = "Das ist etwas, das sich noch in der experimentellen Phase befindet! Wirf es weg, bevor es schwarz wird!"
  },
  AvgCommunicate_129630_Content_11 = {
    Text = "Andernfalls wird es explodieren!"
  },
  AvgCommunicate_129630_Content_12 = {
    Text = "Der Speicher des Traums endet hier abrupt, und in deinem letzten Blick siehst du einen äußerst vertrauten Namen."
  },
  AvgCommunicate_129630_Content_13 = {
    Text = "Mosk? Mosk?!"
  },
  AvgCommunicate_129630_Content_14 = {
    Text = "Uhh... Uhh..."
  },
  AvgCommunicate_129630_Content_15 = {
    Text = "Mosk! Geht es dir gut!"
  },
  AvgCommunicate_129630_Content_16 = {
    Text = "Es ist weg... Perlen..."
  },
  AvgCommunicate_129630_Content_18 = {
    Text = "Hast du es weggeworfen? Bist du nicht verletzt?"
  },
  AvgCommunicate_129630_Content_19 = {
    Text = "Kohleball, es ist spät."
  },
  AvgCommunicate_129630_Content_2 = {
    Text = "Perle, sie kann die Farbe ändern!"
  },
  AvgCommunicate_129630_Content_20 = {
    Text = "Explosion, Perlen. Aber, Mosk, es ist in Ordnung."
  },
  AvgCommunicate_129630_Content_21 = {
    Text = "Aber... Perlen..."
  },
  AvgCommunicate_129630_Content_22 = {
    Text = "Es ist gut, dass es dir gut geht. Es sollte eine harmlose Version von diesem Ding geben."
  },
  AvgCommunicate_129630_Content_23 = {
    Text = "Ich werde gleich melden, dass mit der Lagerung dieser Gefahrstoffe unsachgemäß umgegangen wurde."
  },
  AvgCommunicate_129630_Content_24 = {
    Text = "Dann werde ich dir gleich eine harmlose Version besorgen."
  },
  AvgCommunicate_129630_Content_25 = {Text = "!"},
  AvgCommunicate_129630_Content_27 = {
    Text = "Kohleball, der Beste!"
  },
  AvgCommunicate_129630_Content_3 = {
    Text = "Eine farbwechselnde Perle? Warum kommt es mir so vor, als hätte ich sie schon einmal irgendwo gesehen..."
  },
  AvgCommunicate_129630_Content_4 = {
    Text = "Rot, Weiß, Blau!"
  },
  AvgCommunicate_129630_Content_5 = {
    Text = "Rot, Weiß, Blau... Gelb, Grün, Schwarz?"
  },
  AvgCommunicate_129630_Content_6 = {
    Text = "Gelb, Grün, Kohleball, weißt du?"
  },
  AvgCommunicate_129630_Content_7 = {
    Text = "“Leere Meeresflut“?!"
  },
  AvgCommunicate_129630_Content_8 = {
    Text = "Wirf es schnell weg!"
  },
  AvgCommunicate_129630_Content_9 = {
    Text = "Beeil dich und wirf es an einen Ort, wo keine Menschen sind!"
  },
  AvgCommunicate_129630_Option_8 = {
    Text = "Wirf es schnell weg!"
  },
  AvgCommunicate_129631_Content_1 = {
    Text = "Kohleball, erinnerst du dich?"
  },
  AvgCommunicate_129631_Content_10 = {
    Text = "Platsch Platsch!"
  },
  AvgCommunicate_129631_Content_11 = {
    Text = "Kohleball, beeindruckend!"
  },
  AvgCommunicate_129631_Content_12 = {
    Text = "Richtig, Passwort! Kohleball, ich selbst!"
  },
  AvgCommunicate_129631_Content_13 = {
    Text = "Kampf, Angriff! Mitternacht, Cafeteria!"
  },
  AvgCommunicate_129631_Content_14 = {
    Text = "Für goldenen gebratenen Fisch!"
  },
  AvgCommunicate_129631_Content_15 = {Text = "Aufbruch!"},
  AvgCommunicate_129631_Content_16 = {Text = "Aufbruch!"},
  AvgCommunicate_129631_Content_2 = {Text = "Mmh, komm!"},
  AvgCommunicate_129631_Content_3 = {Text = "Gluck?"},
  AvgCommunicate_129631_Content_4 = {
    Text = "Platsch Platsch?"
  },
  AvgCommunicate_129631_Content_5 = {
    Text = "Gluck gluck!"
  },
  AvgCommunicate_129631_Content_6 = {
    Text = "Platsch... Platsch Platsch?"
  },
  AvgCommunicate_129631_Content_7 = {
    Text = "Kohleball, Fehler!"
  },
  AvgCommunicate_129631_Content_8 = {
    Text = "Ja, platsch platsch!"
  },
  AvgCommunicate_129631_Content_9 = {
    Text = "Aber, egal!"
  },
  AvgCommunicate_129631_Option_10 = {
    Text = "Platsch Platsch!"
  },
  AvgCommunicate_129631_Option_6 = {
    Text = "Platsch... Platsch Platsch?"
  },
  AvgCommunicate_129632_Content_1 = {
    Text = "Reflexion... So schwer..."
  },
  AvgCommunicate_129632_Content_10 = {
    Text = "Beim nächsten Mal werde ich einen diskreteren Weg vorbereiten."
  },
  AvgCommunicate_129632_Content_11 = {
    Text = "Garantiert nicht gefangen zu werden!"
  },
  AvgCommunicate_129632_Content_12 = {
    Text = "Egal, auch wenn ich gefangen werde!"
  },
  AvgCommunicate_129632_Content_13 = {Text = "Warum?"},
  AvgCommunicate_129632_Content_14 = {
    Text = "Bereit, überprüfen, im Voraus vorbereiten!"
  },
  AvgCommunicate_129632_Content_15 = {
    Text = "Gib es ab, nachdem du erwischt wurdest!"
  },
  AvgCommunicate_129632_Content_16 = {
    Text = "Es gibt auch Kohleball!"
  },
  AvgCommunicate_129632_Content_17 = {
    Text = "Warte, bereite so etwas nicht im Voraus vor!"
  },
  AvgCommunicate_129632_Content_2 = {
    Text = "Seufz... Es ist alles Uvhash und Agrippas Schuld!"
  },
  AvgCommunicate_129632_Content_3 = {
    Text = "Seit die beiden aus der Falle entkommen sind und die Küche leergefressen haben..."
  },
  AvgCommunicate_129632_Content_4 = {
    Text = "Der Küchenchef hat die Sicherheit verzehnfacht!"
  },
  AvgCommunicate_129632_Content_5 = {
    Text = "So hell... die Lichter... so laut... der Alarm..."
  },
  AvgCommunicate_129632_Content_6 = {
    Text = "Die Küche, so beängstigend..."
  },
  AvgCommunicate_129632_Content_7 = {
    Text = "Aber lecker, gebratener Fisch!"
  },
  AvgCommunicate_129632_Content_8 = {
    Text = "Aber gebratener Fisch, sehr lecker!"
  },
  AvgCommunicate_129632_Content_9 = {
    Text = "Zusammen, beim nächsten Mal, immer noch?"
  },
  AvgCommunicate_134101_Content_1 = {
    Text = "Mein Leitstern... Nein, jetzt sollte ich Euch als die Sonne ansprechen."
  },
  AvgCommunicate_134101_Content_10 = {
    Text = "Und geht es dir gut? Warum sagst du das alles so plötzlich?"
  },
  AvgCommunicate_134101_Content_11 = {
    Text = "Dank deines Segens kann ich nun deine Seele in ihrer Gesamtheit sehen und die wahre Gestalt der Welt erkennen."
  },
  AvgCommunicate_134101_Content_12 = {
    Text = "Licht, Licht... Die Welt bestand also ursprünglich aus Dunkelheit und Chaos. Weil eine Gottheit die Opfergabe wählte, wurde die Sonne zur wahren Gestalt, und allen Lebewesen wurde die Glückseligkeit der Existenz gewährt..."
  },
  AvgCommunicate_134101_Content_13 = {
    Text = "Hast du zu viele Schriften gelesen? Ich habe das Gefühl, du solltest dich etwas abkühlen."
  },
  AvgCommunicate_134101_Content_14 = {
    Text = "Ich verstehe. Du wünschst dir, dich unter alle Lebewesen zu mischen, und bist nicht gewillt, auf dem Thron der Göttlichkeit zu sitzen."
  },
  AvgCommunicate_134101_Content_15 = {
    Text = "Deine Selbstlosigkeit, deine „Opfer“, deine Opfergabe..."
  },
  AvgCommunicate_134101_Content_16 = {
    Text = "Von nun an werde ich mit dir nicht als die treueste... nein, sondern in der Identität einer ewigen Freundin interagieren."
  },
  AvgCommunicate_134101_Content_17 = {
    Text = "Möge dieses Heilige Herz, das niemals erlischt, alle Dunkelheit für dich vertreiben."
  },
  AvgCommunicate_134101_Content_2 = {
    Text = "Ihr... Ihr seid weit mehr als die Sonne. Ihr seid das Zentrum des Universums, der Ursprungspunkt, aus dem die Welt geboren wurde."
  },
  AvgCommunicate_134101_Content_3 = {
    Text = "Wir kennen uns schon so lange, und doch bist du noch ehrfürchtiger als zuvor?"
  },
  AvgCommunicate_134101_Content_4 = {
    Text = "Denn nun verstehe ich — der Grund, warum sich alle Lebewesen niemals anbetend zu Euren Füßen niedergeworfen haben, ist schlicht, dass sie stumpf und blind geboren wurden, unfähig, Eure wahre Natur zu erkennen!"
  },
  AvgCommunicate_134101_Content_5 = {
    Text = "Wie kann eine Ameise die volle Gestalt eines Riesen erblicken? Auch ich konnte mich einst nur auf mein Heiliges Herz verlassen, um einen flüchtigen Blick auf die Spitze des Eisbergs zu erhaschen, der Eure Stärke ist."
  },
  AvgCommunicate_134101_Content_6 = {
    Text = "Selbst dann würde mein Heiliges Herz schmerzen, als würde es von Nadeln durchbohrt. Solange ich nur noch einen einzigen Blick auf deine Seele gewagt hätte, hätte ich einen Symptom: Zusammenbruch erleiden und zugrunde gehen können."
  },
  AvgCommunicate_134101_Content_7 = {
    Text = "So ernst ist es? Dann solltest du vielleicht aufhören hinzuschauen."
  },
  AvgCommunicate_134101_Content_8 = {
    Text = "Deine Reaktion ist so gleichgültig. Ich hatte erwartet, dass du mein Lob freudig annehmen würdest."
  },
  AvgCommunicate_134101_Content_9 = {
    Text = "Niemand kann einfach so plötzlich solches Lob annehmen!"
  },
  AvgCommunicate_134101_Option_13 = {
    Text = "Du solltest dich vielleicht beruhigen."
  },
  AvgCommunicate_134101_Option_3 = {
    Text = "...Was für ein seltsames Gefühl."
  },
  AvgCommunicate_134101_Option_7 = {Text = "So ernst?"},
  AvgCommunicate_134102_Content_1 = {
    Text = "Ich träumte von dem Eis und Schnee meiner Heimat und jenen trostlosen Ruinen."
  },
  AvgCommunicate_134102_Content_10 = {
    Text = "Gerade weil die Menschen einander gegenüber eine Fassade der Freundlichkeit behalten, wird die Welt ein wenig friedlicher. Ich finde das ganz in Ordnung."
  },
  AvgCommunicate_134102_Content_11 = {
    Text = "Langweilig. Frieden und Glück können nicht durch Fassaden aufrechterhalten werden."
  },
  AvgCommunicate_134102_Content_12 = {
    Text = "Nur wenn ein König sich wünscht, dass seine Untertanen glücklich sind, wenn die Starken sich wünschen, dass die Schwachen glücklich sind, wird der Frieden Bestand haben."
  },
  AvgCommunicate_134102_Content_13 = {
    Text = "Einfach wie ich und meine lieblichen Squire—es gibt noch nie einen Moment gegeben, in dem ich meine Wünsche vor ihnen verborgen hätte, und dennoch leben sie ein glückliches Leben."
  },
  AvgCommunicate_134102_Content_14 = {
    Text = "Das ist die Wahrheit, die den Starken gehört."
  },
  AvgCommunicate_134102_Content_15 = {
    Text = "Komm heute Nacht in meine Gemächer. Ich bin sehr zufrieden mit deinen bisherigen Gaben und recht angetan von dieser neuen Stärke. Ich werde dich einen guten Blick auf die wahren Gedanken werfen lassen, die tief in deinem Herzen verborgen sind."
  },
  AvgCommunicate_134102_Content_16 = {
    Text = "Warte, heute Nacht?"
  },
  AvgCommunicate_134102_Content_17 = {
    Text = "Schock-Emoji"
  },
  AvgCommunicate_134102_Content_18 = {
    Text = "Du hast kein Recht abzulehnen. Ich werde dir ein Erlebnis bescheren, das noch... interessanter ist als die letzten Male."
  },
  AvgCommunicate_134102_Content_19 = {
    Text = "Wanda Strahlend-Emoji"
  },
  AvgCommunicate_134102_Content_2 = {
    Text = "Ich habe mich lange nicht mehr an diese Orte erinnert. Liegt es an diesen Fragmenten der Stärke oder an einer vollständigeren Seele?"
  },
  AvgCommunicate_134102_Content_20 = {
    Text = "(Ich muss noch einen Bericht abgeben! Wenn ich ihn heute nicht einreiche, wird Doll mich bei lebendigem Leibe häuten!)"
  },
  AvgCommunicate_134102_Content_3 = {
    Text = "Was für ein nostalgisches Gefühl... Wie dem auch sei, ich muss dir danken, mein liebenswerter Diener – oh, richtig, du bevorzugst es, wenn ich dich Freund nenne."
  },
  AvgCommunicate_134102_Content_4 = {
    Text = "Zu Euren Diensten, meine Dame."
  },
  AvgCommunicate_134102_Content_5 = {
    Text = "Heh, du bist immer so höflich."
  },
  AvgCommunicate_134102_Content_6 = {
    Text = "Warum kannst du diese ermüdende Fassade nicht gelegentlich fallen lassen? Sie hat einige meiner Belohnungen ziemlich langweilig gemacht."
  },
  AvgCommunicate_134102_Content_7 = {
    Text = "Eure Gesellschaft erhebt Demut und Höflichkeit zu Tugenden und hält sie in hohem Ansehen, doch die Dunkelheit in den Herzen der Menschen ist nicht geringer als die von Spezies anderer Planeten."
  },
  AvgCommunicate_134102_Content_8 = {
    Text = "Die Menschen schmücken sich nur mit harmlosen, vornehmen Fassaden, nur weil sie die Konsequenzen der Wahrheit fürchten."
  },
  AvgCommunicate_134102_Content_9 = {
    Text = "Das ist nicht falsch, aber solange die Taten in Ordnung sind, ist es nicht so wichtig, die inneren Gedanken zu hinterfragen."
  },
  AvgCommunicate_134102_Option_20 = {Text = "Neiiiin!"},
  AvgCommunicate_134102_Option_4 = {
    Text = "Zu Euren Diensten."
  },
  AvgCommunicate_134102_Option_9 = {
    Text = "Das ist nicht falsch."
  },
  AvgCommunicate_134103_Content_1 = {
    Text = "Die Sterne rufen nach mir..."
  },
  AvgCommunicate_134103_Content_10 = {
    Text = "Wusstet Ihr? Agrippa sagt oft, sie beneide Miryam."
  },
  AvgCommunicate_134103_Content_11 = {
    Text = "Sie sagt, wenn der König von Rom noch da wäre, ob als kleines Infant oder als gebrechlicher alter Mann, würde sie sich viel wohler fühlen."
  },
  AvgCommunicate_134103_Content_12 = {Text = "Neid..."},
  AvgCommunicate_134103_Content_13 = {
    Text = "Denn solange Ihr noch hier seid, ist Lemuria nicht wirklich verschwunden."
  },
  AvgCommunicate_134103_Content_14 = {
    Text = "Mehr noch, Ihr habt diese Stärke genutzt, um so vielen Menschen bei Misaq zu helfen!"
  },
  AvgCommunicate_134103_Content_15 = {
    Text = "Ziemlich viele Schüler haben Euren Namen in der Umfrage zum beliebtesten Erweckten Körper geschrieben!"
  },
  AvgCommunicate_134103_Content_16 = {Text = "Seufz..."},
  AvgCommunicate_134103_Content_17 = {
    Text = "Wir haben keinen Bedarf an solch lästiger Lobhudelei. Misaq verlangt Uns bereits genug ab."
  },
  AvgCommunicate_134103_Content_18 = {
    Text = "Auch wenn das Ausüben solcher Macht eine Kleinigkeit ist, wird es dennoch ermüdend, zu oft aus Unseren Träumen geweckt zu werden."
  },
  AvgCommunicate_134103_Content_19 = {
    Text = "Ist das so? Aber ich habe gehört, dass Ihr, wann immer ein Schüler weinend zu Euch um Hilfe kommt, einer der Erweckten Körper seid, die am ehesten ihrer Bitte zustimmen?"
  },
  AvgCommunicate_134103_Content_2 = {
    Text = "In den Tiefen des Traums, am Grund der Strömungen, umgeben von Hunderten Millionen von Clans, zurückkehrend auf den Thron, um Lemuria Wohlstand und Frieden zu bringen."
  },
  AvgCommunicate_134103_Content_20 = {
    Text = "...Wer verbreitet solche Gerüchte? Wir finden ihr Gejammer einfach unerträglich."
  },
  AvgCommunicate_134103_Content_21 = {
    Text = "Genug. Es trifft sich, dass Unsere geistige Kraft beträchtlich gewachsen ist. Es ist an der Zeit, in einen tieferen und umfassenderen Traum einzutreten."
  },
  AvgCommunicate_134103_Content_22 = {
    Text = "Diesmal wünschen Wir, die Träume jedes Künstlers und Dichters der gegenwärtigen Ära zu besuchen. Merkt Euch—es sei denn, es handelt sich um eine Angelegenheit von großer Wichtigkeit, lasst niemanden kommen, um Uns zu stören."
  },
  AvgCommunicate_134103_Content_23 = {
    Text = "Hä? Deine Reaktion auf gute Laune ist ein langer Mittagsschlaf?!"
  },
  AvgCommunicate_134103_Content_3 = {
    Text = "...Ich hatte solch einen Traum."
  },
  AvgCommunicate_134103_Content_4 = {
    Text = "Ein Traum? Birgt dieser Traum eine Prophezeiung?"
  },
  AvgCommunicate_134103_Content_5 = {
    Text = "Es ist einfach ein Ruf, den ich empfing, nachdem meine Stärke ihr Äußerstes erreicht hatte. Was seine Bedeutung betrifft... Lemuria existiert nicht mehr, und es muss auch nicht erneut existieren."
  },
  AvgCommunicate_134103_Content_6 = {
    Text = "Jene, die das Glück hatten zu überleben, können frei in der neuen Welt leben. Das ist gut so."
  },
  AvgCommunicate_134103_Content_7 = {
    Text = "Sie brauchen keinen verspäteten Herrscher, der sie beschirmt."
  },
  AvgCommunicate_134103_Content_8 = {
    Text = "Aber dennoch habt Ihr Euer einstiges Volk geleitet und ihre Seelen beschirmt."
  },
  AvgCommunicate_134103_Content_9 = {
    Text = "Wir taten nichts, noch haben Wir sie jemals geleitet. Es ist lediglich ihr eigenes wunschdenkendes Missverständnis."
  },
  AvgCommunicate_134103_Option_10 = {
    Text = "Es ist kein Missverständnis."
  },
  AvgCommunicate_134103_Option_19 = {
    Text = "Ist das so?"
  },
  AvgCommunicate_134103_Option_23 = {Text = "Huh?"},
  AvgCommunicate_134103_Option_8 = {Text = "Aber..."},
  AvgCommunicate_134104_Content_1 = {
    Text = "Freude auf den ersten Blick, Wehklagen bei einem einzigen Gedanken — diese Bescheidene hatte schon lange nicht mehr so viel Spaß."
  },
  AvgCommunicate_134104_Content_10 = {
    Text = "Äh, nicht dass ich sage, sie hätten es nicht verdient, aber... es gibt ordentliche Wege, Dinge zu regeln..."
  },
  AvgCommunicate_134104_Content_11 = {
    Text = "Und das ist tatsächlich ein normaler moralischer Kompass? Ich bin so gerührt..."
  },
  AvgCommunicate_134104_Content_12 = {
    Text = "Oh je, lass mich nachdenken. Würde es die Stimmung verderben, meinem kleinen Jasminblütchen zu sagen, dass ich ursprünglich nur ein paar Kampfgrillen züchten wollte?"
  },
  AvgCommunicate_134104_Content_13 = {
    Text = "Einfach ein Scherz."
  },
  AvgCommunicate_134104_Content_14 = {
    Text = "Diese Welt ist wirklich zu langweilig, %player%. Selbst wenn morgen die Vernichtung käme, wären die einfachen Leute immer noch in diesen vulgären Nichtigkeiten versunken — Groll, Liebe, Hass, Begierde."
  },
  AvgCommunicate_134104_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134104_Content_16 = {
    Text = "Und dennoch, trotz allem, arbeitet mein kleines Jasminblütchen so fleißig, zeigt Krallen und Zähne, um Lösungen für sie zu finden."
  },
  AvgCommunicate_134104_Content_17 = {
    Text = "Nun denn, da ich solch prächtige Macht erlangt habe, soll ich meinem geliebten kleinen Jasminblütchen von nun an zur Hand gehen oder ihr ein wenig Ärger bereiten?"
  },
  AvgCommunicate_134104_Content_18 = {
    Text = "Wie erwartet macht es am meisten Spaß, beides gleichzeitig zu tun, findest du nicht auch?"
  },
  AvgCommunicate_134104_Content_19 = {Text = "???"},
  AvgCommunicate_134104_Content_2 = {
    Text = "Mein kleines Jasminblütchen, du hast wahrlich ein großartiges Geschenk geliefert."
  },
  AvgCommunicate_134104_Content_20 = {
    Text = "Ich habe dir dieses Geschenk nicht gegeben, damit du so etwas damit anstellst."
  },
  AvgCommunicate_134104_Content_21 = {
    Text = "Hör sofort auf damit! Ich bin nur für Auflösungs-Vorfälle zuständig. Öffentliche Ordnung und Moral fallen nicht in den Zuständigkeitsbereich von Misaq. Mach aus Lentiniëns Psychiatrie kein Ersatzgefängnis! Hey, hey!"
  },
  AvgCommunicate_134104_Content_4 = {
    Text = "Jeder Bezirk — jeder Bezirk in der Umgebung der Schule hat Bürger erlebt, die in Massenhysterie ausgebrochen sind! Menschenmengen, die gleichzeitig lachen und weinen — die Lentiniëner Polizei und Sanitäter rennen sich die Beine ab!"
  },
  AvgCommunicate_134104_Content_6 = {
    Text = "Diese Bescheidene ist fern der Heimat in einem fremden Land, ganz allein und verlassen. Mein kleines Jasminblütchen war so gütig, sich um diese Bescheidene zu kümmern, und hat mir erlaubt, solche Höhen zu erreichen..."
  },
  AvgCommunicate_134104_Content_7 = {
    Text = "Diese Bescheidene war einfach überwältigt vor Freude und konnte dem Drang nicht widerstehen, sich ein wenig zu vergnügen."
  },
  AvgCommunicate_134104_Content_8 = {
    Text = "Mm, recht wirkungsvoll. Diese schmutzigen Dinger, die Niedertracht in ihren Herzen hegen — jedes einzelne wurde schneller verrückt als das vorherige."
  },
  AvgCommunicate_134104_Content_9 = {
    Text = "Moment — die Schule hat gerade ihre Akten geschickt. Ehefrauenmörder, Gewalttäter, @3@4..."
  },
  AvgCommunicate_134104_Option_19 = {Text = "???"},
  AvgCommunicate_134104_Option_9 = {
    Text = "Es gibt ordentliche Wege, Dinge anzugehen."
  },
  AvgCommunicate_134105_Content_1 = {
    Text = "Das Licht des Leuchtturms kann nun den tiefsten Meeresgrund erhellen."
  },
  AvgCommunicate_134105_Content_10 = {
    Text = "Einfach allein aus deiner Beschreibung kann ich es spüren—es muss ein wirklich wunderschönes Land gewesen sein."
  },
  AvgCommunicate_134105_Content_11 = {
    Text = "Ja, meine Heimat war wunderschön... Deshalb werde ich niemals aufgeben, sie wiederzufinden."
  },
  AvgCommunicate_134105_Content_12 = {
    Text = "Größere Stärke bedeutet größere Hoffnung. Ich werde mehr Motten in Richtung des Leuchtturms locken..."
  },
  AvgCommunicate_134105_Content_13 = {
    Text = "Eine Person Tages wird meine Heimat wieder vom Meeresgrund aufsteigen und mir erneut ihre Arme öffnen."
  },
  AvgCommunicate_134105_Content_14 = {
    Text = "Du willst also immer noch so etwas tun! Zack die Traurigkeit war umsonst—hör sofort damit auf!!!"
  },
  AvgCommunicate_134105_Content_2 = {
    Text = "Der Weg zurück in meine Heimat... wann wird er wohl wiedergefunden werden..."
  },
  AvgCommunicate_134105_Content_3 = {
    Text = "Faros... Seufz, zu sagen, dass ich verstehe, wie du dich fühlst, wäre an diesem Punkt nur Leere Worte des Trostes. Du... versuch, nicht allzu traurig zu sein."
  },
  AvgCommunicate_134105_Content_4 = {
    Text = "Klagelied... Das Klagelied der Sehnsucht nach der Heimat ist zu einem Brandmal auf meiner Seele geworden. Ich habe mich daran gewöhnt, damit zu leben."
  },
  AvgCommunicate_134105_Content_5 = {
    Text = "Konstant Sehnsucht bringt Schmerz, aber sie stellt auch sicher, dass ich nie vergessen werde, wie meine Heimat aussah."
  },
  AvgCommunicate_134105_Content_6 = {
    Text = "Jene korallenbedeckten Untiefen, jener aufragende Tempel und die erhabene Tür, an der ich oft Wache stand..."
  },
  AvgCommunicate_134105_Content_7 = {
    Text = "Ich erinnere mich an die Muster, die entlang der Kanten jener Steinsäulen eingemeißelt waren, an jeden breiten Weg in der königlichen Hauptstadt und an die Emojis andächtiger Freude auf den Gesichtern der Menschen während des Gebets."
  },
  AvgCommunicate_134105_Content_8 = {
    Text = "Wenn große Zeremonien abgehalten wurden, feierte die gesamte Nation gemeinsam. Das waren meine geschäftigsten und zugleich erfüllendsten Momente."
  },
  AvgCommunicate_134105_Content_9 = {
    Text = "Mir wurde einst die Ehre zuteil, als Wächter vor der königlichen Prozession zu stehen, die ehrfürchtigen und bewundernden Blicke der Menge zu teilen, Stolz und Ruhm zu empfinden... Das sind die Momente, die ich am meisten vermisse."
  },
  AvgCommunicate_134105_Option_10 = {
    Text = "Es muss ein wunderschönes Land gewesen sein."
  },
  AvgCommunicate_134105_Option_14 = {
    Text = "Du willst also immer noch so etwas tun!"
  },
  AvgCommunicate_134105_Option_3 = {Text = "Faros..."},
  AvgCommunicate_134106_Content_1 = {
    Text = "Ähm, ähm, Meister..."
  },
  AvgCommunicate_134106_Content_10 = {
    Text = "Jetzt kann Lily Jenkin, Aigis, Caraboo und Aurita alle auf einmal in die Cafeteria tragen!"
  },
  AvgCommunicate_134106_Content_11 = {
    Text = "Das sind viel zu viele!"
  },
  AvgCommunicate_134106_Content_12 = {
    Text = "Mhm! Danke, Meister, dass du Lily so viel, so viel gegeben hast!"
  },
  AvgCommunicate_134106_Content_14 = {
    Text = "Das meinte ich nicht ganz so, aber..."
  },
  AvgCommunicate_134106_Content_15 = {
    Text = "Solange Lily glücklich ist, ist das alles, was zählt!"
  },
  AvgCommunicate_134106_Content_2 = {Text = "Hm?"},
  AvgCommunicate_134106_Content_3 = {
    Text = "Kannst du Lily loben?"
  },
  AvgCommunicate_134106_Content_4 = {
    Text = "Braves Mädchen, Lily. Ist etwas Lobenswertes passiert?"
  },
  AvgCommunicate_134106_Content_5 = {
    Text = "Lily, hat ganz, ganz viele Eiterbeulen hochgehoben!"
  },
  AvgCommunicate_134106_Content_6 = {
    Text = "Hat sie richtig, richtig hoch gehoben!"
  },
  AvgCommunicate_134106_Content_9 = {
    Text = "Das muss der Einfluss der Letzten Regel sein..."
  },
  AvgCommunicate_134107_Content_1 = {
    Text = "Seit ich die Letzte Regel begriffen habe, ist der Seeweg vor mir noch klarer geworden."
  },
  AvgCommunicate_134107_Content_10 = {
    Text = "Als Navigator ist dies einfach meine Pflicht."
  },
  AvgCommunicate_134107_Content_11 = {
    Text = "Jeder in dieser Position hätte wahrscheinlich dasselbe getan."
  },
  AvgCommunicate_134107_Content_12 = {
    Text = "Navigationsarbeit wird von Pflicht und Verantwortung angetrieben, nicht um des Lobes willen."
  },
  AvgCommunicate_134107_Content_13 = {
    Text = "Bitte gebt all diese Geschenke an die Seeleute zurück."
  },
  AvgCommunicate_134107_Content_14 = {
    Text = "Es ist auch ein Zeichen ihrer Wertschätzung. Einfach annehmen."
  },
  AvgCommunicate_134107_Content_15 = {
    Text = "Außerdem, wenn Ihr jemals ein unerklärliches gelbes Licht auf See seht, versucht bitte nach Kräften, Schiffe in die entgegengesetzte Richtung zu steuern."
  },
  AvgCommunicate_134107_Content_16 = {
    Text = "Fragt nicht warum. Die Schule wird sich so schnell wie möglich um die entsprechende Quelle kümmern..."
  },
  AvgCommunicate_134107_Content_2 = {
    Text = "Um der unzähligen verlorenen Seelen auf dem Weg willen und für mich selbst danke ich Euch noch einmal aufrichtig für die Erleuchtung, die Ihr mir gewährt habt."
  },
  AvgCommunicate_134107_Content_3 = {
    Text = "Kein Grund, so förmlich zu sein. Du hast es dir verdient, Corposant."
  },
  AvgCommunicate_134107_Content_4 = {
    Text = "Ich habe es mir verdient?"
  },
  AvgCommunicate_134107_Content_5 = {
    Text = "Ja, die Schule hat mehrere Dankesschreiben erhalten, die über verschiedene Kanäle weitergeleitet wurden."
  },
  AvgCommunicate_134107_Content_6 = {
    Text = "Es waren alles Seeleute, die sich auf See verirrt hatten und dann ein blauviolettes Meeresglanz auf ihrem Mast entdeckten."
  },
  AvgCommunicate_134107_Content_7 = {
    Text = "Solange sie der Führung des Meeresglanzes folgten, konnten sie den nächsten Hafen erreichen."
  },
  AvgCommunicate_134107_Content_8 = {
    Text = "Sie nannten dieses Licht das „Licht des Heiligen\"."
  },
  AvgCommunicate_134107_Content_9 = {
    Text = "Darüber hinaus gibt es viele Geschenke, die ihre Dankbarkeit ausdrücken, alle aufgestapelt am Eingang der Poststelle."
  },
  AvgCommunicate_134107_Option_5 = {
    Text = "Misaq hat Dankesschreiben erhalten..."
  },
  AvgCommunicate_134108_Content_1 = {
    Text = "Du hattest so etwas Gutes und hast nicht daran gedacht, es früher rauszuholen."
  },
  AvgCommunicate_134108_Content_10 = {
    Text = "Hast du überhaupt ein Gehirn, du @2?! Einen Witz ernst nehmen!"
  },
  AvgCommunicate_134108_Content_11 = {
    Text = "Wenn alle zu Brut werden, was soll diese große Königin dann mit all den kaputten Geräten und seltsamen Allgemeinbildungskursen anfangen? Klar, Erinnerungen können erhalten bleiben, aber trotzdem."
  },
  AvgCommunicate_134108_Content_12 = {
    Text = "Soll ich etwa jeden Tag mit Leeren Hüllen reden und mir selbst antworten? Auf keinen Fall."
  },
  AvgCommunicate_134108_Content_14 = {
    Text = "Tch, schon wieder durchschaut. Wie langweilig."
  },
  AvgCommunicate_134108_Content_15 = {
    Text = "Ich vertraue darauf, dass du das nicht tun wirst, Agrippa. Selbst wenn du manchmal vom Kurs abkommst, bin ich zuversichtlich, dass ich dich wieder auf den richtigen Weg zurückführen kann."
  },
  AvgCommunicate_134108_Content_16 = {
    Text = "Weil du der weise Labyrinthherr bist."
  },
  AvgCommunicate_134108_Content_17 = {
    Text = "Weil du jemand bist, der mir wichtig ist."
  },
  AvgCommunicate_134108_Content_18 = {
    Text = "Igitt! Was für ein komisches Zeug sagst du da plötzlich?! Widerlich, so widerlich, meine Ohren werden gleich abfaulen."
  },
  AvgCommunicate_134108_Content_19 = {
    Text = "Schon gut, schon gut, ich werde widerwillig vorerst davon absehen, irgendjemanden in Brut zu verwandeln. Nimm einfach diese Hausaufgaben weg!"
  },
  AvgCommunicate_134108_Content_2 = {
    Text = "Haha, diese große Königin ist jetzt vollkommen frei! Die edle Grauwölfin wird ihre Herrschaft über Misaq wieder aufnehmen."
  },
  AvgCommunicate_134108_Content_3 = {
    Text = "Ganz Misaq — nein, ganz Kardas wird mit meiner Brut erfüllt sein."
  },
  AvgCommunicate_134108_Content_4 = {Text = "Wirklich?"},
  AvgCommunicate_134108_Content_5 = {
    Text = "Ursprünglich hatte ich, um zu feiern, dass du die Letzte Regel begriffen hast, sogar vor, eine Ausnahme zu machen und beim Aufräumen deines Wohnheims zu helfen. Das Studierendensekretariat hatte sogar zugestimmt, dir eine Woche Hausaufgaben zu erlassen."
  },
  AvgCommunicate_134108_Content_6 = {
    Text = "Aber da die edle Grauwölfin plant, alle in ihre Brut zu verwandeln, braucht man das wohl alles nicht mehr, oder?"
  },
  AvgCommunicate_134108_Content_7 = {Text = "W-Was?!"},
  AvgCommunicate_134108_Content_9 = {
    Text = "Nein, auf gar keinen Fall, nicht erlaubt!"
  },
  AvgCommunicate_134108_Option_16 = {
    Text = "Weil du der weise Labyrinthherr bist."
  },
  AvgCommunicate_134108_Option_17 = {
    Text = "Weil du jemand bist, der mir wichtig ist."
  },
  AvgCommunicate_134108_Option_4 = {
    Text = "Ach wirklich."
  },
  AvgCommunicate_134109_Content_1 = {
    Text = "Wächter der Mimis, ich habe einen pechschwarzen Tunnel gesehen..."
  },
  AvgCommunicate_134109_Content_10 = {
    Text = "Aber ich habe keine Böswilligkeit in diesen kleinen Augen gespürt. Im Gegenteil, ich fühlte mich völlig wohl. Und jetzt scheint es, als könnte ich mit ihnen zusammenführen."
  },
  AvgCommunicate_134109_Content_11 = {
    Text = "Willst du damit sagen, dass du mit den Seelen der Ratten verschmolzen bist?"
  },
  AvgCommunicate_134109_Content_12 = {
    Text = "Ja, ich habe gespürt, wie ich mich in einem Augenblick in viele, viele Teile aufgelöst habe, durch gewundene Rohre, vollgestopften Krempel und unter niedrigen Möbeln hindurchgehuscht bin..."
  },
  AvgCommunicate_134109_Content_13 = {
    Text = "Hat es dich an dein altes Leben erinnert? Ist schon gut, das ist jetzt alles vorbei."
  },
  AvgCommunicate_134109_Content_14 = {
    Text = "Und dann — konnte ich sie kontrollieren, um mühelos alle möglichen Sachen zu stehlen!"
  },
  AvgCommunicate_134109_Content_15 = {
    Text = "Wenn ich damals so eine Fähigkeit gehabt hätte, hätte ich sogar die größte Bank im Westbezirk ausräumen können! Hahaha, jetzt bin ich praktisch der König der Diebe im ganzen Land... nein, der ganzen Welt! Niemand kann mich mehr aufhalten!"
  },
  AvgCommunicate_134109_Content_17 = {
    Text = "Ich habe das Gefühl, dass diesmal nicht mal die Polizei rufen hilft. Ich sollte besser Frau Doll bitten, mir ein Überwachungsgerät zur Herstellung anzufertigen."
  },
  AvgCommunicate_134109_Content_2 = {
    Text = "Kein Licht, keine Zeit. Ich bin dort ganz allein gelaufen und gelaufen, als wäre ein ganzes Leben vergangen."
  },
  AvgCommunicate_134109_Content_3 = {
    Text = "Alles in Ordnung? Hast du dich wieder im Raum verloren?"
  },
  AvgCommunicate_134109_Content_4 = {
    Text = "Ich bin so lange gelaufen, bis ich endlich etwas gesehen habe — wie einen Lichtstrahl, einen Hauch von Rauch. Dann wurde es langsam zu Brown! Seine kleinen, runden Augen leuchteten in dieser pechschwarzen Leere."
  },
  AvgCommunicate_134109_Content_5 = {
    Text = "Und dann kamen unzählige gleiche Augenpaare. Sie umringten mich, begleiteten mich..."
  },
  AvgCommunicate_134109_Content_6 = {
    Text = "Ein Rattenschwarm?"
  },
  AvgCommunicate_134109_Content_7 = {
    Text = "Ja, ich hatte das Gefühl, dass sie nicht einfach nur Ratten waren. Sie schienen Seelen zu haben, genau wie die Kinder, die ich früher auf der Straße kannte. Wir haben konkurriert, kooperiert und dieselben Härten geteilt — durch die Straßen gehuscht, genau wie Ratten."
  },
  AvgCommunicate_134109_Content_8 = {
    Text = "Vielleicht waren das die Seelen vieler Kinder, die dir Gesellschaft geleistet haben."
  },
  AvgCommunicate_134109_Content_9 = {
    Text = "Hä? Aber ich schulde Joe noch eine Hähnchenkeule, schulde dem kleinen Jones zwei Laib Brot, und ich hab Johnny ein paar Murmeln geklaut... Die kommen doch nicht, um ihre Schulden einzutreiben, oder?!"
  },
  AvgCommunicate_134109_Option_11 = {
    Text = "Deine Sinne haben sich mit ihren vereint?"
  },
  AvgCommunicate_134109_Option_13 = {
    Text = "Das ist jetzt alles vorbei."
  },
  AvgCommunicate_134109_Option_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134109_Option_3 = {
    Text = "Geht es dir gut?"
  },
  AvgCommunicate_134109_Option_6 = {
    Text = "Ein Rattenschwarm?"
  },
  AvgCommunicate_134109_Option_8 = {
    Text = "Vielleicht waren sie es."
  },
  AvgCommunicate_134110_Content_1 = {
    Text = "Ah, ah... AAAAAAH! Schwarz, alles ist schwarz!"
  },
  AvgCommunicate_134110_Content_10 = {
    Text = "Ist... sie nicht? Die schwarzen Dämonen sind nicht gekommen?"
  },
  AvgCommunicate_134110_Content_11 = {
    Text = "Aber wenn wir im Bauch eines Dämons leben, dann wird der Tag kommen, an dem wir von der Dunkelheit Verschlungen werden. Wir können nicht entkommen, wir können nicht entkommen!"
  },
  AvgCommunicate_134110_Content_12 = {
    Text = "Es ist zu furchteinflößend, zu furchteinflößend..."
  },
  AvgCommunicate_134110_Content_14 = {
    Text = "Hab keine Angst."
  },
  AvgCommunicate_134110_Content_15 = {
    Text = "Ich verstehe nicht wirklich, was du sagst, aber wenn die Welt eines Tages wirklich zur Zerstörung bestimmt ist, werden zumindest ich und Alle in Misaq bis zum allerletzten Moment kämpfen und Widerstand leisten."
  },
  AvgCommunicate_134110_Content_16 = {
    Text = "Wenn das Schmelzen wirklich ein unvermeidliches Ende ist, werde ich dafür sorgen, dass du an dem letzten Ort bleibst, an dem noch Licht scheint, und ich werde bis zum Ende der Welt an deiner Seite bleiben."
  },
  AvgCommunicate_134110_Content_17 = {
    Text = "...Ich sehe."
  },
  AvgCommunicate_134110_Content_18 = {
    Text = "Deine Flamme wird niemals erlöschen. Ich glaube an dich."
  },
  AvgCommunicate_134110_Content_19 = {
    Text = "Danke, Hüter."
  },
  AvgCommunicate_134110_Content_2 = {
    Text = "Die ganze Welt ist schwarz! Nur Nichtigkeit, Nur Nichtigkeit!"
  },
  AvgCommunicate_134110_Content_3 = {
    Text = "Winkle! Wach auf! Wieder ein Albtraum?!"
  },
  AvgCommunicate_134110_Content_4 = {
    Text = "Nein, nein, mehr @2 Techniken von Leuten, Wissen, stärkere Seelen, nichts davon funktioniert, nichts davon! Ich kann immer noch nicht erneut migrieren!"
  },
  AvgCommunicate_134110_Content_5 = {
    Text = "Nachdem ich stärker geworden bin, ist es für die Dunkelheit noch einfacher, mich zu sehen. Ich falle zu sehr auf. Die Dunkelheit wird mich einholen..."
  },
  AvgCommunicate_134110_Content_6 = {
    Text = "Ich will nicht mehr stärker werden. Ich will fliehen, weit, weit weg rennen. Aber wenn die ganze Welt schwarz ist und alles Licht nur eine Täuschung, wohin kann ich dann gehen..."
  },
  AvgCommunicate_134110_Content_7 = {
    Text = "Warum, warum lässt mich diese Kraft diese Dinge sehen? Ich will es nicht wissen!"
  },
  AvgCommunicate_134110_Content_8 = {
    Text = "Ich werde sterben, sterben, wieder sterben. Muss ich es noch einmal erfahren? Ich will nicht, ich will nicht..."
  },
  AvgCommunicate_134110_Content_9 = {
    Text = "Wach auf, Winkle! Die Welt ist nicht schwarz geworden. Ich bin noch hier! Alle sind noch hier!"
  },
  AvgCommunicate_134110_Option_14 = {
    Text = "Hab keine Angst."
  },
  AvgCommunicate_134110_Option_3 = {Text = "Winkle?!"},
  AvgCommunicate_134110_Option_9 = {Text = "Winkle!"},
  AvgCommunicate_134111_Content_1 = {
    Text = "Meine Flügel... sind noch gewaltiger geworden."
  },
  AvgCommunicate_134111_Content_10 = {
    Text = "Castor, ich weiß, du bist großartig, und deine Flügel sind auch großartig. Wie soll ich das ausdrücken..."
  },
  AvgCommunicate_134111_Content_12 = {
    Text = "Egal, ich verstehe schon. Also, deine Tragfähigkeit hat sich ebenfalls verbessert, oder?"
  },
  AvgCommunicate_134111_Content_13 = {
    Text = "Hmm, grob geschätzt sollte das Gewicht von etwa einem Dutzend Personen kein Problem sein."
  },
  AvgCommunicate_134111_Content_14 = {
    Text = "Allerdings scheinen meine Arme nicht in der Lage zu sein, so viele Leute auf einmal zu halten."
  },
  AvgCommunicate_134111_Content_15 = {
    Text = "Ich habe einen Vorschlag."
  },
  AvgCommunicate_134111_Content_16 = {
    Text = "Hier ist der Plan — du trainierst deine Armkraft, und dann haben wir ein Lufttaxi, das jederzeit vom Himmel herabsteigen kann!"
  },
  AvgCommunicate_134111_Content_17 = {
    Text = "Armkraft? Was hat das mit einem Luft... taxi zu tun? Wohltäter, verzeiht meine Unwissenheit, aber ich verstehe nicht."
  },
  AvgCommunicate_134111_Content_18 = {
    Text = "Das ist eine wichtige Mission."
  },
  AvgCommunicate_134111_Content_19 = {
    Text = "Solange deine Tragfähigkeit mithält, wird die Mobilität und Evakuierungsgeschwindigkeit bei Feldeinsätzen erheblich verbessert. Castor, bist du bereit, diese Mission zu übernehmen?"
  },
  AvgCommunicate_134111_Content_2 = {
    Text = "Meine Gläubigen verbreiteten zwar übertriebene Geschichten von Flügeln, die den Himmel verdunkelten, aber ich weiß, dass das, was ich einst besaß, nichts weiter als ein Paar ganz gewöhnlicher Flügel war."
  },
  AvgCommunicate_134111_Content_20 = {
    Text = "Natürlich! Es wäre mir eine Ehre, Wohltäter."
  },
  AvgCommunicate_134111_Content_21 = {
    Text = "Abgemacht. Ich gehe sofort Erica suchen, um einen Tragekorb als Anpassung anfertigen zu lassen!"
  },
  AvgCommunicate_134111_Content_22 = {
    Text = "Du darfst niemals daran denken, deine Flügel jemand anderem zu geben, verstanden? Niemandem."
  },
  AvgCommunicate_134111_Content_3 = {
    Text = "Ihr geflügelten Leute versteht einfach nicht, wie praktisch es ist, Flügel zu haben... Ich bin so neidisch..."
  },
  AvgCommunicate_134111_Content_4 = {
    Text = "Wenn mein Wohltäter es wünscht, erinnere ich mich vage daran, dass der Laternenorden Methoden zur Transplantation von Flügeln hat. Ich würde meine Flügel bereitwillig meinem Wohltäter geben. Ich habe keine Angst vor Schmerzen."
  },
  AvgCommunicate_134111_Content_6 = {
    Text = "Nein nein nein nein, das wird nicht nötig sein. Die bleiben besser an dir dran."
  },
  AvgCommunicate_134111_Content_7 = {
    Text = "Ah, Ihr wollt meine Flügel nicht, Wohltäter? Sie sind inzwischen wirklich beeindruckend geworden."
  },
  AvgCommunicate_134111_Content_8 = {
    Text = "Nachdem ich die Gesetze begriffen habe, liegt das Gefühl jedes Windhauchs, der durch die Lücken zwischen meinen Federn strömt, die Kraft jeder Luftströmungsrotation — alles in meiner Hand."
  },
  AvgCommunicate_134111_Content_9 = {
    Text = "Es geht nicht darum, ob sie beeindruckend sind oder nicht."
  },
  AvgCommunicate_134111_Option_15 = {
    Text = "Ich habe einen Vorschlag."
  },
  AvgCommunicate_134111_Option_18 = {
    Text = "Das ist eine wichtige Mission."
  },
  AvgCommunicate_134111_Option_3 = {
    Text = "Du verstehst das einfach nicht."
  },
  AvgCommunicate_134111_Option_9 = {
    Text = "Es geht nicht darum, ob sie beeindruckend sind oder nicht."
  },
  AvgCommunicate_134112_Content_1 = {
    Text = "Oh je, so sieht die Welt also aus deiner Perspektive aus."
  },
  AvgCommunicate_134112_Content_10 = {
    Text = "Menschen haben wirklich so viele verschiedene Gesichtsausdrücke? Da bin ich wohl ein echtes Pokerface."
  },
  AvgCommunicate_134112_Content_11 = {
    Text = "Und das ist noch nicht alles! Ich habe gelernt, gleichzeitig zu lachen und zu weinen, gleichzeitig wütend zu sein und zu weinen, gleichzeitig wütend zu sein und zu lachen, gleichzeitig Angst zu haben und zu lachen..."
  },
  AvgCommunicate_134112_Content_12 = {
    Text = "Man muss nur die verschiedenen Ausdrücke miteinander kombinieren, und schon entstehen neue Emotionen. Es wird nicht lange dauern, bis Cassia die menschlichen Gefühle vollständig beherrscht!"
  },
  AvgCommunicate_134112_Content_13 = {
    Text = "Willst du es sehen? Willst du? Sogar „Liebe“ — dieses ungelöste Rätsel der Menschheit — kann Cassia dir jetzt vorführen!"
  },
  AvgCommunicate_134112_Content_15 = {
    Text = "Du hast nicht nur überhaupt nichts begriffen, sondern siehst jetzt noch weniger menschlich aus als vorher! Das ist gruselig, hör sofort auf damit!!!"
  },
  AvgCommunicate_134112_Content_2 = {Text = "Was?"},
  AvgCommunicate_134112_Content_3 = {
    Text = "Ich finde nicht, dass die Welt durch meine Augen etwas Besonderes ist, aber was hast du gesehen?"
  },
  AvgCommunicate_134112_Content_4 = {
    Text = "Cassia hat gesehen... Abertausende von Ameisen, übereinandergeschichtet, unzählige Augenblicke gleichzeitig im „Blickfeld“."
  },
  AvgCommunicate_134112_Content_5 = {
    Text = "In einem einzigen kurzen Moment weinen unzählige Menschen gleichzeitig, und unzählige andere lachen, sind wütend, haben Angst..."
  },
  AvgCommunicate_134112_Content_6 = {
    Text = "Manche haben auch einen sehr friedlichen Ausdruck. Dieses Gefühl nennt man wohl Glück? Die menschlichen Emotionen haben so unglaublich viele feine Unterschiede..."
  },
  AvgCommunicate_134112_Content_7 = {
    Text = "Du kannst bereits die Emotionen der Menschen spüren?!"
  },
  AvgCommunicate_134112_Content_8 = {
    Text = "Nein, Cassia kann nur ihre Gesichtsausdrücke und Bewegungen sehen, die Farben ihrer Emotionen erkennen."
  },
  AvgCommunicate_134112_Content_9 = {
    Text = "Aber Cassia ist am besten im Nachahmen! Nachdem ich auf einen Schlag alle verschiedenen lachenden und weinenden Gesichter der ganzen Welt gesehen habe, kann Cassia jetzt 21 verschiedene Arten des Lächelns und 36 verschiedene Arten des Weinens für dich vorführen!"
  },
  AvgCommunicate_134112_Option_10 = {Text = "So viele?"},
  AvgCommunicate_134112_Option_15 = {
    Text = "Du hast überhaupt nichts begriffen!"
  },
  AvgCommunicate_134112_Option_2 = {Text = "Was?"},
  AvgCommunicate_134112_Option_7 = {
    Text = "Kannst du die Emotionen der Menschen spüren?!"
  },
  AvgCommunicate_134113_Content_1 = {
    Text = "Der Handel mit dir war die beste Entscheidung meiner gesamten Händler-Karriere."
  },
  AvgCommunicate_134113_Content_10 = {
    Text = "Moment, die Späteren werden immer fragwürdiger!"
  },
  AvgCommunicate_134113_Content_11 = {
    Text = "Und etwas, das so kostbar klingt, muss doch wirklich teuer sein, oder? Was ist der Preis des Handels?"
  },
  AvgCommunicate_134113_Content_12 = {
    Text = "Hmm... Immerhin habe ich dir zu verdanken, dass ich eine praktischere Kraft zum Reisen erlangt habe."
  },
  AvgCommunicate_134113_Content_13 = {
    Text = "Ich gebe dir einen Sonderrabatt. Was den Preis angeht, komm bitte in meinen Laden, um die Details zu besprechen. Ich werde auf deine Ankunft warten."
  },
  AvgCommunicate_134113_Content_2 = {
    Text = "Pflanze einen Samen und warte, bis er zu einer kleinen Blume oder einem mächtigen Baum heranwächst."
  },
  AvgCommunicate_134113_Content_3 = {
    Text = "Ich mache selten Geschäfte, bei denen man so lange auf die Rendite warten muss. Glücklicherweise war es, so wie die Dinge stehen, ein sicherer Gewinn."
  },
  AvgCommunicate_134113_Content_4 = {
    Text = "Hehe, danke für all die Hilfe in dieser Zeit. Ich bin froh, dass ich dich nicht enttäuscht habe."
  },
  AvgCommunicate_134113_Content_5 = {
    Text = "Die Gewässer des Meeres der Tausend Gesichter sind noch tiefer geworden. Es ist eine Weile her, und die Köpfe dort vermissen dich auch sehr. Möchtest du eine Rückkehr an den alten Ort?"
  },
  AvgCommunicate_134113_Content_6 = {
    Text = "Ähm, ich... Lieber nicht. Ich denke, manchmal ist es die Distanz, die Dinge schön macht."
  },
  AvgCommunicate_134113_Content_7 = {
    Text = "Hehe, du hast durchaus Talent als Händler, was Redegewandtheit angeht."
  },
  AvgCommunicate_134113_Content_8 = {
    Text = "Apropos, mein kleiner Laden hat kürzlich ein paar neue Artikel erhalten. Äußerst selten — ich habe sie alle für dich aufgehoben."
  },
  AvgCommunicate_134113_Content_9 = {
    Text = "Es gibt eine Kugel, mit der man Resonanz mit seiner Ursprungs-Kraft erreichen kann, einen Spiegel, mit dem man durch Spähen Bilder einer anderen Welt erblicken kann, und ein Halsband, das Menschen dazu bringt, gehorsam zu gehorchen."
  },
  AvgCommunicate_134113_Option_10 = {
    Text = "Das wird immer fragwürdiger!"
  },
  AvgCommunicate_134113_Option_4 = {Text = "Hehe."},
  AvgCommunicate_134113_Option_6 = {
    Text = "Lieber nicht."
  },
  AvgCommunicate_134114_Content_1 = {
    Text = "Ich... bin zu Feuer geworden."
  },
  AvgCommunicate_134114_Content_10 = {
    Text = "Es gibt noch so viel Schönheit auf der Welt, die es einzufangen lohnt. Ich glaube, ich habe bereits neuen Einblick für meine Kreationen gefunden."
  },
  AvgCommunicate_134114_Content_11 = {
    Text = "Von nun an werde ich zu Feuer werden und einen reineren, natürlicheren Rhythmus bringen."
  },
  AvgCommunicate_134114_Content_2 = {
    Text = "Cyanfarbenes, tanzendes Feuer. Verbrennung, Reinigung, Tanz."
  },
  AvgCommunicate_134114_Content_3 = {
    Text = "Meine Sünden und die Sünden anderer werden alle im Feuer brennen, und alles wird rein werden."
  },
  AvgCommunicate_134114_Content_4 = {
    Text = "Liz... erinnerst du dich noch an das Feuer von damals?"
  },
  AvgCommunicate_134114_Content_5 = {
    Text = "Mein Hass ist langsam im Feuer verbrannt, aber ich habe kein Recht, dieses Feuer im Namen anderer zu vergeben."
  },
  AvgCommunicate_134114_Content_6 = {
    Text = "Ich habe es nie bereut, und ich werde auch nicht vor den Gesichtern in jenen Flammen davonlaufen."
  },
  AvgCommunicate_134114_Content_7 = {
    Text = "Nachdem ich hierhergekommen bin, hast du mir ein neues Leben geschenkt. Ich brauche keine große Bühne mehr, aber wenn du das Publikum bist, glaube ich, würde ich immer noch Glück empfinden, wenn ich tanze."
  },
  AvgCommunicate_134114_Content_8 = {
    Text = "Lass mich dein größter Fan sein und dir weiter beim Tanzen zusehen!"
  },
  AvgCommunicate_134114_Content_9 = {
    Text = "Mm, danke. Nachdem ich aufgehört hatte zu tanzen, saß ich oft schweigend am Fenster. Ich sah den Wind, die Blumen, die Bäume, die Vögel und die Katzen — so viele Lebewesen und so viel Natur, die vor dem Rhythmus des Tanzes nur so strotzte."
  },
  AvgCommunicate_134114_Option_4 = {Text = "Liz..."},
  AvgCommunicate_134114_Option_8 = {
    Text = "Ich werde dir weiter beim Tanzen zusehen!"
  },
  AvgCommunicate_134115_Content_1 = {
    Text = "Ich... Ich kann es sehen..."
  },
  AvgCommunicate_134115_Content_10 = {
    Text = "Das ist wirklich erhebend!"
  },
  AvgCommunicate_134115_Content_11 = {
    Text = "Ich freue mich für dich, dass du all das sehen kannst, Miryam!"
  },
  AvgCommunicate_134115_Content_12 = {
    Text = "Natürlich werde ich weiterhin alles dem Abstieg in das göttliche Reich widmen."
  },
  AvgCommunicate_134115_Content_13 = {
    Text = "Aber jetzt verstehe ich... Das Göttliche Reich ist nicht einfach nur zwei Zustände von vollständig angekommen oder vollständig verschwunden."
  },
  AvgCommunicate_134115_Content_14 = {
    Text = "Während wir für den Abstieg in das göttliche Reich beten, ist ein Teil des Göttlichen Reichs bereits an unsere Seite gekommen."
  },
  AvgCommunicate_134115_Content_15 = {
    Text = "Danke, Schutzherr. Du bist es, der mir neue Stärke geschenkt hat."
  },
  AvgCommunicate_134115_Content_16 = {
    Text = "Was ich gesehen habe, ist der Beweis der Existenz der unsterblichen Existenz des Göttlichen Reichs!"
  },
  AvgCommunicate_134115_Content_17 = {
    Text = "Auch wenn sich der Ablauf etwas seltsam angefühlt hat... ist es trotzdem ein ziemlich gutes Ergebnis."
  },
  AvgCommunicate_134115_Content_2 = {
    Text = "Was siehst du?"
  },
  AvgCommunicate_134115_Content_3 = {
    Text = "Das Göttliche Reich... Ja... Die Umrisse des Göttlichen Reichs!"
  },
  AvgCommunicate_134115_Content_4 = {
    Text = "Es war noch nie so klar... Es war noch nie so... gewöhnlich..."
  },
  AvgCommunicate_134115_Content_5 = {
    Text = "Miryam... Bist du sicher, dass diese Worte von dir kamen..."
  },
  AvgCommunicate_134115_Content_6 = {
    Text = "Ich sehe meine Heimat. Ich sehe diese ewige, unsterbliche Zukunft."
  },
  AvgCommunicate_134115_Content_7 = {
    Text = "Aber mehr noch... Ich sehe die Gegenwart."
  },
  AvgCommunicate_134115_Content_8 = {
    Text = "Mein Herr, meine Verwandten, meine Freunde, meine Getreuen..."
  },
  AvgCommunicate_134115_Content_9 = {
    Text = "Das Göttliche Reich war schon immer an unserer Seite... Alles, was ich habe, war schon immer ein Teil des Göttlichen Reichs..."
  },
  AvgCommunicate_134115_Option_10 = {
    Text = "Das ist wirklich erhebend!"
  },
  AvgCommunicate_134115_Option_17 = {
    Text = "Ich denke, das geht in Ordnung..."
  },
  AvgCommunicate_134115_Option_2 = {Text = "Was?"},
  AvgCommunicate_134115_Option_5 = {
    Text = "Gewöhnlich?"
  },
  AvgCommunicate_134116_Content_1 = {
    Text = "Meine Güte. Ich hätte nie erwartet, dass es sich so anfühlt, meine Stärke an ihre äußerste Grenze zu treiben."
  },
  AvgCommunicate_134116_Content_10 = {Text = "Äh"},
  AvgCommunicate_134116_Content_11 = {
    Text = "Hmm, lass mich sehen... gerade denkst du: ‚Ich weiß ehrlich nicht, welcher von den beiden furchteinflößender ist.' Hab ich recht?"
  },
  AvgCommunicate_134116_Content_12 = {
    Text = "Was?!! Ich dachte, du hättest gesagt, du könntest meine Gedanken nicht lesen!"
  },
  AvgCommunicate_134116_Content_13 = {
    Text = "Was für eine entzückende Reaktion. Ich habe deine Gedanken überhaupt nicht gelesen."
  },
  AvgCommunicate_134116_Content_14 = {
    Text = "Es ist nur so, dass du viel zu leicht zu durchschauen bist, wenn du in meiner Nähe so die Deckung fallen lässt."
  },
  AvgCommunicate_134116_Content_15 = {
    Text = "Willst du die kleinen Geheimnisse in deinem Herzen schützen? Dann streng dich beim Plaudern mit mir ein bisschen mehr an."
  },
  AvgCommunicate_134116_Content_2 = {
    Text = "Wie fühlt es sich an? Ich habe ein schlechtes Gefühl dabei..."
  },
  AvgCommunicate_134116_Content_3 = {
    Text = "Wie soll ich es ausdrücken? Im Grunde sind diese mittelmäßigen Geister für mich jetzt wie offene Tagebücher – langweilig und völlig durchschaubar. Es ist ziemlich ermüdend, ehrlich gesagt."
  },
  AvgCommunicate_134116_Content_4 = {
    Text = "Was?! Du hast Gedankenlesen gemeistert?!"
  },
  AvgCommunicate_134116_Content_5 = {
    Text = "So dramatisch ist es nicht. Immerhin gibt es in dieser Welt noch einige Menschen mit widerstandsfähigem Geist und sturer Persönlichkeit, die versuchen, ihr Inneres Schicht um Schicht zu verhüllen und sich nicht so leicht von anderen durchschauen lassen."
  },
  AvgCommunicate_134116_Content_6 = {
    Text = "Und dann gibt es Wesen wie dich, die schon immer rätselhaft und unergründlich waren."
  },
  AvgCommunicate_134116_Content_7 = {
    Text = "Kein Grund, nervös zu sein. Die Antworten einer Prüfung im Voraus zu erfahren ist genauso langweilig, wie das Ende einer Geschichte vorher zu kennen oder den Täter eines Mordfalls zu früh zu Entdecken."
  },
  AvgCommunicate_134116_Content_8 = {
    Text = "Ich genieße den Prozess des Leitens, Spekulierens und des Faden-für-Faden-Abwickelns des Kokons, der jemandes Herz umhüllt, zutiefst."
  },
  AvgCommunicate_134116_Content_9 = {
    Text = "Ohne dieses Hin und Her – wie würden sich diese groben Diagnosen dann von Quacksalbern unterscheiden, die einfach ein Stück von jemandes Gehirn herausschneiden?"
  },
  AvgCommunicate_134116_Option_10 = {Text = "Äh"},
  AvgCommunicate_134116_Option_12 = {Text = "?!!"},
  AvgCommunicate_134116_Option_2 = {
    Text = "Wie fühlt es sich an?"
  },
  AvgCommunicate_134116_Option_4 = {Text = "Was?!"},
  AvgCommunicate_134117_Content_1 = {
    Text = "Die Reime der Verse sind noch bezaubernder geworden."
  },
  AvgCommunicate_134117_Content_10 = {
    Text = "Ich kann dich in die Welt der Poesie entführen, damit wir gemeinsam darin wandeln."
  },
  AvgCommunicate_134117_Content_12 = {
    Text = "Das ist fast wie Wortmagie! Wie erstaunlich!"
  },
  AvgCommunicate_134117_Content_13 = {
    Text = "Dann würde ich gerne eine Fata Morgana vom Ruhestand, Reichtum und unbegrenztem Gourmetessen erleben. Kannst du mich dorthin bringen?"
  },
  AvgCommunicate_134117_Content_14 = {
    Text = "Das... sollte, ja, es ist möglich! Bitte gib mir einen Moment, ich muss es sorgfältig durchdenken..."
  },
  AvgCommunicate_134117_Content_2 = {
    Text = "Jetzt kann ich die Emotionen sehen, die in diesen gesungenen Rhythmen aufwallen, die Stärke, die sich hinter jener Imagination widerspiegelt."
  },
  AvgCommunicate_134117_Content_3 = {
    Text = "Ich verstehe es nicht ganz, aber es klingt nach einem wunderschönen Anblick."
  },
  AvgCommunicate_134117_Content_4 = {
    Text = "Ja, Poesie ist ein Schlüssel zur Erkundung der Schönheit. Poesie kann die universellen Gesetze der Welt offenbaren und das Leben so widerspiegeln, wie es wirklich ist."
  },
  AvgCommunicate_134117_Content_5 = {
    Text = "In der Poesie finden wir uns selbst, finden die Weisheit der Geschichte und Philosophie, finden ein reines Heiligtum für den Geist."
  },
  AvgCommunicate_134117_Content_6 = {
    Text = "Ach, ich habe mich wieder in Selbstgespräche verloren. Es tut mir so leid..."
  },
  AvgCommunicate_134117_Content_7 = {
    Text = "Alles gut! Ich liebe es, wie leidenschaftlich du aussiehst, wenn du über Poesie sprichst. Das ist sehr charmant!"
  },
  AvgCommunicate_134117_Content_8 = {
    Text = "D-danke, Schutzherr. Jedenfalls kann ich jetzt Verse nutzen, um noch mehr Stärke aus jener Welt zu entleihen und eine vollständige poetische Fata Morgana zu erschaffen."
  },
  AvgCommunicate_134117_Content_9 = {
    Text = "Ob du Ruhe, Leidenschaft oder Melancholie genießen möchtest – ob du dem Duft von Blumen, Meeresströmungen oder Wolken nachjagen willst."
  },
  AvgCommunicate_134117_Option_12 = {
    Text = "Das ist fast wie Wortmagie."
  },
  AvgCommunicate_134117_Option_3 = {
    Text = "Das klingt wunderschön."
  },
  AvgCommunicate_134117_Option_7 = {
    Text = "Schon in Ordnung."
  },
  AvgCommunicate_134118_Content_1 = {
    Text = "Dass du meiner Wenigkeit etwas so Kostbares anbietest, du..."
  },
  AvgCommunicate_134118_Content_10 = {
    Text = "Aber kannst du wirklich so viel essen? Ein Koch hat sich mal beschwert, dass du die gesamten Butter- und Käsevorräte aufgebraucht hast, und ich musste aus eigener Tasche die Kantine wieder auffüllen."
  },
  AvgCommunicate_134118_Content_11 = {
    Text = "Oh? Wer hat hinter meinem Rücken geplaudert? Die sollen mir bloß nicht in die Hände fallen!"
  },
  AvgCommunicate_134118_Content_12 = {
    Text = "Was die Kuchen angeht, misch dich nicht in die Angelegenheiten einer Dame ein! Ich kann so viele essen, wie ich backe!"
  },
  AvgCommunicate_134118_Content_13 = {
    Text = "Und wenn ich sie nicht alle schaffe, kommst du und isst mit mir!"
  },
  AvgCommunicate_134118_Content_14 = {
    Text = "Ich... Ich muss die auch essen? Ich werde mich zu Tode vollstopfen und in der Blüte meines Lebens zunehmen!"
  },
  AvgCommunicate_134118_Content_15 = {
    Text = "Hör auf zu jammern. Nach dem ganzen Gerede habe ich deine Belohnung noch gar nicht erwähnt. Diese Dame wird gnädig genug sein, dir von nun an von jedem Kuchen, den ich persönlich backe, ein Stück aufzuheben."
  },
  AvgCommunicate_134118_Content_16 = {
    Text = "Sei dankbar! Das sind Meisterwerke einer genialen Pâtissière, die man für kein Geld der Welt kaufen kann!"
  },
  AvgCommunicate_134118_Content_17 = {
    Text = "Also... dieser Kuchenladen ist am Ende nur Eigenproduktion und Eigenkonsum!"
  },
  AvgCommunicate_134118_Content_2 = {
    Text = "Hmph, gar nicht schlecht."
  },
  AvgCommunicate_134118_Content_3 = {
    Text = "Jetzt kann meine Wenigkeit zehn – nein, hundert Seefahrer gleichzeitig wie Kreisel herumwirbeln! Ich werde nie wieder jemanden brauchen, der mich rettet!"
  },
  AvgCommunicate_134118_Content_4 = {
    Text = "Die große Dame ist mächtig!"
  },
  AvgCommunicate_134118_Content_5 = {
    Text = "Auch wenn mein Leben jetzt nicht mehr ständige Sorgen erfordert – wenn es um Stärke geht, ist mehr immer besser für die Seelenruhe."
  },
  AvgCommunicate_134118_Content_6 = {
    Text = "Wer die größeren Fäuste hat, zieht nie den Kürzeren!"
  },
  AvgCommunicate_134118_Content_7 = {
    Text = "Allerdings, so mächtige Stärke nur für die Arbeit bei Misaq zu nutzen, ist so eine Verschwendung... Ich hab's!"
  },
  AvgCommunicate_134118_Content_8 = {
    Text = "Da so viele Tentakel unabhängig arbeiten können, könnte ich genauso gut meinen eigenen Kuchenladen eröffnen. Wenn ich allein acht Stellen besetze, hätte ich dann nicht ewige Kuchenfreiheit!"
  },
  AvgCommunicate_134118_Content_9 = {
    Text = "Du kannst sie so benutzen?"
  },
  AvgCommunicate_134118_Option_14 = {
    Text = "Ich muss die auch essen?"
  },
  AvgCommunicate_134118_Option_17 = {Text = "Also..."},
  AvgCommunicate_134118_Option_4 = {
    Text = "Murphy ist mächtig!"
  },
  AvgCommunicate_134118_Option_9 = {
    Text = "Du kannst sie so benutzen?"
  },
  AvgCommunicate_134119_Content_1 = {
    Text = "Hahahaha... Hahahahaha!"
  },
  AvgCommunicate_134119_Content_10 = {
    Text = "Vor absoluter Macht ist Eroberung einfach nur ein langes Spiel."
  },
  AvgCommunicate_134119_Content_11 = {
    Text = "Was auch immer dich glücklich macht..."
  },
  AvgCommunicate_134119_Content_12 = {
    Text = "Die Zeit wird dir Kunde von meinem Triumph bringen. Wenn dieser Tag kommt, werde ich dir als wichtigstem Beitragenden zu meinem neuen Königreich das fruchtbarste Land als Lehen vorbehalten."
  },
  AvgCommunicate_134119_Content_13 = {
    Text = "Oder... wäre dir diese triste Stadt Lentiniën lieber?"
  },
  AvgCommunicate_134119_Content_2 = {
    Text = "Du bist doch nicht etwa von der Stärke in den Wahnsinn getrieben worden und hast plötzlich den Verstand verloren, oder?"
  },
  AvgCommunicate_134119_Content_3 = {
    Text = "Hmph hmph, als mein größter Stärke-Lieferant kann ich deine kleine Frechheit verzeihen."
  },
  AvgCommunicate_134119_Content_4 = {
    Text = "Ah... der Moment, auf den ich so lange gewartet habe, dieser vertraute süße Geschmack, dieses Gefühl, das das Blut in den Adern rasen lässt!"
  },
  AvgCommunicate_134119_Content_5 = {
    Text = "Ich kann jetzt mühelos Eisberge heben und Tiefseegräben aufspalten."
  },
  AvgCommunicate_134119_Content_6 = {
    Text = "Kein Anführer irgendeines Stammes, kein mächtigster Krieger der Seefahrer würde auch nur einen einzigen Kampf gegen mich bestehen, und diese wahnsinnige Frau kann mich auch nicht länger unterdrücken."
  },
  AvgCommunicate_134119_Content_7 = {
    Text = "Bald werde ich die Meere erobern, und dann alle Länder! Hahahahaha!"
  },
  AvgCommunicate_134119_Content_8 = {
    Text = "...Selbstvertrauen ist eine gute Sache, aber sei nicht so narzisstisch! Das ist bereits auf dem Niveau von Symptom: Wahnvorstellung!"
  },
  AvgCommunicate_134119_Content_9 = {
    Text = "Du weißt nichts von der Stärke einer Riesin, Kleines."
  },
  AvgCommunicate_134119_Option_11 = {
    Text = "Was auch immer dich glücklich macht..."
  },
  AvgCommunicate_134119_Option_2 = {
    Text = "Hast du den Verstand verloren?"
  },
  AvgCommunicate_134119_Option_8 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134120_Content_1 = {
    Text = "Meine Singstimme... ist anders als zuvor."
  },
  AvgCommunicate_134120_Content_10 = {
    Text = "Mm, das werde ich!"
  },
  AvgCommunicate_134120_Content_11 = {
    Text = "Übrigens, Schutzherr, dank deiner Ermutigung zuvor habe ich die Zusammenarbeit mit der Musikfirma angenommen. Mein erstes Album ist jetzt offiziell erschienen, und ich höre, es verkauft sich wirklich gut."
  },
  AvgCommunicate_134120_Content_12 = {
    Text = "Das sind tolle Neuigkeiten! Herzlichen Glückwunsch! Wie viele Exemplare wurden verkauft?"
  },
  AvgCommunicate_134120_Content_13 = {
    Text = "Ich glaube... es wurden hunderttausend Exemplare verkauft. Aber ich brauche die Währung dieses Planeten sowieso nicht wirklich. Da ich nichts anderes habe, um es dir zu vergelten, warum gebe ich dir nicht einfach alle Einnahmen des Albums?"
  },
  AvgCommunicate_134120_Content_14 = {Text = "Juhu!!!"},
  AvgCommunicate_134120_Content_2 = {
    Text = "Schutzherr, nachdem du mir geholfen hast, die Letzte Regel zu begreifen, scheint meine Stimme eine wundersame Resonanz mit dem Äther erreicht zu haben."
  },
  AvgCommunicate_134120_Content_3 = {
    Text = "Klingt, als wärst du stärker geworden. Faint wird sich sicher auch freuen!"
  },
  AvgCommunicate_134120_Content_4 = {
    Text = "Wie kann ich dir das jemals vergelten, Schutzherr? Mit meiner Schwester wiedervereint zu sein, war bereits ein Glück, von dem mein früheres Ich nie hätte träumen können, und dennoch hast du mir obendrein einen so kostbaren Schatz geschenkt."
  },
  AvgCommunicate_134120_Content_5 = {
    Text = "Im Moment besitze ich nichts, und ich bin auch kein Star mehr, der von Fans angehimmelt wird. Die einzige Art, wie ich es dir vergelten kann, ist... bitte, lass mich ein Lied für dich singen."
  },
  AvgCommunicate_134120_Content_6 = {
    Text = "Tinct, du hast bereits deinen eigenen Weg gefunden. Wenn du bereit bist, mir meinen Wunsch zu erfüllen."
  },
  AvgCommunicate_134120_Content_7 = {
    Text = "Bitte sing frei, für dich selbst und für mich."
  },
  AvgCommunicate_134120_Content_8 = {
    Text = "Nicht um jemandem zu gefallen, nicht um den Anforderungen anderer gerecht zu werden — Nur für dein eigenes Glück."
  },
  AvgCommunicate_134120_Content_9 = {
    Text = "Mein eigenes... Glück."
  },
  AvgCommunicate_134120_Option_12 = {
    Text = "Das sind tolle Neuigkeiten."
  },
  AvgCommunicate_134120_Option_14 = {Text = "?!!"},
  AvgCommunicate_134120_Option_3 = {
    Text = "Das ist wunderbar."
  },
  AvgCommunicate_134120_Option_6 = {
    Text = "Hast du jemals daran gedacht"
  },
  AvgCommunicate_134180_Content_1 = {
    Text = "Der Wind füllt die Segel, und Vögel fliegen in Formation neben uns her..."
  },
  AvgCommunicate_134180_Content_10 = {
    Text = "Ich möchte für immer und ewig die Meere besegeln — mit dir, mit dem Kapitän, mit allen zusammen."
  },
  AvgCommunicate_134180_Content_11 = {
    Text = "Gemeinsam sonnige und regnerische Tage erleben, in alle möglichen Häfen einlaufen und in verschiedenen Ländern anlegen."
  },
  AvgCommunicate_134180_Content_12 = {
    Text = "Zusammen fischen, zusammen Fisch grillen... Mm, und wir könnten sogar Muscheln vom Rumpf kratzen und sie in Rotwein schmoren."
  },
  AvgCommunicate_134180_Content_13 = {
    Text = "Lass uns in den nächsten Urlaub fahren."
  },
  AvgCommunicate_134180_Content_14 = {
    Text = "Ich habe lange darüber nachgedacht. Segeln... ist, wenn ich am glücklichsten bin."
  },
  AvgCommunicate_134180_Content_15 = {
    Text = "Ich werde alle sicher durch jeden Sturm steuern, damit wir fröhlich zusammen weitersegeln können."
  },
  AvgCommunicate_134180_Content_16 = {
    Text = "Das klingt wunderbar, aber wenn wir für immer ohne Pause segeln würden, würde jeder außer den Erweckten Körpern des Aequor-Reichs seekrank werden!"
  },
  AvgCommunicate_134180_Content_2 = {
    Text = "Ich sehe den Bug, wie er durch die Wellen schneidet, ich höre die Seeleute ihre Shanties singen, ich spüre das Flüstern von Wind und Regen."
  },
  AvgCommunicate_134180_Content_3 = {
    Text = "Ich kann es jetzt deutlicher sehen — den Kurs, der zu ruhigen, ningen Gewässern führt."
  },
  AvgCommunicate_134180_Content_4 = {
    Text = "Herzlichen Glückwunsch! Celeste!"
  },
  AvgCommunicate_134180_Content_5 = {
    Text = "Jetzt kann ich vielleicht wirklich den Wunsch aller erfüllen und die Schiffe unter meinem Schutz sicher ans andere Ufer geleiten."
  },
  AvgCommunicate_134180_Content_6 = {
    Text = "Ich werde nicht noch einmal alle enttäuschen."
  },
  AvgCommunicate_134180_Content_7 = {
    Text = "Und was ist mit deinem Wunsch? Hast du dich für deinen eigenen Wunsch entschieden?"
  },
  AvgCommunicate_134180_Content_8 = {
    Text = "Mein Wunsch..."
  },
  AvgCommunicate_134180_Content_9 = {
    Text = "Ich habe mich bereits entschieden."
  },
  AvgCommunicate_134180_Option_13 = {
    Text = "Lass uns in den nächsten Urlaub fahren."
  },
  AvgCommunicate_134180_Option_16 = {
    Text = "Das klingt wunderbar."
  },
  AvgCommunicate_134180_Option_4 = {
    Text = "Herzlichen Glückwunsch"
  },
  AvgCommunicate_134180_Option_7 = {
    Text = "Und was ist mit dir?"
  },
  AvgCommunicate_134181_Content_1 = {
    Text = "Ah... Der Ruf des Ozeans, so sanft, so warm."
  },
  AvgCommunicate_134181_Content_10 = {
    Text = "Hat Rogers' grobes Verhalten dich so traumatisiert, oder hältst du mich für eine derart einfallslose und faule Künstlerin?"
  },
  AvgCommunicate_134181_Content_11 = {
    Text = "Beim Verfeinern des Handwerks gibt es keine Abkürzungen. Meine Skulpturen sind selbstverständlich alle von meinen eigenen Händen gemeißelt, Schlag für Schlag."
  },
  AvgCommunicate_134181_Content_12 = {
    Text = "Sei unbesorgt, nicht ein einziges deiner Haare wird verwendet."
  },
  AvgCommunicate_134181_Content_13 = {
    Text = "Haha... Vielleicht sind deine bildhauerischen Fähigkeiten einfach zu gut. Jedes Mal, wenn ich deine Werke sehe, habe ich die Illusion, einen lebenden Menschen zu sehen."
  },
  AvgCommunicate_134181_Content_14 = {
    Text = "Hmm... Nun, da meine Stärke ihren Höhepunkt erreicht hat, könnte ich vielleicht wirklich eine Skulptur erschaffen, die zum Leben erwacht."
  },
  AvgCommunicate_134181_Content_15 = {
    Text = "In der tiefen Nacht, jenseits deines Blickfelds, würden sich die Augen der Skulptur langsam drehen, und die Mundwinkel würden sich ganz sachte nach oben kräuseln..."
  },
  AvgCommunicate_134181_Content_16 = {
    Text = "Sobald ich mein neuestes Werk fertig habe, stelle ich eines direkt neben dein Bett, damit es in meinem Namen über dich wacht. Wie klingt das?"
  },
  AvgCommunicate_134181_Content_17 = {
    Text = "Ich würde mein ganzes restliches Leben nie wieder schlafen können!!!"
  },
  AvgCommunicate_134181_Content_18 = {
    Text = "Das war nur ein Scherz."
  },
  AvgCommunicate_134181_Content_19 = {
    Text = "Es scheint, als hättest du wirklich Angst vor solch simplen Gruselgeschichten. Wie niedlich."
  },
  AvgCommunicate_134181_Content_2 = {
    Text = "Du musst ihn doch auch gehört haben, oder?"
  },
  AvgCommunicate_134181_Content_3 = {
    Text = "Er lädt uns ein, sie warten auf uns... um gemeinsam zum reinweißen Palast auf dem Meeresgrund zu reisen."
  },
  AvgCommunicate_134181_Content_4 = {
    Text = "Wer? Ich muss wohl taub sein — ich habe rein gar nichts gehört."
  },
  AvgCommunicate_134181_Content_5 = {
    Text = "Dann ist dies mein ganz eigener Kuss der Muse. Die Schönheit des Ozeans ist nun mit meiner Seele verschmolzen."
  },
  AvgCommunicate_134181_Content_6 = {
    Text = "Du bringst mir immer neuen kreativen Einblick. Ich gewinne dich wirklich von Tag zu Tag mehr lieb."
  },
  AvgCommunicate_134181_Content_7 = {
    Text = "Würdest du in Betracht ziehen, mein langfristiger Assistent zu sein? Du müsstest nichts tun — komm einfach jeden Tag in mein Atelier, sitz eine Weile, trink eine Tasse Tee und plaudere."
  },
  AvgCommunicate_134181_Content_8 = {
    Text = "Ich fühle mich zwar wirklich geehrt durch deine Güte, aber... werde ich eines Tages aufwachen und feststellen, dass ich in eine Steinskulptur verwandelt wurde?"
  },
  AvgCommunicate_134181_Content_9 = {
    Text = "Heh heh, siehst du mich wirklich so?"
  },
  AvgCommunicate_134181_Option_13 = {
    Text = "Deine Handwerkskunst ist zu gut."
  },
  AvgCommunicate_134181_Option_17 = {
    Text = "Auf keinen Fall!!!"
  },
  AvgCommunicate_134181_Option_4 = {
    Text = "Nein, habe ich nicht."
  },
  AvgCommunicate_134181_Option_8 = {
    Text = "Werde ich in eine Skulptur verwandelt?"
  },
  AvgCommunicate_134187_Content_1 = {
    Text = "Kleiner Welpe, wie geht es dir in letzter Zeit?"
  },
  AvgCommunicate_134187_Content_10 = {
    Text = "Tu nichts Unüberlegtes. Egal was passiert, der Schwarze Teich wird dich fest gefangen halten."
  },
  AvgCommunicate_134187_Content_11 = {
    Text = "Du hast absolut keine Ahnung, welche Art von Macht Wissen mir verleihen kann."
  },
  AvgCommunicate_134187_Content_12 = {
    Text = "Ich bin sehr erfreut über dieses Geschenk. Also, mein liebster Schüler, werde ich dir ein Geschenk erwidern."
  },
  AvgCommunicate_134187_Content_13 = {Text = "...?"},
  AvgCommunicate_134187_Content_14 = {
    Text = "Rate. Rate doch mal, wie weit ich jetzt gehen kann."
  },
  AvgCommunicate_134187_Content_15 = {
    Text = "Rate, ob eure arroganten Eindämmungsmaßnahmen tatsächlich greifen können."
  },
  AvgCommunicate_134187_Content_16 = {
    Text = "Rate, ob die Wahrheit, die ich erblickt habe, nun da ich diese Macht erlangt habe, in die Erkenntnis eines jeden Einzelnen von euch eingepflanzt wird."
  },
  AvgCommunicate_134187_Content_17 = {
    Text = "Das ist die wichtigste Hausaufgabe. Sehr bald, sehr bald werde ich persönlich kommen, um sie zu benoten."
  },
  AvgCommunicate_134187_Content_2 = {
    Text = "Deine Dreistigkeit überrascht mich wirklich — du hast es tatsächlich gewagt, ein Geschenk dieses Kalibers zu schicken."
  },
  AvgCommunicate_134187_Content_3 = {
    Text = "Würdest du mir glauben, wenn ich sage, dass es einen schweren Unfall beim Transport seltener Materialien gab..."
  },
  AvgCommunicate_134187_Content_5 = {
    Text = "Du unterschätzt mich, und du unterschätzt Misaq."
  },
  AvgCommunicate_134187_Content_6 = {
    Text = "Wir sind bereit, jeden Erweckten Körper an diese Grenze heranreichen zu lassen, denn wir werden jede Methode versuchen, um die Zerstörung zu verhindern."
  },
  AvgCommunicate_134187_Content_7 = {
    Text = "Das ist... der größte Unterschied zwischen dieser Lehrerin Doll, und uns, und dir — selbst wenn die Zerstörung vorbestimmt ist, werden wir uns ihr niemals beugen."
  },
  AvgCommunicate_134187_Content_8 = {
    Text = "Seufz, wie habe ich vorher nicht bemerkt, dass Misaqs Bildungssystem Narren hervorbringt."
  },
  AvgCommunicate_134187_Content_9 = {
    Text = "Zum Glück ein Narr, so erbärmlich dumm, dass man gar nicht anders kann, als Zuneigung zu empfinden."
  },
  AvgCommunicate_134187_Option_13 = {Text = "...?"},
  AvgCommunicate_134187_Option_3 = {
    Text = "Es war ein Unfall."
  },
  AvgCommunicate_134187_Option_5 = {
    Text = "Es war Absicht."
  },
  AvgCommunicate_134188_Content_1 = {
    Text = "Regeln, so toll! Peng–! Bumm–! Kabumm–!"
  },
  AvgCommunicate_134188_Content_11 = {
    Text = "Wenn das der Fall ist, sollten die Reparaturkosten der Schule in diesem Monat deutlich sinken..."
  },
  AvgCommunicate_134188_Content_12 = {
    Text = "Schlechte Hausaufgaben, auftauchen, Mosk, totschlagen!"
  },
  AvgCommunicate_134188_Content_13 = {
    Text = "Nein, du kannst Hausaufgaben nicht auch als Feind zählen!"
  },
  AvgCommunicate_134188_Content_14 = {
    Text = "Mosk, Mosk?"
  },
  AvgCommunicate_134188_Content_16 = {
    Text = "Schutzherr, hier ist Nautila. Keine Sorge, Mosk wurde unter Kontrolle gebracht. Die Hausaufgaben und das Klassenzimmer sind beide in Sicherheit."
  },
  AvgCommunicate_134188_Content_17 = {
    Text = "Gott sei Dank..."
  },
  AvgCommunicate_134188_Content_18 = {
    Text = "Nautila, Misaq, Mosk und ich werden dich immer brauchen."
  },
  AvgCommunicate_134188_Content_2 = {
    Text = "Denk an Regel Nr. 1 des Misaq-Kodex, Mosk-Sonderausgabe: Unter keinen Umständen darf jemand eine tödliche Waffe auf irgendeine Person in Misaq richten."
  },
  AvgCommunicate_134188_Content_5 = {
    Text = "%player%, keine Sorge, Mosk, Kontrolle, kann das!"
  },
  AvgCommunicate_134188_Content_6 = {
    Text = "Mosk, zurückhalten, Wirbel."
  },
  AvgCommunicate_134188_Content_7 = {
    Text = "Mosk, Freund, Knuddler."
  },
  AvgCommunicate_134188_Content_8 = {
    Text = "Mosk, Feind, peng–! bumm–! kabumm–!"
  },
  AvgCommunicate_134188_Option_2 = {
    Text = "Sicherheit zuerst."
  },
  AvgCommunicate_134189_Content_1 = {
    Text = "Wir sind Waffenbrüder, also sage ich nicht danke."
  },
  AvgCommunicate_134189_Content_2 = {
    Text = "Meine Waffe wurde bis aufs Schärfste geschliffen – scharf genug, um einem Sklavenmeister im Nu die Kehle aufzuschlitzen."
  },
  AvgCommunicate_134189_Content_3 = {
    Text = "Die Bedeutung des Widerstands, die Bedeutung der Rache, die Bedeutung des Kampfes – ich grüble bis zum heutigen Tag darüber nach."
  },
  AvgCommunicate_134189_Content_4 = {
    Text = "Vielleicht werde ich für den Rest meines Lebens weiter darüber nachdenken, bis zu dem Tag, an dem ich nicht mehr stehen kann."
  },
  AvgCommunicate_134189_Content_5 = {
    Text = "Zumindest bin ich nicht mehr verloren."
  },
  AvgCommunicate_134189_Content_6 = {
    Text = "Auf meine Waffenbrüder."
  },
  AvgCommunicate_134189_Content_7 = {
    Text = "Auf Waffenbrüder. Du warst es, der mich befreit hat, der mir die Festigkeit gab, weiterzumachen."
  },
  AvgCommunicate_134189_Content_8 = {
    Text = "Wann immer du mich brauchst, werde ich dir stets meinen Rücken anvertrauen und an deiner Seite kämpfen – Schulter an Schulter."
  },
  AvgCommunicate_134189_Content_9 = {
    Text = "Lasst uns weiter zusammen kämpfen – für die Rache, die vollzogen werden muss, und für den Rausch des Kampfes selbst."
  },
  AvgCommunicate_134189_Option_6 = {
    Text = "Auf Waffenbrüder."
  },
  AvgCommunicate_134201_Content_1 = {
    Text = "Schutzherr, ich habe beim Ausbildungsbüro einen Antrag eingereicht. Ich werde die nächsten drei Tage nicht am Training teilnehmen."
  },
  AvgCommunicate_134201_Content_10 = {
    Text = "Aber nachdem ich diese Grenze überschritten hatte, verstand ich."
  },
  AvgCommunicate_134201_Content_11 = {Text = "Was?"},
  AvgCommunicate_134201_Content_13 = {
    Text = "Ich bin die Klinge der Vorhut. Gerade weil ich immer diesen Weg gegangen bin, konnte ich euch alle treffen — dich treffen."
  },
  AvgCommunicate_134201_Content_14 = {
    Text = "Mein Streben stellt sicher, dass ich niemals allein bin. Vielleicht können wir es nie erreichen, aber Solange wir durchhalten, kann ich diese ideale, gerechte Welt ein wenig näher bringen — nur ein kleines Stück näher."
  },
  AvgCommunicate_134201_Content_15 = {
    Text = "Mit mir selbst als Klinge, bis wir die Utopie erreichen, in der Alle im Licht leben können."
  },
  AvgCommunicate_134201_Content_16 = {
    Text = "Was für eine großartige Vision, Ausbilderin Alva! Ich werde dich bedingungslos unterstützen!"
  },
  AvgCommunicate_134201_Content_17 = {
    Text = "Wunderbar. In dem Fall werde ich diese drei Tage nutzen, um einen noch strengeren und anspruchsvolleren Trainingsplan zu entwickeln."
  },
  AvgCommunicate_134201_Content_18 = {
    Text = "Du wirst unter den Ersten sein, die ihn ausprobieren. Sei versichert, ich werde die ganze Zeit als Sparringspartnerin dabei sein und mich gemeinsam mit allen verbessern."
  },
  AvgCommunicate_134201_Content_19 = {
    Text = "Warte, ich denke, wir können das noch ein wenig besprechen..."
  },
  AvgCommunicate_134201_Content_2 = {
    Text = "Gab es ein Problem mit den Materialien? Geht es dir gut? Brauchst du Hilfe?"
  },
  AvgCommunicate_134201_Content_3 = {
    Text = "Nein, ganz im Gegenteil. Alles lief reibungslos. Ich habe Verbesserungen erfahren, die anders sind als zuvor."
  },
  AvgCommunicate_134201_Content_4 = {
    Text = "Ich bin mir nicht sicher, ob ich folgen kann..."
  },
  AvgCommunicate_134201_Content_5 = {
    Text = "Ich... nachdem ich das Militär verlassen hatte, trieb ich sehr lange umher."
  },
  AvgCommunicate_134201_Content_6 = {
    Text = "Ich weiß nicht, wofür ich kämpfen sollte. Das Einzige, dem ich folgen kann, ist ein Gefühl der Gerechtigkeit — eines, von dem ich nicht einmal sicher bin, ob ich es letztlich erreichen kann."
  },
  AvgCommunicate_134201_Content_7 = {
    Text = "Ich hoffe, auf der Seite der Schwachen zu stehen, auf der Seite derer, die nicht für sich sprechen können, auf der Seite derer, die ungerecht behandelt werden."
  },
  AvgCommunicate_134201_Content_8 = {
    Text = "Aber ich weiß auch genau, dass es, egal wie stark ich werde, immer Dinge geben wird, die hilflos sind — so wie ich selbst bei einer Umkehr der Zeit den Fall von Aram nicht hätte verhindern können."
  },
  AvgCommunicate_134201_Content_9 = {
    Text = "Ausbilderin Alva..."
  },
  AvgCommunicate_134201_Option_2 = {
    Text = "Was ist passiert?"
  },
  AvgCommunicate_134202_Content_1 = {
    Text = "Danke, dass du mir etwas so Kostbares anvertraut hast, %player%."
  },
  AvgCommunicate_134202_Content_10 = {
    Text = "Ich glaube, sie will mir sagen, dass die Welt nicht nur Schatten in der Erinnerung hinterlässt, sondern auch mit Schritten vermessen werden kann."
  },
  AvgCommunicate_134202_Content_11 = {
    Text = "Wenn ich es nicht festhalten kann, dann gehe ich einfach immer weiter, immer, immer — die Welt und ihr alle werdet euch für mich erinnern."
  },
  AvgCommunicate_134202_Content_12 = {
    Text = "Selbst ich kann nicht anders, als Feuer und Flamme zu sein..."
  },
  AvgCommunicate_134202_Content_13 = {
    Text = "Ich werde die größte Entdeckerin, die unglaublichste Meistermechanikerin. %player%, ich möchte dich hiermit offiziell einladen."
  },
  AvgCommunicate_134202_Content_14 = {
    Text = "Wenn der Tag kommt, an dem alles gelöst ist, bitte geh mit mir auf ein Abenteuer — lass uns mehr kostbare Erinnerungen in dieser Welt schaffen."
  },
  AvgCommunicate_134202_Content_15 = {
    Text = "Vielleicht ist dieser Tag noch weit entfernt, oder vielleicht ist er schon morgen."
  },
  AvgCommunicate_134202_Content_16 = {
    Text = "Diese Einladung gilt für immer. Ich werde sie mir auf jeden Fall merken."
  },
  AvgCommunicate_134202_Content_2 = {
    Text = "Ich habe sehr, sehr lange gebraucht, um sie aufzunehmen... Jetzt geben sie mir das Gefühl, wieder vollständig zu sein."
  },
  AvgCommunicate_134202_Content_3 = {
    Text = "Heißt das also, du vergisst jetzt nichts mehr?"
  },
  AvgCommunicate_134202_Content_4 = {
    Text = "Hmm, lass mich nachdenken..."
  },
  AvgCommunicate_134202_Content_5 = {
    Text = "Haha, ich kann mich immer noch nicht erinnern!"
  },
  AvgCommunicate_134202_Content_6 = {
    Text = "Warum klingst du dabei so stolz!"
  },
  AvgCommunicate_134202_Content_7 = {
    Text = "Weil, auch wenn ich vielleicht immer noch vieles vergesse, in der Vergangenheit und jetzt, %player% immer da war, um mich zu erinnern und mir beim Erinnern zu helfen."
  },
  AvgCommunicate_134202_Content_8 = {
    Text = "Wer ich bin, wo ich bin, was ich tun muss — die Menschen, denen ich am meisten vertraue, werden es mir sagen."
  },
  AvgCommunicate_134202_Content_9 = {
    Text = "Vielleicht ist das der Grund, warum sich nach dem Begreifen der Letzten Regel, obwohl mein Gedächtnis sich nicht verbessert hat, die ganze Welt vor meinen Augen wie eine riesige Landkarte entfaltet hat."
  },
  AvgCommunicate_134202_Option_3 = {
    Text = "Hat sich dein Gedächtnis verbessert?"
  },
  AvgCommunicate_134208_Content_1 = {
    Text = "Ich glaubte einst, dass ich Nur durch das Spielen der Rolle des Publikums die Freude des Unbekannten erleben könnte."
  },
  AvgCommunicate_134208_Content_10 = {
    Text = "Ich verstehe es nicht ganz... aber es klingt nach etwas Gutem?"
  },
  AvgCommunicate_134208_Content_11 = {
    Text = "Seit ich jene Tür durchschritten habe, ist dies das größte Glück, das mir widerfahren ist."
  },
  AvgCommunicate_134208_Content_12 = {
    Text = "Schutzherr, dies ist die Überraschung, die Ihr mir geschenkt habt—eine, die ich niemals hätte vorhersehen können."
  },
  AvgCommunicate_134208_Content_13 = {
    Text = "Das Schicksal enttäuscht niemals jene, die großzügig geben."
  },
  AvgCommunicate_134208_Content_14 = {
    Text = "Ich kann die Fäden Eures Schicksals nicht berühren, doch wenn Ihr dafür kämpft, wird sich mein Spinnrad für immer für Euch drehen."
  },
  AvgCommunicate_134208_Content_2 = {
    Text = "Es ist so lange her... so unendlich lange, seit ich mich das letzte Mal so gefühlt habe..."
  },
  AvgCommunicate_134208_Content_3 = {
    Text = "Wie fühlt es sich an?"
  },
  AvgCommunicate_134208_Content_4 = {Text = "Neuheit."},
  AvgCommunicate_134208_Content_5 = {
    Text = "Das stille Erblühen der Knospen, das Verweben von Worten auf Papier, das sanfte Dahingleiten der Wolken im Wind..."
  },
  AvgCommunicate_134208_Content_6 = {
    Text = "Und natürlich die Menschen—diese ausgestreckten Arme, diese fallenden Tränen, diese Herzschläge wie Kriegstrommeln oder Regentropfen..."
  },
  AvgCommunicate_134208_Content_7 = {
    Text = "Ich sehe mehr als zuvor, und doch ruht mein Blick tiefer als früher."
  },
  AvgCommunicate_134208_Content_8 = {
    Text = "Er verweilt nicht mehr am Himmel, Schutzherr. Er ist herabgestiegen—auf jede Straße gefallen, neben jeden Passanten."
  },
  AvgCommunicate_134208_Content_9 = {
    Text = "Nun muss ich keine Rolle mehr spielen. Ich kann wahrhaftig als Individuum existieren."
  },
  AvgCommunicate_134208_Option_10 = {
    Text = "Das klingt nach etwas Gutem?"
  },
  AvgCommunicate_134208_Option_3 = {
    Text = "Wie fühlt es sich an?"
  },
  AvgCommunicate_134242_Content_1 = {
    Text = "Temporärer Text"
  },
  AvgCommunicate_134245_Content_1 = {
    Text = "Das wirkt wie etwas sehr Wertvolles – ist es wirklich in Ordnung, es Shaye zu geben?"
  },
  AvgCommunicate_134245_Content_12 = {
    Text = "Also hat auch diese Welt ihre schönen Seiten, auch wenn sie sich von der Welt in meiner Erinnerung etwas unterscheidet."
  },
  AvgCommunicate_134245_Content_13 = {
    Text = "Die Art, wie sie aufgebaut ist, die Logik, nach der sie funktioniert – Shaye versteht das nun vollständig."
  },
  AvgCommunicate_134245_Content_14 = {
    Text = "Daher könnte ich diese Welt vielleicht ganz leicht in die Welt umschreiben, an die ich mich erinnere."
  },
  AvgCommunicate_134245_Content_16 = {
    Text = "Auch wenn ich weiß, dass du Spaß machst – bitte tu so etwas auf keinen Fall."
  },
  AvgCommunicate_134245_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134245_Content_18 = {
    Text = "Warum sagst du nichts mehr – das war ein Scherz, oder? Schweig nicht ausgerechnet jetzt!"
  },
  AvgCommunicate_134245_Content_19 = {
    Text = "Also, ich bin eben nur kurz weggegangen und habe alle mal aus einer neuen Perspektive beobachtet..."
  },
  AvgCommunicate_134245_Content_2 = {
    Text = "Ich vertraue Shaye, also ist es in Ordnung."
  },
  AvgCommunicate_134245_Content_20 = {
    Text = "Solange alle, die Shaye kennen und freundlich behandeln, noch wohlauf sind, ist es so."
  },
  AvgCommunicate_134245_Content_21 = {
    Text = "Ich kann nicht genau sagen, was daran nicht stimmt, aber ich habe irgendwie das Gefühl, dass irgendetwas nicht ganz stimmt."
  },
  AvgCommunicate_134245_Content_22 = {
    Text = "Und jetzt trägst du bestimmt wieder dieses Gesicht, als hättest du einen Streich erfolgreich ausgeführt!"
  },
  AvgCommunicate_134245_Content_23 = {
    Text = "Keine Sorge, ich werde gut mit allen in dieser Welt auskommen."
  },
  AvgCommunicate_134245_Content_24 = {
    Text = "Hm... aber die Welt in Shayes Erinnerungen ist vielleicht noch interessanter. Sollen wir alle zusammen einen Blick darauf werfen? Das sollte jetzt möglich sein!"
  },
  AvgCommunicate_134245_Content_25 = {
    Text = "Das ist ja noch erschreckender!"
  },
  AvgCommunicate_134245_Content_3 = {
    Text = "Wenn es dir hilft, diese Welt besser zu verstehen, dürfte es auch für die Forschung darüber, „wie man die Auflösung aufhalten kann\", eine große Hilfe sein."
  },
  AvgCommunicate_134245_Content_4 = {
    Text = "Schließlich bist du beim Lernen und Forschen wirklich außerordentlich stark..."
  },
  AvgCommunicate_134245_Content_5 = {
    Text = "Eigentlich war es ein Versehen bei der Versorgung... aber jetzt ist es wohl zu spät, um es rückgängig zu machen?"
  },
  AvgCommunicate_134245_Content_6 = {
    Text = "Hä? Soll ich es dann zurückgeben? Das ist ein bisschen schwierig."
  },
  AvgCommunicate_134245_Content_7 = {
    Text = "Hä? Kann ich es zurückgeben?"
  },
  AvgCommunicate_134245_Content_8 = {
    Text = "Hmm, lass Shaye kurz nachdenken..."
  },
  AvgCommunicate_134245_Content_9 = {
    Text = "Die Antwort lautet — nein."
  },
  AvgCommunicate_134245_Option_2 = {
    Text = "Kein Problem"
  },
  AvgCommunicate_134245_Option_5 = {
    Text = "Es war ein Versehen"
  },
  AvgCommunicate_134246_Content_1 = {
    Text = "Mein liebster, verehrtester, großartigster Wohltäter~"
  },
  AvgCommunicate_134246_Content_10 = {
    Text = "Lass mich nachsehen."
  },
  AvgCommunicate_134246_Content_11 = {
    Text = "Lass mich deine Schwankungsdaten des Gnostischen Index überprüfen."
  },
  AvgCommunicate_134246_Content_12 = {
    Text = "Nun schau mal an – unser Caraboo hat diesmal tatsächlich nicht gelogen."
  },
  AvgCommunicate_134246_Content_13 = {
    Text = "Heh heh, glaubst du dem armen kleinen Caraboo jetzt, oder?"
  },
  AvgCommunicate_134246_Content_14 = {
    Text = "Bitte investiere weiterhin großzügig in mich – damit ich meinem lieben Wohltäter auf dem weiteren Weg das Hundert-, das Tausendfache zurückbringen kann!"
  },
  AvgCommunicate_134246_Content_15 = {
    Text = "Nur noch acht – nein, fünf Erwachens-Splitter! Und ich werde dich erneut verblüffen, das verspreche ich!"
  },
  AvgCommunicate_134246_Content_16 = {
    Text = "Das ist unmöglich."
  },
  AvgCommunicate_134246_Content_17 = {
    Text = "Netter Versuch."
  },
  AvgCommunicate_134246_Content_18 = {
    Text = "Professor Doll hat mir gesagt, dass die Forschung zum Erwachen der Erwecker bereits an ihre Grenzen gestoßen ist. Es wird in einem Jahrhundert keinen weiteren Durchbruch geben."
  },
  AvgCommunicate_134246_Content_19 = {
    Text = "Sobald ein Erwecker das Absolute Axiom erlangt, kann er das Psyche-Surge-Ritual nie wieder durchführen."
  },
  AvgCommunicate_134246_Content_2 = {
    Text = "Was brauchst du diesmal, dass du so plötzlich so dick aufträgst?"
  },
  AvgCommunicate_134246_Content_21 = {
    Text = "Haha – ich muss da wohl versehentlich etwas durcheinandergebracht haben!"
  },
  AvgCommunicate_134246_Content_22 = {
    Text = "Bitte spule deine Erinnerung an dieses Gespräch um sechs Nachrichten zurück. Einen wunderschönen Tag noch~"
  },
  AvgCommunicate_134246_Content_3 = {
    Text = "Oh je, hör dir das an – wofür hältst du mich eigentlich? Für jemanden, der nur auftaucht, wenn sie etwas will?"
  },
  AvgCommunicate_134246_Content_4 = {
    Text = "Genau das bist du..."
  },
  AvgCommunicate_134246_Content_5 = {
    Text = "Buh-huu, ich bin untröstlich. Mein Wohltäter verkennt mich so schrecklich."
  },
  AvgCommunicate_134246_Content_6 = {
    Text = "Ich bin diesmal tatsächlich gekommen, um dir gute Neuigkeiten zu bringen!"
  },
  AvgCommunicate_134246_Content_7 = {
    Text = "Deine Investition hat sich ausgezahlt – mit super, super erstaunlichen Ergebnissen~"
  },
  AvgCommunicate_134246_Content_8 = {
    Text = "Siehst du? Ich bin ein völlig neues Ich. Wiedergeboren, verwandelt, eine ganz andere Person~"
  },
  AvgCommunicate_134246_Content_9 = {Text = "Wirklich?"},
  AvgCommunicate_134246_Option_10 = {
    Text = "Lass mich nachsehen."
  },
  AvgCommunicate_134246_Option_16 = {
    Text = "Das ist unmöglich."
  },
  AvgCommunicate_134246_Option_17 = {
    Text = "Netter Versuch."
  },
  AvgCommunicate_134246_Option_9 = {Text = "Wirklich?"},
  AvgCommunicate_134247_Content_1 = {
    Text = "Temporärer Text"
  },
  AvgCommunicate_134249_Content_1 = {Text = "Hüter..."},
  AvgCommunicate_134249_Content_10 = {
    Text = "Mmm... dieses Gefühl ist wieder da. Mir ist plötzlich so heiß, so durstig. Mein Magen, innen in meinem Magen,"
  },
  AvgCommunicate_134249_Content_11 = {
    Text = "Schutzherr, bin ich krank? Mein Magen wird ganz weich, mein Herz wird ganz weich, alles ist weich. Ich kann nichts mehr auseinanderhalten, es ist, als würde ich schmelzen..."
  },
  AvgCommunicate_134249_Content_12 = {
    Text = "Tief durchatmen, Leigh. Du wirst nicht schmelzen."
  },
  AvgCommunicate_134249_Content_13 = {
    Text = "Das ist eine normale Reaktion bei intimen Beziehungen unter Menschen. Keine Medizin nötig... und auch keine Peitsche!"
  },
  AvgCommunicate_134249_Content_14 = {
    Text = "Hä? Nicht mal eine Peitsche? Wie enttäuschend."
  },
  AvgCommunicate_134249_Content_16 = {
    Text = "...Äh, wenn du wirklich eine brauchst, frag vielleicht Pandia..."
  },
  AvgCommunicate_134249_Content_17 = {Text = "Heh heh."},
  AvgCommunicate_134249_Content_18 = {
    Text = "Schutzherr, ich werde versuchen, nicht mehr vor deiner Tür zu kauern."
  },
  AvgCommunicate_134249_Content_19 = {
    Text = "Aber... könntest du vielleicht ab und zu nachts eine Tür für mich offen lassen? Ein Fenster würde auch reichen."
  },
  AvgCommunicate_134249_Content_2 = {
    Text = "Das Fleisch meines Bruders und mein Körper sind kompatibler als zuvor. Es atmet leise unter meiner Haut, schreit nicht mehr ständig danach, mich zu zerreißen."
  },
  AvgCommunicate_134249_Content_20 = {
    Text = "Ich werde nicht reinkommen. Einfach zu wissen, dass es einen Weg gibt, der jederzeit zu dir führt, würde mir helfen, friedlicher zu schlafen."
  },
  AvgCommunicate_134249_Content_3 = {
    Text = "Das Verlangen nach Blut schmerzt auch nicht mehr so sehr. Früher war es, als steckte etwas in meinem Hals—Erstickung, wenn ich nicht trank. Jetzt scheint es... bereit zu sein, ein wenig auf mich zu warten."
  },
  AvgCommunicate_134249_Content_4 = {
    Text = "Das sind wirklich gute Neuigkeiten."
  },
  AvgCommunicate_134249_Content_5 = {
    Text = "Die Nächte in der Schule sind so still. Der Brunnen plätschert leise."
  },
  AvgCommunicate_134249_Content_6 = {
    Text = "Schutzherr, du hast mir so viele Schätze gegeben. Bin ich das wirklich wert?"
  },
  AvgCommunicate_134249_Content_7 = {
    Text = "Natürlich bist du das."
  },
  AvgCommunicate_134249_Content_8 = {
    Text = "...Du antwortest immer so schnell."
  },
  AvgCommunicate_134249_Content_9 = {
    Text = "Leigh, du hast uns so sehr geholfen. Das ist das Mindeste, was ich tun kann."
  },
  AvgCommunicate_134250_Content_1 = {
    Text = "Wisst Ihr nicht, wie es endet, wenn man ein Biest aufzieht?"
  },
  AvgCommunicate_134250_Content_10 = {
    Text = "Ich frage mich oft—bist du wirklich so, wie du nach außen hin wirkst, oder..."
  },
  AvgCommunicate_134250_Content_11 = {
    Text = "Spielst du die ganze Zeit nur Theater, genau wie diese Sklavenmeister?"
  },
  AvgCommunicate_134250_Content_12 = {
    Text = "Was meinst du? Ich bin nicht gut im Schauspielern, und ich bin nicht gut im Lügen."
  },
  AvgCommunicate_134250_Content_13 = {
    Text = "Du kannst deinen eigenen Gefühlen vertrauen. Ich werde nicht versuchen, dich zu überzeugen, und ich werde dich zu nichts zwingen."
  },
  AvgCommunicate_134250_Content_14 = {
    Text = "Einfach so, wie das andere Du einst sagte—wir sind Freunde, wir sind Kameraden."
  },
  AvgCommunicate_134250_Content_15 = {
    Text = "Tch, vergleich mich nicht mit dieser schwachen Närrin."
  },
  AvgCommunicate_134250_Content_16 = {
    Text = "Ich habe mehr als genug von Verrat. Ich brauche keine Freunde."
  },
  AvgCommunicate_134250_Content_17 = {
    Text = "Und ich will auch keine deiner Versprechen."
  },
  AvgCommunicate_134250_Content_18 = {
    Text = "Solange du mir mehr Stärke gibst, reicht das."
  },
  AvgCommunicate_134250_Content_19 = {
    Text = "Und ich werde mich für dich an deinen Feinden rächen."
  },
  AvgCommunicate_134250_Content_2 = {
    Text = "Ein Biest, das stark geworden ist, sprengt seine Ketten und—RAWR—beißt seinem Hüter die Kehle durch."
  },
  AvgCommunicate_134250_Content_20 = {
    Text = "Bis zu dem Tag, an dem du mich wirklich verrätst... selbst wenn du bis ans Ende der Welt fliehst, werde ich dich jagen und dir die Kehle durchbeißen."
  },
  AvgCommunicate_134250_Content_3 = {
    Text = "Im Moment sieht die Verbindung zwischen Euch und mir in meinen Augen noch zerbrechlicher aus als eiserne Ketten."
  },
  AvgCommunicate_134250_Content_4 = {
    Text = "Habt Ihr keine Angst?"
  },
  AvgCommunicate_134250_Content_5 = {
    Text = "Du bist frei. Unsere Verbindung ist nicht dazu da, dich zu fesseln."
  },
  AvgCommunicate_134250_Content_6 = {
    Text = "Ich habe keinen Grund, Angst zu haben."
  },
  AvgCommunicate_134250_Content_7 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134250_Content_8 = {
    Text = "Tch, Schmeicheleien."
  },
  AvgCommunicate_134250_Content_9 = {
    Text = "Trotzdem, ich beobachte dich schon lange, und ich habe noch nicht gesehen, dass du zögerst."
  },
  AvgCommunicate_134250_Option_12 = {
    Text = "Was denkst du?"
  },
  AvgCommunicate_134250_Option_5 = {
    Text = "Du bist frei"
  },
  AvgCommunicate_134263_Content_1 = {
    Text = "Schutzherr!!"
  },
  AvgCommunicate_134263_Content_10 = {
    Text = "Natürlich. Ich habe nie daran gezweifelt, dass du stärker werden würdest."
  },
  AvgCommunicate_134263_Content_11 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134263_Content_12 = {
    Text = "Du bist wirklich ein seltsamer Mensch."
  },
  AvgCommunicate_134263_Content_13 = {
    Text = "Solltest du in so einem Moment nicht etwas sagen wie „Siehst du, ich wusste, dass ich den richtigen Blick für Talent habe\" oder „Wie erwartet, du hast mich nicht enttäuscht\"?"
  },
  AvgCommunicate_134263_Content_14 = {
    Text = "Warum bist du so gelassen dabei?"
  },
  AvgCommunicate_134263_Content_16 = {
    Text = "Äh... weil du so hart gearbeitet hast. Stärker zu werden ist nur natürlich. Was gibt es da zu sagen?"
  },
  AvgCommunicate_134263_Content_17 = {
    Text = "Die 50 Dollar, die du mir vorvorletztes Jahr zurückgezahlt hast, und die 54 vom letzten Jahr—ich habe sie alle aufbewahrt."
  },
  AvgCommunicate_134263_Content_18 = {
    Text = "Warum aufbewahren... Gib sie einfach aus."
  },
  AvgCommunicate_134263_Content_19 = {
    Text = "Vergiss es, egal. Es gibt etwas Wichtigeres."
  },
  AvgCommunicate_134263_Content_2 = {
    Text = "Diese Markierungen brennen heiß. Die Stärke des Aequor fließt unter meiner Haut, so viel deutlicher als zuvor!"
  },
  AvgCommunicate_134263_Content_20 = {
    Text = "Komm jetzt zum Seeufer. Ich warte hier auf dich."
  },
  AvgCommunicate_134263_Content_21 = {
    Text = "Was ist los?"
  },
  AvgCommunicate_134263_Content_22 = {
    Text = "Das erfährst du, wenn du hier bist."
  },
  AvgCommunicate_134263_Content_23 = {
    Text = "In Ordnung... dann warte kurz auf mich. Es regnet gerade draußen. Ich muss zurück zum Wohnheim und einen Regenschirm holen."
  },
  AvgCommunicate_134263_Content_24 = {
    Text = "Hör auf zu trödeln. Für das, was wir als Nächstes vorhaben, brauchst du keinen Regenschirm."
  },
  AvgCommunicate_134263_Content_25 = {
    Text = "Du wirst nicht nass. Meine Membranflügel sind groß genug."
  },
  AvgCommunicate_134263_Content_3 = {
    Text = "Hast du eine Ahnung, wie sich das anfühlt?!"
  },
  AvgCommunicate_134263_Content_4 = {
    Text = "Jedenfalls ist es unglaublich, unbeschreiblich. Ihr Menschen könnt das wahrscheinlich nicht einmal begreifen."
  },
  AvgCommunicate_134263_Content_5 = {
    Text = "...Caecus, bist du in Ordnung?"
  },
  AvgCommunicate_134263_Content_6 = {
    Text = "Natürlich bin ich in Ordnung. Mir ging es noch nie besser."
  },
  AvgCommunicate_134263_Content_7 = {
    Text = "Ich habe dir schon lange gesagt, dass sich deine Investition nicht als Verschwendung erweisen würde. Mein Blut lügt nicht."
  },
  AvgCommunicate_134263_Content_8 = {Text = "Ich weiß."},
  AvgCommunicate_134263_Content_9 = {
    Text = "...Das ist alles?"
  },
  AvgCommunicate_134264_Content_1 = {
    Text = "Bitte verzeiht mir, bleicher Bote. Ich war darauf nicht vorbereitet und habe Euch wohl erschreckt."
  },
  AvgCommunicate_134264_Content_10 = {
    Text = "Allein der Gedanke daran erfüllt mein Herz mit einem Frieden, der jedes körperliche Leid bei Weitem übersteigt."
  },
  AvgCommunicate_134264_Content_11 = {
    Text = "Ich verstehe. Vielleicht hege ich keine so erhabenen Gedanken. Aber selbst wenn es nur für dich ist, für meine Freunde –"
  },
  AvgCommunicate_134264_Content_12 = {
    Text = "Solange wir jene ideale, friedvolle Welt erreichen können, werde ich alles in meiner Macht Stehende tun, ganz gleich, was es erfordert."
  },
  AvgCommunicate_134264_Content_13 = {
    Text = "Ich danke dir, blasser Gesandter."
  },
  AvgCommunicate_134264_Content_14 = {
    Text = "Möge alles Leid eines Tages ein Ende finden, und mögen wir stets Seite an Seite voranschreiten."
  },
  AvgCommunicate_134264_Content_15 = {
    Text = "Möge der Segen des Vatergottes auch auf all das herabkommen, was dir teuer ist."
  },
  AvgCommunicate_134264_Content_2 = {
    Text = "Puh ... Gut, dass es dir gut geht. Ich hätte nicht erwartet, dass die Erkenntnis des Gesetzes solche Auswirkungen hat."
  },
  AvgCommunicate_134264_Content_3 = {
    Text = "Du brauchst dir keine Sorgen um mich zu machen. Das ist die Bestimmung, mit der ich auf diese Welt gekommen bin."
  },
  AvgCommunicate_134264_Content_4 = {
    Text = "Noch bevor ich den Gipfel erreichte und der Vatergott mir diese unergründlichen Mysterien offenbarte, hatte ich mich bereits diesem Pfad verschrieben."
  },
  AvgCommunicate_134264_Content_5 = {
    Text = "Das Leid aller Lebewesen in mir zu vereinen und sie in ein makelloses Reines Land zu führen, in dem kein Leid mehr existiert — das ist keine Last. Es ist die Gnade, die der Vatergott mir geschenkt hat."
  },
  AvgCommunicate_134264_Content_6 = {
    Text = "Ich hatte immer das Gefühl, dass du viel zu viel auf dich nimmst. Das Leid der anderen wird gelindert, aber der Preis dafür ..."
  },
  AvgCommunicate_134264_Content_7 = {
    Text = "Mein blasses Feuer, du besitzt ein weiches Herz."
  },
  AvgCommunicate_134264_Content_8 = {
    Text = "Doch sei unbesorgt. Körperliches Leid ist für mich wie Dornen für die Erde – je tiefer sie eindringen, desto fester schlage ich Wurzeln."
  },
  AvgCommunicate_134264_Content_9 = {
    Text = "Solange noch ein einziger Mensch in dieser Welt leidet, soll er nicht allein sein. Solange noch einer das Meer des Leids nicht überwunden hat, werde ich nicht vor ihm das andere Ufer erreichen."
  },
  AvgCommunicate_134264_Option_11 = {
    Text = "Ich verstehe"
  },
  AvgCommunicate_134264_Option_6 = {Text = "Aber ..."},
  AvgCommunicate_134265_Content_1 = {
    Text = "Haha, berauschend, absolut berauschend!"
  },
  AvgCommunicate_134265_Content_10 = {
    Text = "Frag irgendeinen meiner Untergebenen – die kennen mich seit Jahren. Wann haben die mich jemals so etwas tun sehen!"
  },
  AvgCommunicate_134265_Content_11 = {
    Text = "Ah, jetzt ist meine Stärke sogar noch intensiver. Nächstes Mal muss ich aufpassen, dass ich dich nicht verbrenne."
  },
  AvgCommunicate_134265_Content_12 = {
    Text = "Was... du warst das? Dann, die Male, als meine Kleidung gewechselt wurde... warst das auch du?"
  },
  AvgCommunicate_134265_Content_13 = {
    Text = "Ja, deine Klamotten waren ganz dreckig von Alkohol und Essen. Ich konnte dich doch nicht einfach so ins Bett kriechen lassen."
  },
  AvgCommunicate_134265_Content_14 = {
    Text = "Danke, Katyusha."
  },
  AvgCommunicate_134265_Content_15 = {
    Text = "Aber könntest du mich nächstes Mal einfach wachrütteln..."
  },
  AvgCommunicate_134265_Content_16 = {
    Text = "Oh, wirst du schüchtern? Mach dir nichts draus – schau doch, wie eng wir befreundet sind."
  },
  AvgCommunicate_134265_Content_17 = {
    Text = "Vergiss so eine Kleinigkeit wie Kleidung wechseln – selbst wenn du mich bräuchtest, um durchs Feuer zu gehen und jeder Gefahr zu trotzen, wäre das überhaupt kein Problem!"
  },
  AvgCommunicate_134265_Content_18 = {
    Text = "Wenn es dich wirklich stört, hilf mir einfach nächstes Mal beim Umziehen, und dann sind wir quitt."
  },
  AvgCommunicate_134265_Content_19 = {
    Text = "...Nichts davon ergibt Sinn, und genau deshalb habe ich keine Ahnung, wie ich darauf antworten soll!"
  },
  AvgCommunicate_134265_Content_2 = {
    Text = "Ein so noch nie dagewesenes Gefühl der Hochstimmung — gerade jetzt bin ich die Sonne!"
  },
  AvgCommunicate_134265_Content_3 = {
    Text = "Kleine, ich bin wirklich immer mehr beeindruckt von dir."
  },
  AvgCommunicate_134265_Content_4 = {
    Text = "Siehst du? Da kommt noch einiges mehr."
  },
  AvgCommunicate_134265_Content_5 = {
    Text = "Oh? Es scheint, als hätten wir dich die ganze Zeit wie eine Kleine behandelt. Das passt wirklich nicht mehr so ganz."
  },
  AvgCommunicate_134265_Content_6 = {
    Text = "Hmm... Von jetzt an sollten wir dich wohl besser die Große nennen."
  },
  AvgCommunicate_134265_Content_7 = {
    Text = "Was soll denn ‚die Große' heißen!? Du veralberst mich wieder mit diesem ernsten Gesicht, oder?"
  },
  AvgCommunicate_134265_Content_8 = {
    Text = "Hahaha, ich kann nicht anders. Schließlich bist du jedes Mal, wenn wir trinken gehen, immer die Erste, die umkippt."
  },
  AvgCommunicate_134265_Content_9 = {
    Text = "Also blieb mir jedes Mal nichts anderes übrig, als dich zurück ins Quartier zu tragen, dir die Schuhe auszuziehen, dich zuzudecken und dir das Gesicht abzuwischen."
  },
  AvgCommunicate_134265_Option_12 = {
    Text = "Du warst das?"
  },
  AvgCommunicate_134265_Option_7 = {Text = "?!"},
  AvgCommunicate_134267_Content_1 = {
    Text = "%player%, meine Musik ist noch perfekter geworden."
  },
  AvgCommunicate_134267_Content_10 = {
    Text = "Meine Musik war wie eine präzise laufende Maschine, und sie machte mich einst zum Teil des feinsten Orchesters. Natürlich war ich stolz darauf."
  },
  AvgCommunicate_134267_Content_11 = {
    Text = "Er war anders. Er war nicht für das Ensemble geeignet. Seine Musik war dazu bestimmt, allein am Himmel zu leuchten, wie die Sonne oder der Mond."
  },
  AvgCommunicate_134267_Content_12 = {
    Text = "Ich habe ihn immer beobachtet, bin ihm nachgejagt, aber ich habe für immer die Chance verloren, Worte mit ihm zu wechseln."
  },
  AvgCommunicate_134267_Content_13 = {
    Text = "Aber... diese Darbietung, die nun ultimative Perfektion erreicht hat, ist wohl die beste Antwort, die ich nach einem Leben voller Streben präsentieren kann."
  },
  AvgCommunicate_134267_Content_14 = {
    Text = "Das ist so rührend... Wie kannst du nur so eine Vergangenheit haben? Eine legendäre Geschichte von Musikern, die in ihrer Blütezeit gegenseitig ihre Brillanz widerspiegeln..."
  },
  AvgCommunicate_134267_Content_15 = {
    Text = "Mm, nur ein paar ganz gewöhnliche Überlegungen. Es ist wirklich nicht so dramatisch, wie es klingt."
  },
  AvgCommunicate_134267_Content_16 = {
    Text = "Wie dem auch sei, was ich am meisten sagen möchte, ist: Danke, %player%."
  },
  AvgCommunicate_134267_Content_17 = {
    Text = "Bitte lass mich von nun an weiterhin meine Flöte für dich spielen und dich jede Nacht in einen friedlichen Schlummer begleiten."
  },
  AvgCommunicate_134267_Content_2 = {
    Text = "Ohne deine Anleitung hätte ich diesen letzten Schritt wohl nie überwinden können — die winzigen Fehler zu kalibrieren, die einst jenseits menschlicher Korrekturmöglichkeiten lagen."
  },
  AvgCommunicate_134267_Content_3 = {
    Text = "Perfektes Tempo, makellose Tonhöhe, alles klingt so erlesen..."
  },
  AvgCommunicate_134267_Content_4 = {
    Text = "In der Tat! Ich habe noch nie eine so wunderbare Darbietung gehört!"
  },
  AvgCommunicate_134267_Content_5 = {
    Text = "Dies ist das Ergebnis der Resonanz zwischen Musik und Berechnung, Instrument und Körper, Gehirn und Muskel."
  },
  AvgCommunicate_134267_Content_6 = {
    Text = "Ich habe endlich bewiesen, dass am Ende dieses trockenen und mühsamen Wegs auch solch perfekte Musik existieren kann."
  },
  AvgCommunicate_134267_Content_7 = {
    Text = "Auch? Was meinst du damit?"
  },
  AvgCommunicate_134267_Content_8 = {
    Text = "Früher hatte ich Einen Freund, dessen Musik das Produkt ultimativer Sensibilität und Kreativität war."
  },
  AvgCommunicate_134267_Content_9 = {
    Text = "Das Talent, das er so mühelos einsetzte, erlaubte es ihm, bei jeder Aufführung einzigartige Kompositionen zu improvisieren."
  },
  AvgCommunicate_134267_Option_14 = {Text = "Waaah..."},
  AvgCommunicate_134267_Option_4 = {Text = "In der Tat"},
  AvgCommunicate_134267_Option_7 = {Text = "Außerdem?"},
  AvgCommunicate_134268_Content_1 = {
    Text = "Mein hochverehrter Gast, wie kann ich Euch jemals für Eure Großzügigkeit danken?"
  },
  AvgCommunicate_134268_Content_10 = {
    Text = "Ich verstehe, ich verstehe. Ihr wollt nicht diese vulgären Feierlichkeiten — auch ich glaube, sie passen nicht zu Euch."
  },
  AvgCommunicate_134268_Content_11 = {
    Text = "Es gibt noch eine recht feine Idee. Vielleicht wärt Ihr bereit, mich außerhalb von Nekropolis zu begleiten, um jemanden zu empfangen, der sich seinem Ende nähert?"
  },
  AvgCommunicate_134268_Content_12 = {
    Text = "Sollte uns eine solche Ehre zuteilwerden, hoffe ich, dass Ihr Euch mir anschließt, um sie zu empfangen, sie zu ihrem letzten Bestimmungsort und zur Neugeboren genesen zu geleiten. Was sagt Ihr?"
  },
  AvgCommunicate_134268_Content_13 = {
    Text = "Auch wenn es vielleicht etwas unangemessen ist zu fragen... Ich vermute, es wird am Ende dennoch Verzehr beinhalten, da das der Brauch von Nekropolis ist."
  },
  AvgCommunicate_134268_Content_14 = {
    Text = "Mm, ich würde es nicht als Verzehr bezeichnen — Einfach wie bei den Geschichten, die Ihr bereits kennt."
  },
  AvgCommunicate_134268_Content_15 = {
    Text = "Es ist Nur der feierlichste und zugleich friedvollste Abschied."
  },
  AvgCommunicate_134268_Content_16 = {
    Text = "Ich würde gerne teilnehmen, Solange ich bestimmte Teile auslassen darf..."
  },
  AvgCommunicate_134268_Content_17 = {
    Text = "Natürlich, natürlich."
  },
  AvgCommunicate_134268_Content_18 = {
    Text = "Dann werden die Kutsche von Nekropolis und ich morgen früh vor der Tür auf Eure Ankunft warten."
  },
  AvgCommunicate_134268_Content_2 = {
    Text = "Euer Geschenk hat mir die Stärke verliehen, Nekropolis wahrhaft und standhaft zu beschützen."
  },
  AvgCommunicate_134268_Content_3 = {
    Text = "Gewöhnliche Küche ist Eurer Darbietung unwürdig, und meine persönliche Sammlung dürfte Eurem Gaumen wohl nicht ganz zusagen."
  },
  AvgCommunicate_134268_Content_4 = {
    Text = "Was für ein wonnig quälendes Dilemma."
  },
  AvgCommunicate_134268_Content_5 = {
    Text = "Ihr seid zu gütig, Doresain."
  },
  AvgCommunicate_134268_Content_6 = {
    Text = "Wir haben so viel zusammen durchgemacht. Ihr müsst Euch wirklich nicht mit all diesen lästigen Förmlichkeiten abmühen."
  },
  AvgCommunicate_134268_Content_7 = {
    Text = "Oh nein, nein, das ist keineswegs eine bloße Förmlichkeit. Ich überlege ernsthaft, wie ich ein Zusammentreffen mit einem lieben Freund gestalten kann."
  },
  AvgCommunicate_134268_Content_8 = {
    Text = "Ihr habt bereits den außergewöhnlichsten Tanz von Nekropolis miterlebt. Wie man die Bande zwischen Euch und uns weiter vertiefen kann — das ist in der Tat eine Herausforderung."
  },
  AvgCommunicate_134268_Content_9 = {
    Text = "Ähm... Wenn Ihr meine Vorliebe wissen wollt, so hoffe ich bescheiden, dass es etwas Gewöhnliches sein könnte, ohne irgendwelche Schrecken..."
  },
  AvgCommunicate_134268_Option_13 = {
    Text = "Ich vermute"
  },
  AvgCommunicate_134268_Option_9 = {Text = "Ähm"},
  AvgCommunicate_134269_Content_1 = {
    Text = "Mein kleiner Setzling..."
  },
  AvgCommunicate_134269_Content_10 = {
    Text = "In meinem Körper erwacht nach der letzten Berührung eine Kraft, die der „Fortpflanzung“ gehört."
  },
  AvgCommunicate_134269_Content_11 = {
    Text = "So süß, so üppig... Ah, es genügt mir nicht mehr, durch diesen kleinen Metallblock mit dir zu sprechen."
  },
  AvgCommunicate_134269_Content_12 = {Text = "Thais?"},
  AvgCommunicate_134269_Content_13 = {
    Text = "Komm zu mir, kleiner Setzling, jetzt, sofort."
  },
  AvgCommunicate_134269_Content_14 = {
    Text = "Ich möchte deine warmen Hände halten, deine weiche Haut berühren..."
  },
  AvgCommunicate_134269_Content_15 = {
    Text = "Ich möchte dich im Mondlicht umarmen, so wie in jener Nacht, als wir unser Versprechen gaben."
  },
  AvgCommunicate_134269_Content_16 = {
    Text = "Mit meiner nun noch reicheren Kraft möchte ich Stück für Stück mit dir verschmelzen, und deinen süßen Atem mich Stück für Stück erwärmen lassen..."
  },
  AvgCommunicate_134269_Content_2 = {
    Text = "Was du mir versprochen hast—in jener Nacht inmitten des Mondlichts und des Sandmeeres—unser Pakt... du erfüllst ihn bereits für mich."
  },
  AvgCommunicate_134269_Content_3 = {
    Text = "Ich bin so glücklich."
  },
  AvgCommunicate_134269_Content_4 = {
    Text = "Auch wenn eine Welt, in der alle in Frieden leben können, noch weit entfernt ist, werde ich weiter danach streben."
  },
  AvgCommunicate_134269_Content_5 = {
    Text = "Von dem Moment an, als wir uns zum ersten Mal trafen, habe ich an dich geglaubt."
  },
  AvgCommunicate_134269_Content_6 = {
    Text = "Du bist jemand, der vom Schicksal gesegnet ist. Du hast die Stärke, und du hast die Entschlossenheit."
  },
  AvgCommunicate_134269_Content_7 = {
    Text = "Mein kleiner Setzling, du bist einfach zu bezaubernd, wenn du so entschlossen gegen die Welt ankämpfst."
  },
  AvgCommunicate_134269_Content_8 = {
    Text = "Ich werde geduldig und aufrichtig warten – auf den Tag, an dem unser Versprechen in Erfüllung geht."
  },
  AvgCommunicate_134269_Content_9 = {
    Text = "Sicherlich!"
  },
  AvgCommunicate_134269_Option_12 = {Text = "Thais?"},
  AvgCommunicate_134269_Option_4 = {
    Text = "Ich werde weiter hart arbeiten."
  },
  AvgCommunicate_134269_Option_9 = {
    Text = "Sicherlich!"
  },
  AvgCommunicate_134270_Content_1 = {
    Text = "Ich werde dich nicht töten."
  },
  AvgCommunicate_134270_Content_10 = {
    Text = "Nachdem ich dich ausgesaugt habe, bringe ich dann einfach alle um."
  },
  AvgCommunicate_134270_Content_11 = {
    Text = "Dann werde ich ... versuchen, möglichst lange am Leben zu bleiben?"
  },
  AvgCommunicate_134270_Content_12 = {
    Text = "Hahaha, eine interessante Antwort."
  },
  AvgCommunicate_134270_Content_13 = {
    Text = "Da du also vorhast, mit diesem schwachen Körper die ganze Welt zu beschützen ..."
  },
  AvgCommunicate_134270_Content_14 = {Text = "Dann ..."},
  AvgCommunicate_134270_Content_15 = {
    Text = "... Und dann?"
  },
  AvgCommunicate_134270_Content_16 = {
    Text = "Bis dahin werde ich nur deine Feinde abschlachten."
  },
  AvgCommunicate_134270_Content_17 = {
    Text = "Am Ende wird also doch getötet ...?!"
  },
  AvgCommunicate_134270_Content_2 = {
    Text = "......? Hä? Was soll ich sagen? Danke?"
  },
  AvgCommunicate_134270_Content_3 = {
    Text = "Diese Welt ist nach dem Untergang Roms unerträglich langweilig geworden."
  },
  AvgCommunicate_134270_Content_4 = {
    Text = "Töten, Töten, Töten, nichts als pures Gemetzel und Blut. Ohne Rom ist nichts mehr übrig."
  },
  AvgCommunicate_134270_Content_5 = {
    Text = "Dein Geschenk hat mich von diesen Fesseln befreit. Jetzt werde ich ein oder zwei Arme oder Kehlen zerreißen."
  },
  AvgCommunicate_134270_Content_6 = {
    Text = "Leider, Yuuhashi, ist es in der heutigen Zeit ohne Sondergenehmigung illegal, einfach so Menschen zu töten."
  },
  AvgCommunicate_134270_Content_7 = {
    Text = "Und ich bin immer noch dein Verbundener — nicht nur mich darfst du nicht töten, auch keine anderen."
  },
  AvgCommunicate_134270_Content_8 = {Text = "Tch."},
  AvgCommunicate_134270_Content_9 = {
    Text = "Na gut, zumindest schmeckst du besser als all die Sklavenhalter."
  },
  AvgCommunicate_134271_Content_1 = {
    Text = "Hü~ter～ Bist du beschäftigt? Es gibt noch etwas, das ich dir sagen möchte～"
  },
  AvgCommunicate_134271_Content_10 = {Text = "Leer?"},
  AvgCommunicate_134271_Content_11 = {
    Text = "Ja～ dieses dunkle, kalte Gefühl, das Gefühl, von Allen verlassen zu sein, das jedes Mal hervorströmt, wenn der Wind hindurchweht."
  },
  AvgCommunicate_134271_Content_12 = {
    Text = "Aber jetzt ist alles warm～ und hell～"
  },
  AvgCommunicate_134271_Content_13 = {
    Text = "Das ist alles wegen %player%."
  },
  AvgCommunicate_134271_Content_14 = {
    Text = "Also ist das wirklich ein aufrichtiges Dankeschön?"
  },
  AvgCommunicate_134271_Content_15 = {
    Text = "Hmph～ Natürlich, ich kann auch mal ernst sein, weißt du!"
  },
  AvgCommunicate_134271_Content_16 = {
    Text = "Aber im Gegenzug — musst du ab jetzt mehr Zeit mit mir verbringen, okay?"
  },
  AvgCommunicate_134271_Content_17 = {
    Text = "Sonst werde ich meine neu erlernten Fähigkeiten nutzen, um dich ordentlich zu be~stra~fen～"
  },
  AvgCommunicate_134271_Content_18 = {
    Text = "...Ist das wirklich deine Art, Danke zu sagen?!"
  },
  AvgCommunicate_134271_Content_19 = {
    Text = "Oh je, das ist Pandias exklusive Art, Zuneigung auszudrücken～ Mwah～ Vergiss nicht, dankbar zu sein!"
  },
  AvgCommunicate_134271_Content_2 = {
    Text = "Was heckst du jetzt schon wieder aus?"
  },
  AvgCommunicate_134271_Content_3 = {
    Text = "Wie kannst du so etwas sagen! Ich bin hier, um mich aufrichtig bei dir zu bedanken!"
  },
  AvgCommunicate_134271_Content_4 = {
    Text = "Die schönen Sachen, die du mir vorher gegeben hast... sie haben meinen Körper so heiß gemacht, so heiß～"
  },
  AvgCommunicate_134271_Content_5 = {
    Text = "Es ist, als würde etwas Glühendes unter meiner Haut fließen, süß und scharf～"
  },
  AvgCommunicate_134271_Content_6 = {
    Text = "Obwohl ich weiß, dass es keine Nebeneffekte geben sollte, bist du sicher, dass das kein Nebeneffekt ist..."
  },
  AvgCommunicate_134271_Content_7 = {
    Text = "Auf keinen Fall! Dieses Gefühl ist fantastisch! Hundertmal aufregender als jede Auspeitschung!"
  },
  AvgCommunicate_134271_Content_8 = {
    Text = "Und weißt du was, das Unglaublichste ist..."
  },
  AvgCommunicate_134271_Content_9 = {
    Text = "Diese leere Stelle innen in meinem Herzen wurde aufgefüllt."
  },
  AvgCommunicate_134271_Option_14 = {Text = "So"},
  AvgCommunicate_134271_Option_6 = {Text = "Obwohl"},
  AvgCommunicate_134272_Content_1 = {
    Text = "Meister～ Wie soll Karen das jemals zurückzahlen? Getränke, Putzen, Kochen — bitte scheue dich nicht, Karen herumzukommandieren!"
  },
  AvgCommunicate_134272_Content_10 = {
    Text = "Wenn Karen es will, kann Karens Haut heller strahlen als der kostbarste Edelstein und schillernder leuchten als die vollkommenste Perle."
  },
  AvgCommunicate_134272_Content_11 = {
    Text = "Wenn Karen jetzt zum Ball ginge, wäre sie garantiert der absolute Mittelpunkt – nie wieder die kleine Unbekannte, die niemand beachtet."
  },
  AvgCommunicate_134272_Content_12 = {
    Text = "Obwohl ich denke, dass das wohl nicht der Hauptzweck der Verstärkung durch das Ultimative Gesetz ist, aber..."
  },
  AvgCommunicate_134272_Content_13 = {
    Text = "Solange es dich glücklich macht, ist es gut."
  },
  AvgCommunicate_134272_Content_2 = {
    Text = "Jedenfalls lasst uns zuerst die Mahlzeiten ausschließen!"
  },
  AvgCommunicate_134272_Content_3 = {
    Text = "Oh je, meine Haushaltsfähigkeiten werden angezweifelt. Eigentlich sollte Karen jetzt traurig sein, aber, aber ..."
  },
  AvgCommunicate_134272_Content_4 = {
    Text = "So viel, so viel Schmuck und Juwelen! Karen fühlt sich wie der strahlendste Edelstein überhaupt – Karen kann wirklich nicht traurig sein!"
  },
  AvgCommunicate_134272_Content_5 = {
    Text = "Beruhige dich erst mal, ich kann dir schon kaum noch folgen."
  },
  AvgCommunicate_134272_Content_6 = {
    Text = "Entschuldigung, Karen ist einfach zu aufgeregt. Nachdem der Meister Karen geholfen hat, dieses ... Dings ... Haarspange? Band oder so etwas zu begreifen ..."
  },
  AvgCommunicate_134272_Content_7 = {
    Text = "... Es war ein Gesetz."
  },
  AvgCommunicate_134272_Content_8 = {
    Text = "Oh ja, genau, dieses sehr teure, sehr wertvolle Ding. Danach hatte Karen das Gefühl, eine unglaublich mächtige Fähigkeit erlangt zu haben."
  },
  AvgCommunicate_134272_Content_9 = {
    Text = "Die Effizienz bei der Hausarbeit hat sich enorm gesteigert, und was noch wichtiger ist – Karens Körper strahlt und glitzert!"
  },
  AvgCommunicate_134272_Option_7 = {
    Text = "Das war keine Haarspange"
  },
  AvgCommunicate_134273_Content_1 = {
    Text = "%player%, meine Verbindung zu dir ist tiefer geworden."
  },
  AvgCommunicate_134273_Content_10 = {
    Text = "Sachen wie Lösungen für Integralrechnung, Fragen aus Allgemeinbildungsprüfungen und so weiter — kann man die auch direkt aus dem unendlichen Wissen beziehen?"
  },
  AvgCommunicate_134273_Content_11 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134273_Content_12 = {
    Text = "In der Tat, du müsstest dir nicht mehr so mühsam so viele Dinge einprägen."
  },
  AvgCommunicate_134273_Content_13 = {
    Text = "Aber ich glaube, die Bedeutung des Lernens liegt im Prozess der Wissenssuche und im Training der Stärke des Denkens."
  },
  AvgCommunicate_134273_Content_14 = {
    Text = "Du musst zuerst wissen, was du nicht weißt und was du wissen solltest, bevor du die Antwort, die du brauchst, aus der endlosen Schatzkammer finden kannst."
  },
  AvgCommunicate_134273_Content_15 = {
    Text = "In Ordnung, ich verstehe. Auch wenn die Antwort anders ist als die von Ramona, ist die Schlussfolgerung letztlich dieselbe."
  },
  AvgCommunicate_134273_Content_16 = {
    Text = "Ich werde lernen, ich werde lernen! Reicht das!"
  },
  AvgCommunicate_134273_Content_17 = {
    Text = "Es freut mich, deinen Lerneifer zu sehen. Mach weiter so. Ich werde, wie immer, an deiner Seite bleiben."
  },
  AvgCommunicate_134273_Content_2 = {
    Text = "Herzlichen Glückwunsch, und danke für deine Hingabe. Nun kann ich mehr Bewusstseinsfragmente sammeln und eine vollständigere Existenz in den Ritzen der Welt verbergen."
  },
  AvgCommunicate_134273_Content_3 = {
    Text = "Du kannst dich jetzt in der Welt manifestieren!?"
  },
  AvgCommunicate_134273_Content_4 = {
    Text = "Bedauerlicherweise kann ich meine Existenz noch immer nicht wahrhaft offenbaren, noch den Schwarzen Teich verlassen."
  },
  AvgCommunicate_134273_Content_5 = {
    Text = "Aber mein Geist, mein Traum, mein Blick auf die unzähligen Welten — all das kann nun vollständiger existieren und dir vollständiger übermittelt werden."
  },
  AvgCommunicate_134273_Content_6 = {
    Text = "Zumindest besitzt du nun den Schlüssel zu unendlichem Wissen."
  },
  AvgCommunicate_134273_Content_7 = {
    Text = "Du meinst, egal was ich frage, ich kann eine Antwort bekommen?"
  },
  AvgCommunicate_134273_Content_8 = {
    Text = "Solange es existiert oder bewiesen werden kann."
  },
  AvgCommunicate_134273_Content_9 = {
    Text = "Hehe, zum Beispiel, rein hypothetisch gesprochen."
  },
  AvgCommunicate_134273_Option_15 = {
    Text = "Ich verstehe"
  },
  AvgCommunicate_134273_Option_7 = {
    Text = "Unendliches Wissen?"
  },
  AvgCommunicate_134274_Content_1 = {
    Text = "Der Samen... ist vollständiger geworden."
  },
  AvgCommunicate_134274_Content_10 = {
    Text = "So lebhafte Szenen sind für mich immer noch viel zu nervenaufreibend."
  },
  AvgCommunicate_134274_Content_11 = {
    Text = "Es ist in Ordnung, ich werde zusammen mit Tinct direkt an deiner Seite sein."
  },
  AvgCommunicate_134274_Content_12 = {
    Text = "Natürlich, wenn du dich allein wohler fühlst, unterstütze ich deine Entscheidung voll und ganz!"
  },
  AvgCommunicate_134274_Content_13 = {
    Text = "Schutzherr... danke. Wenn du und Tinct euch das wünscht."
  },
  AvgCommunicate_134274_Content_14 = {
    Text = "Mm... lass mich damit beginnen, mich an die Ecke in der letzten Reihe des Klassenzimmers zu gewöhnen."
  },
  AvgCommunicate_134274_Content_2 = {
    Text = "Ich kann eine Stärke spüren, die fähig ist, mein Keimen aufrechtzuerhalten, und die allmählich die Leere in meiner Seele füllt."
  },
  AvgCommunicate_134274_Content_3 = {
    Text = "Also... bedeutet das, dass du anderen nicht mehr die Lebenskraft entziehen wirst?"
  },
  AvgCommunicate_134274_Content_4 = {
    Text = "Leider ist diese angeborene Fähigkeit von mir nicht verschwunden."
  },
  AvgCommunicate_134274_Content_5 = {
    Text = "Allerdings beginne ich, Kontrolle über diese Kraft zu erlangen."
  },
  AvgCommunicate_134274_Content_6 = {
    Text = "Solange ich weiter übe, werden Ermittler, die mit mir in Kontakt kommen, diese umständlichen Schutzanzüge nicht mehr tragen müssen."
  },
  AvgCommunicate_134274_Content_7 = {
    Text = "Jetzt besteht die Möglichkeit, dass ich sicher an der Seite aller bleiben kann."
  },
  AvgCommunicate_134274_Content_8 = {
    Text = "Das ist wunderbar! Von nun an kannst du an allen möglichen Schulaktivitäten, Galas und sogar Feiern unter Erweckten Körpern teilnehmen."
  },
  AvgCommunicate_134274_Content_9 = {
    Text = "P-Partys... Ich glaube, die Fähigkeit zu meistern, mit Menschen auszukommen, ist weitaus schwieriger, als die Kontrolle über meine Instinkte zu meistern."
  },
  AvgCommunicate_134274_Option_11 = {
    Text = "Es ist okay"
  },
  AvgCommunicate_134274_Option_3 = {Text = "Also..."},
  AvgCommunicate_134274_Option_8 = {
    Text = "Das ist wunderbar!"
  },
  AvgCommunicate_134275_Content_1 = {
    Text = "Der Prinzessin alle edlen Dinge darzubringen, ist dein Privileg."
  },
  AvgCommunicate_134275_Content_10 = {
    Text = "...Danke? Du hast nicht versucht, mich mit Geschenken für dich zu gewinnen, damit du ein paar aufmunternde Worte von mir hören kannst, oder damit ich irgendeine Erwartung von dir erfülle?"
  },
  AvgCommunicate_134275_Content_11 = {
    Text = "„Murphy,\" ich mache dir Geschenke und behandle dich gut, einfach weil du du bist."
  },
  AvgCommunicate_134275_Content_12 = {
    Text = "Es hat nichts damit zu tun, dass du eine Prinzessin, die Göttliche Mutter oder irgendetwas anderes bist. Du bist meine Freundin. Darüber hinaus habe ich keine weiteren Erwartungen."
  },
  AvgCommunicate_134275_Content_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134275_Content_14 = {
    Text = "Hmph! Das ist... das ist doch nur deine silberzüngige, schmeichlerische Masche! Glaubst du, so etwas bringt mich zum Weinen?"
  },
  AvgCommunicate_134275_Content_15 = {
    Text = "Hab keine Wahnvorstellungen. Freunde? Erfüll einfach deine Pflicht als treuer Anhänger, das reicht völlig."
  },
  AvgCommunicate_134275_Content_16 = {
    Text = "Das ist so verletzend. Ich werde heute Nacht wirklich die ganze Nacht weinen, weißt du?"
  },
  AvgCommunicate_134275_Content_17 = {
    Text = "D-Du... ugh, du nutzloses Ding."
  },
  AvgCommunicate_134275_Content_18 = {
    Text = "Nur dieses eine Mal, also hör gut zu."
  },
  AvgCommunicate_134275_Content_19 = {
    Text = "Vielen Dank."
  },
  AvgCommunicate_134275_Content_2 = {
    Text = "Überhaupt nicht schlecht."
  },
  AvgCommunicate_134275_Content_20 = {
    Text = "Wie dem auch sei, von nun an wird diese Prinzessin mehr als genug Stärke haben, um dich zu beschützen. Also sei dankbar und fahre fort, mich zu verehren!"
  },
  AvgCommunicate_134275_Content_3 = {
    Text = "Hast du sonst nichts zu sagen?"
  },
  AvgCommunicate_134275_Content_4 = {
    Text = "Was, gehörte diese Macht nicht von Anfang an rechtmäßig mir?"
  },
  AvgCommunicate_134275_Content_5 = {
    Text = "Oh, verstehe. Du willst eine Belohnung, einen Segen, eine höhere Position, oder vielleicht eine vornehmere Identität?"
  },
  AvgCommunicate_134275_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134275_Content_7 = {
    Text = "Was soll „...\" bedeuten? Wie lästig. Es gibt noch kein Interesse daran, Ratespiele mit dir zu spielen."
  },
  AvgCommunicate_134275_Content_8 = {
    Text = "Ich gebe dir eine letzte Chance. Sag mir, was du willst, schnell, und hör auf, um den heißen Brei herumzureden."
  },
  AvgCommunicate_134275_Content_9 = {
    Text = "Wäre es möglich, dass, ich meine, du könntest zumindest Danke sagen."
  },
  AvgCommunicate_134275_Option_16 = {
    Text = "Das ist verletzend"
  },
  AvgCommunicate_134275_Option_3 = {
    Text = "Das ist alles?"
  },
  AvgCommunicate_134275_Option_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134275_Option_9 = {
    Text = "Wäre es möglich, dass"
  },
  AvgCommunicate_134276_Content_1 = {
    Text = "Danke, Schutzherr, danke! Ich... ich weiß nicht, wie ich ausdrücken soll..."
  },
  AvgCommunicate_134276_Content_10 = {
    Text = "So in etwa?"
  },
  AvgCommunicate_134276_Content_11 = {
    Text = "Ich habe gehört, dass Farben in einem Gemälde unterschiedliche emotionale und atmosphärische Bedeutungen tragen. Du könntest neue Farben nach deiner eigenen kreativen Vision erschaffen."
  },
  AvgCommunicate_134276_Content_12 = {
    Text = "Oh! Ohh! Völlig neue Farbkombinationen mischen, ganz nach meinem Belieben!"
  },
  AvgCommunicate_134276_Content_13 = {
    Text = "Was für eine geniale Idee! Verschiedene Polarisierungen... verschiedene Texturen... Ich habe schon so viele Ideen!"
  },
  AvgCommunicate_134276_Content_14 = {
    Text = "Entschuldigt mich, Schutzherr!"
  },
  AvgCommunicate_134276_Content_15 = {
    Text = "Ich habe das Gefühl, dass mein nächstes Gemälde noch wundersamere Pinselstriche besitzen wird."
  },
  AvgCommunicate_134276_Content_16 = {
    Text = "Vielleicht kann ich wirklich ein gemaltes Reich erschaffen, das eine Verbindung zum Unbekannten Wesen herstellt. Wenn es so weit ist, wirst du der Erste sein, der es sieht!"
  },
  AvgCommunicate_134276_Content_2 = {
    Text = "Danke, dass du mir die Chance gegeben hast, das wahre Antlitz der Welt zu sehen, die ultimativen Gesetze des Universums, die Grundfarbe auf der Leinwand der Welt..."
  },
  AvgCommunicate_134276_Content_3 = {
    Text = "Ah, es ist so wunderschön... Wie könnte ich jemals solche Farben mischen?"
  },
  AvgCommunicate_134276_Content_4 = {
    Text = "Regenbogenkristalle? Mithril? Perlmutt? Kristallwurmpulver? Leuchtende Schmetterlingsflügel?"
  },
  AvgCommunicate_134276_Content_5 = {
    Text = "Nein, nein, nein... Diese gewöhnlichen, banalen Dinge könnten es niemals nachbilden. Denk nach, ich muss schärfer nachdenken..."
  },
  AvgCommunicate_134276_Content_6 = {
    Text = "Pickman? Es scheint, als hättest du dich bereits in deiner eigenen Kunst verloren..."
  },
  AvgCommunicate_134276_Content_7 = {
    Text = "Shh, was glaubst du, wie die wahren Farben des Universums aussehen? Jemand so Außergewöhnliches wie du muss mir doch einen ganz anderen Einblick gewähren können!"
  },
  AvgCommunicate_134276_Content_8 = {
    Text = "Ich denke, die Welt sieht durch die Augen jedes Menschen anders aus."
  },
  AvgCommunicate_134276_Content_9 = {
    Text = "Oh! Du meinst... ich soll meinem eigenen Herzen folgen... meinen Gefühlen, um die verschiedenen Farben des Universums darzustellen..."
  },
  AvgCommunicate_134276_Option_10 = {Text = "Vielleicht"},
  AvgCommunicate_134276_Option_8 = {Text = "Ich denke"},
  AvgCommunicate_134277_Content_1 = {
    Text = "Schutzherr —"
  },
  AvgCommunicate_134277_Content_10 = {
    Text = "Ich werde dich nicht bemitleiden, ich werde nicht von oben herab deine Handlungslogik unterstellen – ich wünsche mir nur, dass du in dieser Welt Spaß hast."
  },
  AvgCommunicate_134277_Content_11 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134277_Content_12 = {
    Text = "Wow, wer von uns ist eigentlich verrückter? Aus so einem Grund einer Irren wie mir diese Stufe an Macht zu überlassen?"
  },
  AvgCommunicate_134277_Content_13 = {
    Text = "Könnte es sein, dass meine Ankunft in dieser Welt tatsächlich vom Schicksal vorbestimmt war?"
  },
  AvgCommunicate_134277_Content_15 = {
    Text = "Jedenfalls, dank dir habe ich in eurer Welt mein eigenes „Limit\" berührt."
  },
  AvgCommunicate_134277_Content_16 = {
    Text = "Also los, gib mir schnell einen Auftrag! Ich kann es kaum erwarten, ein paar Köpfe abzuschlagen und sie euch zu zeigen～"
  },
  AvgCommunicate_134277_Content_2 = {
    Text = "Ein Mädchen, das in einer fremden Welt gestrandet ist, bekommt ein teures Geschenk, das sie stärker macht – weißt du, woran das erinnert?"
  },
  AvgCommunicate_134277_Content_3 = {
    Text = "Bevor du etwas sagst, das von normalen Denkmustern abweicht, möchte ich klarstellen: Du bist ein Mitglied von Misaga. Wir helfen einander – das ist der Grund, warum ich dir diese Materialien gegeben habe."
  },
  AvgCommunicate_134277_Content_4 = {
    Text = "Ach wirklich? Kein langweiliges, umständliches soziales Fassadenverhalten der menschlichen Gesellschaft?"
  },
  AvgCommunicate_134277_Content_5 = {
    Text = "„Sie kann nicht mehr nach Hause, die Arme, lasst uns ihr etwas mehr Zuneigung schenken.\""
  },
  AvgCommunicate_134277_Content_6 = {
    Text = "„Es ist so anstrengend, alles alleine zu bewältigen, geben wir ihr etwas Unterstützung.\" – Es ist wirklich nicht so ein typischer Grund, wie er in einer gewöhnlichen Gesellschaft ständig vorkommt?"
  },
  AvgCommunicate_134277_Content_7 = {
    Text = "Erstens, egal aus welchem Blickwinkel man es betrachtet, Moxia, du hast wirklich nichts mit dem Wort „gewöhnlich\" zu tun!"
  },
  AvgCommunicate_134277_Content_8 = {
    Text = "Hm☆hm, diese Einschätzung gefällt mir."
  },
  AvgCommunicate_134277_Content_9 = {
    Text = "Zweitens, egal wie du dich selbst siehst oder wie du nach außen wirkst – für mich bist du, wie du selbst sagst, einfach „Moxia„."
  },
  AvgCommunicate_134277_Option_7 = {Text = "Erstens"},
  AvgCommunicate_134278_Content_1 = {
    Text = "Danke, mein Liebling. Du hast mir so viel Glück gebracht und dafür gesorgt, dass ich meinen Ehrgeiz für immer bewahren kann."
  },
  AvgCommunicate_134278_Content_10 = {
    Text = "Welche Form der Dankbarkeit du dir auch wünschst, ich kann sie wahr werden lassen."
  },
  AvgCommunicate_134278_Content_11 = {
    Text = "Selbst wenn ich es noch nicht besitze, selbst wenn es die Sterne und der Mond wären, würde ich einen Weg finden, sie für dich zu beschaffen."
  },
  AvgCommunicate_134278_Content_12 = {
    Text = "Alles, was ich will? Wirklich alles?"
  },
  AvgCommunicate_134278_Content_13 = {
    Text = "Ein gehaltenes Versprechen ist Gold wert — ein unverzichtbarer Pass in der Welt von Ruhm und Reichtum."
  },
  AvgCommunicate_134278_Content_14 = {
    Text = "Dann hätte ich gerne ein Versprechen von Madame. Was die Einzelheiten betrifft, brauche ich noch etwas Zeit, um darüber nachzudenken."
  },
  AvgCommunicate_134278_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134278_Content_16 = {
    Text = "Hahahaha, was für eine gerissene Wahl. Du wirst mir wirklich immer sympathischer."
  },
  AvgCommunicate_134278_Content_17 = {
    Text = "Natürlich, mein Lieber, du hast reichlich Zeit, darüber nachzudenken."
  },
  AvgCommunicate_134278_Content_18 = {
    Text = "Wenn du Zeit hast, warum kommst du nicht heute Abend auf mein Anwesen? Vielleicht fällt dir, wenn wir nur zu zweit sind... leichter eine erfrischend „gute Idee\" ein."
  },
  AvgCommunicate_134278_Content_2 = {
    Text = "Euch zu dienen, Madame, ist mir eine Ehre."
  },
  AvgCommunicate_134278_Content_3 = {
    Text = "Hehe, wohlerzogen, klug, mutig, loyal, und dazu noch ein Hauch von genau der richtigen ... Schönheit."
  },
  AvgCommunicate_134278_Content_4 = {
    Text = "Wer könnte bestreiten, dass du ein perfektes ..."
  },
  AvgCommunicate_134278_Content_5 = {
    Text = "... Ein perfektes was?"
  },
  AvgCommunicate_134278_Content_6 = {
    Text = "Du scheinst ein wenig nervös zu sein?"
  },
  AvgCommunicate_134278_Content_7 = {
    Text = "Madame versteht es immer wieder, einen sprachlos zu machen."
  },
  AvgCommunicate_134278_Content_8 = {
    Text = "Manche Dinge müssen nicht in Worte gefasst werden. Deine Zuneigung all die Zeit über – ich habe sie stets empfangen."
  },
  AvgCommunicate_134278_Content_9 = {
    Text = "Land, Besitz, seltene Schätze, Kunst und die Chance, so viele Stars zu treffen... mit meiner jetzigen Macht ist alles in Reichweite."
  },
  AvgCommunicate_134278_Option_12 = {
    Text = "Wirklich, alles?"
  },
  AvgCommunicate_134278_Option_14 = {
    Text = "Ich möchte ein Versprechen von Madame."
  },
  AvgCommunicate_134278_Option_2 = {
    Text = "Es ist mir eine Ehre"
  },
  AvgCommunicate_134278_Option_5 = {Text = "Perfektes?"},
  AvgCommunicate_134278_Option_7 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_134279_Content_1 = {
    Text = "Schutzherr, bist du noch wach?"
  },
  AvgCommunicate_134279_Content_10 = {
    Text = "Doch alles, was du in mich hineingegeben hast... hat sich zu einem neuen See in mir gesammelt. Einer, der noch weiter ist als jenes Meer."
  },
  AvgCommunicate_134279_Content_11 = {
    Text = "Er sagte mir: Es gibt keinen Grund mehr, Angst zu haben."
  },
  AvgCommunicate_134279_Content_12 = {
    Text = "Ich verstehe, dass sich der Schmerz vielleicht nie vollständig auflösen wird, aber egal wie oft es nötig ist, ich werde dich immer wieder ans Ufer zurückziehen."
  },
  AvgCommunicate_134279_Content_13 = {
    Text = "...Wenn Mama und Papa dich das sagen hören könnten, bin ich sicher, sie würden Frieden finden."
  },
  AvgCommunicate_134279_Content_14 = {
    Text = "Ich denke... vielleicht sind sie irgendwo da draußen in diesem Meer und wachen darüber, wer ich jetzt bin."
  },
  AvgCommunicate_134279_Content_15 = {
    Text = "Von nun an werde ich diese Stärke, die mir gegeben wurde, führen und zur Flut werden, die dich beschützt."
  },
  AvgCommunicate_134279_Content_16 = {
    Text = "Vielleicht... wärst du bereit, mir noch eine kühne Bitte zu gewähren?"
  },
  AvgCommunicate_134279_Content_17 = {
    Text = "Was denn? Solange es in meiner Macht steht, gerne."
  },
  AvgCommunicate_134279_Content_18 = {
    Text = "Wenn das Wetter aufklart, geh bitte mit mir am Meer spazieren."
  },
  AvgCommunicate_134279_Content_19 = {
    Text = "Es gibt noch so vieles, das ich dir erzählen möchte. Nur einen Nachmittag – mehr verlange ich nicht."
  },
  AvgCommunicate_134279_Content_2 = {
    Text = "Falls ich deine Ruhe störe, tut es mir leid..."
  },
  AvgCommunicate_134279_Content_20 = {
    Text = "Natürlich, selbstverständlich."
  },
  AvgCommunicate_134279_Content_3 = {
    Text = "Nein, ich bin noch wach. Was ist los?"
  },
  AvgCommunicate_134279_Content_4 = {
    Text = "Nachdem ich dein Geschenk erhalten hatte, fiel ich in einen tiefen Schlummer und glitt in einen Traum. Ich träumte von jenem Meer von damals und dem Sonnenuntergang vor dem Sanatorium."
  },
  AvgCommunicate_134279_Content_5 = {
    Text = "Aber diesmal... bin ich nicht ins Meer gegangen."
  },
  AvgCommunicate_134279_Content_6 = {
    Text = "Ich stand am Ufer und blickte auf jenes Meer. Es erfüllte mich noch immer mit einem Gefühl von Ning, doch ich hatte kein Verlangen, einen Schritt vorwärts zu tun."
  },
  AvgCommunicate_134279_Content_7 = {
    Text = "Wenn die Vermutung nicht zu anmaßend ist — liegt es daran, dass du diesmal einen Grund hattest zu bleiben?"
  },
  AvgCommunicate_134279_Content_8 = {Text = "Gut."},
  AvgCommunicate_134279_Content_9 = {
    Text = "Ich wurde einst von Schmerz erdrückt. Nichts konnte die Schwere aus meiner Kehle forttragen — nichts außer dem Ozean, der über alle Dinge hinwegspült und sie umarmt."
  },
  AvgCommunicate_134279_Option_12 = {
    Text = "Nymphaea..."
  },
  AvgCommunicate_134279_Option_17 = {Text = "Was?"},
  AvgCommunicate_134279_Option_7 = {Text = "Weil..."},
  AvgCommunicate_134280_Content_1 = {
    Text = "%player%, letzte Nacht hatte ich wieder diesen Traum."
  },
  AvgCommunicate_134280_Content_10 = {
    Text = "Vielleicht war es der Effekt der Letzten Regel."
  },
  AvgCommunicate_134280_Content_11 = {
    Text = "Ja, deshalb möchte ich sagen — im Namen aller „24\"s, danke, %player%."
  },
  AvgCommunicate_134280_Content_12 = {
    Text = "Danke, dass du uns einander hören, sehen, verstehen und akzeptieren lässt."
  },
  AvgCommunicate_134280_Content_13 = {
    Text = "Das war nicht mein Verdienst."
  },
  AvgCommunicate_134280_Content_14 = {
    Text = "Nein, die Führung und der Trost, die du gegeben hast, haben jeden unruhigen Geist beruhigt."
  },
  AvgCommunicate_134280_Content_15 = {
    Text = "Es ist deine Gegenwart, die alle Flüsse dazu gebracht hat, in einen zusammenzufließen."
  },
  AvgCommunicate_134280_Content_16 = {
    Text = "„Ich\" — wir alle — werden deine Güte niemals vergessen."
  },
  AvgCommunicate_134280_Content_2 = {
    Text = "Ich schien zum Fuß der Schneeberge im hohen Norden zurückgekehrt zu sein, in eine pechschwarze Höhle."
  },
  AvgCommunicate_134280_Content_3 = {
    Text = "Unzählige Massen von Schleim, die unzählige Schatten von „24\" widerspiegelten..."
  },
  AvgCommunicate_134280_Content_4 = {
    Text = "Sie... sind alle du, alle ein Teil von dir."
  },
  AvgCommunicate_134280_Content_5 = {Text = "Ich weiß."},
  AvgCommunicate_134280_Content_6 = {
    Text = "Inmitten des Chaos schien ich jemanden etwas zu mir sagen zu hören."
  },
  AvgCommunicate_134280_Content_7 = {
    Text = "Die Stimme war verschwommen, ich konnte sie nicht ausmachen..."
  },
  AvgCommunicate_134280_Content_8 = {
    Text = "Aber nachdem diese Person gegangen war, spürte ich, wie sich der ganze Lärm um mich herum in Ruhe legte."
  },
  AvgCommunicate_134280_Content_9 = {
    Text = "Das Stimmengewirr in meinen Ohren wurde harmonisch und natürlich, als ob eine Melodie in vollkommenem Einklang..."
  },
  AvgCommunicate_134280_Option_4 = {
    Text = "Sie sind alle du."
  },
  AvgCommunicate_134281_Content_1 = {
    Text = "Schutzherr, glaubst du an das Schicksal?"
  },
  AvgCommunicate_134281_Content_10 = {
    Text = "...Als gewöhnlicher Mensch kann ich mir kaum vorstellen, wie großartig das sein muss. Erlaube mir, mit zusammengebissenen Zähnen zu fragen — wie genau fühlt sich das an?"
  },
  AvgCommunicate_134281_Content_11 = {
    Text = "Wie soll ich es beschreiben? Zum Beispiel habe ich gerade ein wenig Hunger..."
  },
  AvgCommunicate_134281_Content_12 = {
    Text = "? Und dann?"
  },
  AvgCommunicate_134281_Content_13 = {
    Text = "Oh, Entschuldigung fürs Warten. Es hat Einfach jemand an die Tür geklopft — es war Fräulein Mason, die frisch gebackenen Rührkuchen vorbeibrachte."
  },
  AvgCommunicate_134281_Content_14 = {Text = "Was???"},
  AvgCommunicate_134281_Content_15 = {
    Text = "Einfach so. Und dann... Ich habe ein bisschen Durst."
  },
  AvgCommunicate_134281_Content_16 = {
    Text = "Hm? Der Hausdiener von Herrn Doresain hat gerade eine Einladung geschickt. Er sagt, er möchte mich einladen, seine Rotwein-Sammlung in einem nahegelegenen Restaurant zu Verkosten."
  },
  AvgCommunicate_134281_Content_17 = {
    Text = "...Genug. Könntest du beim nächsten Mal aufrichtig Lust haben, mir bei meinen Hausaufgaben zu helfen?"
  },
  AvgCommunicate_134281_Content_18 = {
    Text = "Hahaha, wie Ihr wünscht, %player%. Ihr seid nun mein größter Mäzen, Sponsor, Partner und unverzichtbarer {Male=Mr.,Female=Miss} Watson."
  },
  AvgCommunicate_134281_Content_19 = {
    Text = "Glücksdetektiv, ganz zu Ihren Diensten."
  },
  AvgCommunicate_134281_Content_2 = {
    Text = "Ich glaube an das Schicksal, und ich glaube, ich besitze das glücklichste Schicksal von allen."
  },
  AvgCommunicate_134281_Content_3 = {
    Text = "Unerwartete Glücksfälle, überraschende Reichtümer, Segen, der vom Himmel fällt — wenn mir solche Dinge passieren, zucke ich nicht einmal mehr mit der Wimper."
  },
  AvgCommunicate_134281_Content_4 = {
    Text = "Wenn man sich erst einmal an die Gunst des Schicksals gewöhnt hat, werden all diese wunderbaren Überraschungen ziemlich unspektakulär."
  },
  AvgCommunicate_134281_Content_5 = {
    Text = "Diese Aussage von dir ist wirklich gleichermaßen beneidenswert und ärgerlich."
  },
  AvgCommunicate_134281_Content_6 = {
    Text = "Warte, ich bin noch nicht fertig. Dich zu treffen ist das Glücklichste unter all meinem Glück."
  },
  AvgCommunicate_134281_Content_7 = {
    Text = "Was du mir gibst, bringt immer neue Überraschungen."
  },
  AvgCommunicate_134281_Content_8 = {
    Text = "Einfach wie jetzt — die Stärke, die nach dem Begreifen der Letzten Regel Erschienen ist, lässt mich bereits jeden Glücksmoment deutlich spüren, bevor er eintrifft."
  },
  AvgCommunicate_134281_Content_9 = {
    Text = "Glückliche Ereignisse fallen wie Regentropfen, von einem sanften Nieseln bis zu einem Platschen — in Strömen herabprasselnd."
  },
  AvgCommunicate_134281_Option_10 = {
    Text = "Wie fühlt sich das an?"
  },
  AvgCommunicate_134281_Option_14 = {Text = "???"},
  AvgCommunicate_134281_Option_5 = {
    Text = "Das ist beneidenswert und ärgerlich"
  },
  AvgCommunicate_137645_Content_1 = {Text = "Keeper."},
  AvgCommunicate_137645_Content_10 = {
    Text = "Aber mit so vielen Beinen ist es doch ein bisschen unfair, an einem Wettlauf teilzunehmen..."
  },
  AvgCommunicate_137645_Content_11 = {
    Text = "Castor hat Flügel, und Nautila hat auch Ihr Fahrzeug mitgebracht."
  },
  AvgCommunicate_137645_Content_12 = {
    Text = "Ich webe normalerweise im Theater und bin nicht gut im Sport. Allerdings habe ich bereits meine Zofe angemeldet."
  },
  AvgCommunicate_137645_Content_13 = {
    Text = "Es ist schwer vorstellbar, warum dich so etwas interessieren würde?"
  },
  AvgCommunicate_137645_Content_14 = {
    Text = "Zuzusehen, wie Menschen ihren Willen und ihre Lebenskraft für ein gemeinsames Ziel entblößen – darin liegt eine stille Freude."
  },
  AvgCommunicate_137645_Content_15 = {
    Text = "Und... ich gebe zu, ich bin neugierig, welche Magie dieser Kuchen als Preis in sich trägt. Selbst Tawil scheint davon angetan zu sein."
  },
  AvgCommunicate_137645_Content_16 = {
    Text = "Solange es nicht wieder eine dieser Situationen ist, in der jemand wählen muss, welche Welt vernichtet wird, bin ich dabei..."
  },
  AvgCommunicate_137645_Content_17 = {
    Text = "...Du manipulierst die Ergebnisse nicht mit Schicksalsfäden, oder?"
  },
  AvgCommunicate_137645_Content_18 = {
    Text = "...Arachne?"
  },
  AvgCommunicate_137645_Content_2 = {
    Text = "Was ist los?"
  },
  AvgCommunicate_137645_Content_20 = {
    Text = "Bis gleich auf den Tribünen, Hüter."
  },
  AvgCommunicate_137645_Content_3 = {
    Text = "Glaubst du... welche Art von Schicksal kann wirklich als gerecht und richtig bezeichnet werden?"
  },
  AvgCommunicate_137645_Content_4 = {
    Text = "Gerecht und richtig?... Wahrscheinlich die Interessen der Mehrheit so weit wie möglich zu schützen."
  },
  AvgCommunicate_137645_Content_5 = {
    Text = "Was aber, wenn — die Interessen der Wenigen dazu bestimmt sind, geopfert zu werden? Du billigst eine solche Richtung des Schicksals, ja?"
  },
  AvgCommunicate_137645_Content_6 = {
    Text = "Du... warum fragst du das plötzlich? Versteh mich nicht falsch!"
  },
  AvgCommunicate_137645_Content_7 = {
    Text = "Wenn du vorhast, wieder irgendeine Welt zu zerstören, dann überleg es dir bitte noch einmal, Arachne!"
  },
  AvgCommunicate_137645_Content_8 = {
    Text = "Kein Grund zur Sorge, Schutzherr. Es ist Einfach ein Wettlauf."
  },
  AvgCommunicate_137645_Content_9 = {
    Text = "Puh... du hast mir einen Schrecken eingejagt..."
  },
  AvgCommunicate_137645_Option_2 = {
    Text = "Was ist los?"
  },
  AvgCommunicate_137646_Content_1 = {
    Text = "Hüter, ich habe gehört, du brichst zu einer Untersuchung auf. Ich habe etwas für dich geschrieben."
  },
  AvgCommunicate_137646_Content_10 = {
    Text = "Dein Gespür für Titel ist wirklich einzigartig, Arachne..."
  },
  AvgCommunicate_137646_Content_11 = {
    Text = "Jeder gesponnene Faden hat seinen bestimmten Besitzer. Jede geschriebene Geschichte hat ihren bestimmten Leser."
  },
  AvgCommunicate_137646_Content_12 = {
    Text = "Ein Name, der leicht reist, kann eine würdige Geschichte zu denen tragen, für die sie schon immer bestimmt war."
  },
  AvgCommunicate_137646_Content_13 = {
    Text = "Nehmen wir zum Beispiel den Bestseller-Titel..."
  },
  AvgCommunicate_137646_Content_14 = {
    Text = "<Italic:Die Freude am Kochen: Seefahrer-Edition>? Das ist der Bestseller?"
  },
  AvgCommunicate_137646_Content_15 = {
    Text = "Bitte sag mir, dass Doresain nicht massenweise Exemplare für ganz Nekropolis bestellt hat..."
  },
  AvgCommunicate_137646_Content_16 = {
    Text = "Weiß Tulu davon?"
  },
  AvgCommunicate_137646_Content_18 = {
    Text = "Genau diese scharfe Einsicht in das menschliche Herz und das Schicksal ist es, die mir wahrhaft Bewunderung für Euch einflößt."
  },
  AvgCommunicate_137646_Content_19 = {
    Text = "„Alle lieben den Schutzherr\"."
  },
  AvgCommunicate_137646_Content_2 = {
    Text = "Ich hatte erwogen, ein Theaterstück zu inszenieren, aber da du auf Reisen sein wirst, schien ein Roman praktischer."
  },
  AvgCommunicate_137646_Content_20 = {
    Text = "Bitte nehmt dieses Werk mit auf Euren Aufbruch."
  },
  AvgCommunicate_137646_Content_3 = {Text = "Das ist..."},
  AvgCommunicate_137646_Content_4 = {
    Text = "<Italic:Der große Hüter>? <Italic:Hüter Crusoe>? <Italic:Projekt Notfall Misaq>?"
  },
  AvgCommunicate_137646_Content_5 = {
    Text = "Was schreibst du überhaupt? Lesen die Leute so etwas wirklich??"
  },
  AvgCommunicate_137646_Content_6 = {
    Text = "Unterschätze nicht deine Beliebtheit in Misaq. Das sind alles äußerst gut aufgenommene Werke."
  },
  AvgCommunicate_137646_Content_7 = {
    Text = "Ein so dramatisches Schicksal verdient es, von der Welt gesehen zu werden."
  },
  AvgCommunicate_137646_Content_8 = {
    Text = "Und es bist nicht nur du. Ich habe auch um das Schicksal anderer Geschichten gewoben."
  },
  AvgCommunicate_137646_Content_9 = {
    Text = "<Italic:Kampf-Abitur: 5 Jahre Übungsaufgaben>... <Italic:Nachgeburtliche Pflege von Mäusen>... <Italic:Fifty Shades of Wachs>..."
  },
  AvgCommunicate_137646_Option_3 = {Text = "Das ist..."},
  AvgCommunicate_137647_Content_1 = {
    Text = "Menschen aus verschiedenen Zeiten und Räumen mit unsichtbaren Fäden verbinden..."
  },
  AvgCommunicate_137647_Content_10 = {
    Text = "Ich freue mich darauf, Schutzherr."
  },
  AvgCommunicate_137647_Content_2 = {
    Text = "Die menschliche Zivilisation überrascht mich immer wieder."
  },
  AvgCommunicate_137647_Content_3 = {
    Text = "Überrascht?"
  },
  AvgCommunicate_137647_Content_4 = {
    Text = "Aber sind diese Schicksale nicht von deiner eigenen Hand gewählt?"
  },
  AvgCommunicate_137647_Content_5 = {
    Text = "Was ich wähle, ist Nur die Richtung. Zack die Zivilisation und Geschichte wird noch immer von euch selbst erschaffen."
  },
  AvgCommunicate_137647_Content_6 = {
    Text = "Die Schicksalsleine, die sich auf natürliche Weise erstreckt, wird letztendlich neue Schöpfungen zur Geburt bringen, Unbekanntes Wesen Ursprungs."
  },
  AvgCommunicate_137647_Content_7 = {
    Text = "Indem ich Zeuge all dessen bin und mich an diesem Textil erfreue, bin ich in der Lage, diese Verantwortung zu tragen."
  },
  AvgCommunicate_137647_Content_8 = {
    Text = "Ich verstehe..."
  },
  AvgCommunicate_137647_Content_9 = {
    Text = "Wenn es neue Schöpfungen gibt, lass mich sie bitte ebenfalls bewundern."
  },
  AvgCommunicate_137647_Option_3 = {
    Text = "Überrascht?"
  },
  AvgCommunicate_140194_Content_1 = {
    Text = "Irgendetwas fühlt sich seltsam an. Die Tatsache, dass niemand auch nur ein bisschen Angst vor mir hat..."
  },
  AvgCommunicate_140194_Content_10 = {
    Text = "Keine Sorge, alle waren so nett zu mir! Sie sind sicher!"
  },
  AvgCommunicate_140194_Content_11 = {
    Text = "...Wahrscheinlich. Vorerst."
  },
  AvgCommunicate_140194_Content_12 = {
    Text = "Vorerst? ...Bitte mach es zu einem Definitiv!"
  },
  AvgCommunicate_140194_Content_13 = {
    Text = "Vorerst～!"
  },
  AvgCommunicate_140194_Content_2 = {
    Text = "Doll hat ein spezielles Pheromon entwickelt. Im Moment siehst du für alle wie ein ganz gewöhnliches menschliches Mädchen aus."
  },
  AvgCommunicate_140194_Content_4 = {
    Text = "Praktisch, nehme ich an, aber..."
  },
  AvgCommunicate_140194_Content_5 = {
    Text = "Es ist fast ein bisschen enttäuschend, dass ich die Leute nicht mehr erschrecken kann?"
  },
  AvgCommunicate_140194_Content_6 = {Text = "...?"},
  AvgCommunicate_140194_Content_7 = {
    Text = "Wie soll ich es ausdrücken... hmm... zum Beispiel wird es meine „Jagd\" schwieriger machen..."
  },
  AvgCommunicate_140194_Content_8 = {
    Text = "In letzter Zeit hatte ich keine Probleme, Mahlzeiten zu finden, also ist die Jagd kein dringendes Bedürfnis, aber... manchmal... ja..."
  },
  AvgCommunicate_140194_Content_9 = {
    Text = "Ich bin mittlerweile fast daran gewöhnt, dass alle Erweckten verschiedene verrückte Sachen sagen, aber ich muss dir trotzdem sagen... Das ist eine sehr gefährliche Aussage!"
  },
  AvgCommunicate_140195_Content_1 = {
    Text = "Kaufanfrage"
  },
  AvgCommunicate_140195_Content_10 = {
    Text = "...Und ich werde einfach so tun, als wüsste ich von alldem absolut nichts. Einverstanden?"
  },
  AvgCommunicate_140195_Content_2 = {
    Text = "Vier große Haushaltskühlschränke... Das Universitätsbudget ist zwar nicht gerade knapp, aber wofür brauchst du diese Kühlschränke?"
  },
  AvgCommunicate_140195_Content_3 = {
    Text = "Wenn ich mich richtig erinnere, Shaye, hast du bereits am ersten Tag deines Einzugs einen für dein Wohnheimzimmer angefordert."
  },
  AvgCommunicate_140195_Content_4 = {
    Text = "Nun, ähm... Man weiß nie, wann der Kühlschrankplatz sich als nützlich erweisen wird..."
  },
  AvgCommunicate_140195_Content_5 = {
    Text = "Außerdem, weißt du, die Frische des Fleisches ist wichtig..."
  },
  AvgCommunicate_140195_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_140195_Content_7 = {
    Text = "Tut mir leid, aber ich kann keine weiteren Kühlschränke genehmigen. Ich werde dir jedoch die Kontaktdaten von Xu und Doresain weiterleiten."
  },
  AvgCommunicate_140195_Content_9 = {
    Text = "Ich denke, du hättest viel Spaß daran, mit ihnen über Essen und Rezepte zu reden."
  },
  AvgCommunicate_140196_Content_1 = {Text = "¥%&#...%"},
  AvgCommunicate_140196_Content_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_140196_Content_11 = {
    Text = "Falsch! Du sollst Plitsch Platsch sagen!"
  },
  AvgCommunicate_140196_Content_12 = {
    Text = "Anscheinend wirkt das Pheromon, das Professorin Doll entwickelt hat, nicht bei Fräulein Mosk."
  },
  AvgCommunicate_140196_Content_13 = {
    Text = "Aber sie behandelt mich trotzdem genauso. Ihre Haltung hat sich überhaupt nicht verändert."
  },
  AvgCommunicate_140196_Content_14 = {
    Text = "Ich glaube, das liegt daran, ähm, wie soll ich das ausdrücken..."
  },
  AvgCommunicate_140196_Content_15 = {
    Text = "...Vielleicht ist Mosk einfach mit... außergewöhnlichen sozialen Fähigkeiten gesegnet?"
  },
  AvgCommunicate_140196_Content_2 = {
    Text = "A... Aufgeben. Ah, wieder ein neues Wort gelernt. Hmm."
  },
  AvgCommunicate_140196_Content_3 = {Text = "?"},
  AvgCommunicate_140196_Content_4 = {
    Text = "Ich habe in letzter Zeit alle möglichen Sprachen studiert. ...Es ist faszinierend."
  },
  AvgCommunicate_140196_Content_6 = {
    Text = "Neben der leonischen Standardsprache habe ich auch viele neue Vokabeln gelernt. Zum Beispiel..."
  },
  AvgCommunicate_140196_Content_7 = {
    Text = "Gluckgluck?"
  },
  AvgCommunicate_140196_Content_8 = {
    Text = "Platsch Platsch!"
  },
  AvgCommunicate_140196_Content_9 = {Text = "Richtig!"},
  AvgCommunicate_140196_Option_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_140196_Option_8 = {
    Text = "Platsch Platsch!"
  },
  AvgCommunicate_141374_Content_1 = {
    Text = "Ein feierlicher Dank mag vielleicht etwas zu förmlich wirken, aber von Herzen: Danke dir, für mich selbst und für ganz Ebwynnos."
  },
  AvgCommunicate_141374_Content_10 = {
    Text = "Ich zeige diese Eigenschaften, weil sie meiner Natur entsprechen."
  },
  AvgCommunicate_141374_Content_12 = {
    Text = "Sag so etwas nicht in einem so stolzen Tonfall."
  },
  AvgCommunicate_141374_Content_13 = {
    Text = "Also hast du mir wirklich einen großen Gefallen getan, indem du mir geholfen hast, jene Grenze zu berühren und mich von Seiner Kontrolle zu befreien."
  },
  AvgCommunicate_141374_Content_14 = {
    Text = "Vieles, was zuvor schwer zu erreichen war, ist jetzt kein Problem mehr."
  },
  AvgCommunicate_141374_Content_15 = {
    Text = "Ist es noch nicht zu spät, die Sachen zurückzunehmen?"
  },
  AvgCommunicate_141374_Content_16 = {
    Text = "Bleib ruhig, Pontos, Lentiniën hat ein ausgereiftes Rechtssystem!"
  },
  AvgCommunicate_141374_Content_2 = {
    Text = "So plötzlich so ernst zu sein, das ist wirklich etwas ungewohnt."
  },
  AvgCommunicate_141374_Content_3 = {
    Text = "Du weißt wahrscheinlich nicht, was das bedeutet – bevor ich stark genug war, konnte Ebwynnos sich eigentlich nie wirklich von der Kontrolle jenes uralten Wesens befreien."
  },
  AvgCommunicate_141374_Content_4 = {
    Text = "Das war ein Handel, den ich mit Ihm geschlossen habe. Zum Glück hegte Er keinen bösen Willen, man könnte Ihn sogar als großzügig bezeichnen."
  },
  AvgCommunicate_141374_Content_5 = {
    Text = "Doch Er gehört letztlich nicht zur Menschheit. Unter Seiner Kontrolle wäre Ebwynnos noch unberechenbarer geworden, und die Menschen in Ebwynnos wären in ihrer Gesinnung noch extremer geworden."
  },
  AvgCommunicate_141374_Content_6 = {
    Text = "Wenn man es so betrachtet, warst du etwa zuvor auch wegen Seines Einflusses so, nun ja..."
  },
  AvgCommunicate_141374_Content_7 = {
    Text = "Lass mich raten, du wolltest sagen: Paranoia, Nachtragen oder Kontrollzwang?"
  },
  AvgCommunicate_141374_Content_9 = {Text = "Nein."},
  AvgCommunicate_141374_Option_2 = {
    Text = "Etwas ungewohnt"
  },
  AvgCommunicate_141374_Option_6 = {Text = "Etwa doch"},
  AvgCommunicate_143429_Content_1 = {
    Text = "Obwohl diese Kultanhänger, die falsche Götter anbeten, so dumm sind, dass man lachen muss, muss man zugeben, dass manche von ihnen einen recht guten Geschmack haben."
  },
  AvgCommunicate_143429_Content_10 = {
    Text = "Außerdem stimmt die Epoche doch gar nicht!"
  },
  AvgCommunicate_143429_Content_11 = {
    Text = "Ich finde, wenn du dich mehr von solchen Einflüssen inspirieren lassen würdest und deinen Ehrgeiz stärken würdest, könnte das dazu beitragen, die Häufigkeit, mit der du im Außendienst in Not gerätst und um Hilfe rufst, erheblich zu reduzieren."
  },
  AvgCommunicate_143429_Content_12 = {
    Text = "Natürlich, wenn du mich öfter Onkel nennst, bin ich sehr gerne bereit, für wenig ehrgeizige Kleine immer einzuspringen."
  },
  AvgCommunicate_143429_Content_13 = {
    Text = "...Ich gehe jetzt und rede mit Goliath."
  },
  AvgCommunicate_143429_Content_14 = {
    Text = "Ich werde sie auf Misaqs Verbotsliste setzen – man darf sie nicht einfach so weiterempfehlen!"
  },
  AvgCommunicate_143429_Content_2 = {
    Text = "Als er vor ein paar Tagen hinter Miryams Rücken Misaq so häufig verlassen hat, war ich schon sehr schockiert..."
  },
  AvgCommunicate_143429_Content_3 = {
    Text = "Du meinst doch nicht etwa Goliath..."
  },
  AvgCommunicate_143429_Content_4 = {
    Text = "Nun, zunächst bewundere ich seine Entschlossenheit, sich unterzuordnen, um seine Ziele zu erreichen."
  },
  AvgCommunicate_143429_Content_5 = {
    Text = "Außerdem sind die Stücke, die er empfohlen hat, wirklich sehr interessant."
  },
  AvgCommunicate_143429_Content_6 = {
    Text = "Es ist schwer vorstellbar, dass Goliath ins Theater geht."
  },
  AvgCommunicate_143429_Content_7 = {
    Text = "Er empfahl mir <Italic:Once Upon a Time in Leonia> und <Italic:The Go▼father> – alle liebten sie."
  },
  AvgCommunicate_143429_Content_8 = {
    Text = "Heute Abend soll Ebwynnos „Der Wolf von Lentiniën\" aufführen."
  },
  AvgCommunicate_143429_Content_9 = {
    Text = "Nein, warte mal, Misaq erlaubt keine Gangsterbosse, und eine Wolfsmentalität ist auch nicht erlaubt!"
  },
  AvgCommunicate_143429_Option_2 = {
    Text = "Du meinst doch wohl nicht etwa"
  },
  AvgCommunicate_143430_Content_1 = {
    Text = "Der sechste Umzugsantrag dieses Monats – es scheint, dass die Vorschriften des Schulverwaltungsbüros auch nicht immer wirken."
  },
  AvgCommunicate_143430_Content_10 = {
    Text = "Ach, schade."
  },
  AvgCommunicate_143430_Content_11 = {
    Text = "Hä?? Hey?! Warum hat ein Mahr eine Prüfungsantwort herausgeholt und sich hingesetzt, um meine Abschlussarbeit zu schreiben?"
  },
  AvgCommunicate_143430_Content_12 = {
    Text = "Die Last auf deinen Schultern ist zu schwer. Selbst wenn du so etwas nur als Scherz sagst, zeigt es, dass du dich wirklich gut entspannen solltest, Kleines."
  },
  AvgCommunicate_143430_Content_13 = {
    Text = "Nur dieses eine Mal – auch wenn ich es sehr gerne tue, werde ich trotzdem versuchen, nicht zu dem Elternteil zu werden, das sein Kind verwöhnt."
  },
  AvgCommunicate_143430_Content_14 = {
    Text = "Jetzt öffne das Fenster. Ich nehme dich mit, einen Abend lang Spaß zu haben und den Spaß zu erleben, die Realität zu vergessen, ohne nach Ebwynnos gehen zu müssen."
  },
  AvgCommunicate_143430_Content_15 = {
    Text = "......Juhu!"
  },
  AvgCommunicate_143430_Content_3 = {
    Text = "Notendurchschnitt, Anwesenheit, effektive Praxisumsetzungsrate, ähm, und der Beschäftigungsdruck, den die meisten normalen Schüler haben, auch wenn die Hüter ihn nicht kennen."
  },
  AvgCommunicate_143430_Content_4 = {
    Text = "Selbst wenn die Auflösung zum Greifen nah ist, sind die alltäglichen Probleme immer noch erschreckend beängstigend."
  },
  AvgCommunicate_143430_Content_5 = {
    Text = "Es ist ganz normal, dass alle der Realität entfliehen wollen. Warum nimmst du mich nicht auch mit nach Ebwynnos......"
  },
  AvgCommunicate_143430_Content_6 = {
    Text = "Meinst du das ernst?"
  },
  AvgCommunicate_143430_Content_7 = {
    Text = "Ist da draußen vor dem Fenster wirklich ein Flügelschlagen zu hören, oder leide ich nach drei aufeinanderfolgenden Lernnächten schon unter Trugbildern?"
  },
  AvgCommunicate_143430_Content_8 = {
    Text = "Die Gelegenheit ist günstig und kommt nicht wieder – bei einer so guten Chance würde ich sehr gerne zustimmen, selbst wenn danach ganz Misaq mir Ärger machen würde."
  },
  AvgCommunicate_143430_Content_9 = {
    Text = "Nein nein nein nein nein nein, ich habe nur Spaß gemacht, bitte tu so etwas auf keinen Fall."
  },
  AvgCommunicate_143431_Content_1 = {
    Text = "Du brauchst mich?"
  },
  AvgCommunicate_143431_Content_10 = {
    Text = "Hahahahahaha, gut, hör auf, so ein Gesicht zu machen."
  },
  AvgCommunicate_143431_Content_11 = {
    Text = "An sein persönliches Siegel zu kommen ist keine schwierige Sache. Was die Adresse des Wohltätigkeitsdinnners betrifft – wie wäre es mit Ebwynnos?"
  },
  AvgCommunicate_143431_Content_12 = {
    Text = "Im nächsten Schritt würde die Polizei uns alle wegen Hausfriedensbruchs verhaften."
  },
  AvgCommunicate_143431_Content_14 = {
    Text = "Nun gut, bedauerlich. Ich werde für ein paar Tage vorübergehend ausweichen."
  },
  AvgCommunicate_143431_Content_15 = {
    Text = "Ihn zu töten, wenn er nicht auf der Hut ist, wäre vielleicht etwas interessanter."
  },
  AvgCommunicate_143431_Content_16 = {Text = "???!"},
  AvgCommunicate_143431_Content_2 = {
    Text = "Äh, Pontos, hast du schon darüber nachgedacht, für eine Weile nach Ebwynnos zurückzukehren?"
  },
  AvgCommunicate_143431_Content_3 = {
    Text = "Professor Dexter ist seit vollen zwei Monaten nicht mehr in der Schule gewesen."
  },
  AvgCommunicate_143431_Content_4 = {
    Text = "Ha, das feige dreckige Ding ist wahrscheinlich gerade dabei, wutentbrannt irgendeinen seiner unglücklichen Untergebenen anzuschreien."
  },
  AvgCommunicate_143431_Content_5 = {
    Text = "Keine Sorge, solange er nicht zu seinem Ursprung zurückgekehrt ist, hat er noch nicht das Recht, mein Gegner zu sein."
  },
  AvgCommunicate_143431_Content_6 = {
    Text = "Das Problem ist, dass ein Haufen Dokumente auf seinen Stempel wartet – was soll mit dem diesjährigen Wohltätigkeitsdinner werden! Direktorin Czort und Professorin Doll zu so einer Veranstaltung zu bringen ist schwieriger, als sie Misaq direkt in die Luft sprengen zu lassen."
  },
  AvgCommunicate_143431_Content_7 = {
    Text = "Wenn Lehrerin Sylvia die Leitung übernimmt, muss man sich um ganz andere Dinge Sorgen machen..."
  },
  AvgCommunicate_143431_Content_8 = {
    Text = "Das ist wirklich traurig, Kleines. Ich weiß, dass du in Misaq unter dem Schutz vieler Menschen stehst und mich nicht mehr brauchst, obwohl ich so viel für dich getan habe, und du hast sogar......"
  },
  AvgCommunicate_145234_Content_1 = {
    Text = "Es ist still geworden."
  },
  AvgCommunicate_145234_Content_10 = {
    Text = "Also... willst du nicht mehr kämpfen?"
  },
  AvgCommunicate_145234_Content_11 = {
    Text = "Hehehehe ..."
  },
  AvgCommunicate_145234_Content_12 = {
    Text = "Natürlich nicht."
  },
  AvgCommunicate_145234_Content_13 = {
    Text = "Ich brauche den Kampf nicht mehr, um meinen Körper zu beruhigen, aber..."
  },
  AvgCommunicate_145234_Content_14 = {
    Text = "Jetzt kann ich meine Stärke freier einsetzen und jeden herausfordern, den ich will!"
  },
  AvgCommunicate_145234_Content_15 = {
    Text = "Ich glaube... ich schulde dir meinen Dank."
  },
  AvgCommunicate_145234_Content_16 = {
    Text = "Du hast mich zu einem Gipfel geführt, nach dem ich mich lange gesehnt habe. Aber..."
  },
  AvgCommunicate_145234_Content_17 = {
    Text = "Der Weg der Stärke hat kein Ende. Stimmt's, Schutzherr?"
  },
  AvgCommunicate_145234_Content_2 = {
    Text = "Still? Was meinst du damit?"
  },
  AvgCommunicate_145234_Content_3 = {
    Text = "Mein Blut kocht nicht mehr. Meine Knochen schmerzen nicht mehr. Meine Klinge brüllt nicht länger..."
  },
  AvgCommunicate_145234_Content_4 = {
    Text = "Seit dem Moment meiner Geburt haben sie nie aufgehört."
  },
  AvgCommunicate_145234_Content_5 = {
    Text = "Jetzt sind sie alle still."
  },
  AvgCommunicate_145234_Content_6 = {
    Text = "Ist das eine schlechte Sache?"
  },
  AvgCommunicate_145234_Content_7 = {
    Text = "Geht es dir gut?"
  },
  AvgCommunicate_145234_Content_8 = {
    Text = "Der Lärm zuvor – das war nur Hunger. Ein verzweifeltes Jucken, weil ich nicht stark genug, nicht schnell genug war."
  },
  AvgCommunicate_145234_Content_9 = {
    Text = "Jetzt ist er verschwunden. Mein Körper fühlt sich... zum ersten Mal gesättigt an."
  },
  AvgCommunicate_145234_Option_6 = {
    Text = "Ist das eine schlechte Sache?"
  },
  AvgCommunicate_145234_Option_7 = {
    Text = "Geht es dir gut?"
  },
  AvgCommunicate_146392_Content_1 = {
    Text = "Bist du da?"
  },
  AvgCommunicate_146392_Content_10 = {
    Text = "Ich habe sie bezahlt, damit ich den Auftrag stattdessen übernehmen kann."
  },
  AvgCommunicate_146392_Content_11 = {
    Text = "Hast du es gefunden?"
  },
  AvgCommunicate_146392_Content_12 = {
    Text = "Es ist direkt vor mir. Schläft tief und fest."
  },
  AvgCommunicate_146392_Content_13 = {
    Text = "Ich warte darauf, dass es aufwacht."
  },
  AvgCommunicate_146392_Content_14 = {Text = "...Na gut."},
  AvgCommunicate_146392_Content_15 = {
    Text = "Lass mich überlegen, wie du dir die Zeit vertreiben kannst..."
  },
  AvgCommunicate_146392_Content_16 = {
    Text = "Oh, ich weiß! Du könntest..."
  },
  AvgCommunicate_146392_Content_17 = {
    Text = "Seine Augen zucken… Es wacht auf."
  },
  AvgCommunicate_146392_Content_18 = {Text = "Muss los."},
  AvgCommunicate_146392_Content_19 = {
    Text = "Hey? Lotan?"
  },
  AvgCommunicate_146392_Content_2 = {Text = "?"},
  AvgCommunicate_146392_Content_3 = {
    Text = "Lotan? Ich dachte, dich interessieren solche Dinge nicht."
  },
  AvgCommunicate_146392_Content_4 = {
    Text = "Nur gelangweilt. Ich teste dieses Gerät aus, das Doll mir gegeben hat."
  },
  AvgCommunicate_146392_Content_5 = {
    Text = "Könnte eines Tages nützlich sein."
  },
  AvgCommunicate_146392_Content_6 = {
    Text = "Du? Gelangweilt?"
  },
  AvgCommunicate_146392_Content_7 = {
    Text = "Ich dachte, du kämpfst entweder oder suchst nach einem Kampf."
  },
  AvgCommunicate_146392_Content_8 = {
    Text = "Wo bist du überhaupt? Ich habe dich seit Tagen nicht gesehen..."
  },
  AvgCommunicate_146392_Content_9 = {
    Text = "Ich habe gehört, Daffodil jagt irgendein mächtiges uraltes Ding."
  },
  AvgCommunicate_146392_Option_14 = {Text = "...Na gut."},
  AvgCommunicate_146392_Option_6 = {
    Text = "Du? Gelangweilt?"
  },
  AvgCommunicate_146393_Content_1 = {
    Text = "Hörner. Zähne. Klauen. Fleisch. Augäpfel. Tentakel."
  },
  AvgCommunicate_146393_Content_10 = {
    Text = "Hoffentlich bist du genauso zäh."
  },
  AvgCommunicate_146393_Content_11 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_146393_Content_12 = {
    Text = "Na, danke schön."
  },
  AvgCommunicate_146393_Content_2 = {
    Text = "Such dir eines aus."
  },
  AvgCommunicate_146393_Content_3 = {
    Text = "Ist das so eine Art „Rate, was du dir wünschst\"-Spiel...?"
  },
  AvgCommunicate_146393_Content_4 = {
    Text = "Ich habe das Monster mitgebracht, das ich zuletzt getötet habe."
  },
  AvgCommunicate_146393_Content_5 = {
    Text = "Hatte sowieso keinen Platz dafür, dachte, du möchtest vielleicht ein Andenken."
  },
  AvgCommunicate_146393_Content_6 = {
    Text = "Keines davon klingt verlockend..."
  },
  AvgCommunicate_146393_Content_7 = {
    Text = "Ist es seltsam, wenn ich alle haben möchte..."
  },
  AvgCommunicate_146393_Content_8 = {
    Text = "Schwere Entscheidung... kannst du nicht einfach für mich wählen..."
  },
  AvgCommunicate_146393_Content_9 = {
    Text = "Das Horn ist gut. Hat drei Schläge gehalten, bevor es zerbrach. Es passt zu dir."
  },
  AvgCommunicate_146393_Option_6 = {
    Text = "Keines davon klingt verlockend..."
  },
  AvgCommunicate_146393_Option_7 = {
    Text = "Ist es seltsam, wenn ich alle haben möchte..."
  },
  AvgCommunicate_146394_Content_1 = {
    Text = "Ich habe ein Problem."
  },
  AvgCommunicate_146394_Content_10 = {
    Text = "Ich bin dreimal gegangen. Jedes Mal fingen sie an, sich selbst zu opfern. Offenbar hielten sie es für eine göttliche Prüfung."
  },
  AvgCommunicate_146394_Content_11 = {
    Text = "Die sind doch alle verrückt."
  },
  AvgCommunicate_146394_Content_12 = {
    Text = "Und warum bist du überhaupt zurückgegangen??"
  },
  AvgCommunicate_146394_Content_13 = {
    Text = "Ich hatte meine Klinge nicht aus seinem Kadaver gezogen."
  },
  AvgCommunicate_146394_Content_14 = {
    Text = "Jetzt haben sie auch sie als Heiligtum verehrt."
  },
  AvgCommunicate_146394_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_146394_Content_16 = {
    Text = "Ich muss meine Klinge zurückbekommen, ohne dass sie vor meinen Augen Massenselbstmord begehen."
  },
  AvgCommunicate_146394_Content_17 = {
    Text = "Du verstehst diese schwachen kleinen Kreaturen besser als ich. Hilf mir."
  },
  AvgCommunicate_146394_Content_18 = {
    Text = "...Hey, was soll das denn heißen?!"
  },
  AvgCommunicate_146394_Content_2 = {
    Text = "Wow, selbst du gerätst also manchmal in Schwierigkeiten!"
  },
  AvgCommunicate_146394_Content_3 = {
    Text = "Ich hörte von einem starken Wurm, also habe ich ihn getötet."
  },
  AvgCommunicate_146394_Content_4 = {
    Text = "Nachdem er starb, krochen die Menschen, die lange unter seiner Masse im Inneren des Planeten gefangen waren, heraus."
  },
  AvgCommunicate_146394_Content_5 = {
    Text = "Sie nannten mich einen Gott, verbeugten sich vor mir und bauten mir sogar eine goldene Statue – hässlich wie die Nacht."
  },
  AvgCommunicate_146394_Content_6 = {Text = "HAHAHAHAHA"},
  AvgCommunicate_146394_Content_7 = {
    Text = "Hör auf zu lachen."
  },
  AvgCommunicate_146394_Content_8 = {
    Text = "Magst du es nicht, verehrt zu werden?"
  },
  AvgCommunicate_146394_Content_9 = {
    Text = "Magst du es nicht, verehrt zu werden?"
  },
  AvgCommunicate_146394_Option_6 = {Text = "HAHAHAHA"},
  AvgCommunicate_146394_Option_8 = {
    Text = "Warum bist du nicht einfach gegangen?"
  },
  AvgCommunicate_146394_Option_9 = {
    Text = "Warum bist du nicht einfach gegangen?"
  },
  AvgCommunicate_148438_Content_1 = {
    Text = "Ich nehme an, du weißt es bereits, hmm?"
  },
  AvgCommunicate_148438_Content_10 = {
    Text = "Hihi, denk nicht zu viel nach~ Wer zu viel nachdenkt, wird zu einem langweiligen, spaßlosen Erwachsenen~"
  },
  AvgCommunicate_148438_Content_11 = {
    Text = "Obwohl natürlich, wenn der Schutzherr einfach nicht anders kann, als von der Fee angezogen zu werden – wenn du dich dabei ertappst, mir Tag und Nacht auf Schritt und Tritt zu folgen, nur um meine wahre Zuneigung zu gewinnen – nun, das wäre vollkommen verständlich~"
  },
  AvgCommunicate_148438_Content_12 = {Text = "Ugh..."},
  AvgCommunicate_148438_Content_13 = {
    Text = "Ich habe bereits den süßesten Kandisapfel von allen auf dem Schreibtisch in deinem Schlafsaal hinterlassen."
  },
  AvgCommunicate_148438_Content_14 = {
    Text = "Jetzt musst du ihn, unbedingt musst du ihn, langsam genießen, jeden Bissen aufmerksam kosten und ihn ganz für dich allein genießen~"
  },
  AvgCommunicate_148438_Content_2 = {
    Text = "Du hast also all diese Mühe auf dich genommen, um eine Ausgangsgenehmigung zu bekommen... nur um Aigis, Ogier und Murphy limitierte Kandisäpfel zu kaufen, die sie noch nie probiert hatten?"
  },
  AvgCommunicate_148438_Content_3 = {
    Text = "Diese kleinen Bra– ähem – diese frommen Kinder haben vielleicht ihre Mitgliedsbeiträge nicht vollständig bezahlt, aber sie spielen eine absolut unverzichtbare Rolle dabei, den Segen der Fee weit und breit zu verbreiten."
  },
  AvgCommunicate_148438_Content_4 = {
    Text = "Meine Herde zu hegen und zu pflegen, damit sie das gute Wort umso eifriger verbreitet – nun, das ist nur eine weitere schwere Last, die die Fee auf ihren Schultern trägt~"
  },
  AvgCommunicate_148438_Content_5 = {
    Text = "Selbst wenn du diesmal einen guten Grund hattest, warum buchst du es immer auf MEIN Konto..."
  },
  AvgCommunicate_148438_Content_7 = {
    Text = "Oh, mach dir keine Sorgen um solche Kleinigkeiten~ Schau, die Kinder sind jetzt wahre Gläubige. Wann wirst du endlich zu ihnen stoßen, hmm?"
  },
  AvgCommunicate_148438_Content_9 = {
    Text = "Ich kann ehrlich gesagt nicht sagen, ob du ab und zu einen Funken deines wahren Ichs durchscheinen lässt, oder ob du einfach eine Zwiebel bist, die ihr wahres Ziel immer unter einer weiteren Schicht verbirgt..."
  },
  AvgCommunicate_148439_Content_1 = {Text = "[Bild]"},
  AvgCommunicate_148439_Content_10 = {
    Text = "[Bild erfolgreich geladen]"
  },
  AvgCommunicate_148439_Content_11 = {Text = "[Bild]"},
  AvgCommunicate_148439_Content_12 = {
    Text = "Was... das ist wirklich ein Entschuldigungsbrief..."
  },
  AvgCommunicate_148439_Content_13 = {
    Text = "Es tut mir leid... Caraboo. Ich hätte nicht so reagieren sollen, als du ausnahmsweise einmal aufrichtig warst."
  },
  AvgCommunicate_148439_Content_14 = {
    Text = "Ich werde jetzt sofort die Beschwerde zurückziehen, die ich gerade eingereicht habe. Die, in der ich empfohlen habe, dich mit Ausgangsverbot zu belegen... alle Ausgangsanträge abzulehnen... So! Ich habe jede Beschwerde zurückgezogen, die ich je gegen dich eingereicht habe."
  },
  AvgCommunicate_148439_Content_15 = {
    Text = "Wunderbar~ Hihihi, Schutzherr – ich glaube, sobald eine Beschwerde zurückgezogen wird, kann man einen ganzen Monat lang keine neue gegen denselben Erwecker einreichen, nicht wahr?"
  },
  AvgCommunicate_148439_Content_17 = {
    Text = "Ich habe ein sehr schlechtes Gefühl dabei..."
  },
  AvgCommunicate_148439_Content_18 = {
    Text = "Oh, die Fee wäre niemals so ungnädig, mit %player%s aufrichtigem Herzen zu spielen~ Jedes Wort in diesem Entschuldigungsbrief war die reine Wahrheit. Wenn ich von meinem Ausgang zurückkomme, bringe ich dir garantiert den süßesten roten Apfel mit~"
  },
  AvgCommunicate_148439_Content_19 = {
    Text = "Warte! Warum ist Aigis gerade weinend zu mir gekommen und hat gesagt, dass sie zwar keine Ahnung hat, was sie falsch gemacht hat, aber hofft, dass ich ihr vergebe, wenn ich den Entschuldigungsbrief sehe?"
  },
  AvgCommunicate_148439_Content_2 = {
    Text = "Wird geladen..."
  },
  AvgCommunicate_148439_Content_20 = {
    Text = "Und dass du versprochen hast, ihn weiterzuleiten – sie aber trotzdem beschlossen hat, sich persönlich bei mir zu entschuldigen, nur um sicherzugehen, dass ich ihr nicht wieder böse bin?!"
  },
  AvgCommunicate_148439_Content_21 = {
    Text = "Hey, Caraboo. CARABOO!!"
  },
  AvgCommunicate_148439_Content_3 = {Text = "?"},
  AvgCommunicate_148439_Content_4 = {
    Text = "Caraboo, diesen Trick hast du schon einmal angewendet. Was auch immer du sagst, ich werde dieses Bild NICHT öffnen."
  },
  AvgCommunicate_148439_Content_5 = {
    Text = "Nein, %player%... Ich habe wirklich darüber nachgedacht. Du und alle in Misaq waren so freundlich zu mir. Ich hätte meine alten Gewohnheiten wirklich nicht an diesen wunderschönen Ort bringen sollen."
  },
  AvgCommunicate_148439_Content_6 = {
    Text = "Schließlich habe ich nie gewählt, wer ich bin – zumindest nicht ganz am Anfang."
  },
  AvgCommunicate_148439_Content_7 = {
    Text = "Also habe ich mich hingesetzt und dir einen richtigen Entschuldigungsbrief geschrieben – handschriftlich, jedes einzelne Wort, von meiner eigenen Hand~ Aber stell dir vor, der Kommunikator hat genau in diesem Moment eine Störung gehabt..."
  },
  AvgCommunicate_148439_Content_8 = {
    Text = "Ich verstehe, wenn du mir nicht glaubst. Ich werde einfach... warten. So lange es dauert, bis du mir wieder vertraust..."
  },
  AvgCommunicate_148439_Content_9 = {
    Text = "...Ugh, warum meldet sich mein Gewissen? Jedenfalls gibt es keine Möglichkeit, dass ich..."
  },
  AvgCommunicate_148440_Content_1 = {Text = "[Bild]"},
  AvgCommunicate_148440_Content_10 = {
    Text = "Wovon redest du? Als würde ich dir jemals etwas zurückzahlen!"
  },
  AvgCommunicate_148440_Content_11 = {Text = "Huh?"},
  AvgCommunicate_148440_Content_12 = {
    Text = "Du gibst nicht mal mehr vor?"
  },
  AvgCommunicate_148440_Content_13 = {
    Text = "Hihihi. Der Fee zu dienen ist selbst deine größte Ehre. Sie wird dich in ein unvergleichliches Paradies führen. Dagegen ist weltliche Vergeltung natürlich kaum der Rede wert."
  },
  AvgCommunicate_148440_Content_14 = {
    Text = "Genug davon! Wenn du das Geld nicht bald überweist, ist die Karte für immer verloren..."
  },
  AvgCommunicate_148440_Content_16 = {
    Text = "Ich habe mir das Ding, das du mir geschickt hast, bereits angesehen. Es war eindeutig mit irgendeiner billigen Silberkern-Technik gefälscht..."
  },
  AvgCommunicate_148440_Content_17 = {
    Text = "Oh? Du hast es geöffnet? Das war völlig deine eigene Entscheidung, weißt du~ Wunderbar! *Die Fee wird %player%s Opfergabe für immer in Erinnerung behalten.*"
  },
  AvgCommunicate_148440_Content_18 = {
    Text = "Warte, warum bekomme ich eine Benachrichtigung, dass gerade 1.000 Florins abgebucht wurden – das ist mein Feldforschungsstipendium!"
  },
  AvgCommunicate_148440_Content_2 = {
    Text = "Wird geladen..."
  },
  AvgCommunicate_148440_Content_20 = {
    Text = "Na, na. Du bist doch ganz schön wohlhabend, oder? Ich nehme diesmal nur 200 Florins – als Bezahlung für die freundliche Lektion, dass man keine unbekannten Links auf seinem Komm öffnen sollte. Sei dankbar für die Gnade der Fee, hmm?"
  },
  AvgCommunicate_148440_Content_21 = {
    Text = "[Überweisung: 800 Leonian Florins]"
  },
  AvgCommunicate_148440_Content_3 = {
    Text = "[Bild beschädigt]"
  },
  AvgCommunicate_148440_Content_4 = {
    Text = "...Was hast du geschickt?"
  },
  AvgCommunicate_148440_Content_5 = {Text = "Oops!"},
  AvgCommunicate_148440_Content_6 = {
    Text = "Wir sind am Ende! Dieses Bild enthielt eine Karte in den Osten, erkauft mit Blut, Schweiß und Tränen meiner treuen Anhänger – und jetzt ist das Original zusammen damit korrumpiert! Das muss ein böses @2 sein, das uns daran hindern will, den Osten zu erreichen!"
  },
  AvgCommunicate_148440_Content_7 = {
    Text = "%player%, wie viele Florins hast du bei dir? Schnell, gib mir alle davon! Es gibt noch eine Chance, es wiederherzustellen..."
  },
  AvgCommunicate_148440_Content_8 = {
    Text = "Lass mich raten: Du zahlst mir das Zehnfache zurück, sobald du den Osten erreichst. Ich bin doch nicht von gestern."
  },
  AvgCommunicate_148440_Content_9 = {
    Text = "Ein Betrug, der nicht mit der Zeit geht, hat keine Zukunft."
  },
  AvgCommunicate_149803_Content_1 = {
    Text = "Die Eskortiermission, die mir die Akademie zuvor anvertraut hatte, ist abgeschlossen. Gibt es etwas, das Ihr von mir benötigt, mein Herr?"
  },
  AvgCommunicate_149803_Content_10 = {
    Text = "Wie auch immer, wenn Ihr nicht untätig sein wollt — in ein paar Tagen finden viele Veranstaltungen an der Akademie statt. Warum geht Ihr nicht hin und amüsiert Euch?"
  },
  AvgCommunicate_149803_Content_11 = {
    Text = "...Da es der Befehl meines Herrn ist, werde ich gehorchen."
  },
  AvgCommunicate_149803_Content_12 = {
    Text = "Ich gehe jetzt auf Patrouille."
  },
  AvgCommunicate_149803_Content_13 = {
    Text = "Ich hoffe, Ihr haltet Euch später auch wirklich daran!"
  },
  AvgCommunicate_149803_Content_2 = {
    Text = "Wollt Ihr Euch nicht ausruhen?"
  },
  AvgCommunicate_149803_Content_3 = {
    Text = "Das ist nicht nötig."
  },
  AvgCommunicate_149803_Content_4 = {
    Text = "Außerdem... habe ich kein Recht, solchen Frieden zu genießen."
  },
  AvgCommunicate_149803_Content_5 = {
    Text = "Dieser dunkle Schatten stört mich von Zeit zu Zeit und flüstert mir ins Ohr."
  },
  AvgCommunicate_149803_Content_6 = {
    Text = "Vielleicht bin ich tatsächlich ruhiger, wenn ich Aufgaben zu erledigen habe."
  },
  AvgCommunicate_149803_Content_7 = {
    Text = "Das ist alles. Bitte macht Euch keine Sorgen darum, mein Herr."
  },
  AvgCommunicate_149803_Content_8 = {
    Text = "Vielleicht muss ich Euch die Notwendigkeit des Faulenzens beibringen."
  },
  AvgCommunicate_149803_Content_9 = {
    Text = "Ihr kämpft besser, wenn Ihr Euch mehr entspannt."
  },
  AvgCommunicate_149803_Option_8 = {
    Text = "Vielleicht muss ich Euch die Notwendigkeit des Faulenzens beibringen."
  },
  AvgCommunicate_149803_Option_9 = {
    Text = "Ihr kämpft besser, wenn Ihr Euch mehr entspannt."
  },
  AvgCommunicate_149950_Content_10 = {
    Text = "Hmph... verspottest du mich? Dies ist bereits das Äußerste, wie viel ich diesen Körper im Moment kontrollieren kann!"
  },
  AvgCommunicate_149950_Content_11 = {
    Text = "Was hast du vor? Ihn weiter reizen und manipulieren?"
  },
  AvgCommunicate_149950_Content_12 = {
    Text = "Wenn ich könnte, hätte ich längst schon..."
  },
  AvgCommunicate_149950_Content_13 = {
    Text = "Egal. Anstatt eine Klinge zu sein, scheint es auch gar nicht so schlecht zu sein, ein Schild oder ein Bollwerk zu sein..."
  },
  AvgCommunicate_149950_Content_14 = {
    Text = "Was den Herrn betrifft, dem er vertraut und dient – dich – war es tatsächlich recht interessant, dich kennenzulernen."
  },
  AvgCommunicate_149950_Content_15 = {
    Text = "Jetzt sehe ich es. Du wurdest im Gegenzug von Ogier beeinflusst, nicht wahr."
  },
  AvgCommunicate_149950_Content_17 = {Text = "???"},
  AvgCommunicate_149950_Content_18 = {
    Text = "Mein Herr, ich entschuldige mich aufrichtig. Ich hatte gerade für ein paar Minuten einen Aussetzer."
  },
  AvgCommunicate_149950_Content_19 = {
    Text = "Als ich wieder zu mir kam, stellte ich fest, dass das Kommunikationsgerät aufleuchtete."
  },
  AvgCommunicate_149950_Content_2 = {
    Text = "Endlich habe ich dich gefunden..."
  },
  AvgCommunicate_149950_Content_20 = {
    Text = "Ich habe das Gefühl... ich habe diese nervtötende Stimme gerade nach so langer Zeit wieder gehört..."
  },
  AvgCommunicate_149950_Content_21 = {
    Text = "Wie soll ich es sagen... es scheint, als hättest du und die Kraft in dir bereits gelernt, recht harmonisch miteinander zu koexistieren."
  },
  AvgCommunicate_149950_Content_22 = {
    Text = "...Ich habe das Protokoll durchgelesen."
  },
  AvgCommunicate_149950_Content_23 = {
    Text = "Ich hatte Angst, dass es böse, aggressive Worte sprechen würde wie früher."
  },
  AvgCommunicate_149950_Content_24 = {
    Text = "Es ist wirklich überraschend. Früher war es immer ich, der von ihr erodiert wurde – und nun scheinen sich die Rollen umgekehrt zu haben."
  },
  AvgCommunicate_149950_Content_25 = {
    Text = "Das sollte eine gute Sache sein. Zumindest... bedeutet es, dass ich Es vollständig überwunden habe."
  },
  AvgCommunicate_149950_Content_26 = {
    Text = "Oder könnte es sein, dass die Stärkung von Ogiers Kraft es mir ermöglicht hat, die Kontrolle über dieses unfassbare Ding auf ein solches Niveau zu bringen?"
  },
  AvgCommunicate_149950_Content_27 = {
    Text = "Mm, das muss es sein. All diese Veränderungen sind sicherlich durch dich zustande gekommen."
  },
  AvgCommunicate_149950_Content_28 = {
    Text = "Und für mich ist das „Höchste Gesetz“, das ich verstanden habe, nicht nur Kraft..."
  },
  AvgCommunicate_149950_Content_29 = {
    Text = "Da ist auch diese Überzeugung, andere zu schützen, die in meiner Brust mit größerem Eifer als je zuvor brennt. Ich glaube, darin liegt die wahre Quelle."
  },
  AvgCommunicate_149950_Content_3 = {
    Text = "Du bist nicht Ogier. Wer bist du?"
  },
  AvgCommunicate_149950_Content_4 = {
    Text = "Gib dem Besitzer sein Kommunikationsgerät zurück!"
  },
  AvgCommunicate_149950_Content_5 = {
    Text = "Wie lächerlich. Ohne meine Existenz – wie hätte dieses Kind überleben können, und wie hätte er hier als Erwecker bleiben können?"
  },
  AvgCommunicate_149950_Content_6 = {
    Text = "Du bist... die unsichtbare Präsenz, die an ihm haftet?"
  },
  AvgCommunicate_149950_Content_7 = {
    Text = "Ganz genau. Und dennoch erkennst du mich nicht, Schutzherr von Misaq."
  },
  AvgCommunicate_149950_Content_8 = {
    Text = "Nun ja... du wurdest von Ogier stets so gründlich unterdrückt, dass ich dich schlicht nie zuvor gesehen habe."
  },
  AvgCommunicate_149950_Option_3 = {
    Text = "Du bist nicht Ogier. Wer bist du?"
  },
  AvgCommunicate_149950_Option_4 = {
    Text = "Gib dem Besitzer sein Kommunikationsgerät zurück!"
  },
  AvgCommunicate_149986_Content_1 = {
    Text = "Mein Herr, ich bin gekommen, um Euch eine Einladung auszusprechen."
  },
  AvgCommunicate_149986_Content_10 = {
    Text = "...Einen Baum."
  },
  AvgCommunicate_149986_Content_11 = {Text = "Huh?"},
  AvgCommunicate_149986_Content_12 = {
    Text = "Vielleicht liegt es an meiner professionellen Ausbildung — egal wie chaotisch es wird, ich kann auf der Bühne vollkommen still stehen."
  },
  AvgCommunicate_149986_Content_13 = {
    Text = "Was wird in eurem Stück denn alles passieren?!"
  },
  AvgCommunicate_149986_Content_14 = {
    Text = "Das weiß ich nicht. Ich bin nur ein Baum."
  },
  AvgCommunicate_149986_Content_15 = {
    Text = "...Nun, während der Aufführung wird Jenkin, der die Prinzessin spielt, von oben herabsteigen, und Lily, der den Prinzen spielt, muss sie auffangen."
  },
  AvgCommunicate_149986_Content_16 = {
    Text = "Aigis, der den Dämonenkönig spielt, muss auch von der Bühne kommen und mit dem Publikum interagieren."
  },
  AvgCommunicate_149986_Content_17 = {
    Text = "Ich habe es aufgegeben, die Rollenbesetzung zu kommentieren..."
  },
  AvgCommunicate_149986_Content_18 = {
    Text = "Aber ist das nicht so, als würdest du mir alles vorwegnehmen?"
  },
  AvgCommunicate_149986_Content_19 = {
    Text = "Weil ich nichts vor dir verbergen möchte."
  },
  AvgCommunicate_149986_Content_2 = {
    Text = "Der Theaterclub führt ein Märchenspiel auf und hat die minderjährigen Erwecker in Misaq eingeladen, gemeinsam aufzutreten."
  },
  AvgCommunicate_149986_Content_20 = {
    Text = "Außerdem läuft bei den Proben jedes Mal etwas anderes schief, wenn man nach dem bisherigen Verlauf urteilt. Ich kann nicht garantieren, was du am Ende tatsächlich zu sehen bekommst."
  },
  AvgCommunicate_149986_Content_21 = {
    Text = "...Das macht es tatsächlich ziemlich faszinierend."
  },
  AvgCommunicate_149986_Content_22 = {
    Text = "Die Dinge, die während der Aufführung passieren, sind schließlich mit einem gewissen Maß an Gefahr verbunden."
  },
  AvgCommunicate_149986_Content_23 = {
    Text = "Während ich also die Rolle eines Baumes spiele, muss ich gleichzeitig die Lage auf und hinter der Bühne im Blick behalten, um die Sicherheit der Schauspieler und des Publikums zu gewährleisten."
  },
  AvgCommunicate_149986_Content_24 = {
    Text = "Du hast also nebenbei als Leibwächter gearbeitet... das klingt wirklich anstrengend."
  },
  AvgCommunicate_149986_Content_25 = {
    Text = "In der Tat. Jedenfalls, bitte sei unbesorgt. Solange ich noch auf der Bühne stehe, werde ich nicht zulassen, dass jemand erneut verletzt wird."
  },
  AvgCommunicate_149986_Content_3 = {
    Text = "Es ist ein wenig peinlich zu sagen... Ich werde auch auf der Bühne stehen. Ich hoffe, du wirst kommen und zuschauen."
  },
  AvgCommunicate_149986_Content_4 = {
    Text = "! Ich freue mich darauf."
  },
  AvgCommunicate_149986_Content_5 = {
    Text = "Trotzdem hätte ich nicht erwartet, dass du zustimmst, an so etwas teilzunehmen."
  },
  AvgCommunicate_149986_Content_6 = {
    Text = "Nun, ich bin kein Kind mehr, daher passt es mir eigentlich nicht wirklich, daran beteiligt zu sein."
  },
  AvgCommunicate_149986_Content_7 = {
    Text = "Aber sie haben darauf bestanden..."
  },
  AvgCommunicate_149986_Content_8 = {
    Text = "Ich wollte ihre Begeisterung nicht dämpfen, und außerdem wurde mir klar, dass diese bestimmte Rolle wirklich nur von mir gespielt werden konnte."
  },
  AvgCommunicate_149986_Content_9 = {
    Text = "Also, welche Rolle wird Ogier spielen? Einen Ritter?"
  },
  AvgCommunicate_149987_Content_1 = {
    Text = "Mein Herr, gibt es in letzter Zeit Kurse zum Fusionseffekt?"
  },
  AvgCommunicate_149987_Content_10 = {
    Text = "So fleißig... Wenn ich so eifrig wäre wie du, müsste ich mir bestimmt keine Sorgen um Prüfungen machen."
  },
  AvgCommunicate_149987_Content_11 = {
    Text = "Bitte schmeichle mir nicht so. Die Verantwortung, die du trägst, ist weitaus anspruchsvoller als meine."
  },
  AvgCommunicate_149987_Content_12 = {
    Text = "Außerdem ist dies lediglich die notwendige Arbeit, die ich als Buße leiste."
  },
  AvgCommunicate_149987_Content_13 = {
    Text = "Aber du lernst so schnell – wer weiß, vielleicht hat Ogier das Zeug zu einem Gelehrten."
  },
  AvgCommunicate_149987_Content_14 = {
    Text = "Wie das Thema, über das jeder in der Jugend nachdenkt – was die Zukunft bringt."
  },
  AvgCommunicate_149987_Content_15 = {
    Text = "Hat Ogier jemals darüber nachgedacht, was du werden möchtest, wenn du groß bist?"
  },
  AvgCommunicate_149987_Content_16 = {
    Text = "Du weißt, dass ich ein Erwecker geworden bin. Es gibt keine Möglichkeit mehr, groß zu werden."
  },
  AvgCommunicate_149987_Content_17 = {
    Text = "Du kannst trotzdem von deiner Zukunft träumen! Es besteht kein Grund, so pessimistisch zu sein."
  },
  AvgCommunicate_149987_Content_18 = {
    Text = "Gibt es nichts, was Ogier tun möchte, abgesehen davon, „andere zu beschützen“?"
  },
  AvgCommunicate_149987_Content_19 = {
    Text = "Danke für die Ermutigung."
  },
  AvgCommunicate_149987_Content_2 = {
    Text = "Ich würde es gerne eingehender studieren."
  },
  AvgCommunicate_149987_Content_20 = {
    Text = "Was andere Dinge betrifft, die ich tun möchte... Es tut mir leid, mir fällt wirklich nichts ein."
  },
  AvgCommunicate_149987_Content_21 = {
    Text = "Wenn dieser Körper nicht mehr von Sünde befleckt ist, werde ich darüber nachdenken."
  },
  AvgCommunicate_149987_Content_3 = {
    Text = "Natürlich, beim nächsten Mal nehme ich dich mit."
  },
  AvgCommunicate_149987_Content_4 = {
    Text = "Aber warum hat Ogier plötzlich Interesse daran, mehr darüber zu erfahren?"
  },
  AvgCommunicate_149987_Content_5 = {
    Text = "Weil mich heute jemand gefragt hat, ob die Kraft, die meinen Körper umhüllt, mit A-Schleim zusammenhängt."
  },
  AvgCommunicate_149987_Content_6 = {
    Text = "Ich verstehe. Rein von der Form her ähneln sie sich tatsächlich ein wenig."
  },
  AvgCommunicate_149987_Content_7 = {
    Text = "Ja, ich war schon immer neugierig auf das wahre Wesen dieser unsichtbaren Kraft. Vielleicht kann ich sie besser kontrollieren, wenn ich sie gut genug verstehe."
  },
  AvgCommunicate_149987_Content_8 = {
    Text = "Doch seit ich in Misaq bin, habe ich festgestellt, dass es weit mehr unbegreifliche Dinge gibt, als ich je gedacht hätte..."
  },
  AvgCommunicate_149987_Content_9 = {
    Text = "Deshalb habe ich beschlossen, zunächst mehr über A-Schleim und alles, was damit zusammenhängt, zu lernen. Schließlich ist es auch der Feind, gegen den mein Herr seit Langem kämpft."
  },
  AvgCommunicate_149988_Content_1 = {
    Text = "Ah, mein ungehorsames kleines Hundchen, das immer wild durch die ganze Welt streunt."
  },
  AvgCommunicate_149988_Content_10 = {
    Text = "Deinen Wilhelm interessiert hier niemanden."
  },
  AvgCommunicate_149988_Content_11 = {
    Text = "Vergiss nur nicht: Du bist mein persönliches Haushündchen. Jede Bedrohung für dein erbärmliches Leben bedeutet schlicht einen Verlust meines Eigentums."
  },
  AvgCommunicate_149988_Content_12 = {
    Text = "Außerdem habe ich diese spezifische Welt eigenhändig ausgewählt – einen kleinen Riss, sicher vor der Auflösung."
  },
  AvgCommunicate_149988_Content_13 = {
    Text = "Also pass auf, wohin du trittst. Versuch, sie nicht zu zerbrechen."
  },
  AvgCommunicate_149988_Content_2 = {
    Text = "Dein Signal bricht schon wieder ab. In welches gottverlassene Ödland hast du dich diesmal verkrochen?"
  },
  AvgCommunicate_149988_Content_3 = {
    Text = "Ich bin auf dem Nordkontinent."
  },
  AvgCommunicate_149988_Content_4 = {
    Text = "Ich bin weit oben im Hochland."
  },
  AvgCommunicate_149988_Content_5 = {
    Text = "Wir bereiten uns darauf vor, als nächstes einen Berg zu besteigen. Ehrlich gesagt mache ich mir ein wenig Sorgen um meine Ausdauer."
  },
  AvgCommunicate_149988_Content_6 = {
    Text = "Die Luft ist hier oben unglaublich dünn. Es fühlt sich an, als würde ich ohnmächtig werden, wenn ich mehr als ein paar Schritte renne."
  },
  AvgCommunicate_149988_Content_7 = {
    Text = "Und du glaubst tatsächlich, du kannst so einen Berg besteigen? Was für ein leichtsinniges, hirnloses kleines Hundchen, das absolut keine Ahnung von seinen eigenen Grenzen hat."
  },
  AvgCommunicate_149988_Content_8 = {
    Text = "Ich weiß, dass du dir nur Sorgen machst, aber ich habe Dinge, die ich erledigen muss."
  },
  AvgCommunicate_149988_Content_9 = {
    Text = "Mach dir keine Sorgen, Senior Wilhelm ist bei mir. Uns wird nichts passieren."
  },
  AvgCommunicate_149988_Option_3 = {
    Text = "Nordkontinent."
  },
  AvgCommunicate_149988_Option_4 = {
    Text = "Eine Hochgebirgsregion."
  },
  AvgCommunicate_150103_Content_1 = {
    Text = "Ein schwaches Zittern breitet sich durch die fernen Weiten des Schicksalsgeflechts aus."
  },
  AvgCommunicate_150103_Content_10 = {
    Text = "Ist dies ein weiterer Faden in deinem Schicksalsteppich?"
  },
  AvgCommunicate_150103_Content_11 = {
    Text = "Hierzu muss der Webstuhl schweigen."
  },
  AvgCommunicate_150103_Content_12 = {
    Text = "Was ist mit den Menschen, die in dieser Welt leben? Was geschieht nun mit ihnen?"
  },
  AvgCommunicate_150103_Content_13 = {
    Text = "Sie werden zu ihrem reinsten Wesen zurückkehren – den Silberkernen."
  },
  AvgCommunicate_150103_Content_14 = {
    Text = "Und der Gotteskönig wird jene Fragmente aus dem endlosen Regen bergen und die Welt nach einem langen, stillen Schlummer neu formen."
  },
  AvgCommunicate_150103_Content_15 = {
    Text = "Dieser stille Zeuge soll geteilt werden."
  },
  AvgCommunicate_150103_Content_2 = {
    Text = "Die kritische Schwelle wurde überschritten. Das lang ersehnte gelobte Land ist endlich erreicht."
  },
  AvgCommunicate_150103_Content_3 = {
    Text = "Das kann ich nicht glauben."
  },
  AvgCommunicate_150103_Content_4 = {
    Text = "Die Welt verschwindet."
  },
  AvgCommunicate_150103_Content_5 = {
    Text = "Der Himmel schmilzt, der Schnee bricht zusammen, die Berggipfel zerbröckeln."
  },
  AvgCommunicate_150103_Content_6 = {
    Text = "Diese ganze Welt... sie war alles nur Täuschung."
  },
  AvgCommunicate_150103_Content_7 = {
    Text = "Wusstest du es schon immer? Konntest du das schon immer sehen?"
  },
  AvgCommunicate_150103_Content_8 = {
    Text = "Außerhalb der großen Bühne der Welt zu stehen bedeutet, für die Ewigkeit zu weben."
  },
  AvgCommunicate_150103_Content_9 = {
    Text = "Schloss das auch Caraboos Wunsch ein? Die Welt wäre ohne ihn nicht verschwunden."
  },
  AvgCommunicate_150103_Option_3 = {
    Text = "Ich kann es sehen..."
  },
  AvgCommunicate_150103_Option_4 = {
    Text = "Die Welt verschwindet..."
  },
  AvgCommunicate_57593_Content_1 = {
    Text = "Partner, hast du die Bücher über Geschichte und Naturwissenschaften, die ich dir das letzte Mal ausgeliehen habe, schon gelesen?"
  },
  AvgCommunicate_57593_Content_10 = {
    Text = "Huh? Muss es wirklich so ernst sein...?"
  },
  AvgCommunicate_57593_Content_11 = {
    Text = "Das sind essentielle Bücher für Ermittler. Einige musst du auswendig lernen, selbst wenn du es auswendig lernen musst."
  },
  AvgCommunicate_57593_Content_12 = {
    Text = "Ich plane, dich jeden Tag eine Stunde lang zu unterrichten. Wenn du schneller lernen möchtest, macht es mir nichts aus, die ganze Nacht mit dir wach zu bleiben."
  },
  AvgCommunicate_57593_Content_13 = {
    Text = "Langsam... viel langsamer... Ich denke, eine Stunde ist gut genug! Zu viel Lernen ist nicht förderlich für die Überprüfung und Festigung!"
  },
  AvgCommunicate_57593_Content_14 = {
    Text = "Sehr gut, deine Einstellung zum Lernen ist ausgezeichnet."
  },
  AvgCommunicate_57593_Content_15 = {
    Text = "Erinnere dich daran, dein Notizbuch mitzubringen. Ich werde dein Referat jederzeit überprüfen."
  },
  AvgCommunicate_57593_Content_17 = {
    Text = "Ich hasse meinen dreckigen Mund..."
  },
  AvgCommunicate_57593_Content_2 = {
    Text = "Uh, na ja, ein bisschen... habe sie alle beobachtet."
  },
  AvgCommunicate_57593_Content_3 = {
    Text = "Wie viel hast du gesehen?"
  },
  AvgCommunicate_57593_Content_4 = {
    Text = "Wahrscheinlich, einmalig... auf das Inhaltsverzeichnis geschaut."
  },
  AvgCommunicate_57593_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_57593_Content_6 = {
    Text = "Diese Bücher sind viel zu dick und langweilig! Der dichte Text bringt mich allein beim Anschauen zum Schlafen..."
  },
  AvgCommunicate_57593_Content_7 = {
    Text = "Meine Schlafqualität ist tatsächlich ganz gut, nachdem ich Bücher gelesen habe..."
  },
  AvgCommunicate_57593_Content_8 = {
    Text = "Never mind. Komm später zu mir, und ich erkläre es dir Buch für Buch."
  },
  AvgCommunicate_57593_Content_9 = {
    Text = "Berichte nach dem Unterricht jeden Tag in mein Zimmer."
  },
  AvgCommunicate_57593_Option_10 = {
    Text = "Huh? Muss es wirklich so ernst sein...?"
  },
  AvgCommunicate_57593_Option_13 = {
    Text = "Immer noch... langsamer wäre besser..."
  },
  AvgCommunicate_57593_Option_2 = {Text = "Äh"},
  AvgCommunicate_57593_Option_4 = {
    Text = "Wahrscheinlich, einmalig... auf das Inhaltsverzeichnis geschaut."
  },
  AvgCommunicate_57593_Option_6 = {
