  },
  AvgCommunicate_57594_Content_1 = {
    Text = "Partner, hier sind die Notizen und Hausarbeiten, die du während der letzten Mission verpasst hast."
  },
  AvgCommunicate_57594_Content_10 = {Text = "Richtig?!"},
  AvgCommunicate_57594_Content_12 = {
    Text = "Kein Problem, das ist es, was Partner tun sollten."
  },
  AvgCommunicate_57594_Content_13 = {
    Text = "Lehrerin Puppe ist ebenfalls erfreut und hat beschlossen, eine exklusive Bonusfrage für dich zu entwerfen."
  },
  AvgCommunicate_57594_Content_2 = {
    Text = "Erinnere dich daran, es einzureichen."
  },
  AvgCommunicate_57594_Content_3 = {
    Text = "Lass Vergangenes Vergangenheit sein..."
  },
  AvgCommunicate_57594_Content_4 = {
    Text = "Warum ist mein Signal plötzlich schlecht?"
  },
  AvgCommunicate_57594_Content_6 = {
    Text = "Oh wirklich? Ich habe vergessen, dir zu sagen; Lehrerin Puppe ist direkt neben mir und schaut."
  },
  AvgCommunicate_57594_Content_7 = {
    Text = "Plötzlich überwältigt von einer brennenden Leidenschaft für das Studium."
  },
  AvgCommunicate_57594_Content_8 = {
    Text = "Wie kann ich überhaupt unvollendete Hausaufgaben ignorieren?!"
  },
  AvgCommunicate_57594_Content_9 = {
    Text = "So wirst du mir definitiv helfen, meinen Unterricht aufzuholen, richtig, Partner?"
  },
  AvgCommunicate_57594_Option_3 = {
    Text = "Lass Vergangenes Vergangenheit sein..."
  },
  AvgCommunicate_57594_Option_4 = {
    Text = "Warum ist mein Signal plötzlich schlecht?"
  },
  AvgCommunicate_57594_Option_7 = {
    Text = "Plötzlich überwältigt von einer brennenden Leidenschaft für das Studium."
  },
  AvgCommunicate_57595_Content_1 = {
    Text = "Keeper, du hast gesagt..."
  },
  AvgCommunicate_57595_Content_10 = {
    Text = "Ich werde einige Duellankündigungen schreiben und sie an die Wohnheime aller schicken; das sollte höflich genug sein."
  },
  AvgCommunicate_57595_Content_11 = {
    Text = "Es ist beschlossen. Sind vierzig Blätter genug...?"
  },
  AvgCommunicate_57595_Content_12 = {
    Text = "?! Warte, es geht nicht um die Duell-Einladung, oder? Das ist viel zu störend!"
  },
  AvgCommunicate_57595_Content_13 = {
    Text = "Du verstehst nicht. Dexter hat mir gesagt, dass es in der Vergangenheit als Gentleman-Akt galt, durch Duellbücher zu kämpfen. Lerne daraus, junger Mann!"
  },
  AvgCommunicate_57595_Content_14 = {
