  },
  AvgCommunicate_57595_Content_2 = {Text = "?"},
  AvgCommunicate_57595_Content_3 = {
    Text = "Warum ist niemand mehr bereit, mit mir zu kämpfen?"
  },
  AvgCommunicate_57595_Content_4 = {
    Text = "Uh... vielleicht ist deine Aura zu überwältigend."
  },
  AvgCommunicate_57595_Content_5 = {
    Text = "Jeder empfindet zu viel Stress."
  },
  AvgCommunicate_57595_Content_6 = {
    Text = "So ist es also. Ich verstehe. Ja, meine Einstellung war ein wenig hart."
  },
  AvgCommunicate_57595_Content_7 = {
