  },
  AvgCommunicate_57595_Option_2 = {Text = "?"},
  AvgCommunicate_57595_Option_4 = {
    Text = "Uh... vielleicht ist deine Aura zu überwältigend."
  },
  AvgCommunicate_57595_Option_7 = {
    Text = "Wie bemerkenswert von dir!"
  },
  AvgCommunicate_57595_Option_8 = {
    Text = "Es ist nicht nur ein Einstellungsproblem!"
  },
  AvgCommunicate_57596_Content_1 = {
    Text = "Wo bist du?"
  },
  AvgCommunicate_57596_Content_2 = {
    Text = "Ich ruhe mich im Aufenthaltsraum aus. Ist etwas nicht in Ordnung?"
  },
  AvgCommunicate_57596_Content_3 = {Text = "Ruhest du?"},
  AvgCommunicate_57596_Content_4 = {
    Text = "Wer hat mir gesagt, dass wir heute um 12 Uhr eine spezielle Ausbildung zusammen haben würden?"
  },
  AvgCommunicate_57596_Content_5 = {
    Text = "Vorschlägst du, dass wir uns jetzt ausruhen?"
  },
  AvgCommunicate_57596_Content_6 = {Text = "Oh nein..."},
  AvgCommunicate_57596_Content_7 = {
    Text = "Du musst dich falsch erinnert haben. Es war auf jeden Fall Alva, die das gesagt hat."
  },
  AvgCommunicate_57596_Content_8 = {
    Text = "Alright, du Halunke, warte nur ab."
  },
  AvgCommunicate_57596_Option_2 = {
    Text = "Ich bin im Wohnheim."
  },
