  AvgCommunicate_57903_Content_1 = {
    Text = "Guten Tag, blasser Bote."
  },
  AvgCommunicate_57903_Content_10 = {
    Text = "Ich muss sagen, es ist ziemlich genial."
  },
  AvgCommunicate_57903_Content_2 = {
    Text = "Hallo, Bischof Salvador."
  },
  AvgCommunicate_57903_Content_3 = {
    Text = "Es scheint, dass du das neueste Kommunikationsgerät erhalten hast. Was hältst du davon?"
  },
  AvgCommunicate_57903_Content_4 = {
    Text = "Es ist ziemlich interessant und praktisch. Auch wenn wir Hunderte von Meilen entfernt sind, können wir immer noch kommunizieren, als ob wir uns von Angesicht zu Angesicht gegenüberstehen."
  },
  AvgCommunicate_57903_Content_5 = {
    Text = "Wenn die ganze Welt solche Geräte hätte, wäre die Distanz zwischen den Menschen nicht so groß wie jetzt."
  },
  AvgCommunicate_57903_Content_6 = {
    Text = "Aber ich verstehe die Einzigartigkeit dieser Technologie—du weißt, dass es Informationen über die Verbindung zu anderen Geistern überträgt, oder?"
  },
  AvgCommunicate_57903_Content_7 = {
    Text = "Ich weiß nur, dass da Silber drin ist."
  },
  AvgCommunicate_57903_Content_8 = {
    Text = "Hast du es gesehen?"
  },
  AvgCommunicate_57903_Content_9 = {
