    Text = "Wenn ich mit Macht zurückkomme, werde ich hundertfach vergelten."
  },
  AvgCommunicate_57988_Content_12 = {
    Text = "So bist du tatsächlich gekommen, um Geld zu leihen!"
  },
  AvgCommunicate_57988_Content_13 = {
    Text = "Zu viele Dinge, über die man sich beschweren könnte, ich weiß nicht, wo ich anfangen soll!"
  },
  AvgCommunicate_57988_Content_14 = {
    Text = "Obwohl es Ihnen nicht leichtfällt, an der Angelegenheit der Abstammung festzuhalten, denke ich, dass Sie vielleicht die Möglichkeit in Betracht ziehen sollten, getäuscht worden zu sein."
  },
  AvgCommunicate_57988_Content_15 = {
    Text = "Ist das so? Also glaubst selbst du mir nicht."
  },
  AvgCommunicate_57988_Content_16 = {
    Text = "Ich habe nicht... ich habe wirklich nicht..."
  },
  AvgCommunicate_57988_Content_17 = {
    Text = "Alright, ich werde mir etwas einfallen lassen. Wenn ich zurückkomme, werde ich euch alle sicherlich überraschen."
  },
  AvgCommunicate_57988_Content_2 = {
    Text = "Was ist los? Gibt es etwas, das du von mir brauchst?"
  },
  AvgCommunicate_57988_Content_3 = {
    Text = "Ich habe ein Heilmittel entdeckt, das die Blutlinienkräfte erwecken kann."
  },
  AvgCommunicate_57988_Content_4 = {
    Text = "Sie sagen, dass ich mit diesem Hausmittel die gleiche Macht wie Lord Goliath besitzen werde."
  },
  AvgCommunicate_57988_Content_5 = {
    Text = "Das ist gut, aber warum fühlt es sich ein wenig verdächtig an?"
  },
  AvgCommunicate_57988_Content_6 = {
    Text = "Ich weiß, dass du vielleicht neidisch auf diese Macht bist, aber das ist in Ordnung. Ich werde es alleine versuchen."
  },
  AvgCommunicate_57988_Content_7 = {
    Text = "Uh... Auch wenn ich nicht weiß, warum du so denkst, viel Glück dann."
