  },
  AvgCommunicate_57990_Content_5 = {
    Text = "Ich werde in einem Monat eine kleine Aufführung im Mythag-Haus geben. Ich möchte, dass jemand mein Lied vorher hört."
  },
  AvgCommunicate_57990_Content_6 = {
