  },
  AvgCommunicate_57991_Content_7 = {
    Text = "Nachdem ich zurückgekehrt war, habe ich lange und gründlich nachgedacht."
  },
  AvgCommunicate_57991_Content_8 = {
    Text = "Obwohl durch traditionelle Augen betrachtet, fehlt diesem Vers die notwendige ästhetische Verbindung."
