  },
  AvgCommunicate_58020_Content_6 = {
    Text = "Aber wenn ich dich vermisse, kann ich dir eine Nachricht senden?"
  },
  AvgCommunicate_58020_Content_7 = {
    Text = "Natürlich!"
  },
  AvgCommunicate_58020_Content_8 = {
    Text = "Wir werden immer die besten Partner sein."
  },
  AvgCommunicate_58020_Content_9 = {
    Text = "Vielen Dank."
  },
  AvgCommunicate_58020_Option_7 = {
    Text = "Natürlich!"
  },
  AvgCommunicate_58021_Content_2 = {
    Text = "Eine weitere Runde?"
  },
  AvgCommunicate_58021_Content_4 = {
    Text = "Verschone mich..."
  },
  AvgCommunicate_58021_Content_5 = {
    Text = "Hmph, gestehst du die Niederlage ein?"
  },
  AvgCommunicate_58021_Content_6 = {
    Text = "Warum, warum würde eine Königin aus einem uralten Stamm..."
  },
  AvgCommunicate_58021_Content_7 = {
    Text = "Kartenfertigkeiten sind exquisiter als die der modernen Menschen..."
  },
  AvgCommunicate_58021_Content_8 = {
    Text = "Alles, was ich dir sagen kann, ist, dass Übung den Meister macht, mein kleines Kind."
  },
  AvgCommunicate_58021_Content_9 = {
    Text = "Wenn du mein Alter erreichst, wirst du es ganz natürlich verstehen~"
  },
  AvgCommunicate_58021_Option_6 = {Text = "Warum"},
  AvgCommunicate_58498_Content_1 = {
    Text = "Guten Abend, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgCommunicate_58498_Content_11 = {
    Text = "Ein Kind, das das eine sagt, aber etwas anderes meint"
  },
  AvgCommunicate_58498_Content_12 = {
    Text = "Treffen Sie sich am Eingang zur Kapelle, seien Sie nicht zu spät~"
  },
  AvgCommunicate_58498_Content_2 = {
    Text = "Ich habe kürzlich eine wertvolle Peitsche aus Pferdehaar erworben. Hättest du Interesse, es auszuprobieren?"
  },
  AvgCommunicate_58498_Content_3 = {
    Text = "Beschäftigt"
  },
  AvgCommunicate_58498_Content_4 = {
    Text = "Entschuldigung, ich bin beschäftigt."
  },
  AvgCommunicate_58498_Content_6 = {
    Text = "Herzzerreißend. Es scheint, dass ich auf dem Campus umherwandern muss, um zu sehen, ob ich andere gleichgesinnte Enthusiasten finden kann..."
  },
  AvgCommunicate_58498_Content_7 = {Text = "!!"},
  AvgCommunicate_58498_Content_8 = {
    Text = "Warte, Frau Wanda! Bleib, wo du bist, und beweg dich nicht."
  },
  AvgCommunicate_58498_Content_9 = {
    Text = "Ich bin auf dem Weg."
  },
  AvgCommunicate_58498_Option_3 = {
    Text = "Beschäftigt."
  },
  AvgCommunicate_58498_Option_4 = {
    Text = "Entschuldigung, ich bin beschäftigt."
  },
  AvgCommunicate_58498_Option_7 = {Text = "!!"},
  AvgCommunicate_60943_Content_1 = {
    Text = "Partner, uns fehlen Leute. Ich muss allein frühzeitig am Einsatzort Vorbereitungen treffen und kann mich euch diesmal nicht anschließen."
  },
  AvgCommunicate_60943_Content_10 = {
    Text = "Ich weiß. Du nimmst immer auf alle Rücksicht."
  },
  AvgCommunicate_60943_Content_11 = {
    Text = "Aber solltest du nicht langsam lernen, mir deinen Rücken anzuvertrauen? Partner."
  },
  AvgCommunicate_60943_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_60943_Content_13 = {
    Text = "Du hast recht."
  },
  AvgCommunicate_60943_Content_14 = {
    Text = "Diesmal zähle ich auf deine Unterstützung, Partner."
  },
  AvgCommunicate_60943_Content_2 = {
    Text = "Ich habe mehrere Notfallpläne für dich vorbereitet. Im Falle eines Notfalls kannst du im entsprechenden Verzeichnis nachschlagen."
  },
  AvgCommunicate_60943_Content_3 = {
    Text = "Außerdem habe ich eine zusätzliche Notfall-Gnosis für dich angefordert. Auch wenn das Personal knapp ist, werde ich versuchen, jemand anderen zu organisieren, der dich begleitet."
  },
  AvgCommunicate_60943_Content_4 = {Text = "Ramona."},
  AvgCommunicate_60943_Content_5 = {
    Text = "Ich weiß, dass du dir um mich Sorgen machst. Danke für alles, was du getan hast."
  },
  AvgCommunicate_60943_Content_6 = {
    Text = "Aber ich bin nicht mehr die schwache und naive Anfängerin. Ich kann das bewältigen."
  },
  AvgCommunicate_60943_Content_7 = {
    Text = "Natürlich, ich vertraue deinen Fähigkeiten, es ist nur..."
  },
  AvgCommunicate_60943_Content_8 = {
    Text = "Entschuldigung, ich bin es gewohnt, alles zu simulieren. Wenn ich nicht in der Nähe bin, kann ich nicht anders, als mir die schlimmsten Möglichkeiten vorzustellen."
  },
  AvgCommunicate_60943_Content_9 = {
    Text = "Ich kann nicht akzeptieren, dass ich das schlimmste Ergebnis nicht verhindern konnte..."
  },
  AvgCommunicate_60943_Option_10 = {
    Text = "Ich weiß. Du nimmst immer auf alle Rücksicht."
  },
  AvgCommunicate_60943_Option_4 = {Text = "Ramona."},
  AvgCommunicate_66973_Content_1 = {
    Text = "Schutzherr, danke für den Vorschlag, dass meine Schwester und ich gemeinsam zur Feier gehen."
  },
  AvgCommunicate_66973_Content_10 = {
    Text = "Sie sieht so süß aus, wenn sie errötet, Schwesterchen."
  },
  AvgCommunicate_66973_Content_11 = {
    Text = "Mm, die Verbindung zwischen euch Schwestern ist wirklich tief..."
  },
  AvgCommunicate_66973_Content_12 = {
    Text = "Natürlich, meine Schwester wird immer die wichtigste Person für mich sein, und ich werde mich weiterhin um sie kümmern."
  },
  AvgCommunicate_66973_Content_13 = {
    Text = "Sieht so aus, als wäre ich beim nächsten Treffen an der Reihe, meine Schwester anzuleiten."
  },
  AvgCommunicate_66973_Content_14 = {
    Text = "Wenn sich die Gelegenheit ergibt, solltet ihr Schutzherren euch uns auch mal anschließen und Spaß haben!"
  },
  AvgCommunicate_66973_Content_15 = {
    Text = "Kein Problem!"
  },
  AvgCommunicate_66973_Content_2 = {
    Text = "Gern geschehen! Freut mich, helfen zu können!"
  },
  AvgCommunicate_66973_Content_3 = {
    Text = "Ich habe mich immer auf meine Schwester verlassen. Sie wirkte vor mir immer stark, sogar ein bisschen hart."
  },
  AvgCommunicate_66973_Content_4 = {
    Text = "Ich hätte nie erwartet, dass selbst meine Schwester in dieser Situation so nervös wird. Ich habe sie noch nie so schüchtern gesehen."
  },
  AvgCommunicate_66973_Content_5 = {
    Text = "Hm? Ich dachte immer, Faint hätte so eine introvertierte Persönlichkeit."
  },
  AvgCommunicate_66973_Content_6 = {
    Text = "Nein, tatsächlich ist meine Schwester extrem willensstark und entschlossen!"
  },
  AvgCommunicate_66973_Content_7 = {
    Text = "In meinen Momenten der Verwirrung und Verletzlichkeit hat meine Schwester mir immer Ratschläge gegeben und mich mit sanftem Kopfstreicheln getröstet."
  },
  AvgCommunicate_66973_Content_8 = {
    Text = "Verstehe, das ist unerwartet."
  },
  AvgCommunicate_66973_Content_9 = {
    Text = "Aber jetzt sind wir keinen Überlebensbedrohungen mehr ausgesetzt, und meine Schwester kann endlich offen Freundschaften schließen."
  },
  AvgCommunicate_66973_Option_11 = {
    Text = "Mm, die Verbindung zwischen euch Schwestern ist wirklich stark..."
  },
  AvgCommunicate_66973_Option_15 = {
