  AvgCommunicate_66974_Content_1 = {
    Text = "Ich habe Hunger."
  },
  AvgCommunicate_66974_Content_10 = {
    Text = "Natürlich..."
  },
  AvgCommunicate_66974_Content_11 = {
    Text = "Ich habe Hunger!"
  },
  AvgCommunicate_66974_Content_12 = {
    Text = "Schon gut, in Ordnung... Wie wäre es, wenn du mein Blut trinkst? Probier ein bisschen, um deinen Durst zu stillen."
  },
  AvgCommunicate_66974_Content_13 = {
    Text = "Du bist so gut zu mir."
  },
  AvgCommunicate_66974_Content_14 = {
    Text = "Einfach ein kleiner Schluck! Mehr wäre tödlich!"
  },
  AvgCommunicate_66974_Content_15 = {
    Text = "Hmm, ich geb mir Mühe."
  },
  AvgCommunicate_66974_Content_16 = {
    Text = "Du hast mich geschlagen, weil ich zu viel getrunken habe."
  },
  AvgCommunicate_66974_Content_2 = {
    Text = "Gibt es in der Kantine kein Essen?"
  },
  AvgCommunicate_66974_Content_3 = {
    Text = "Ich will Blut trinken."
  },
  AvgCommunicate_66974_Content_4 = {
    Text = "Was ist mit den Blutkonserven, die ich dir vorhin aus dem Krankenhaus mitgebracht habe?"
  },
  AvgCommunicate_66974_Content_5 = {
    Text = "Ausgetrunken."
  },
  AvgCommunicate_66974_Content_6 = {
    Text = "Zack, alles leer? Heb dir was auf! Nächstes Mal verteile ich es strikt auf Wochenbasis."
  },
  AvgCommunicate_66974_Content_7 = {
    Text = "War beim Schlachthof, hab jemanden verprügelt und Kuhblut probiert. Schmeckt nicht."
  },
  AvgCommunicate_66974_Content_8 = {
    Text = "Wann ist das passiert?! Egal, darüber reden wir später... Also, was willst du tun?"
  },
  AvgCommunicate_66974_Content_9 = {
    Text = "Menschenblut trinken hast du mir verboten."
  },
  AvgCommunicate_66974_Option_10 = {
    Text = "Natürlich..."
  },
  AvgCommunicate_66974_Option_12 = {
    Text = "Schon gut, schon gut, lass mich nachdenken..."
  },
  AvgCommunicate_66974_Option_14 = {
    Text = "Einfach ein kleiner Schluck! Mehr wäre tödlich!"
  },
  AvgCommunicate_66974_Option_2 = {
    Text = "Gibt es in der Kantine kein Essen?"
  },
  AvgCommunicate_66974_Option_4 = {
    Text = "Was ist mit den Blutkonserven, die ich dir vorhin aus dem Krankenhaus mitgebracht habe?"
  },
  AvgCommunicate_66974_Option_6 = {
    Text = "Zack, alles weg? Heb dir was für später auf!"
  },
  AvgCommunicate_66974_Option_8 = {
    Text = "Wann war das?!"
  },
  AvgCommunicate_66975_Content_1 = {
    Text = "Meister!! Meine Welt, mein Leben, alles ist zusammengebrochen! Buhuhu—"
  },
  AvgCommunicate_66975_Content_10 = {
    Text = "Das ist ziemlich gut."
  },
  AvgCommunicate_66975_Content_11 = {
    Text = "Hmph, Karen biss die Zähne zusammen, gab all seine Ersparnisse aus, um diese Ornamente zu kaufen, und trug sie alle."
  },
  AvgCommunicate_66975_Content_12 = {
    Text = "Hm... Ist das nicht zu schwer für dich?"
  },
  AvgCommunicate_66975_Content_13 = {
    Text = "Als Karen dann Frau Sorel bediente, hat die Dame sofort auf den ersten Blick erklärt, dass die Edelsteine Fälschungen sind! Sie waren gefälscht!"
  },
  AvgCommunicate_66975_Content_14 = {
    Text = "Was ist passiert? Wie viel hat sie dir abgeknöpft?"
  },
  AvgCommunicate_66975_Content_15 = {
    Text = "Vollständige 500 Leo Fänge!!"
  },
  AvgCommunicate_66975_Content_16 = {
    Text = "500 Mäuse für echte Steine? Lächerlich! Was ist mit den Ersparnissen, die du erwähnt hast??"
  },
  AvgCommunicate_66975_Content_17 = {
    Text = "Weil Karen glitzernde Sachen so liebt, gibt sie all ihr Geld dafür aus, deshalb hat sie nicht viel gespart..."
  },
  AvgCommunicate_66975_Content_18 = {
    Text = "Vergiss es... Wenn du einfach nur glitzernde Steine magst, dann glitzern diese tatsächlich genug und sind sorgfältig gearbeitet."
  },
  AvgCommunicate_66975_Content_19 = {
    Text = "Du hast eine Menge gespart, weil du nicht die echten gekauft hast. Worüber willst du da traurig sein?"
  },
  AvgCommunicate_66975_Content_2 = {
    Text = "?? Was ist denn los?"
  },
  AvgCommunicate_66975_Content_20 = {
    Text = "Oh, da hast du einen guten Punkt."
  },
  AvgCommunicate_66975_Content_21 = {
    Text = "Karen hat sofort das Gefühl, einen Vorteil gewonnen zu haben. Danke, Meister!"
  },
  AvgCommunicate_66975_Content_3 = {
    Text = "Daffodil, diese hinterhältige Frau! Sie hat Karen um all ihre hart verdienten Ersparnisse der letzten Jahre betrogen!"
  },
  AvgCommunicate_66975_Content_4 = {
    Text = "Hat Daffodil dich betrogen? Was hast du bei ihr gekauft?"
  },
  AvgCommunicate_66975_Content_5 = {
    Text = "Karen hat doch nur über die Preise von Schmuck in Zeitschriften geseufzt, und dann hat diese fiese Frau das mitbekommen!"
  },
  AvgCommunicate_66975_Content_6 = {
    Text = "Sie hat Karen erzählt, sie hätte eine Ladung reduzierter Edelsteinschmuckstücke, die sich wegen veralteter Designs nicht verkauft hätten, aber sie würden perfekt zu Karens Retro–Stil passen..."
  },
  AvgCommunicate_66975_Content_7 = {
    Text = "Vintage–Charme? Du??"
  },
  AvgCommunicate_66975_Content_8 = {
    Text = "Was denn? Karen liebt diese glitzernden kleinen Steinchen einfach zu sehr..."
  },
  AvgCommunicate_66975_Content_9 = {
    Text = "Die böse Frau hat Karen die Juwelen gezeigt, eins glänzender als das andere, und Karens Herz war sofort verzaubert!"
  },
  AvgCommunicate_66975_Option_10 = {
    Text = "Das ist ziemlich gut."
  },
  AvgCommunicate_66975_Option_12 = {
    Text = "Hm... Ist das nicht zu schwer für dich?"
  },
  AvgCommunicate_66975_Option_14 = {
    Text = "Was ist passiert? Wie viel hat sie dir abgeknöpft?"
  },
  AvgCommunicate_66975_Option_16 = {
    Text = "500 Mäuse für echte Steine? Lächerlich! Was ist mit den Ersparnissen, die du erwähnt hast??"
  },
  AvgCommunicate_66975_Option_18 = {
    Text = "Schon gut..."
  },
  AvgCommunicate_66975_Option_2 = {
    Text = "?? Was ist denn los?"
  },
  AvgCommunicate_66975_Option_4 = {
    Text = "Hat Daffodil dich betrogen? Was hast du bei ihr gekauft?"
  },
  AvgCommunicate_66975_Option_7 = {
