  },
  AvgCommunicate_66976_Content_1 = {
    Text = "Ähm, {Male=Mr.,Female=Miss} %player%, ich glaube, ich bin in Schwierigkeiten geraten."
  },
  AvgCommunicate_66976_Content_10 = {
    Text = "Ah, tut mir leid, ich habe wieder allen Probleme gemacht."
  },
  AvgCommunicate_66976_Content_11 = {
    Text = "Ich werde den Hut zurückgeben und etwas Trockenfisch mitbringen, um die Schulkater zu entschädigen."
  },
  AvgCommunicate_66976_Content_12 = {
    Text = "Die Schulkatze könnte Silber Fragment dem Trockenfisch vorziehen..."
  },
  AvgCommunicate_66976_Content_13 = {
    Text = "Ist das so? Vielen Dank für Ihre Hilfe! Ich werde mein Bestes tun, um mehr zu sammeln!"
  },
  AvgCommunicate_66976_Content_2 = {
    Text = "Weißt du, wem dieser kleine schwarzer Zylinder gehört?"
  },
  AvgCommunicate_66976_Content_3 = {
    Text = "Diese Größe scheint für Erwachsene nicht geeignet zu sein, aber ich kann mich nicht erinnern, dass ein Kind einen so hohen Hut getragen hat."
  },
  AvgCommunicate_66976_Content_4 = {
    Text = "Ein kleiner schwarzer Zylinderhut? Könnte es der Hut der Schulkater sein?!"
  },
  AvgCommunicate_66976_Content_5 = {
    Text = "Was ist los? Warum hast du die Mütze der Schulkatze?"
  },
  AvgCommunicate_66976_Content_6 = {
    Text = "Schulkatze? Kein Wunder, dass mein Katzendasein gerade für eine Weile aufgetaucht ist."
  },
  AvgCommunicate_66976_Content_7 = {
    Text = "Ich kann mich kaum erinnern, aber es scheint, als hätte sie sich mit jemandem gestritten."
  },
  AvgCommunicate_66976_Content_8 = {
    Text = "Dann schnappte sie sich den Hut des anderen... Sie schien diesen Hut sehr zu mögen."
  },
  AvgCommunicate_66976_Option_12 = {
    Text = "Die Schulkatze könnte Silber Fragment dem Trockenfisch vorziehen..."
  },
  AvgCommunicate_66976_Option_4 = {
    Text = "Ein kleiner schwarzer Zylinderhut? Könnte es der Hut der Schulkater sein?!"
  },
  AvgCommunicate_66977_Content_1 = {
    Text = "Hüter! Habe ich dir gerade Plätzchen geliefert?"
  },
  AvgCommunicate_66977_Content_10 = {
    Text = "Was soll ich tun, ich habe dich wieder in Schwierigkeiten gebracht, ich gehe jetzt, um Frau Sylwia zu kontaktieren!"
  },
  AvgCommunicate_66977_Content_11 = {
    Text = "Warte, warte mal, egal... Ich weiß, was sie hineingetan hat..."
  },
  AvgCommunicate_66977_Content_12 = {
    Text = "Was? Was ist los, Hüter?"
  },
  AvgCommunicate_66977_Content_13 = {
    Text = "Es ist ein Abführmittel... Ich muss sofort die Toilette benutzen..."
  },
  AvgCommunicate_66977_Content_14 = {
    Text = "Das Papier in meinem Raum könnte ausgehen. Denk daran, mir später welches mitzubringen..."
  },
  AvgCommunicate_66977_Content_15 = {
    Text = "Alright, alright, ich werde es tun! Entschuldigung!!"
  },
  AvgCommunicate_66977_Content_2 = {
    Text = "Uh, richtig? Ich habe gerade gegessen. Es war lecker. Deine Fähigkeiten verbessern sich wirklich."
  },
  AvgCommunicate_66977_Content_3 = {
    Text = "Ah! Gott! Ich wollte dir sagen, dass du diese Kekse nicht essen sollst! Sie wurden nicht von mir gemacht!"
  },
  AvgCommunicate_66977_Content_4 = {
    Text = "Was? Nicht von dir gemacht?"
  },
  AvgCommunicate_66977_Content_5 = {
    Text = "Ja, diejenige, die dir vorhin Plätzchen gegeben hat, ist meine neu entstandene Persönlichkeit. Sie liebt Unfug..."
  },
  AvgCommunicate_66977_Content_6 = {
    Text = "Ich erinnere mich vage, dass sie beim Plätzchenbacken etwas hinzugefügt hat... Wie auch immer, fühlen Sie sich gerade unwohl?"
  },
  AvgCommunicate_66977_Content_7 = {
    Text = "Jetzt, wo du es erwähnst, fühle ich mich plötzlich ganz furchtbar..."
  },
  AvgCommunicate_66977_Content_8 = {
    Text = "Was hat sie hineingetan? Es kann sich doch nicht um ein tödliches Gift handeln, oder??"
  },
  AvgCommunicate_66977_Content_9 = {
    Text = "Unwahrscheinlich! Sie genießt einfach Streiche und ist nicht so böse."
  },
  AvgCommunicate_66977_Option_11 = {
    Text = "Warte, warte mal, egal..."
  },
  AvgCommunicate_66977_Option_13 = {
    Text = "Es ist ein Abführmittel..."
  },
  AvgCommunicate_66977_Option_2 = {
    Text = "Uh, richtig?"
  },
  AvgCommunicate_66977_Option_4 = {
    Text = "Was? Nicht von dir gemacht?"
  },
  AvgCommunicate_66977_Option_7 = {
    Text = "Jetzt, wo du es erwähnst, fühle ich mich plötzlich ganz furchtbar..."
  },
  AvgCommunicate_66978_Content_1 = {
    Text = "Hey! Hilf mir! Ich habe mich in der Decke verfangen!"
  },
  AvgCommunicate_66978_Content_10 = {
    Text = "Dies ist die einfachste Hausarbeit. Du hast wirklich den Kontakt zum Leben verloren."
  },
  AvgCommunicate_66978_Content_11 = {
    Text = "Hmph... Ich werde Sklaven von jetzt an sanfter behandeln. Jetzt, geh und finde mir einige fleißige!"
  },
  AvgCommunicate_66978_Content_12 = {
    Text = "Ich habe dir bereits gesagt, Rom ist gefallen!"
  },
  AvgCommunicate_66978_Content_13 = {
    Text = "Du musst in dieser gesetzestreuen Gesellschaft träumen!"
  },
  AvgCommunicate_66978_Content_14 = {
    Text = "Es ist mir egal! Es ist mir egal! Ich sterbe lieber, als jeden Tag diese Hausarbeiten zu machen!"
  },
  AvgCommunicate_66978_Content_15 = {
    Text = "Hehe, nicht nur Hausarbeiten, sondern auch Hausaufgaben."
  },
  AvgCommunicate_66978_Content_16 = {
    Text = "Ich werde dich ins Labyrinth werfen, um meine Nachkommen zu füttern!"
  },
  AvgCommunicate_66978_Content_2 = {
    Text = "? Von was gebissen??"
  },
  AvgCommunicate_66978_Content_3 = {
    Text = "Es ist alles deine Schuld, dass du mir keine Diener zugewiesen hast!! Wer hätte gedacht, dass dieses verdammte Bettlaken so schwer zu wechseln wäre?!"
  },
  AvgCommunicate_66978_Content_4 = {
    Text = "Egal wie sehr ich es versuchte, ich konnte es nicht herausfinden, und aus Frustration habe ich schließlich mit der Decke gekämpft!"
  },
  AvgCommunicate_66978_Content_5 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgCommunicate_66978_Content_6 = {
    Text = "Wofür stehst du da? Beeil dich und hilf mir! Ich kann nicht raus!"
  },
  AvgCommunicate_66978_Content_7 = {
    Text = "Manchmal wundere ich mich, wie jemand wie du so lange überlebt hat."
  },
  AvgCommunicate_66978_Content_8 = {
    Text = "Das sind Aufgaben für Sklaven. Warum sind sie so schwierig...?"
  },
  AvgCommunicate_66978_Content_9 = {
    Text = "Haben diese Sklaven das jeden Tag gemacht? Unmöglich! Wie haben sie das geschafft?"
  },
  AvgCommunicate_66978_Option_10 = {
