  },
  AvgCommunicate_66978_Option_2 = {
    Text = "? Von was gebissen??"
  },
  AvgCommunicate_66978_Option_5 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgCommunicate_66978_Option_7 = {
    Text = "Manchmal wundere ich mich, wie jemand wie du so lange überlebt hat."
  },
  AvgCommunicate_66979_Content_1 = {
    Text = "Schutzherr, der Kuchen, den du gerade zum Schwarzen Becken geschickt hast, war für den Geburtstag des langjährigen Mitarbeiters, der für die Herstellung der Silberschlüssel zuständig ist, richtig?"
  },
  AvgCommunicate_66979_Content_10 = {
    Text = "Pff, ich verstehe. Ich schicke dir sofort noch einen!"
  },
  AvgCommunicate_66979_Content_11 = {
    Text = "Vielen Dank."
  },
  AvgCommunicate_66979_Content_2 = {
    Text = "Mm! Obwohl sie wissen, dass du nicht isst, wollten sie, dass du am Spaß teilhast, also haben sie es durchgehen lassen."
  },
  AvgCommunicate_66979_Content_3 = {
    Text = "Danke für die Freundlichkeit. Bitte richte meine Geburtstagswünsche aus und frage, ob noch ein Kuchen geschickt werden kann?"
  },
  AvgCommunicate_66979_Content_4 = {
    Text = "Hmm? Du hast ihn tatsächlich gegessen?!"
  },
  AvgCommunicate_66979_Content_5 = {
    Text = "Einer Laune folgend. Dieser Mitarbeiter hat viele Jahre mit mir gearbeitet, ohne einen einzigen Fehler zu machen."
  },
  AvgCommunicate_66979_Content_6 = {
    Text = "Obwohl ich über endloses Wissen verfüge und alle Prinzipien verstehe, habe ich tatsächlich noch nie Kuchen gegessen."
  },
  AvgCommunicate_66979_Content_7 = {
    Text = "Du hast also nur theoretisches Wissen über Kuchen?"
  },
  AvgCommunicate_66979_Content_8 = {
    Text = "Ja, ich kenne alle Zutaten dieses Kuchens und sein süßes, buttrig-tierisches Aroma."
  },
  AvgCommunicate_66979_Content_9 = {
    Text = "Aber ich hätte nicht erwartet, dass der Kuchen so süß und wohlriechend schmeckt..."
  },
  AvgCommunicate_66979_Option_10 = {
    Text = "Puh, ich verstehe."
  },
  AvgCommunicate_66979_Option_2 = {Text = "...Okay!"},
  AvgCommunicate_66979_Option_4 = {
    Text = "Hmm? Du hast ihn tatsächlich gegessen?!"
  },
  AvgCommunicate_66979_Option_7 = {
    Text = "Du hast also nur theoretisches Wissen über Kuchen?"
  },
  AvgCommunicate_66980_Content_1 = {
    Text = "Entschuldigen Sie, wofür wird diese komplexe mechanische Box verwendet?"
  },
  AvgCommunicate_66980_Content_10 = {
    Text = "Hör auf zu forschen! Es ist nicht wichtig. Wenn es kaputt geht, wird es sehr teuer!"
  },
  AvgCommunicate_66980_Content_11 = {
    Text = "Alright, wofür wird diese Box benutzt?"
  },
  AvgCommunicate_66980_Content_12 = {
    Text = "Das ist der Kommunikator, der von der Schule für die Fernkommunikation ausgegeben wurde. Er kann auch genutzt werden, um in gefährlichen Situationen Hilfe zu rufen."
  },
  AvgCommunicate_66980_Content_13 = {
    Text = "Ich verstehe, was für eine interessante Erfindung. Danke, Hüter."
  },
  AvgCommunicate_66980_Content_14 = {
    Text = "Erinnerst du dich wirklich daran, wer ich bin?"
  },
  AvgCommunicate_66980_Content_15 = {
    Text = "Ich erinnere mich. Ich habe versprochen, dass ich nicht vergessen werde."
  },
  AvgCommunicate_66980_Content_16 = {
    Text = "Du bist %player%, mein Freund!"
  },
  AvgCommunicate_66980_Content_2 = {
    Text = "? Hast du alles vergessen?"
  },
  AvgCommunicate_66980_Content_3 = {
    Text = "Vergessen? Ich kann mich nicht erinnern, woher diese Kiste kommt."
  },
  AvgCommunicate_66980_Content_4 = {
    Text = "Aber ich habe die Chatprotokolle gesehen. Ich denke, ich habe es schon einmal benutzt, aber ich habe vergessen, wie."
  },
  AvgCommunicate_66980_Content_5 = {
    Text = "Wie benutzt du es jetzt?!"
  },
  AvgCommunicate_66980_Content_6 = {Text = "Hehe."},
  AvgCommunicate_66980_Content_7 = {
    Text = "Lache nicht über meine Angst!"
  },
  AvgCommunicate_66980_Content_8 = {
    Text = "Ich habe es auseinander genommen und wieder zusammengesetzt, und jetzt habe ich ein allgemeines Verständnis dafür, wie es funktioniert."
  },
  AvgCommunicate_66980_Content_9 = {
    Text = "Obwohl die treibenden Prinzipien darin sehr komplex sind, habe ich sie noch nicht vollständig verstanden. Möglicherweise sind sie einer tiefergehenden Forschung bedürftig."
  },
  AvgCommunicate_66980_Option_10 = {
    Text = "Hör auf zu forschen! Es ist nicht wichtig. Wenn es kaputt geht, wird es sehr teuer!"
  },
  AvgCommunicate_66980_Option_12 = {
    Text = "Das ist der Kommunikator, der von der Schule ausgegeben wurde."
  },
  AvgCommunicate_66980_Option_14 = {
    Text = "Erinnerst du dich wirklich daran, wer ich bin?"
  },
  AvgCommunicate_66980_Option_2 = {
    Text = "? Hast du alles vergessen?"
  },
  AvgCommunicate_66980_Option_5 = {
    Text = "Wie benutzt du es jetzt?!"
  },
  AvgCommunicate_66980_Option_7 = {
    Text = "Lache nicht über meine Angst!"
  },
  AvgCommunicate_66981_Content_1 = {
    Text = "Keeper, was denkst du über menschliche Emotionen?"
  },
  AvgCommunicate_66981_Content_10 = {
    Text = "Was ist mit dir? Als Intellektueller Körper, solltest du nicht absolut rational sein?"
  },
  AvgCommunicate_66981_Content_11 = {
    Text = "Du bist sehr scharfsinnig, Hüter, was einer der Gründe ist, warum ich stets versucht habe, meine Kontakte zur Welt zu minimieren."
  },
  AvgCommunicate_66981_Content_12 = {
    Text = "Wenn ich mich von der Welt distanziere und vermeide, übermäßig enge Bindungen zu Menschen aufrechtzuerhalten, bleibe ich klar und unabhängig."
  },
  AvgCommunicate_66981_Content_13 = {
    Text = "Es ist, als hätte ich nie die Süße des Kuchens gekostet, würde ich nicht ständig darüber nachdenken."
  },
  AvgCommunicate_66981_Content_14 = {
    Text = "Ich verstehe... Willst du jetzt kleine Kuchen essen?"
  },
  AvgCommunicate_66981_Content_15 = {
    Text = "Es ist keine Notwendigkeit, aber wenn es dir angenehm ist, wäre ich dir sehr dankbar."
  },
  AvgCommunicate_66981_Content_2 = {
    Text = "So ein tiefgründiges Thema gleich zu Beginn!"
  },
  AvgCommunicate_66981_Content_3 = {
    Text = "Emotionen... jeder hat sie, schließlich sind wir nur Menschen."
  },
  AvgCommunicate_66981_Content_4 = {
    Text = "Genau, Menschen existieren, indem sie auf ihr Fleisch angewiesen sind, und Emotionen entstehen aus instinktiven Reaktionen."
  },
  AvgCommunicate_66981_Content_5 = {
    Text = "Die meisten menschlichen Entscheidungen werden von Emotionen und nicht von rationalem Denken beeinflusst, was Zurückhaltung und Anstrengung erfordert."
  },
  AvgCommunicate_66981_Content_6 = {
    Text = "In der Tat, absolute Rationalität zu jeder Zeit aufrechtzuerhalten, scheint nur für Lehrerin Puppe möglich zu sein."
  },
  AvgCommunicate_66981_Content_7 = {
    Text = "Nein, die Puppe kann es auch nicht. Sie hält immer noch emotionale Bindungen und wird große Risiken eingehen, wenn sie Entscheidungen trifft."
  },
  AvgCommunicate_66981_Content_8 = {
    Text = "Ist das so? Sind alle Menschen so, einschließlich dieser verdrehten und verrückten Individuen?"
  },
  AvgCommunicate_66981_Content_9 = {
    Text = "Ja, extreme Entscheidungen sind stärker von Emotionen getrieben."
  },
  AvgCommunicate_66981_Option_10 = {
    Text = "Was ist mit dir? Als Intellektueller Körper, solltest du nicht absolut rational sein?"
  },
  AvgCommunicate_66981_Option_14 = {
    Text = "Ich verstehe... Willst du jetzt kleine Kuchen essen?"
  },
  AvgCommunicate_66981_Option_2 = {
    Text = "So ein tiefgründiges Thema gleich zu Beginn!"
  },
  AvgCommunicate_66981_Option_6 = {
    Text = "In der Tat, absolute Rationalität zu jeder Zeit aufrechtzuerhalten, scheint nur für Lehrerin Puppe möglich zu sein."
  },
  AvgCommunicate_66981_Option_8 = {
    Text = "Ist das so? Sind alle Menschen so, einschließlich dieser verdrehten und verrückten Individuen?"
  },
  AvgCommunicate_66982_Content_1 = {
    Text = "Schutzherr, hier ist eine Gelegenheit, meine Gunst zu gewinnen."
  },
  AvgCommunicate_66982_Content_10 = {
    Text = "Einfach mich gleich verkaufen."
  },
  AvgCommunicate_66982_Content_11 = {
    Text = "Wie soll ich mir solch luxuriösen Schnickschnack für wohlhabende Damen leisten, selbst wenn ich das Geld hätte!"
  },
  AvgCommunicate_66982_Content_12 = {
    Text = "Das ist mir egal! Lass dir was einfallen! Der Hase will bestimmt auch bei mir sein."
  },
  AvgCommunicate_66982_Content_13 = {
    Text = "Ich habe mich für einen Namen entschieden: Ivy!"
  },
  AvgCommunicate_66982_Content_14 = {
    Text = "Er wird zusammen mit mir, Jenny und Oliver an der Teeparty teilnehmen."
  },
  AvgCommunicate_66982_Content_15 = {
    Text = "Schon gut, schon gut, ich werde Frau Sorel fragen und ihn auf jeden Fall zu unserem Wiedersehen mitbringen."
  },
  AvgCommunicate_66982_Content_16 = {
    Text = "Hehe, das ist eher nach meinem Geschmack!"
  },
  AvgCommunicate_66982_Content_2 = {
    Text = "Welchen limitierten Kuchen möchtest du diesmal?"
  },
  AvgCommunicate_66982_Content_3 = {
    Text = "Denkst du wirklich, alles, was mich interessiert, ist Essen!"
