  AvgCommunicate_66982_Content_4 = {
    Text = "Ansonsten... Was noch?"
  },
  AvgCommunicate_66982_Content_5 = {
    Text = "Hmph, Kuchen sind gut, aber diesmal geht es nicht ums Essen."
  },
  AvgCommunicate_66982_Content_6 = {
    Text = "In der Zeitschrift, die du letztes Mal mitgebracht hast, habe ich gesehen, dass das Kaufhaus in Lentiniën handgemachte Plüschtiere herausgebracht hat."
  },
  AvgCommunicate_66982_Content_7 = {
    Text = "Da gibt es einen besonderen schwarz-rosa Hasen-Plüsch!"
  },
  AvgCommunicate_66982_Content_8 = {
    Text = "Der ist praktisch für mich gemacht! In der Zeitschrift steht, es sei ein Meisterwerk eines Meisters. Beeil dich und kauf ihn mir!"
  },
  AvgCommunicate_66982_Content_9 = {
    Text = "Meisterwerk?"
