  },
  AvgCommunicate_66982_Option_4 = {
    Text = "Ansonsten... Was noch?"
  },
  AvgCommunicate_66982_Option_9 = {
    Text = "Meisterwerk?"
  },
  AvgCommunicate_66983_Content_1 = {
    Text = "Hey, du musst mir in dieser Zeit keine Kuchen bringen."
  },
  AvgCommunicate_66983_Content_10 = {
    Text = "Und mit einer schillernden Auswahl von Zutaten kannst du so viel hinzufügen, wie du möchtest—es ist absolut köstlich!"
  },
  AvgCommunicate_66983_Content_11 = {
    Text = "Das ist der springende Punkt! Würde es nicht überwältigend werden, wenn man mehr hinzufügt?"
  },
  AvgCommunicate_66983_Content_12 = {
    Text = "Du würdest es nicht verstehen—meine neuen Kreationen haben endlosen Lob von den Köchen erhalten!"
  },
  AvgCommunicate_66983_Content_13 = {
    Text = "Die Produktion begann gestern und ist bereits im Speisesaal erhältlich. Es stehen viele Menschen in der Schlange!"
  },
  AvgCommunicate_66983_Content_14 = {
    Text = "So warst du diejenige, die die neuen Mini-Küchlein gemacht hat, die alle gestern hastig kaufen wollten!"
  },
  AvgCommunicate_66983_Content_15 = {
    Text = "Hahahaha, bin ich nicht erstaunlich? Nenn mich ein Genie!"
  },
  AvgCommunicate_66983_Content_16 = {Text = "Genie!"},
  AvgCommunicate_66983_Content_17 = {
    Text = "Aber ich habe plötzlich realisiert, dass selbstgemachte Kuchen vielleicht besser schmecken. Das weiterzumachen ist von nun an keine schlechte Idee."
  },
  AvgCommunicate_66983_Content_18 = {
    Text = "Wie entzückend, die junge Dame hat endlich die Freude an der Arbeit erfahren."
  },
  AvgCommunicate_66983_Content_2 = {
    Text = "Was habe ich gesehen? Was hat dich getroffen?"
  },
  AvgCommunicate_66983_Content_3 = {
    Text = "Welcher Angriff? Mir geht es bestens!"
  },
  AvgCommunicate_66983_Content_4 = {
    Text = "Wer bist du?"
  },
  AvgCommunicate_66983_Content_5 = {
    Text = "Seufz, ich habe mich einfach in letzter Zeit an den kleinen Kuchen der Mensa sattgesehen, und diese leerköpfigen Köche haben nicht die Absicht, neue einzuführen!"
  },
  AvgCommunicate_66983_Content_6 = {
    Text = "In der Tat, niemand hat ein so großes Verlangen nach Cupcakes wie du..."
  },
  AvgCommunicate_66983_Content_7 = {
    Text = "Es ist alles ihre Schuld, weil sie so inkompetent sind, also bin ich in die Küche gestürmt und habe sie gebeten, mir zu zeigen, wie man einen Kuchen backt."
  },
  AvgCommunicate_66983_Content_8 = {
    Text = "Hä? Du, kochen?"
  },
  AvgCommunicate_66983_Content_9 = {
