  AvgCommunicate_66984_Content_11 = {
    Text = "Tatsächlich bin ich erst jetzt auf der Suche nach meinem reizenden Tanzpartner."
  },
  AvgCommunicate_66984_Content_12 = {
    Text = "Ich denke, {Male=he,Female=she} würde es nicht ertragen, mich ganz allein zum Ball gehen zu lassen, oder?"
  },
  AvgCommunicate_66984_Content_13 = {
    Text = "Was sagst du?"
