  },
  AvgCommunicate_66984_Content_4 = {
    Text = "In ein paar Tagen nehme ich an einem Abendessen teil, Ihr wisst schon, eine Zusammenkunft vornehmer, aber eingebildeter Leute, die nichts tun."
  },
  AvgCommunicate_66984_Content_5 = {
    Text = "Ärgerlich ist, dass mich in letzter Zeit ein unhöflicher Kerl ständig belästigt; er nimmt ebenfalls am Ball teil und hat mich sogar dreist eingeladen, seine Begleitung zu sein."
  },
  AvgCommunicate_66984_Content_6 = {
    Text = "So eine lästige Person. Soll ich mich für Euch um ihn kümmern, Madame?"
  },
  AvgCommunicate_66984_Content_7 = {
    Text = "Heh heh, Ihr werdet immer besser darin, Witze zu machen."
  },
  AvgCommunicate_66984_Content_8 = {
    Text = "Leider nicht jetzt. Die Welt der Erwachsenen ist immer so kompliziert. Allerdings habe ich seine Einladung bereits abgelehnt."
  },
  AvgCommunicate_66984_Content_9 = {
    Text = "Dann ist das Problem also gelöst?"
  },
  AvgCommunicate_66984_Option_14 = {
    Text = "Es ist mir eine Ehre, Madame."
  },
  AvgCommunicate_66984_Option_2 = {
    Text = "Was hat Frau Sorel ratlos gemacht?"
  },
  AvgCommunicate_66984_Option_3 = {
    Text = "Ich bin ganz Ohr."
  },
  AvgCommunicate_66984_Option_6 = {
    Text = "So eine lästige Person. Soll ich mich für Euch um ihn kümmern, Madame?"
  },
  AvgCommunicate_66984_Option_9 = {
    Text = "Dann ist das Problem also gelöst?"
  },
  AvgCommunicate_66985_Content_1 = {
    Text = "Mein kleiner Ritter, dank deiner Hilfe beim letzten Ball habe ich es endlich geschafft, diese lästige Person loszuwerden."
  },
  AvgCommunicate_66985_Content_10 = {
    Text = "Einen Wunsch äußern? Dann wünsche ich mir ein großes Abendessen bei Kerzenschein mit der wunderschönen Frau Sorel."
  },
  AvgCommunicate_66985_Content_11 = {
    Text = "Nur du und ich. Kein Smalltalk mit irgendwem sonst."
  },
  AvgCommunicate_66985_Content_12 = {
    Text = "Wie du wünschst, du schlaues kleines Ding."
  },
  AvgCommunicate_66985_Content_13 = {
    Text = "Was möchtest du essen? Sag es mir, und ich werde es mit dir kosten."
  },
  AvgCommunicate_66985_Content_14 = {
    Text = "Das stellt die Vorstellungskraft von jemandem, der jeden Tag in der Kantine isst, wirklich auf die Probe. Lasst mich das Gericht probieren, das die Dame am meisten liebt."
  },
  AvgCommunicate_66985_Content_15 = {
    Text = "Heh, du bist wirklich ein charmantes Kind."
  },
  AvgCommunicate_66985_Content_16 = {
    Text = "Ich werde in meinem Anwesen auf Eure Ankunft warten."
  },
  AvgCommunicate_66985_Content_2 = {
    Text = "Um meine Dankbarkeit für deine Freundlichkeit und Großzügigkeit auszudrücken, möchte ich etwas für dich tun, als Zeichen meiner Wertschätzung."
  },
  AvgCommunicate_66985_Content_3 = {
    Text = "Ihr seid zu gütig, Frau Sorel. Ich dachte, unsere Beziehung erfordert keine Dankesbekundungen mehr."
  },
  AvgCommunicate_66985_Content_4 = {
    Text = "Ich mag es wirklich nicht, Dankbarkeit in Worte zu fassen; meistens sind es doch nur unaufrichtige Höflichkeitsfloskeln."
  },
  AvgCommunicate_66985_Content_5 = {
    Text = "Aber eine Gelegenheit, einen beliebigen Wunsch an mich zu richten — interessiert dich das nicht?"
  },
  AvgCommunicate_66985_Content_6 = {
    Text = "Wow, jeder beliebige Wunsch? Wenn die edlen Herren das hören, werden sie vor Neid erblassen."
  },
  AvgCommunicate_66985_Content_7 = {
    Text = "Du wirst von mir immer eine Sonderbehandlung verdienen."
  },
  AvgCommunicate_66985_Content_8 = {
    Text = "Das bringt mich wirklich in Verlegenheit... Ich bin so hin- und hergerissen. Wenn ich aufs Ganze gehe und um eine Villa bitte, wird die Schule das herausfinden?"
  },
  AvgCommunicate_66985_Content_9 = {
    Text = "Keine Sorge. Ich kümmere mich um alles, also äußere ruhig deinen Wunsch."
  },
  AvgCommunicate_66985_Option_10 = {
    Text = "Möchtet Ihr Euch etwas wünschen?"
  },
  AvgCommunicate_66985_Option_14 = {
    Text = "Dann lasst mich das Gericht probieren, das die Dame am meisten liebt."
  },
  AvgCommunicate_66985_Option_3 = {
    Text = "Ihr seid zu gütig, Frau Sorel."
  },
  AvgCommunicate_66985_Option_6 = {
    Text = "Wow, irgendwelche Wünsche?"
  },
  AvgCommunicate_66985_Option_8 = {
    Text = "Das bringt mich wirklich in Verlegenheit..."
  },
  AvgCommunicate_66986_Content_1 = {
    Text = "Ich habe gerade gegen Lotan gekämpft. Es war ein Unentschieden."
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "Hahaha... Ich glaube, ich habe nicht so viele ablenkende Gedanken, also lassen wir es erstmal dabei."
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "Du bist also auch sehr stark."
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "Schade, dass immer jemand in der Nähe des Wasserfalls angelt. Das ist etwas laut."
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "Einmal bin ich aus dem Wasserfall herausgetreten und habe ihn gebeten, leiser zu sein. Er hat sich so erschrocken, dass er mir den Fisch ins Gesicht geworfen hat und weggerannt ist."
  },
  AvgCommunicate_66986_Content_14 = {
    Text = "Ich weiß nicht, ob er nochmal kommen wird."
  },
  AvgCommunicate_66986_Content_15 = {
    Text = "Mm... Ich glaube eher nicht..."
  },
  AvgCommunicate_66986_Content_2 = {
    Text = "Was ist los mit dir?"
  },
  AvgCommunicate_66986_Content_3 = {
    Text = "Kein Streit, oder?"
  },
  AvgCommunicate_66986_Content_4 = {
    Text = "Nichts, nur ein freundschaftlicher Übungskampf unter Kriegern."
  },
  AvgCommunicate_66986_Content_5 = {
    Text = "Zuvor sagte sie, mein Kampf sei nicht rein genug. Jetzt, glaube ich, verstehe ich es."
  },
  AvgCommunicate_66986_Content_6 = {
    Text = "Ich habe einen Weg gefunden, reiner zu werden. Ich bin jetzt stärker."
  },
  AvgCommunicate_66986_Content_7 = {
    Text = "Das ist gut, aber welche Methode sollte man anwenden, um Reinheit zu erlangen?"
  },
  AvgCommunicate_66986_Content_8 = {
    Text = "Stell dich unter den Wasserfall und lass das fließende Wasser deine ablenkenden Gedanken fortspülen."
  },
  AvgCommunicate_66986_Content_9 = {
    Text = "Das ist nützlich. Willst du mit mir mitkommen?"
  },
  AvgCommunicate_66986_Option_10 = {
    Text = "Hahaha... Ich glaube, ich habe nicht so viele ablenkende Gedanken, also lassen wir es erstmal dabei."
  },
  AvgCommunicate_66986_Option_15 = {
    Text = "Mm... Ich glaube eher nicht..."
  },
  AvgCommunicate_66986_Option_2 = {
    Text = "Was ist los mit dir?"
