  AvgCommunicate_66987_Content_1 = {
    Text = "Schutzherr, kennst du irgendwelche Rezepte mit Fisch?"
  },
  AvgCommunicate_66987_Content_10 = {
    Text = "Was für eine freundliche und sanfte alte Dame."
  },
  AvgCommunicate_66987_Content_11 = {
    Text = "Mm, deshalb möchte ich auch lernen, wie man Fisch zubereitet. Nächstes Mal mache ich ihn für sie."
  },
  AvgCommunicate_66987_Content_12 = {
    Text = "So rührend! Das müssen wir tun! Ich gehe sofort den Kantinenkoch befragen!"
  },
  AvgCommunicate_66987_Content_13 = {
    Text = "Vielen Dank."
  },
  AvgCommunicate_66987_Content_2 = {
    Text = "Rezept?? Willst du kochen?"
  },
  AvgCommunicate_66987_Content_3 = {
    Text = "Mm, die Gegend um den Wasserfall war lange ruhig, seit ich den letzten Fischer verscheucht habe."
  },
  AvgCommunicate_66987_Content_4 = {
    Text = "Eine alte Dame kommt in letzter Zeit hierher zum Angeln. Sie ist ruhig, also habe ich mich nicht gezeigt."
  },
  AvgCommunicate_66987_Content_5 = {
    Text = "Später hat sie ein Feuer angezündet, um den Fisch zu grillen, den sie gefangen hatte."
  },
  AvgCommunicate_66987_Content_6 = {
    Text = "Weil es so gut roch, hat mein Magen ein wenig geknurrt, und sie hat es bemerkt."
  },
  AvgCommunicate_66987_Content_7 = {
    Text = "Hä? Hat sie sich auch vor dir erschreckt?"
  },
  AvgCommunicate_66987_Content_8 = {
    Text = "Nein, sie hat mich eingeladen, zusammen gebratenen Fisch zu essen. Es war köstlich."
  },
  AvgCommunicate_66987_Content_9 = {
    Text = "Später fing sie an, einen kleinen Topf zum Angeln mitzubringen und teilte dann Fischsuppe mit mir."
  },
  AvgCommunicate_66987_Option_10 = {
    Text = "Was für eine freundliche und sanfte alte Dame."
  },
  AvgCommunicate_66987_Option_12 = {
    Text = "So rührend! Das müssen wir tun! Ich gehe sofort den Kantinenkoch befragen!"
  },
  AvgCommunicate_66987_Option_2 = {
    Text = "Rezept?? Willst du kochen?"
  },
  AvgCommunicate_66987_Option_7 = {
    Text = "Hä? Hat sie sich auch vor dir erschreckt?"
  },
  AvgCommunicate_66988_Content_1 = {
    Text = "Kürzlich bin ich zu etwas Geld gekommen, aber ich wäre dabei fast gestorben. Zum Glück ist die Göttin des Glücks immer an meiner Seite."
  },
  AvgCommunicate_66988_Content_10 = {
    Text = "Während unseres Kampfes hat die ausgelöste Falle dann versehentlich ihn selbst getroffen."
  },
  AvgCommunicate_66988_Content_11 = {Text = "Huh?"},
  AvgCommunicate_66988_Content_12 = {
    Text = "Ich habe bei ihm eine Notfall-Blutstillung durchgeführt und ihn dann lebend zur Polizeistation gebracht."
  },
  AvgCommunicate_66988_Content_13 = {
    Text = "Die Polizei hat mir eine Prämie gegeben, und der Verbrecher wurde zurück ins Gefängnis geschickt. Ich habe gehört, dass sein Urteil in lebenslänglich umgewandelt wurde."
  },
  AvgCommunicate_66988_Content_14 = {
    Text = "Er hätte in ein paar Jahren freigelassen werden können. Warum etwas so Dummes tun? Seufz..."
  },
  AvgCommunicate_66988_Content_15 = {
    Text = "Schwierig zu sagen, ob du oder er mehr gelitten hat..."
  },
  AvgCommunicate_66988_Content_16 = {
    Text = "Aber ich erinnere mich, dass du gestern von Leuten aus der Spielhalle gejagt wurdest, um Schulden einzutreiben. Wo ist dein Preisgeld?"
  },
  AvgCommunicate_66988_Content_17 = {
    Text = "Hahaha... Schließlich ist mein Glück begrenzt, und wenn ich es zu früh aufbrauche, könnte ich am Spieltisch ein paar Mal daneben greifen..."
  },
  AvgCommunicate_66988_Content_18 = {
    Text = "Als ich das hörte, fühlte ich mich plötzlich viel besser."
  },
  AvgCommunicate_66988_Content_2 = {
    Text = "Was ist passiert??"
  },
  AvgCommunicate_66988_Content_3 = {
    Text = "Weißt du, ich nehme nebenbei Detektivaufträge an, und meine hohe Erfolgsquote sorgt dafür, dass ich gefragt bleibe."
  },
  AvgCommunicate_66988_Content_4 = {
    Text = "Aber umgekehrt hassen mich diejenigen, die ich ins Gefängnis gebracht habe, bis aufs Blut."
  },
  AvgCommunicate_66988_Content_5 = {
    Text = "Weil sie wirklich auf so unerklärliche Weise verloren haben."
  },
  AvgCommunicate_66988_Content_6 = {
    Text = "Neulich ist ein Krimineller aus dem Gefängnis ausgebrochen und hat sich mehrere Tage in meiner üblichen Spielhölle versteckt. Schließlich haben sie mich erwischt."
  },
  AvgCommunicate_66988_Content_7 = {
    Text = "Ist das Rache an mir?!"
  },
  AvgCommunicate_66988_Content_8 = {
    Text = "Genau, er hatte mich schon lange verfolgt und mich schließlich in einer Gasse in die Enge getrieben."
  },
  AvgCommunicate_66988_Content_9 = {
    Text = "Er hatte eine Falle in der Gasse aufgestellt, mit der Absicht, mich zu töten."
