  AvgCommunicate_66989_Content_12 = {
    Text = "Seufz... Meine aufrichtigen Gefühle waren fehl am Platz!"
  },
  AvgCommunicate_66989_Content_13 = {
    Text = "Also, die Aufgabe – äh, nein, ich meine die Frage – kannst du mir ein paar Hinweise geben, wie ich sie angehen soll?"
