  AvgCommunicate_66994_Content_6 = {
    Text = "Sie küsste die grünen Elfen auf die Stirn, verwandelte sie in große und gutaussehende Prinzen, und sie lebten glücklich bis ans Ende ihrer Tage mit Prinzessin Weiße Wolke!"
  },
  AvgCommunicate_66994_Content_7 = {
    Text = "Was ist das alles? Was soll das bedeuten?"
  },
  AvgCommunicate_66994_Content_8 = {
    Text = "Das ist ein Raubkopie-Buch, oder?"
  },
  AvgCommunicate_66994_Content_9 = {
    Text = "Was ist los, Meister? Lily und alle anderen lieben diese Geschichte!"
  },
  AvgCommunicate_66994_Option_10 = {
    Text = "Nichts... Solange ihr glücklich seid!"
  },
  AvgCommunicate_66994_Option_13 = {
    Text = "Kein Problem, diesmal besorge ich euch definitiv die echten Bücher."
  },
  AvgCommunicate_66994_Option_15 = {
    Text = "Vielleicht war die Geschichte in dem Raubdruck bei näherer Betrachtung eigentlich besser..."
  },
  AvgCommunicate_66994_Option_2 = {
    Text = "Oh? Was für eine Geschichte?"
  },
  AvgCommunicate_66994_Option_4 = {
    Text = "Ist der Name dieser Geschichte nicht ein bisschen seltsam...?"
  },
  AvgCommunicate_66994_Option_7 = {
    Text = "Was ist das alles? Was soll das bedeuten?"
  },
  AvgCommunicate_66994_Option_8 = {
    Text = "Das ist ein Raubkopie-Buch, oder?"
  },
  AvgCommunicate_66995_Content_1 = {Text = "Hey."},
  AvgCommunicate_66995_Content_10 = {
    Text = "Wenn du sie nicht von mir fernhältst, wirst du meinen Flegel aus nächster Nähe kennenlernen."
  },
  AvgCommunicate_66995_Content_2 = {
    Text = "Nenn mich nicht „hey\"..."
  },
  AvgCommunicate_66995_Content_3 = {
    Text = "Du wagst es tatsächlich, mich aktiv zu suchen."
  },
  AvgCommunicate_66995_Content_4 = {
    Text = "Genug geredet. Schaff mir diese Frau namens Lotan vom Hals."
  },
  AvgCommunicate_66995_Content_5 = {
    Text = "Diese Verrückte belästigt mich schon seit einem Monat."
  },
  AvgCommunicate_66995_Content_6 = {
    Text = "Und egal wie hart wir zuschlagen, sie will einfach nicht sterben. So nervig!"
  },
  AvgCommunicate_66995_Content_7 = {
    Text = "Äh, es scheint, dass du wirklich sehr geschickt bist."
  },
  AvgCommunicate_66995_Content_8 = {
    Text = "Lotan trifft selten auf eine Gegnerin, die es so lange mit ihr aufnehmen kann, also muss sie sehr glücklich sein."
  },
  AvgCommunicate_66995_Content_9 = {
    Text = "Hmph, Schmeicheleien ziehen bei mir nicht."
  },
  AvgCommunicate_66995_Option_2 = {
    Text = "Erstens, mein Name ist nicht „Hey\"..."
  },
  AvgCommunicate_66995_Option_3 = {
    Text = "Zweitens, du bist tatsächlich zu mir gekommen, um mich zu suchen."
  },
  AvgCommunicate_66995_Option_7 = {
    Text = "Äh, es scheint, dass du wirklich sehr geschickt bist."
  },
  AvgCommunicate_66996_Content_1 = {
    Text = "Mythag ist so ein langweiliger Ort."
  },
  AvgCommunicate_66996_Content_10 = {
    Text = "Dann viel Glück dabei, das zu bekommen, was du willst. Solltest du jemals zurückkehren wollen, die Tore von Misaq werden dir immer offen stehen."
  },
  AvgCommunicate_66996_Content_2 = {
    Text = "Eine Gruppe selbsternannter Gerechter, die Bestien mit Halsbändern einsperrt."
  },
  AvgCommunicate_66996_Content_3 = {
    Text = "Ich kann nicht nachvollziehen, warum ich früher an euren langweiligen Spielchen teilgenommen habe, aber wenn man ihre Schwäche bedenkt, ergibt alles einen Sinn."
  },
  AvgCommunicate_66996_Content_4 = {
    Text = "Du wurdest noch nie standhaft von jemandem beschützt, deshalb kannst du das Gefühl und die Bedeutung, beschützt zu werden, nicht verstehen."
  },
  AvgCommunicate_66996_Content_5 = {
    Text = "Helot ist eine herausragende Kriegerin. Sie hat sich einfach dafür entschieden, die Wärme und Hilfe anderer anzunehmen."
  },
  AvgCommunicate_66996_Content_6 = {
    Text = "Ha, macht, was ihr wollt. Wenn sie sich dafür entscheidet, das Halsband zu tragen, soll sie bleiben."
  },
  AvgCommunicate_66996_Content_7 = {
    Text = "Ich gehe. Hier zu bleiben wird die Kriegerin nur abstumpfen lassen."
  },
  AvgCommunicate_66996_Content_8 = {
    Text = "Schön, ich nehme an, du wirst mir nicht verraten, wohin du gehst."
  },
  AvgCommunicate_66996_Content_9 = {
    Text = "Wo auch immer Macht ist, dorthin werde ich gehen."
  },
  AvgCommunicate_66996_Option_10 = {
    Text = "Dann viel Glück dabei, das zu erlangen, was du begehrst."
  },
  AvgCommunicate_66996_Option_4 = {
    Text = "Du wurdest noch nie standhaft von jemandem beschützt, deshalb kannst du das Gefühl und die Bedeutung, beschützt zu werden, nicht verstehen."
  },
  AvgCommunicate_66996_Option_8 = {
    Text = "Schön, ich nehme an, du wirst mir nicht verraten, wohin du gehst."
  },
  AvgCommunicate_66997_Content_1 = {
    Text = "Hey, ich habe gehört, Murphy hat in letzter Zeit nicht am Unterricht teilgenommen. Was ist los?"
  },
  AvgCommunicate_66997_Content_10 = {
    Text = "Natürlich, erober es einfach zurück."
  },
  AvgCommunicate_66997_Content_11 = {
    Text = "Hallo, ist das die Polizei? Jemand ist im Begriff, wieder ein Verbrechen zu begehen."
  },
  AvgCommunicate_66997_Content_12 = {
    Text = "Gut, ich kaufe es, in Ordnung? Neugierige Person."
  },
  AvgCommunicate_66997_Content_13 = {
    Text = "Erinnere dich, ich beobachte dich. Wenn du mit Murphy etwas Lustiges versuchst... Hmph."
  },
  AvgCommunicate_66997_Content_2 = {
    Text = "Sie hat zu viele kleine Kuchen gegessen und bekam Bauchschmerzen. Aber warum fragst du nicht sie selbst?"
  },
  AvgCommunicate_66997_Content_3 = {
    Text = "Genug geredet. Hast du etwas gemacht? Ich habe gesehen, dass du ihr ständig Kuchen gekauft hast."
  },
  AvgCommunicate_66997_Content_4 = {
    Text = "Was hat das mit mir zu tun? Sie konnte sich dem alten Kuchen vom Vortag selbst nicht widersetzen"
  },
  AvgCommunicate_66997_Content_5 = {
    Text = "Nein, was geht es dich an?"
  },
  AvgCommunicate_66997_Content_6 = {
    Text = "Du würdest es nicht wagen."
  },
  AvgCommunicate_66997_Content_7 = {
    Text = "Hmph, was ist schon so besonders an ein paar Kuchen? Ich werde einen Koch finden, der sie ihr jeden Tag macht."
  },
  AvgCommunicate_66997_Content_8 = {
    Text = "Du denkst doch nicht wirklich, dass du ihr Vater bist, oder? Hast nie erwartet, dass du so eine väterliche Seite hast."
  },
  AvgCommunicate_66997_Content_9 = {
    Text = "Warte, wie wirst du den Koch finden?"
  },
  AvgCommunicate_66997_Option_11 = {
    Text = "Hallo, ist das die Polizei? Jemand ist im Begriff, wieder ein Verbrechen zu begehen."
  },
  AvgCommunicate_66997_Option_2 = {
    Text = "Sie hat zu viele kleine Kuchen gegessen und bekam Bauchschmerzen."
  },
  AvgCommunicate_66997_Option_4 = {
    Text = "Was hat das mit mir zu tun?"
  },
  AvgCommunicate_66997_Option_8 = {
    Text = "Hätte nie gedacht, dass du so eine väterliche Seite zeigst."
  },
  AvgCommunicate_66998_Content_1 = {
    Text = "Die Reise der Starken ist wahrlich einsam."
  },
  AvgCommunicate_66998_Content_10 = {
    Text = "Im Moment ist unklar, ob du etwas Gutes oder Schlechtes getan hast..."
  },
  AvgCommunicate_66998_Content_11 = {
    Text = "Hmph, ich habe lediglich getan, was die Starken tun sollten."
  },
  AvgCommunicate_66998_Content_12 = {
    Text = "Die Unterwelt hier ist jetzt etwas langweilig. Was soll ich als Nächstes tun..."
  },
  AvgCommunicate_66998_Content_13 = {
    Text = "Was auch immer du vorhast, ich werde die Polizei informieren, damit sie dich genau im Auge behält."
  },
  AvgCommunicate_66998_Content_2 = {
    Text = "Eine Reise? Was hast du angestellt? Bist du wieder auf der Polizeiwache?"
  },
  AvgCommunicate_66998_Content_3 = {
    Text = "Was für ein Witz! Als ob diese Narren mich jemals einsperren könnten."
  },
  AvgCommunicate_66998_Content_4 = {
    Text = "Nach dem letzten Vorfall habe ich es nun geschafft, die Hälfte von Lentiniëns Unterwelt zu erobern."
  },
  AvgCommunicate_66998_Content_5 = {
    Text = "Es gibt noch etwas Bedauerliches – die Gangs hier sind viel schwächer als meine Philistinen; sie werden es letztlich nicht zu Größe bringen."
  },
  AvgCommunicate_66998_Content_6 = {
    Text = "Gang?? In was für illegale Aktivitäten bist du verwickelt gewesen?"
  },
  AvgCommunicate_66998_Content_7 = {
    Text = "Was? Wenn der Kampf gegen das Verbrechersyndikat als falsch gilt, dann gibt es wohl keine guten Menschen mehr auf der Welt."
  },
  AvgCommunicate_66998_Content_8 = {
    Text = "Ehrlich gesagt schuldet mir Misaq oder diese Polizeibehörde eine Ehrenmedaille."
  },
  AvgCommunicate_66998_Content_9 = {
    Text = "Jetzt wurde diese Bande von mir in die Knie gezwungen. Ist euch nicht aufgefallen, dass sich die Sicherheitslage in der Stadt verbessert hat?"
  },
  AvgCommunicate_66998_Option_10 = {
    Text = "Im Moment ist unklar, ob du etwas Gutes oder Schlechtes getan hast..."
  },
  AvgCommunicate_66998_Option_13 = {
    Text = "Was auch immer du vorhast, ich werde die Polizei informieren, damit sie dich genau im Auge behält."
  },
  AvgCommunicate_66998_Option_2 = {
    Text = "Eine Reise? Was hast du angestellt? Bist du wieder auf der Polizeiwache?"
  },
  AvgCommunicate_66998_Option_6 = {
    Text = "Gang?? In was für illegale Aktivitäten bist du verwickelt gewesen?"
  },
  AvgCommunicate_66999_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%, ich wurde kürzlich von der Misaq Universität eingeladen, um bei der Aufnahme der Musik für den Stundenwechsel zu helfen."
  },
  AvgCommunicate_66999_Content_10 = {
    Text = "Wenn es etwas Besonderes gibt, plätschert es wahrscheinlich voller meiner Gefühle, dich zu beschützen."
  },
  AvgCommunicate_66999_Content_11 = {
    Text = "Ich hatte immer ein wenig Schwierigkeiten, aufzustehen. Vielleicht würde etwas erquickende Musik es leichter machen!"
  },
  AvgCommunicate_66999_Content_12 = {
    Text = "Aufregend, nicht wahr? Ich verstehe."
  },
  AvgCommunicate_66999_Content_13 = {
    Text = "Auch wenn ich denke, dass ausreichend und qualitativ hochwertiger Schlaf wichtiger ist, ist es angesichts der vielen Verantwortungen, die du trägst, unvermeidlich, beschäftigt zu sein."
  },
  AvgCommunicate_66999_Content_14 = {
    Text = "Hoffe, dass dieser Marsch dir Macht bringt."
  },
  AvgCommunicate_66999_Content_2 = {
    Text = "In der Aufnahme erwähnte Professor Puppe ebenfalls, dass die Schule eine neue Art von Rekorder entwickelt hat. Er ist klein, hat eine klare Audioqualität und kann sogar bei Missionen mitgeführt werden, mit Funktionen für Aufnahme und Wiedergabe."
  },
  AvgCommunicate_66999_Content_3 = {
    Text = "Als ich es sah, dachte ich an dich. Wenn nötig, kann ich das Musikstück, das du magst, für dich aufnehmen."
  },
  AvgCommunicate_66999_Content_4 = {
    Text = "Auch wenn ich nicht an deiner Seite bin, wird es Musik geben, um deine Seele zu trösten."
  },
  AvgCommunicate_66999_Content_5 = {
    Text = "Hameln... Ich bin tief berührt!"
  },
  AvgCommunicate_66999_Content_6 = {
    Text = "Es ist alles Teil meiner Pflicht. Gibt es etwas, das du hören möchtest?"
  },
  AvgCommunicate_66999_Content_7 = {
    Text = "Apropos, ich schlafe immer gut, wenn du das Wiegenlied spielst."
  },
  AvgCommunicate_66999_Content_8 = {
    Text = "Was ist besonders an dieser Melodie?"
  },
  AvgCommunicate_66999_Content_9 = {
    Text = "Dieser hier? Ich sehe."
  },
  AvgCommunicate_66999_Option_11 = {
    Text = "Musik, um aufzuwache"
  },
  AvgCommunicate_66999_Option_5 = {
    Text = "Hameln... Ich bin tief berührt!"
  },
  AvgCommunicate_66999_Option_7 = {
    Text = "Musik, die beim Schlafen hilft"
  },
  AvgCommunicate_67000_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%. Ich habe kürzlich ein neues Stück komponiert und würde dich gerne einladen, es dir in deiner Freizeit anzuhören und deine Meinung dazu abzugeben."
  },
  AvgCommunicate_67000_Content_10 = {
    Text = "Ah, solche Anforderungen sind tatsächlich hart. Entschuldigung, dass ich das nicht gründlich genug bedacht habe."
  },
  AvgCommunicate_67000_Content_11 = {
    Text = "Vielleicht werde ich das nächste Mal an deinem Bett spielen und deinen Schlaf sorgfältig aufzeichnen."
  },
  AvgCommunicate_67000_Content_12 = {
    Text = "Ich hoffe, meine Wachsamkeit bringt dir Frieden in jedem Schlaf."
  },
  AvgCommunicate_67000_Content_2 = {
    Text = "Du bist zu freundlich, Hameln. Als unausgereifter Amateur bin ich kaum qualifiziert, deine Arbeit zu kritisieren."
  },
  AvgCommunicate_67000_Content_3 = {
    Text = "Nein, unterschätze dich nicht; deine Vorschläge sind meine größte Motivationsquelle."
  },
  AvgCommunicate_67000_Content_4 = {
    Text = "Ist es wirklich so übertrieben? Ich muss jedoch beschämend zugeben, dass ich immer einschlafe, während ich deinen neuen Kompositionen lausche..."
  },
  AvgCommunicate_67000_Content_5 = {
    Text = "Deine Musik ist schön und tadellos gespielt, jedoch bringt sie mich immer sofort zum Einschlafen. Vielleicht fehlt mir wirklich das musikalische Talent."
  },
  AvgCommunicate_67000_Content_6 = {
    Text = "Nein, das ist genau das, was ich will."
  },
  AvgCommunicate_67000_Content_7 = {
    Text = "Dir friedlichen Schlaf zu bringen, ist meine Mission und Pflicht."
  },
  AvgCommunicate_67000_Content_8 = {
    Text = "Stattdessen bitte beschreibe im Detail die Gefühle, die verschiedene Stücke bei dir hervorrufen, sowie die Qualität deines Schlafes, wie lange es dauert, einzuschlafen und die Dauer deines Schlafes."
  },
  AvgCommunicate_67000_Content_9 = {Text = "Huh?"},
  AvgCommunicate_67000_Option_2 = {
    Text = "Du bist wirklich zu höflich."
  },
  AvgCommunicate_67000_Option_4 = {
    Text = "Ist es wirklich so übertrieben?"
  },
  AvgCommunicate_67000_Option_9 = {Text = "Huh?"},
  AvgCommunicate_67001_Content_1 = {
    Text = "Schutzherr, wurden die neuen Tanzschuhe vor meiner Tür von dir geschickt?"
  },
  AvgCommunicate_67001_Content_10 = {
    Text = "Nein, ganz und gar nicht. Die Tanzschuhe, die du mir geschenkt hast, inspirieren meine Seele."
  },
  AvgCommunicate_67001_Content_11 = {
    Text = "Der Gedanke, dass sich jemand auf meinen Tanz freut, motiviert mich, weiterzutanzen."
  },
  AvgCommunicate_67001_Content_2 = {
    Text = "Haha, ist es so offensichtlich? Ich dachte, ich hätte keine Spuren hinterlassen?"
  },
  AvgCommunicate_67001_Content_3 = {
    Text = "In Misaq gibt es tatsächlich nur wenige, die sich so um mich sorgen und so sehr an andere denken."
  },
  AvgCommunicate_67001_Content_4 = {
    Text = "Ich bin dir für alles, was du für mich getan hast, stets dankbar. Danke, Schutzherr."
  },
  AvgCommunicate_67001_Content_5 = {
    Text = "Du bringst mich zum Erröten. Eigentlich ist mir aufgefallen, dass die Tanzschuhe, die du bei deinem letzten Auftritt getragen hast, etwas abgenutzt waren, also dachte ich, ich besorge dir ein neues Paar."
  },
  AvgCommunicate_67001_Content_6 = {
    Text = "Ah, tatsächlich, diese Tanzschuhe begleiten mich schon lange. Allerdings gilt für eine Tänzerin: Neuer ist nicht immer besser."
  },
  AvgCommunicate_67001_Content_7 = {
    Text = "Oh? Warum denn das?"
  },
  AvgCommunicate_67001_Content_8 = {
    Text = "Ein Paar Tanzschuhe muss unzählige Anpassungen durchlaufen, um sich allmählich den Füßen anzupassen. Die Abnutzung der Schuhe spiegelt oft die gewohnten Bewegungen der Tänzerin wider."
  },
  AvgCommunicate_67001_Content_9 = {
    Text = "Verstehe, es scheint, als hätte meine gute Absicht zum falschen Ergebnis geführt."
  },
  AvgCommunicate_67001_Option_2 = {
    Text = "Haha, ist es so offensichtlich? Ich dachte, ich hätte keine Spuren hinterlassen?"
  },
  AvgCommunicate_67001_Option_5 = {
    Text = "Du bringst mich ganz in Verlegenheit..."
  },
  AvgCommunicate_67001_Option_7 = {
    Text = "Oh? Warum denn das?"
  },
  AvgCommunicate_67001_Option_9 = {
    Text = "Verstehe, es scheint, als hätte meine gute Absicht zum falschen Ergebnis geführt."
  },
  AvgCommunicate_67002_Content_1 = {
    Text = "Schutzherr, wurde diese Einladung zur Veranstaltungsaufführung von dir geschickt?"
  },
  AvgCommunicate_67002_Content_10 = {
    Text = "Du hast mich überzeugt, Hüter."
  },
  AvgCommunicate_67002_Content_11 = {
    Text = "Ich werde mich gut vorbereiten. Danke."
  },
  AvgCommunicate_67002_Content_2 = {
    Text = "Weißt du, ich tanze nicht mehr in der Öffentlichkeit..."
  },
  AvgCommunicate_67002_Content_3 = {
    Text = "Ich weiß, deshalb erfordert dieser Auftritt auch kein Tanzen vor einem Publikum."
  },
  AvgCommunicate_67002_Content_4 = {
    Text = "Nicht nötig... vor anderen?"
  },
  AvgCommunicate_67002_Content_5 = {
    Text = "Genau, wir haben einen Schirm für dich gebaut und ihn mit Lichteffekten dahinter gestaltet."
  },
  AvgCommunicate_67002_Content_6 = {
    Text = "Während du hinter dem Schirm tanzt, sehen die Leute nur einen sich bewegenden Schatten, nicht dein Aussehen."
  },
  AvgCommunicate_67002_Content_7 = {
    Text = "Dein Auftritt verkörpert den Tanz selbst, nicht bloß dich."
  },
  AvgCommunicate_67002_Content_8 = {
    Text = "Den Tanz selbst..."
  },
  AvgCommunicate_67002_Content_9 = {
    Text = "Liz, bitte bringe die Schönheit des Tanzes zu allen. Dies ist eine reine Hommage an die Schönheit."
  },
  AvgCommunicate_67002_Option_3 = {
    Text = "Ich weiß, deshalb erfordert dieser Auftritt auch kein Tanzen vor einem Publikum."
  },
  AvgCommunicate_67002_Option_5 = {
    Text = "Genau, wir haben einen Schirm für dich gebaut und ihn mit Lichteffekten dahinter gestaltet."
  },
  AvgCommunicate_67002_Option_9 = {
    Text = "Liz, bitte bring jedem die Schönheit des Tanzes."
  },
  AvgCommunicate_67003_Content_1 = {
    Text = "Schutzherr, es gibt noch eine persönliche Aufgabe für dich."
  },
  AvgCommunicate_67003_Content_10 = {
    Text = "Verstanden, aber ich weiß nicht, wie man Maschinen repariert. Die Teile des Doll müssen sehr filigran sein."
  },
  AvgCommunicate_67003_Content_11 = {
    Text = "Die Körper dort sind unbenutzt und erfordern keine komplexe Wartung."
  },
  AvgCommunicate_67003_Content_12 = {
    Text = "Du musst sie nur einölen und ihre Gelenke ein wenig bewegen."
  },
  AvgCommunicate_67003_Content_13 = {
    Text = "Doll-Körper können schwer sein. Wenn es zu viel für dich ist, bitte Ramona oder Ogier, dich zu begleiten."
  },
  AvgCommunicate_67003_Content_14 = {
    Text = "Verstanden. Ich werde die Mission erfüllen!"
  },
  AvgCommunicate_67003_Content_15 = {
    Text = "Danke für deine Hilfe. Auch wenn es keine nennenswerte Belohnung gibt, werde ich bei der nächsten Prüfung vielleicht etwas nachsichtiger mit dir sein."
  },
  AvgCommunicate_67003_Content_2 = {
    Text = "Eine private Mission?"
  },
  AvgCommunicate_67003_Content_3 = {
    Text = "Betrachte es als einen persönlichen Gefallen für mich, oder du kannst auch ablehnen."
  },
  AvgCommunicate_67003_Content_4 = {Text = "Gerne!"},
  AvgCommunicate_67003_Content_5 = {
    Text = "Großartig, mehrere meiner Experimente haben kritische Phasen erreicht. Ich stecke schon lange im Labor fest und konnte es nicht verlassen."
  },
  AvgCommunicate_67003_Content_6 = {
    Text = "Aber mein Körper zeigt Anzeichen von Alterung und muss ersetzt werden."
  },
  AvgCommunicate_67003_Content_7 = {
    Text = "Ich brauche dich, um zu meinem Doll-Lager zu gehen, meinen Ersatzkörper zu warten und einen zurückzubringen."
  },
  AvgCommunicate_67003_Content_8 = {
    Text = "Doll-Lager?"
  },
  AvgCommunicate_67003_Content_9 = {
    Text = "Ja, es ist mein geheimer Lagerraum. Nur diejenigen, denen ich voll vertraue, dürfen dorthin."
  },
  AvgCommunicate_67003_Option_10 = {
    Text = "Verstanden, aber ich weiß nicht, wie man Maschinen repariert. Die Teile des Doll müssen sehr filigran sein."
  },
  AvgCommunicate_67003_Option_14 = {
    Text = "Verstanden. Ich werde die Mission erfüllen!"
  },
  AvgCommunicate_67003_Option_2 = {
    Text = "Eine private Mission?"
  },
  AvgCommunicate_67003_Option_4 = {Text = "Gerne!"},
  AvgCommunicate_67003_Option_8 = {
    Text = "Doll-Lager?"
  },
  AvgCommunicate_67004_Content_1 = {
    Text = "Ich habe bemerkt, dass deine Noten für die letzten Arbeiten niedrig waren und einige Einreichungen überfällig sind."
  },
  AvgCommunicate_67004_Content_10 = {
    Text = "Aufgaben sind lediglich eine Methode, dir zu helfen, das Wissen der Ermittler zu meistern, und bestimmen nicht die Fähigkeit oder den Wert einer Person."
  },
  AvgCommunicate_67004_Content_11 = {
    Text = "Wenn die Überarbeitung des einzigen Hüters in Mythag deinen Zustand aufgrund einiger Aufgaben beeinflusst, wäre das, als würde man das Pferd hinter den Wagen spannen."
  },
  AvgCommunicate_67004_Content_12 = {
    Text = "Doll... Ich bin so berührt!"
  },
  AvgCommunicate_67004_Content_13 = {
    Text = "Wenn Sie das Gefühl haben, dass Sie absolut keine Hausaufgaben machen müssen, können Sie weiterhin auf diese Weise vorgehen."
  },
  AvgCommunicate_67004_Content_14 = {
    Text = "Gibt es wirklich so etwas Gutes?!"
