  AvgCommunicate_67006_Content_1 = {
    Text = "Ich finde, dass, obwohl der technologische Fortschritt und die Unternehmensentwicklung langweilig bleiben, viele neue Arten von Kissen entstanden sind."
  },
  AvgCommunicate_67006_Content_10 = {
    Text = "Dieser Verkäufer hat Yu gesagt, dass Yu ein geborener Schlaftester ist und insisted, dass Yu langfristig Kissen für sie testet."
  },
  AvgCommunicate_67006_Content_11 = {
    Text = "Sie machen dich arbeiten? Wenn Miryam es erfährt, könnte sie sie einfach umbringen."
  },
  AvgCommunicate_67006_Content_12 = {
    Text = "Ich wollte ablehnen, aber er sagte, dass Testschläfer alle neuen Produkte kostenlos mit nach Hause nehmen könnten, um sie auszuprobieren."
  },
  AvgCommunicate_67006_Content_13 = {
    Text = "Als du seine Aufrichtigkeit siehst, stimmte ich zu."
  },
  AvgCommunicate_67006_Content_14 = {
    Text = "Hätte nie gedacht, dass du mit einem Kissen bestochen wirst... Ich meine, was für ein netter König."
  },
  AvgCommunicate_67006_Content_2 = {
    Text = "Neulich bin ich am Kaufhaus in Londinium vorbeigekommen und habe gesehen, dass sie eine Reihe neuer Kissen beworben haben."
  },
  AvgCommunicate_67006_Content_3 = {
    Text = "Ich warf nur zweimal einen Blick, und der Verkäufer zog mich dazu, ein Musterbett auszuprobieren. Wie unhöflich."
  },
  AvgCommunicate_67006_Content_4 = {
    Text = "Uh, es ähnelt wirklich ihrem Verkaufsstil."
  },
  AvgCommunicate_67006_Content_5 = {
    Text = "Aber das sogenannte Wolkenkissen ist tatsächlich außergewöhnlich weich. Es ist nicht wie Daunen oder Baumwolle; ich kann nicht herausfinden, woraus es besteht."
  },
  AvgCommunicate_67006_Content_6 = {
    Text = "Wahrscheinlich einige Industrieprodukte? Dinge, die in der alten Zeit definitiv nicht existierten."
  },
  AvgCommunicate_67006_Content_7 = {
    Text = "Es ist alles, weil das Kissen zu bequem war. Ich wurde schläfrig und bin dort tatsächlich eingeschlafen – wie peinlich."
  },
  AvgCommunicate_67006_Content_8 = {
    Text = "Ist es wirklich so bequem?!"
  },
  AvgCommunicate_67006_Content_9 = {
    Text = "Beim Wachwerden diskutierte ich einige Fragen zur Form des Kissens mit dem Verkäufer."
