  },
  AvgCommunicate_67007_Content_1 = {
    Text = "Meister, heute hat Aigis Jenkin und mir von den Spielsachen im Waisenhaus erzählt."
  },
  AvgCommunicate_67007_Content_10 = {
    Text = "Nein, Schutzherr, hör nicht auf Jenkin. Meiner Puppe geht es gut, und wir brauchen keine neue!"
  },
  AvgCommunicate_67007_Content_11 = {
    Text = "In Ordnung, in Ordnung, ich kaufe alles!"
  },
  AvgCommunicate_67007_Content_12 = {
    Text = "Meister, der Kommunikator wurde gerade weggeschnappt und fallen gelassen; es scheint, als hätte er ein Bauteil verloren."
  },
  AvgCommunicate_67007_Content_13 = {
    Text = "Kann man den auch neu kaufen?"
  },
  AvgCommunicate_67007_Content_14 = {Text = "Hä???"},
  AvgCommunicate_67007_Content_2 = {
    Text = "Sie sagte, es gibt ein Spielzeug namens Tangram, das aus sieben flachen Teilen besteht, die verschiedene Muster bilden können und dann wieder zu einem Quadrat zusammengesetzt werden."
  },
  AvgCommunicate_67007_Content_3 = {
    Text = "Jenkin sagte, man könnte eines aus Papier basteln, aber nach langer Diskussion konnten wir das Muster dieses Tangrams immer noch nicht herausfinden."
  },
  AvgCommunicate_67007_Content_4 = {
    Text = "Meister, hast du schon einmal gesehen, wie ein Tangram aussieht?"
