  AvgCommunicate_67007_Content_5 = {
    Text = "Ich habe es schon einmal gesehen, aber jetzt, wo du es erwähnst, habe ich vergessen, wie es genau aussah..."
  },
  AvgCommunicate_67007_Content_6 = {
