  AvgCommunicate_67008_Content_1 = {Text = "*seufz*..."},
  AvgCommunicate_67008_Content_10 = {
    Text = "Für jemanden so nutzlos wie mich wäre es nicht besser, einfach aufzugeben und ein Grab zu finden, um auf den Tod zu warten?"
  },
  AvgCommunicate_67008_Content_11 = {
    Text = "Es muss nicht so extrem sein!!"
  },
  AvgCommunicate_67008_Content_12 = {
    Text = "Ich habe immer das Gefühl gehabt, dass es nicht deine Schuld war. Du wurdest von denen getäuscht, die dir Heilmittel verkauft haben; sie haben einfach deine verzweifelten Gefühle ausgenutzt."
  },
  AvgCommunicate_67008_Content_13 = {
    Text = "Dein Körper ist nicht unfähig, durchzubrechen; er ist einfach vergiftet und krank!"
