  AvgCommunicate_67008_Content_14 = {
    Text = "Ist das so? Was Sie gesagt haben, scheint Sinn zu ergeben."
  },
  AvgCommunicate_67008_Content_15 = {
    Text = "Habe ich das nicht die ganze Zeit gesagt!!"
  },
  AvgCommunicate_67008_Content_16 = {
    Text = "Also bin ich einfach krank, mein Erwachen hat immer noch Hoffnung"
  },
  AvgCommunicate_67008_Content_17 = {
    Text = "Mm-hmm... Genau, also musst du dich nur darauf konzentrieren, besser zu werden."
  },
  AvgCommunicate_67008_Content_18 = {
    Text = "Ich verstehe, danke, Hüter."
  },
  AvgCommunicate_67008_Content_19 = {
    Text = "Also... kannst du mir fünfzig leihen, um einen Arzt aufzusuchen?"
  },
  AvgCommunicate_67008_Content_2 = {
