  },
  AvgCommunicate_67008_Content_7 = {
    Text = "Seit ich dieses Heilmittel genommen habe, fühle ich jeden Tag, wie mein Blut strömt, aber das Erwachen ist nicht gekommen."
  },
  AvgCommunicate_67008_Content_8 = {
