    Text = "Mm... Falls du zufällig durch die Innenstadt gehst, etwas Zeit hast und es dir passt, könntest du mir etwas neues Garn mitbringen?"
  },
  AvgCommunicate_67012_Content_4 = {
    Text = "Ich muss die Puppe, das Kleid und die Kleidung von allen ausbessern. Jenkins Umhang wird auch schon alt..."
  },
  AvgCommunicate_67012_Content_5 = {
    Text = "Reichen die Garne nicht aus? Ich werde es mir merken. Welche Farbe möchtest du?"
  },
  AvgCommunicate_67012_Content_6 = {
    Text = "Wie wäre es, wenn ich dich zum Shoppen für neue Kleidung mitnehme? Lass uns Jenkin und Lily einladen."
  },
  AvgCommunicate_67012_Content_7 = {
    Text = "Nein, kein Bedarf! Meine Kleidung ist noch tragbar. Das wäre so eine Verschwendung..."
  },
  AvgCommunicate_67012_Content_8 = {
    Text = "Wie könnte das eine Verschwendung sein, Aigis? Es gibt keinen Grund, so vorsichtig zu sein. Wir alle sind glücklich, deine Wünsche zu erfüllen."
  },
  AvgCommunicate_67012_Content_9 = {
    Text = "Mythags tägliche Finanzierung ist mehr als ausreichend. Niemand wird dich jemals wieder im Stich lassen, verstanden?"
  },
  AvgCommunicate_67012_Option_11 = {Text = "Gut."},
  AvgCommunicate_67012_Option_2 = {
    Text = "Was ist los?"
  },
  AvgCommunicate_67012_Option_5 = {
    Text = "Reichen die Garne nicht aus? Ich werde es mir merken. Welche Farbe möchtest du?"
  },
  AvgCommunicate_67012_Option_8 = {
    Text = "Wie könnte es eine Verschwendung sein?"
  },
  AvgCommunicate_67013_Content_1 = {
    Text = "Schutzherr, hilf mir! Es fühlt sich an, als würden Ameisen über meinen ganzen Körper krabbeln!"
  },
  AvgCommunicate_67013_Content_10 = {
    Text = "Den Sandsack im Trainingsraum leeren und dich reinstecken. Denk daran, still zu bleiben."
  },
  AvgCommunicate_67013_Content_11 = {
    Text = "Oh mein Gott, Schutzherr, du bist so gütig!"
  },
  AvgCommunicate_67013_Content_2 = {
    Text = "...Was ist los mit dir? Wenn du krank bist, kannst du dich im Krankenzimmer behandeln lassen."
  },
  AvgCommunicate_67013_Content_3 = {
    Text = "Ich... ich weiß nicht. Ich kann kaum noch atmen..."
  },
  AvgCommunicate_67013_Content_4 = {
    Text = "So schlimm? Wo bist du? Soll ich einen Arzt rufen?"
  },
  AvgCommunicate_67013_Content_5 = {
    Text = "Ich... Ich stehe vor deiner Tür, bitte verprügel mich! Ich wurde seit drei Tagen nicht mehr verprügelt! Es ist so unerträglich!"
  },
  AvgCommunicate_67013_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_67013_Content_7 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgCommunicate_67013_Content_8 = {
    Text = "Ich habe bereits den Sicherheitsdienst kontaktiert und eine neue Aufgabe für dich arrangiert. Sie werden dich rübertragen."
  },
  AvgCommunicate_67013_Content_9 = {
    Text = "Was für ein Job?"
  },
  AvgCommunicate_67013_Option_10 = {
    Text = "Den Sandsack im Trainingsraum leeren und dich reinstecken. Denk daran, still zu bleiben."
  },
  AvgCommunicate_67013_Option_2 = {
    Text = "...Was ist los mit dir? Wenn du krank bist, kannst du dich im Krankenzimmer behandeln lassen."
  },
  AvgCommunicate_67013_Option_4 = {
    Text = "So schlimm? Wo bist du? Soll ich einen Arzt rufen?"
  },
  AvgCommunicate_67013_Option_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_67013_Option_7 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgCommunicate_67014_Content_1 = {
    Text = "Hüter, manchmal frage ich mich, ob alles, was ich getan habe, meinen König wirklich zufrieden gestellt hat?"
  },
  AvgCommunicate_67014_Content_10 = {
    Text = "Aber ich glaube, das Einzige, was die Götter fühlen können, ist die fromme, leidenschaftliche Hingabe ihrer Anhänger."
  },
  AvgCommunicate_67014_Content_11 = {
    Text = "Vielleicht ist das, was du getan hast, nicht der wichtigste Teil; was zählt, ist das Herz, das du hineingesteckt hast. Schließlich hat Tulu dich nie aufgehalten, oder?"
  },
  AvgCommunicate_67014_Content_12 = {
    Text = "Ich habe nie erwartet, von einem Skeptiker wie dir erleuchtet zu werden. Deine Worte haben einen tiefen Eindruck bei mir hinterlassen. Danke."
  },
  AvgCommunicate_67014_Content_2 = {
    Text = "Ist der Weg, den ich gewählt habe, wirklich der richtige?"
  },
  AvgCommunicate_67014_Content_3 = {
    Text = "Hätte nie gedacht, dass du eines Tages über dich selbst nachdenkst."
  },
  AvgCommunicate_67014_Content_4 = {
    Text = "Weil ich auch verwirrt, müde und niedergeschlagen bin. Wenn alles, was ich tue, richtig ist, warum hat der König nicht auf mich reagiert?"
  },
  AvgCommunicate_67014_Content_5 = {
    Text = "Auch wenn ich nicht so gläubig bin wie du, glaube ich, dass das, was die Anhänger für Gott tun, nicht unbedingt das ist, was Gott braucht."
  },
  AvgCommunicate_67014_Content_6 = {
    Text = "Was hast du gesagt?"
  },
  AvgCommunicate_67014_Content_7 = {
    Text = "Hey, hey, beeile dich nicht. Ich habe noch nicht fertig gesprochen."
  },
  AvgCommunicate_67014_Content_8 = {
    Text = "Der Unterschied zwischen Sterblichen und Göttern ist vergleichbar mit dem zwischen Ameisen und Menschen. Ich glaube nicht, dass Menschen die Bedürfnisse der Götter vollständig verstehen können."
  },
  AvgCommunicate_67014_Content_9 = {
    Text = "Ameisen... Vielleicht hast du recht."
  },
  AvgCommunicate_67014_Option_10 = {
    Text = "Aber ich glaube..."
  },
  AvgCommunicate_67014_Option_3 = {
    Text = "Hätte nie gedacht, dass du eines Tages über dich selbst nachdenkst."
  },
  AvgCommunicate_67014_Option_5 = {
    Text = "Obwohl mein Glaube nicht so gläubig ist wie deiner..."
  },
  AvgCommunicate_67014_Option_7 = {
    Text = "Hey, hey, beeile dich nicht. Ich habe noch nicht fertig gesprochen."
  },
  AvgCommunicate_67015_Content_1 = {
    Text = "Schutzherr, der Vortrag, den ich auf dem Campus gehalten habe, und die Broschüren, die ich gedruckt habe, wurden gut aufgenommen."
  },
  AvgCommunicate_67015_Content_10 = {
    Text = "Fräulein Sanga? Ich sehe sie selten, aber ich habe gehört, dass sie eine herausragende Bildhauerin ist."
  },
  AvgCommunicate_67015_Content_11 = {
    Text = "Wenn sie bereit ist, für meinen Herrn zu meißeln, wäre das perfekt; das Göttliche Reich wird sie beschützen."
  },
  AvgCommunicate_67015_Content_2 = {
    Text = "Sie begannen, meinen großen Herrn zu verehren. Einige Anhänger baten mich um Miniaturstatuen, damit sie diese in ihren Zimmern zum Beten und Verehren aufstellen können."
  },
  AvgCommunicate_67015_Content_3 = {
    Text = "Ich finde, das ergibt Sinn. Wo kann ich einen Handwerker finden, um eine Charge solcher Statuen anfertigen zu lassen?"
  },
  AvgCommunicate_67015_Content_4 = {
    Text = "Ministatuetten? Klingt ein bisschen seltsam..."
  },
  AvgCommunicate_67015_Content_5 = {
    Text = "Was ist daran falsch? Die Handwerkskunst dieser Statuen ist exquisit. Hat Misaq nicht solch geschickte Kunsthandwerker?"
  },
  AvgCommunicate_67015_Content_6 = {
    Text = "Es liegt nicht am Handwerker; es scheint nur, als wollten sie diese Statuen für etwas anderes als Gebet und Verehrung..."
  },
  AvgCommunicate_67015_Content_7 = {
    Text = "Unmöglich, ich habe ihre Begeisterung für meinen Herrn gesehen. Sie interessieren sich sogar für jedes Detail der Vorlieben und des Lebensstils meines Herrn."
  },
  AvgCommunicate_67015_Content_8 = {
    Text = "Dann erst recht... Egal, solange du glücklich bist."
  },
  AvgCommunicate_67015_Content_9 = {
    Text = "Ich werde Sanga fragen, ob sie bereit ist, diese Charge Statuen anzufertigen."
  },
  AvgCommunicate_67015_Option_4 = {
    Text = "Ministatuetten? Klingt ein bisschen seltsam..."
  },
  AvgCommunicate_67015_Option_6 = {
    Text = "Es liegt nicht am Handwerker..."
  },
  AvgCommunicate_67015_Option_8 = {
    Text = "Dann erst recht... Egal, solange du glücklich bist."
  },
  AvgCommunicate_67016_Content_1 = {
    Text = "Seufz, Schutzherr, ich bin hier, um Euch und dem Edlen Dexter meine Nachlässigkeit zu erklären, in der Hoffnung auf Eure Vergebung."
  },
  AvgCommunicate_67016_Content_10 = {
    Text = "Hust... Auch wenn es tragisch ist, es ist nicht deine Schuld. Mach dir keine Vorwürfe."
  },
  AvgCommunicate_67016_Content_11 = {
    Text = "Nein, es ist meine Schuld, dass ich nicht aufgepasst habe. Ich werde öffentlich eine Selbstkritik abgeben und das tägliche Management verstärken."
  },
  AvgCommunicate_67016_Content_2 = {
    Text = "Aufgrund meiner mangelhaften Aufsicht wurden zwei Patienten im Sanatorium schwer vergiftet. Glücklicherweise konnten sie nach einer Notfallbehandlung stabilisiert werden."
  },
  AvgCommunicate_67016_Content_3 = {
    Text = "Hä? Was ist passiert?"
  },
  AvgCommunicate_67016_Content_4 = {
    Text = "Ja, hinter dem Sanatorium gibt es einen kleinen Teich, der selten besucht wird."
  },
  AvgCommunicate_67016_Content_5 = {
    Text = "Du weißt, wie sehr ich Wasser liebe. An arbeitsreichen Tagen tauche ich nachts still in den Teich ein und genieße einen Moment der Ruhe unter Wasser."
  },
  AvgCommunicate_67016_Content_6 = {
    Text = "Mm... Verständlich. Es gibt keinen Job ohne Stress."
  },
  AvgCommunicate_67016_Content_7 = {
    Text = "Vielleicht habe ich ihn zu oft besucht, und die Giftstoffe in mir haben sich auf den Teich und die Fische darin ausgebreitet."
  },
  AvgCommunicate_67016_Content_8 = {
    Text = "Dieser Teich lag nicht im Aktivitätsbereich der Patienten, aber zwei gierige Patienten haben sich vor zwei Tagen dorthin geschlichen, um zu angeln und ihren Fang zu grillen."
  },
  AvgCommunicate_67016_Content_9 = {
    Text = "Als das medizinische Personal sie fand, hatten sie bereits Schaum vor dem Mund und lagen bewusstlos am Boden..."
  },
  AvgCommunicate_67016_Option_10 = {
    Text = "Hust... Auch wenn es tragisch ist, es ist nicht deine Schuld. Mach dir keine Vorwürfe."
  },
  AvgCommunicate_67016_Option_3 = {
    Text = "Hä? Was ist passiert?"
  },
  AvgCommunicate_67016_Option_6 = {
    Text = "Mm... Verständlich. Es gibt keinen Job ohne Stress."
  },
  AvgCommunicate_67017_Content_1 = {
    Text = "Schutzherr, ein Besucher von Misaq hat mich zufällig beim Üben singen gehört."
  },
  AvgCommunicate_67017_Content_10 = {
    Text = "Du liebst das Singen und Auftreten. Warum nicht mehr Menschen deine Stimme hören lassen?"
  },
  AvgCommunicate_67017_Content_11 = {
    Text = "Liebe... Ich verstehe. Danke, Schutzherr."
  },
  AvgCommunicate_67017_Content_12 = {
    Text = "Ich werde versuchen, auf diesem Planeten noch einmal zu strahlen."
  },
  AvgCommunicate_67017_Content_2 = {
    Text = "Jetzt lädt mich die andere Partei ein, mit seiner Firma zusammenzuarbeiten, um einige Platten herauszubringen. Soll ich zustimmen?"
  },
  AvgCommunicate_67017_Content_3 = {
    Text = "Ich denke, das ist möglich. Ich erinnere mich, dass du einst eine berühmte Sängerin warst, richtig?"
  },
  AvgCommunicate_67017_Content_4 = {
    Text = "Ja, meine Lieder waren einst sehr beliebt auf Wild Star, aber die meiste Zeit waren sie nur zum Handel mit dem Adel gedacht."
  },
  AvgCommunicate_67017_Content_5 = {
    Text = "Jetzt, da ich meine Schwester zurückhabe, brauche ich nichts mehr."
  },
  AvgCommunicate_67017_Content_6 = {
    Text = "Und du? Wenn du singst, fühlst du dich dann immer noch glücklich?"
  },
  AvgCommunicate_67017_Content_7 = {
    Text = "Glück... Vielleicht ist es Glück, schließlich ist alles, was ich jetzt tun kann, singen."
  },
  AvgCommunicate_67017_Content_8 = {
    Text = "Nein, Tinct. Wenn es keine wahre Liebe wäre, würde niemand jeden Tag Gesang üben."
  },
  AvgCommunicate_67017_Content_9 = {
    Text = "Es ist nur natürlich, an dem festzuhalten, was man liebt."
  },
  AvgCommunicate_67017_Option_3 = {
    Text = "Ich denke, das ist möglich. Ich erinnere mich, dass du einst eine berühmte Sängerin warst, richtig?"
  },
  AvgCommunicate_67017_Option_6 = {
    Text = "Und du? Wenn du singst, fühlst du dich dann immer noch glücklich?"
  },
  AvgCommunicate_67017_Option_8 = {
    Text = "Ohne wahre Leidenschaft würde niemand jeden Tag weiter Gesang üben."
  },
  AvgCommunicate_67018_Content_1 = {
    Text = "Blasser Befehlsträger, ich wollte Euch mitteilen, dass ich vorhabe, Misaq zu besuchen."
  },
  AvgCommunicate_67018_Content_2 = {
    Text = "Ein früherer Besuch schien etwas geholfen zu haben, und ich wurde eingeladen, wiederzukommen, um mit allen in der Halle zu plaudern."
  },
  AvgCommunicate_67018_Content_3 = {
    Text = "Falls Ihr zufällig etwas freie Zeit habt, würde ich mich freuen, Euch auf dem Campus zu sehen."
  },
  AvgCommunicate_67018_Content_4 = {
    Text = "Ich würde es lieben!"
  },
  AvgCommunicate_67018_Content_5 = {
    Text = "Großartig, ich werde mir etwas Zeit nur für Euch nehmen, um alles anzuhören, was Ihr mir erzählen möchtet."
  },
  AvgCommunicate_67018_Content_6 = {
    Text = "Treffen wir uns allein?"
  },
  AvgCommunicate_67018_Content_7 = {
    Text = "Ja, schließlich ist das kein Gottesdienst, sondern nur ein Treffen unter Freunden, oder?"
  },
  AvgCommunicate_67018_Content_8 = {
    Text = "Kein Problem, ich zeige Euch die Sehenswürdigkeiten von Misaq. Vielleicht möchtet Ihr die Cafeteria des Erweckten Körpers ausprobieren?"
  },
  AvgCommunicate_67018_Content_9 = {
    Text = "Alles liegt in Eurer Hand. Ich freue mich darauf."
  },
  AvgCommunicate_67018_Option_4 = {
    Text = "Ich würde es lieben!"
  },
  AvgCommunicate_67018_Option_6 = {
    Text = "Treffen wir uns allein?"
  },
  AvgCommunicate_67018_Option_8 = {
    Text = "Kein Problem!"
  },
  AvgCommunicate_67019_Content_1 = {
    Text = "Bleicher Befehlsträger, im Kirchenviertel wird bald eine große Messe abgehalten."
  },
  AvgCommunicate_67019_Content_10 = {
    Text = "Dein aufrichtiges Herz wärmt mich, daher werde ich nicht länger ablehnen."
  },
  AvgCommunicate_67019_Content_11 = {
    Text = "Bitte komm, wann immer du Zeit hast, und hilf mir bei einigen einfachen Reinigungs- und Ordnungsarbeiten."
  },
  AvgCommunicate_67019_Content_12 = {
    Text = "Kein Problem, bis dann!"
  },
  AvgCommunicate_67019_Content_13 = {
    Text = "Nochmals vielen Dank, bleicher Bote. Möge der Vatergott deinen Weg beschützen."
  },
  AvgCommunicate_67019_Content_2 = {
    Text = "Ich werde die Zeremonie leiten und die Lehren des Vaters verkünden."
  },
  AvgCommunicate_67019_Content_3 = {
    Text = "Gläubige aus Lentiniën und den umliegenden Gebieten werden kommen, und du bist herzlich eingeladen, am Erntedankgottesdienst teilzunehmen, wenn du Interesse hast."
  },
  AvgCommunicate_67019_Content_4 = {
    Text = "Sehr gerne! Aber wenn man die Zahl der Gläubigen bedenkt, muss die Vorbereitung dieser Messe ziemlich aufwendig gewesen sein."
  },
  AvgCommunicate_67019_Content_5 = {
    Text = "Du bist immer so aufmerksam, gütig und rücksichtsvoll."
  },
  AvgCommunicate_67019_Content_6 = {
    Text = "In der Tat, alles vorzubereiten, was nötig ist, damit jeder die Gnade des Vaters spüren kann, ist eine ganze Menge."
  },
  AvgCommunicate_67019_Content_7 = {
    Text = "Aber keine Sorge, ich habe umfangreiche Erfahrung in der Leitung von Messen und kann diese Kleinigkeiten mit Leichtigkeit bewältigen."
  },
  AvgCommunicate_67019_Content_8 = {
    Text = "Egal wie erfahren man ist, niemand hat drei Köpfe und sechs Arme. Wenn möglich, lass mich dir im Voraus helfen!"
  },
  AvgCommunicate_67019_Content_9 = {
    Text = "Schließlich gilt bei einem so großen Ereignis: Je sorgfältiger die Vorbereitung, desto besser."
  },
  AvgCommunicate_67019_Option_12 = {
    Text = "Kein Problem, bis dann!"
  },
  AvgCommunicate_67019_Option_4 = {
    Text = "Ich würde es lieben!"
  },
  AvgCommunicate_67019_Option_8 = {
    Text = "Wenn möglich, lass mich dir im Voraus helfen!"
  },
  AvgCommunicate_67020_Content_1 = {
    Text = "Seufz, seit Misaq die Beschränkungsanordnung erlassen hat, kommt kein Süßer mehr, um mit mir zu plaudern."
  },
  AvgCommunicate_67020_Content_10 = {
    Text = "Nun, dann muss ich wohl beten, dass die Sonne bald untergeht."
  },
  AvgCommunicate_67020_Content_11 = {
    Text = "Ah, ich kann es kaum erwarten, das Mondlicht heute Nacht zu sehen."
  },
  AvgCommunicate_67020_Content_2 = {
    Text = "Was soll diese Regel, dass keine Besucher erlaubt sind, es sei denn, du bist dabei?"
  },
  AvgCommunicate_67020_Content_3 = {
    Text = "Du, komm schon, gib es zu. War das dein Werk — hast du es aus Eifersucht der Schule gemeldet?"
  },
  AvgCommunicate_67020_Content_4 = {
    Text = "Du warst es, der die Schüler zuerst dazu verleitet hat, seltsame Sachen zu trinken..."
  },
  AvgCommunicate_67020_Content_5 = {
    Text = "Das war ein Segen der Liebe. Glaubst du wirklich, ich wäre so niederträchtig?"
  },
  AvgCommunicate_67020_Content_6 = {
    Text = "Ich habe jeden Tag in Einsamkeit auf dich gewartet... Ich hätte nie erwartet, dass du so von mir denkst."
  },
  AvgCommunicate_67020_Content_7 = {
    Text = "Genug! Ich verstehe. Ich werde mehr Zeit mit dir verbringen."
  },
  AvgCommunicate_67020_Content_8 = {
    Text = "Du bist so ein rücksichtsvolles Kind, aber ich will dich in jedem Moment sehen, jetzt sofort, ohne auch nur eine Sekunde zu warten."
  },
  AvgCommunicate_67020_Content_9 = {
    Text = "Heute Nacht komme ich. In Ordnung!"
  },
  AvgCommunicate_67020_Option_4 = {
    Text = "Du warst es, der die Schüler zuerst dazu verleitet hat, seltsame Sachen zu trinken..."
  },
  AvgCommunicate_67020_Option_7 = {
    Text = "Genug! Ich verstehe. Ich werde mehr Zeit mit dir verbringen."
  },
  AvgCommunicate_67020_Option_9 = {
    Text = "Heute Nacht komme ich. In Ordnung!"
  },
  AvgCommunicate_67021_Content_1 = {
    Text = "Hüter, entschuldige die Störung. Hast du in letzter Zeit etwas freie Zeit?"
  },
  AvgCommunicate_67021_Content_10 = {
    Text = "Also, könntest du bitte mitkommen?"
  },
  AvgCommunicate_67021_Content_11 = {
    Text = "Mm, wäre das in Ordnung?"
  },
  AvgCommunicate_67021_Content_12 = {
    Text = "Natürlich, kein Problem. Das klingt lustig!"
  },
  AvgCommunicate_67021_Content_13 = {
    Text = "Danke, Schutzherr! Ich fühle mich viel sicherer mit dir an meiner Seite."
  },
  AvgCommunicate_67021_Content_14 = {
    Text = "Ich habe gehört, dass spontan verfasste Gedichte Preise gewinnen können. Wenn ich das Glück habe, einen zu bekommen, schenke ich ihn dir als Dankeschön."
  },
  AvgCommunicate_67021_Content_2 = {
    Text = "Was ist los? Es kommt selten vor, dass du mich aufsuchst."
  },
  AvgCommunicate_67021_Content_3 = {
    Text = "Ja, in Lentiniën wird bald ein Poesiemarkt stattfinden. Auf dem Markt werden viele neue und alte Bücher verkauft, und viele Dichter werden sich versammeln, um Ideen auszutauschen."
  },
  AvgCommunicate_67021_Content_4 = {
    Text = "Die Veranstalter haben mich auch eingeladen, einen Stand aufzubauen, um meine Gedichte zu teilen."
  },
  AvgCommunicate_67021_Content_5 = {
    Text = "Sie haben so herzlich darauf bestanden, und ich habe unachtsam zugesagt, aber..."
  },
  AvgCommunicate_67021_Content_6 = {
    Text = "Aber alleine einen Stand zu betreiben, macht mich zu nervös."
  },
  AvgCommunicate_67021_Content_7 = {
    Text = "Mm... Du verstehst mich immer."
  },
  AvgCommunicate_67021_Content_8 = {
    Text = "Aber ich möchte mein Versprechen nicht brechen, und die Veranstaltung klingt interessant! Es hieß, es würde ein kreatives Live-Staffelschreiben geben."
  },
  AvgCommunicate_67021_Content_9 = {Text = "Also..."},
  AvgCommunicate_67021_Option_10 = {
    Text = "Also, könntest du bitte mitkommen?"
  },
  AvgCommunicate_67021_Option_12 = {
