  },
  AvgCommunicate_67021_Option_6 = {
    Text = "Aber alleine einen Stand zu betreiben, macht mich zu nervös."
  },
  AvgCommunicate_67022_Content_1 = {
    Text = "Schutzherr, mir ist endlich eine gute Methode eingefallen, um tief und fest zu schlafen."
  },
  AvgCommunicate_67022_Content_10 = {
    Text = "Das stört doch schon andere, oder nicht!"
  },
  AvgCommunicate_67022_Content_11 = {
    Text = "Einfach als dekoratives Kunstwerk betrachten! Ich schnarche nicht!"
  },
  AvgCommunicate_67022_Content_12 = {
    Text = "Moment, sag mir nicht, dass ich die vertrauenswürdige Person bin, von der du sprichst."
  },
  AvgCommunicate_67022_Content_13 = {
    Text = "Natürlich, du bist der sanftmütigste, zuverlässigste und mächtigste Schutzherr in ganz Misaq! Diese Rolle gehört ohne Zweifel dir!"
  },
  AvgCommunicate_67022_Content_14 = {
    Text = "Ich plane, die Schlafkugel heute Nacht umzustellen. Wenn du möchtest, kann ich mich auch vor dem Schlafengehen noch mit dir unterhalten～"
  },
