  AvgCommunicate_67022_Content_16 = {Text = "Keeper??"},
  AvgCommunicate_67022_Content_2 = {
    Text = "Herzlichen Glückwunsch! Was ist die Lösung?"
  },
  AvgCommunicate_67022_Content_3 = {
    Text = "Ich habe eine Schlafkugel entworfen, die nachts beleuchtet bleibt, sodass kein starkes Licht nötig ist und keine dunklen Ecken entstehen."
  },
  AvgCommunicate_67022_Content_4 = {
    Text = "Klingt großartig. Jetzt musst du dich endlich nicht mehr in fremde Schlafsäle schleichen und jeden Tag rausgeworfen werden."
  },
  AvgCommunicate_67022_Content_5 = {
    Text = "Nein! Um Fehlfunktionen der Schlafkapsel zu verhindern und äußere Gefahren zu vermeiden, muss ich sie in einem bewohnten Bereich aufstellen."
  },
  AvgCommunicate_67022_Content_6 = {
    Text = "? Willst du das Ding in jemand anderes Zimmer stellen?"
  },
  AvgCommunicate_67022_Content_7 = {
    Text = "Genau, ich übergebe den Notfall-Neustart-Knopf der Schlafkugel an jemanden, dem ich vertraue. So wird alles absolut sicher sein!"
  },
  AvgCommunicate_67022_Content_8 = {
    Text = "Und jetzt wird meine Angewohnheit, bei Licht zu schlafen, niemand anderen mehr stören. Es ist perfekt."
  },
  AvgCommunicate_67022_Content_9 = {
    Text = "Perfekt, mein Fuß!"
  },
  AvgCommunicate_67022_Option_10 = {
    Text = "Das stört doch schon andere, oder nicht!"
  },
  AvgCommunicate_67022_Option_12 = {
    Text = "Moment, sag mir nicht, dass ich die vertrauenswürdige Person bin, von der du sprichst."
  },
  AvgCommunicate_67022_Option_2 = {
    Text = "Herzlichen Glückwunsch! Was ist die Lösung?"
  },
  AvgCommunicate_67022_Option_4 = {
    Text = "Klingt gut."
  },
  AvgCommunicate_67022_Option_6 = {
    Text = "? Willst du das Ding in jemand anderes Zimmer stellen?"
  },
  AvgCommunicate_67022_Option_9 = {
    Text = "Perfekt, mein Fuß!"
  },
  AvgCommunicate_67023_Content_1 = {
    Text = "Schutzherr, ich sehe in letzter Zeit seltsame Flecken, und mir ist oft schwindelig, ich habe Herzrasen, Engegefühl in der Brust und Tinnitus... Sterbe ich etwa?!"
  },
  AvgCommunicate_67023_Content_10 = {
    Text = "Nein, du verstehst das nicht. Die Schwärze ist überall; sie wird mich finden, egal wo ich bin! Ich kann nicht schlafen, kann meine Augen nicht schließen..."
  },
  AvgCommunicate_67023_Content_11 = {
    Text = "Ähm... wie wäre es, jemanden anzuheuern, der dich K.O. schlägt? So hast du keine Angst, wenn du bewusstlos bist."
  },
  AvgCommunicate_67023_Content_12 = {
    Text = "Oh? Das scheint tatsächlich Sinn zu ergeben."
  },
  AvgCommunicate_67023_Content_13 = {
    Text = "Da der Untergang unvermeidlich ist, lass mich friedlich in seliger Unwissenheit sterben..."
  },
  AvgCommunicate_67023_Content_14 = {
    Text = "Einfach nur bewusstlos geschlagen, vom Sterben noch weit entfernt!"
  },
  AvgCommunicate_67023_Content_15 = {
    Text = "Danke, Schutzherr. Dann überlasse ich diese Angelegenheit dir, der Person, der ich am meisten vertraue."
  },
  AvgCommunicate_67023_Content_16 = {
    Text = "...Ich hätte es nicht ansprechen sollen!!"
  },
  AvgCommunicate_67023_Content_2 = {
    Text = "Ähm, deinem Tagesablauf nach zu urteilen, bist du zu lange aufgeblieben. Es wird empfohlen, dass du früher ins Bett gehst."
  },
  AvgCommunicate_67023_Content_3 = {
    Text = "Was? Hat auch dieser Körper seine Grenzen erreicht..."
  },
  AvgCommunicate_67023_Content_4 = {
    Text = "Aber sich dieser schrecklichen Schwärze zu stellen, wäre für mich genauso tödlich!"
  },
  AvgCommunicate_67023_Content_5 = {
    Text = "Ah, verdammt, langfristiger oder kurzfristiger Schmerz, Überleben oder Untergang... Was soll ich wählen..."
  },
  AvgCommunicate_67023_Content_6 = {
    Text = "Ist das wirklich so übertrieben? Das hat ja schon philosophisches Niveau!"
  },
  AvgCommunicate_67023_Content_7 = {
    Text = "Aber es ist doch noch nie etwas Schlimmes wegen des Schlafens passiert, oder? Dieser Schrecken ist nur deine Einbildung. Vielleicht solltest du es mit Desensibilisierung versuchen."
  },
  AvgCommunicate_67023_Content_8 = {
    Text = "Desensibilisierung?"
  },
  AvgCommunicate_67023_Content_9 = {
