  },
  AvgCommunicate_67024_Content_11 = {
    Text = "Oh, das sind die exklusiven Fähigkeiten von Meister Casiah. Natürlich kannst du sie nicht lernen."
  },
  AvgCommunicate_67024_Content_12 = {
    Text = "Aber Lehrer Casiah kann dir beibringen, wie du geschickte Hände bekommst. Auf diese Weise wirst du auch die Techniken des Schlösserknackens und der Diebstahlkunst meistern, wenn du auf Seile triffst, die sich nicht lösen lassen, oder Schlösser, die sich nicht öffnen lassen!"
  },
  AvgCommunicate_67024_Content_13 = {
    Text = "Immer noch seltsame Dinge lehren!"
  },
  AvgCommunicate_67024_Content_14 = {
    Text = "Verwende keine seltsamen Worte leichtfertig!!"
  },
  AvgCommunicate_67024_Content_15 = {
    Text = "Tsk, verursachen Dolls Schüler auch so viel Ärger? Was für eine Mühe. Lehrer zu sein macht wirklich keinen Spaß."
  },
  AvgCommunicate_67024_Content_16 = {
    Text = "Obwohl Mrs. Puppe wirklich fleißig ist, möchte ich besonders nicht von dir ungeliebt sein!"
  },
  AvgCommunicate_67024_Content_2 = {
    Text = "Was hast du wieder vor??"
  },
  AvgCommunicate_67024_Content_3 = {
    Text = "Was? Dieses Mal halte ich ernsthaft eine Vorlesung auf Einladung der Schule!"
  },
  AvgCommunicate_67024_Content_4 = {
