  AvgCommunicate_67025_Content_1 = {
    Text = "Der Effekt des kürzlichen militärischen Hundetrainings übertraf meine Erwartungen."
  },
  AvgCommunicate_67025_Content_10 = {
    Text = "Bitte reservier unbedingt einen Platz für mich!!!"
  },
  AvgCommunicate_67025_Content_2 = {
    Text = "Sogar Schüler, die nicht am Sporttraining teilgenommen haben, kommen zu mir, um sich für Kurse anzumelden. Ich bin wirklich überrascht über die Begeisterung aller."
  },
  AvgCommunicate_67025_Content_3 = {
    Text = "Nachdem alles gesagt und getan ist, kann niemand einem flauschigen Welpen widerstehen!!!"
  },
  AvgCommunicate_67025_Content_4 = {
    Text = "In der Tat, um Teamarbeit unter den Schülern zu fördern, habe ich junge Welpen ausgewählt."
  },
  AvgCommunicate_67025_Content_5 = {
    Text = "Obwohl ich diese Kleinen genauso liebe wie alle anderen, benötigen sie viel mehr Pflege und Training als erwachsene Hunde."
  },
  AvgCommunicate_67025_Content_6 = {
    Text = "Jetzt, wo die Anzahl der Einschreibungen gestiegen ist, muss auch die Anzahl der Welpen steigen, und es wird wirklich schwierig für mich zu bewältigen."
  },
  AvgCommunicate_67025_Content_7 = {
    Text = "Es ist einfach. Wenn Ausbilder Alva den Befehl gibt, werden sich mehr Leute bereitwillig melden, um sich um die Welpen zu kümmern. Zu diesem Zeitpunkt könnten möglicherweise nicht einmal genug Welpen zur Verfügung stehen."
