  AvgCommunicate_67026_Content_10 = {
    Text = "Außerdem können gut ausgebildete Militärhunde Soldaten hervorragend bei verschiedenen Aufgaben unterstützen. Vielleicht können wir das auf Ermittler-Missionen anwenden und die Möglichkeiten weiter erkunden."
