  AvgCommunicate_67027_Content_10 = {
    Text = "Statt einen Wunsch zu äußern, ist es eher so, dass jeder auf Glück und Segen hofft."
  },
  AvgCommunicate_67027_Content_11 = {
    Text = "Selbst wenn Wünsche nicht sofort wahr werden können, bringt es Trost und Vorfreude, sie in unseren Herzen zu bewahren."
  },
  AvgCommunicate_67027_Content_12 = {
    Text = "Unerfüllte Wünsche... sind sie wirklich so wertvoll?"
  },
  AvgCommunicate_67027_Content_13 = {
    Text = "Ich glaube, ich verstehe. Ab morgen werde ich allen meine Segnungen am Schulbrunnen erteilen."
  },
  AvgCommunicate_67027_Content_14 = {
    Text = "Warte, warum der Schulfountain?"
  },
  AvgCommunicate_67027_Content_15 = {
    Text = "Ich habe gehört, dass Wunschbrunnen an vielen Orten beliebt sind, also habe ich den Schulbrunnen in einen verwandelt. Jetzt können alle kommen und sich etwas wünschen und Segen empfangen."
  },
  AvgCommunicate_67027_Content_16 = {
    Text = "Es scheint logisch zu sein, aber es fühlt sich immer noch merkwürdig an!"
