  AvgCommunicate_67028_Content_10 = {
    Text = "Das ist großartig. Ich werde einen passenden Zeitpunkt wählen, um dich zu besuchen."
  },
  AvgCommunicate_67028_Content_11 = {
    Text = "Lass es uns vorerst ein Geheimnis vor Lily halten. Ich möchte sie überraschen."
  },
  AvgCommunicate_67028_Content_2 = {
    Text = "In letzter Zeit habe ich unerwartet zwei wunderschöne rote Goldfische erhalten."
  },
  AvgCommunicate_67028_Content_3 = {
    Text = "Glücklicherweise haben sie unter meiner Pflege erfolgreich viele Eier gelegt, und nun sind sie in unzählige kleine Fische geschlüpft."
