  AvgCommunicate_67028_Content_5 = {
    Text = "Ja, ich habe eine tiefe Verbundenheit zur Unterwasserwelt."
  },
  AvgCommunicate_67028_Content_6 = {
    Text = "Der Fisch, das Seegras und das Korallenriff im Wasser sind ein warmer, heimeliger Ort in meiner Erinnerung."
  },
  AvgCommunicate_67028_Content_7 = {
    Text = "Entschuldigung, ich habe mich ablenken lassen. Ich wollte fragen, ob du daran interessiert bist, einige Goldfische zu halten?"
  },
  AvgCommunicate_67028_Content_8 = {
