  },
  AvgCommunicate_67029_Content_13 = {
    Text = "Gib die Cafeteria ordentlich zurück!!"
  },
  AvgCommunicate_67029_Content_14 = {
    Text = "Oh, diese Mütter und Kinder grausam zu trennen, wie herzlos! Du, der du an mütterlicher Liebe mangelst!"
