  },
  AvgCommunicate_67030_Content_4 = {
    Text = "Aber ich finde, es schmeckt großartig!"
  },
  AvgCommunicate_67030_Content_5 = {
    Text = "Wie machst du deine kleinen Kuchen?"
  },
  AvgCommunicate_67030_Content_6 = {
    Text = "Ich habe die besten getrockneten Spinnen und frische Neunaugen genommen, sie gekocht und in den Teig gemischt..."
  },
  AvgCommunicate_67030_Content_7 = {
    Text = "Warte... ugh, mir wird schon schlecht, wenn ich das nur höre!!"
  },
  AvgCommunicate_67030_Content_8 = {
    Text = "Ist das überhaupt etwas Essbares?!"
  },
  AvgCommunicate_67030_Content_9 = {
    Text = "Es ist doch offensichtlich lecker. Haben alle so einen eigenwilligen Geschmack...?"
  },
  AvgCommunicate_67030_Option_10 = {
    Text = "Wer hat hier bitte so einen eigenwilligen Geschmack!!"
  },
  AvgCommunicate_67030_Option_12 = {
    Text = "Hör auf, bring nicht Unheil über alle!!!"
  },
  AvgCommunicate_67030_Option_3 = {
    Text = "Wie schlecht schmeckt das denn bitte..."
  },
  AvgCommunicate_67030_Option_5 = {
    Text = "Wie machst du deine kleinen Kuchen?"
  },
  AvgCommunicate_67030_Option_7 = {
    Text = "Warte... ugh, mir wird schon schlecht, wenn ich das nur höre!!"
  },
  AvgCommunicate_67030_Option_8 = {
    Text = "Ist das überhaupt etwas Essbares?!"
  },
  AvgCommunicate_67031_Content_1 = {
    Text = "Verdammtes Miststück! Verdammtes Miststück! Verdammtes Miststück!"
  },
  AvgCommunicate_67031_Content_10 = {
    Text = "Ist es möglich, dass ein Etikett darauf ist?"
  },
  AvgCommunicate_67031_Content_11 = {
    Text = "Welches Etikett? Ich kann es nicht verstehen."
  },
  AvgCommunicate_67031_Content_12 = {
    Text = "Hast du deinen grundlegenden Sprachkurs vollständig ignoriert??"
  },
  AvgCommunicate_67031_Content_13 = {
    Text = "Argh, so nervig! Warum muss der Meister des Labyrinths studieren!"
  },
  AvgCommunicate_67031_Content_14 = {
    Text = "Bring mir einige Diener, die sich um mich kümmern!"
  },
  AvgCommunicate_67031_Content_15 = {
    Text = "Wach auf, Rom ist gefallen."
  },
  AvgCommunicate_67031_Content_16 = {
    Text = "Wir leben in einer Gesellschaft, die nach dem Gesetz regiert wird."
  },
  AvgCommunicate_67031_Content_17 = {
    Text = "Es ist mir egal. Wenn du es nicht finden kannst, dann dienst du mir selbst!"
  },
  AvgCommunicate_67031_Content_18 = {
    Text = "Dann könntest du ebenso gut weiterhin Gesichtsreiniger zum Zähneputzen benutzen."
  },
  AvgCommunicate_67031_Content_19 = {
    Text = "Ich werde dich in das Labyrinth werfen, um meinen Nachkommen Futter zu geben!!!"
  },
  AvgCommunicate_67031_Content_2 = {
    Text = "Was ist mit dir los??"
  },
  AvgCommunicate_67031_Content_3 = {
    Text = "Beim letzten Mal hast du erwähnt, dass das Zahnpulver nicht in der kleinen runden Schachtel war, sondern ein langer Streifen war."
  },
  AvgCommunicate_67031_Content_4 = {
    Text = "Warum habe ich die lange benutzt? Jetzt fühlt sich mein Mund so bitter an! So scharf und bitter!!"
  },
  AvgCommunicate_67031_Content_5 = {
    Text = "Uh... Es sollte nicht so schmecken."
  },
  AvgCommunicate_67031_Content_6 = {
    Text = "Warte, welche Farbe hat der lange Streifen, auf den du dich beziehst?"
  },
  AvgCommunicate_67031_Content_7 = {
    Text = "Was ist mit Blau los?"
  },
  AvgCommunicate_67031_Content_8 = {
    Text = "Es ist zum Waschen deines Gesichts. Die Dentaltablette ist grün..."
  },
  AvgCommunicate_67031_Content_9 = {
    Text = "Was? Warum hat mir das niemand gesagt? War das Absicht?!"
  },
  AvgCommunicate_67031_Option_10 = {
