  },
  AvgCommunicate_67031_Option_16 = {
    Text = "Wir leben in einer Gesellschaft, die nach dem Gesetz regiert wird."
  },
  AvgCommunicate_67031_Option_18 = {
    Text = "Dann könntest du ebenso gut weiterhin Gesichtsreiniger zum Zähneputzen benutzen."
  },
  AvgCommunicate_67031_Option_2 = {
    Text = "Was ist mit dir los??"
  },
  AvgCommunicate_67031_Option_5 = {
    Text = "Uh... Es sollte nicht so schmecken."
  },
  AvgCommunicate_67031_Option_8 = {
    Text = "Es ist zum Waschen deines Gesichts. Die Dentaltablette ist grün..."
  },
  AvgCommunicate_67032_Content_1 = {
    Text = "Welpe, es ist so kalt im Schwarzen Teich. Ich spüre, wie meine Lebensenergie jeden Tag schwindet."
  },
  AvgCommunicate_67032_Content_10 = {
    Text = "Was, wenn ich sage, dass ich es geschafft habe, das Gerät, das mich festhält, ein wenig zu lockern?"
  },
  AvgCommunicate_67032_Content_11 = {
    Text = "?! Ich komme jetzt."
  },
  AvgCommunicate_67032_Content_2 = {
    Text = "Wenn du mich nicht bald besuchen kommst, könnte ich eines Tages zu D-Schleim zerfallen."
  },
  AvgCommunicate_67032_Content_3 = {
    Text = "...Ich werde nicht mehr auf deine Tricks hereinfallen."
  },
  AvgCommunicate_67032_Content_4 = {
    Text = "Ist es nicht natürlich, sich um seinen Mentor zu kümmern? Wie kann das als Betrug angesehen werden?"
  },
  AvgCommunicate_67032_Content_5 = {
    Text = "Ich vermisse immer noch, wie du in der Klasse oft geschlafen hast und befürchtet hast, dass ich dich erwische."
  },
  AvgCommunicate_67032_Content_6 = {
    Text = "Wenn du versuchst, mich zu fangen, ist dein frommes, aber naives Gesicht ziemlich süß."
  },
  AvgCommunicate_67032_Content_7 = {
    Text = "Sag nicht mehr, sonst schalte ich den Kommunikator aus."
  },
  AvgCommunicate_67032_Content_8 = {
    Text = "Seufz, wie herzlos. Egal was, weigerst du dich immer noch, mich zu sehen?"
  },
  AvgCommunicate_67032_Content_9 = {
    Text = "Was denkst du?"
  },
  AvgCommunicate_67032_Option_11 = {
    Text = "?! Ich komme jetzt."
  },
  AvgCommunicate_67032_Option_3 = {
    Text = "...Ich werde nicht mehr auf deine Tricks hereinfallen."
  },
  AvgCommunicate_67032_Option_7 = {
    Text = "Sag nicht mehr, sonst schalte ich den Kommunikator aus."
  },
  AvgCommunicate_67032_Option_9 = {
    Text = "Was denkst du?"
  },
  AvgCommunicate_67033_Content_1 = {
    Text = "Watson, das Leben ist wirklich öde."
  },
  AvgCommunicate_67033_Content_10 = {
    Text = "Sag mir nicht, dass du tatsächlich gegen ihn verloren hast?"
  },
  AvgCommunicate_67033_Content_11 = {
    Text = "Nein, keiner von uns war bereit nachzugeben. Die Einsätze stiegen immer weiter, und wir hätten beinahe den Verstand verloren."
  },
  AvgCommunicate_67033_Content_12 = {
    Text = "Am Ende wurde der alte Mann so aufgeregt, dass er sich verriet, und ich entdeckte, dass er die ganze Zeit über geschummelt hatte."
  },
  AvgCommunicate_67033_Content_13 = {
    Text = "Du warst also die ganze Zeit gleichauf mit einem Betrüger?"
  },
  AvgCommunicate_67033_Content_14 = {
    Text = "Ja, es war wirklich enttäuschend. Was die Sache noch schlimmer machte – der alte Mann wurde so wütend, dass er sich auf mich stürzte und anfing zu kämpfen."
  },
  AvgCommunicate_67033_Content_15 = {
    Text = "Er verdächtigt mich tatsächlich, ein Betrüger wie er zu sein! Was für eine Beleidigung."
  },
  AvgCommunicate_67033_Content_16 = {
    Text = "Am Ende wurden wir beide von den Leuten der Spielhalle rausgeworfen, und ich bin so hart gelandet, dass mir immer noch der Hintern wehtut. Was für ein Pech."
  },
  AvgCommunicate_67033_Content_17 = {
    Text = "Ich weiß nicht warum, aber ich kann einfach kein Mitleid empfinden..."
  },
  AvgCommunicate_67033_Content_2 = {
    Text = "? Du hast wieder gezockt, oder? Hast du allen die Hosen abgenommen?"
  },
  AvgCommunicate_67033_Content_3 = {
    Text = "Diesmal wirklich nicht! Ich hatte nur wie üblich meinen Spaß in der Spielhöhle... hust."
  },
  AvgCommunicate_67033_Content_4 = {
    Text = "Schon gut. Erzähl weiter."
  },
  AvgCommunicate_67033_Content_5 = {
    Text = "Ich höre mir deine weiteren Ausreden an."
  },
  AvgCommunicate_67033_Content_6 = {
    Text = "Seufz... Heute bin ich plötzlich auf einen Gegner gestoßen, der mir ebenbürtig ist."
  },
  AvgCommunicate_67033_Content_7 = {
    Text = "Nachdem ich mich diesem Glücksspiel angeschlossen hatte, war ich mit diesem unscheinbaren alten Mann fast gleichauf."
  },
  AvgCommunicate_67033_Content_8 = {
    Text = "Das ist ziemlich schockierend. Um mit deinem Glück zu gewinnen, muss man ein Experte sein."
  },
  AvgCommunicate_67033_Content_9 = {
    Text = "Das dachte ich auch, also konzentrierte ich mich voll und ganz und spielte weiter gegen ihn – ich saß sogar kerzengerade!"
  },
  AvgCommunicate_67033_Option_10 = {
    Text = "Sag mir nicht, dass du tatsächlich gegen ihn verloren hast?"
  },
  AvgCommunicate_67033_Option_13 = {
    Text = "Du warst also die ganze Zeit gleichauf mit einem Betrüger?"
  },
