  },
  AvgCommunicate_67033_Option_8 = {
    Text = "Das ist ziemlich schockierend."
  },
  AvgCommunicate_67034_Content_1 = {
    Text = "Hallo, Geheimnisträger."
  },
  AvgCommunicate_67034_Content_10 = {
    Text = "Ach ja? Wie erklärst du dann diese durchgefallene Klausur? Du hast bei so grundlegendem Stoff Fehler gemacht. Ich denke, du wirst die richtigen Antworten hundertmal abschreiben müssen."
  },
  AvgCommunicate_67034_Content_11 = {
    Text = "Hundertmal?! Auf keinen Fall... Moment, ich hätte fast vergessen, dass du Erica bist!"
  },
  AvgCommunicate_67034_Content_12 = {
    Text = "Warum so realistisch schimpfen? War das Absicht? Ich hinterlasse eine schlechte Bewertung!"
  },
  AvgCommunicate_67034_Content_13 = {Text = "Ramona."},
  AvgCommunicate_67034_Content_14 = {
    Text = "In Ordnung, Persönlichkeitssimulation wird umgeschaltet auf: Ramona."
  },
  AvgCommunicate_67034_Content_15 = {
    Text = "Partner, ein Lehrer hat mir gerade gesagt, dass du anscheinend eine Aufgabe nicht abgegeben hast?"
  },
  AvgCommunicate_67034_Content_16 = {
    Text = "Hä? Wirklich? Ich bin mir sicher, dass ich alle Hausaufgaben fertig hatte..."
  },
  AvgCommunicate_67034_Content_17 = {
    Text = "Wann wirst du endlich diese faule Angewohnheit ablegen?"
  },
  AvgCommunicate_67034_Content_18 = {
    Text = "Vergiss es. Komm einfach jeden Tag in mein Zimmer. Ich werde dich beaufsichtigen, bis du deine Hausaufgaben fertig hast, bevor du gehst. Ach ja, kein Nachschlagen von Antworten oder Hilfsmitteln."
  },
  AvgCommunicate_67034_Content_19 = {
    Text = "Was?! Nein! Wie soll ich denn meine Hausaufgaben ohne Hilfsmittel machen?!"
  },
  AvgCommunicate_67034_Content_2 = {
    Text = "Du bist eingeladen, unser neuestes Simulations-Persona-System auszuprobieren. Es kann abwesende Mitglieder für die Kommunikation nachahmen und ihre Handlungslogik während Missionen ableiten."
  },
  AvgCommunicate_67034_Content_20 = {
    Text = "Warte... Ich hätte fast vergessen, dass du Erica bist! Willst du mir Angst einjagen?! Dafür gibt's eine schlechte Bewertung!!"
  },
  AvgCommunicate_67034_Content_21 = {
    Text = "Okay, ich habe dein Feedback erhalten. Erste Einschätzung: Simulation bestanden."
  },
  AvgCommunicate_67034_Content_22 = {
    Text = "Ich freue mich darauf, dich beim nächsten Systemtest wiederzusehen."
  },
  AvgCommunicate_67034_Content_3 = {
    Text = "Bitte teile dein Feedback und deine Vorschläge mit, sobald du die Testphase abgeschlossen hast."
  },
  AvgCommunicate_67034_Content_4 = {
    Text = "Was für ein seltsames Ding ist das?"
  },
  AvgCommunicate_67034_Content_5 = {
    Text = "Du kannst einen der beiden Anfangscharaktere für die Persönlichkeitssimulation wählen: Doll, Ramona."
  },
  AvgCommunicate_67034_Content_6 = {Text = "Doll."},
  AvgCommunicate_67034_Content_7 = {
    Text = "In Ordnung, Persönlichkeitssimulation wird umgeschaltet auf: Doll."
  },
  AvgCommunicate_67034_Content_8 = {
    Text = "Schutzherr, deine letzten Prüfungsergebnisse sind da. Ich hoffe, du weißt, was du in letzter Zeit getrieben hast."
  },
  AvgCommunicate_67034_Content_9 = {
    Text = "Hä? Ich habe meine Hausaufgaben in letzter Zeit pünktlich abgegeben. Ich bin nur ein paar Mal im Unterricht eingenickt..."
  },
  AvgCommunicate_67034_Option_11 = {
    Text = "Hundertmal?! Auf keinen Fall..."
  },
  AvgCommunicate_67034_Option_13 = {Text = "Ramona."},
  AvgCommunicate_67034_Option_16 = {
    Text = "Hä? Wirklich? Ich bin mir sicher, dass ich alle Hausaufgaben fertig hatte..."
  },
  AvgCommunicate_67034_Option_19 = {
    Text = "Was?! Nein! Wie soll ich denn meine Hausaufgaben ohne Hilfsmittel machen?!"
  },
  AvgCommunicate_67034_Option_4 = {
    Text = "Was für ein seltsames Ding ist das?"
  },
  AvgCommunicate_67034_Option_6 = {Text = "Doll."},
  AvgCommunicate_67034_Option_9 = {Text = "Huh?"},
  AvgCommunicate_67035_Content_1 = {
    Text = "Lieber Keeper! Bitte hilf mir!"
  },
  AvgCommunicate_67035_Content_10 = {
    Text = "Was für ein Job soll das sein?!"
  },
  AvgCommunicate_67035_Content_11 = {
    Text = "Egal... Kürzlich bringt Alvas Trainingskurs Welpen bei, Feinde zu jagen."
  },
  AvgCommunicate_67035_Content_12 = {
    Text = "Wenn es dir nichts ausmacht, von einem Hund gebissen zu werden, geh ruhig hin und spiel dort den Bösewicht."
  },
  AvgCommunicate_67035_Content_13 = {
    Text = "Was? Willst du damit sagen, ein süßer Welpe kann mich zerfleischen?"
  },
  AvgCommunicate_67035_Content_14 = {
    Text = "Ich bin bereit! Du bist so freundlich, Schutzherr!"
  },
  AvgCommunicate_67035_Content_2 = {
    Text = "Kein Schimpfen, kein Kämpfen und kein Verweilen im Raum."
  },
  AvgCommunicate_67035_Content_3 = {
    Text = "Oh, ich war diesmal wirklich nicht vor deinem Zimmereingang."
  },
  AvgCommunicate_67035_Content_4 = {
    Text = "Dank deiner Hilfe beim letzten Mal habe ich lange Zeit glücklich auf den Sandsack im Trainingsraum eingehauen. Es fühlte sich an wie zu Hause – ich war noch nie so glücklich."
  },
  AvgCommunicate_67035_Content_5 = {
    Text = "Mm... Kein Problem, solange du glücklich bist."
  },
  AvgCommunicate_67035_Content_6 = {
    Text = "Seufz, aber kürzlich wurde ich entdeckt. Ich weiß nicht, wie Uvhash erkannt hat, dass ich drin war."
  },
  AvgCommunicate_67035_Content_7 = {
    Text = "Nachdem alle herausgefunden hatten, dass ich im Sandsack steckte, haben mich alle ausgeschimpft."
  },
  AvgCommunicate_67035_Content_8 = {
    Text = "Obwohl dieser Teil auch Spaß macht, kann ich mich nicht mehr als Sandsack ausgeben."
  },
  AvgCommunicate_67035_Content_9 = {
    Text = "Was soll ich tun? Arbeitslos zu sein fühlt sich schrecklich an, Schutzherr! Bitte finde mir einen anderen Job wie diesen!"
  },
  AvgCommunicate_67035_Option_10 = {
    Text = "Was für ein Job soll das sein?!"
  },
  AvgCommunicate_67035_Option_2 = {
    Text = "Kein Schimpfen, kein Kämpfen und kein Verweilen im Raum."
  },
  AvgCommunicate_67035_Option_5 = {
    Text = "Mm... Kein Problem, solange du glücklich bist."
  },
  AvgCommunicate_67036_Content_1 = {
    Text = "Schutzherr! Meine neueste Modifikation war erfolgreich!"
  },
  AvgCommunicate_67036_Content_10 = {
    Text = "So muss ich mir keine Sorgen mehr machen, dass ich vergesse, in mein Tagebuch zu schauen, und meine Erinnerungen wieder verliere."
  },
  AvgCommunicate_67036_Content_11 = {
    Text = "Tolle Idee! Aber war es dir früher nicht egal, vergesslich zu sein?"
  },
  AvgCommunicate_67036_Content_12 = {
    Text = "Das sagt sich leicht, aber ich will meine Freunde nicht vergessen."
  },
  AvgCommunicate_67036_Content_13 = {
    Text = "Ich werde mich gut an dich erinnern, Schutzherr!"
  },
  AvgCommunicate_67036_Content_2 = {
    Text = "Glückwunsch! Meinst du deine Nautilus? Aber du erinnerst dich noch an mich."
  },
  AvgCommunicate_67036_Content_3 = {
    Text = "Nein, es geht um dieses Dialogfenster."
  },
  AvgCommunicate_67036_Content_4 = {
    Text = "? Das nennt man einen Kommunikator. Was für Modifikationen hast du vorgenommen??"
  },
  AvgCommunicate_67036_Content_5 = {
    Text = "Ich kann Nachrichten planen, die später gesendet werden, wobei ich die Verzögerungszeit selbst bestimme."
  },
  AvgCommunicate_67036_Content_6 = {
    Text = "Zum Beispiel wurde der erste Satz, den ich dir gerade geschickt habe, vor fünf Minuten als Test geschrieben."
  },
  AvgCommunicate_67036_Content_7 = {
    Text = "Wow, erstaunlich?! Es fühlt sich an, als könnte man damit bei Missionen vorausplanen und Notfallpläne leichter umsetzen."
  },
  AvgCommunicate_67036_Content_8 = {
    Text = "Ah, so viel steckt da gar nicht dahinter, wie du denkst."
  },
  AvgCommunicate_67036_Content_9 = {
    Text = "Ich dachte mir nur, wenn ich das, woran ich mich heute erinnere, im Voraus an morgen schicke, werde ich es nicht vergessen."
  },
  AvgCommunicate_67036_Option_11 = {
    Text = "Tolle Idee! Aber war es dir früher nicht egal, vergesslich zu sein?"
  },
  AvgCommunicate_67036_Option_2 = {
    Text = "Glückwunsch! Meinst du deine Nautilus? Aber du erinnerst dich noch an mich."
  },
  AvgCommunicate_67036_Option_4 = {
    Text = "? Das nennt man einen Kommunikator. Was für Modifikationen hast du vorgenommen??"
  },
  AvgCommunicate_67036_Option_7 = {
    Text = "Unglaublich?!"
  },
  AvgCommunicate_67037_Content_1 = {
    Text = "Hüter, ich bin neulich auf ein sehr interessantes Gedichtspiel gestoßen."
  },
  AvgCommunicate_67037_Content_10 = {Text = "Kalt."},
  AvgCommunicate_67037_Content_11 = {Text = "Tod."},
  AvgCommunicate_67037_Content_12 = {Text = "Singen."},
  AvgCommunicate_67037_Content_13 = {Text = "Liebe."},
  AvgCommunicate_67037_Content_14 = {
    Text = "Melancholie."
  },
  AvgCommunicate_67037_Content_15 = {Text = "Duft."},
  AvgCommunicate_67037_Content_16 = {
    Text = "Mm, fühlt sich richtig an. Lass mich versuchen, sie zu Versen zu verbinden."
  },
  AvgCommunicate_67037_Content_17 = {
    Text = "Die Liebe der Nachtigall zum Mond erblüht jede Nacht in ihrem melodischen Gesang, doch der Mond bleibt kalt."
  },
  AvgCommunicate_67037_Content_18 = {
    Text = "Sie sang und sang, bis die Rosenblumen ihre Brust durchbohrten."
  },
  AvgCommunicate_67037_Content_19 = {
    Text = "Der Gesang verwehte mit dem purpurnen Tod und hinterließ nur Rosenblumen, die einen melancholischen Duft verströmten."
  },
  AvgCommunicate_67037_Content_2 = {
    Text = "Was für ein Spiel?"
  },
  AvgCommunicate_67037_Content_20 = {
    Text = "Tolles Gedicht! Applaus! Das ist beeindruckend, wie man es von dir erwarten würde!"
  },
  AvgCommunicate_67037_Content_21 = {
    Text = "Das war nur ein zufällig zusammengesetzter Satz, nichts Besonderes..."
  },
  AvgCommunicate_67037_Content_22 = {
    Text = "Wenn diese Zeile schön ist, dann ist die Hälfte ihrer Schönheit von dir erschaffen."
  },
  AvgCommunicate_67037_Content_3 = {
    Text = "Alle beschreiben abwechselnd ein Bild, und nach ein paar Runden werden alle Bilder zu einem Gedicht zusammengefügt."
  },
  AvgCommunicate_67037_Content_4 = {
    Text = "Erfüllt von der Schönheit zufälliger Kollisionen, nicht wahr? Möchtest du es mit mir ausprobieren?"
  },
  AvgCommunicate_67037_Content_5 = {
    Text = "Klingt interessant! Lass uns spielen!"
  },
  AvgCommunicate_67037_Content_6 = {
    Text = "Dann fange ich an. Rosenblume."
  },
