  AvgCommunicate_67038_Content_1 = {
    Text = "Hüter, die Tulu-Statue, die du mich für Miryam machen lassen hast, wurde in dein Zimmer geliefert."
  },
  AvgCommunicate_67038_Content_10 = {
    Text = "Ihr Verständnis von Tulu ist sogar noch geringer als mein Verständnis von dir; wie inkompetent."
  },
  AvgCommunicate_67038_Content_11 = {
    Text = "Genug, sag das nicht. Lass sie es nicht sehen."
  },
  AvgCommunicate_67038_Content_12 = {
    Text = "Auf jeden Fall, danke für deine harte Arbeit. Lass mich nachdenken, wie ich Miryam erzählen kann..."
