  AvgCommunicate_67038_Content_2 = {
    Text = "Ich habe es gesehen, aber dieses Bild... ist es nicht ein bisschen zu süß?"
  },
  AvgCommunicate_67038_Content_3 = {
    Text = "Sieht Tulu so aus? Wird Miryam mich erwürgen"
  },
  AvgCommunicate_67038_Content_4 = {
    Text = "Was? Bist du auch ein glühender Anhänger des jungen Königs?"
  },
  AvgCommunicate_67038_Content_5 = {
    Text = "In meinen Augen war er nur ein Kind, gezwungen von anderen, eine Krone und Ketten zu tragen."
  },
  AvgCommunicate_67038_Content_6 = {
    Text = "Denkst du nicht, dass sein schläfriger, fauler Blick jeden Tag niedlich ist? Er erinnert mich an die langhaarige Katze, die ich als Kind hatte."
  },
  AvgCommunicate_67038_Content_7 = {
    Text = "Wahrhaftig, diejenigen, die die Statue wünschen, werden zufrieden sein..."
