  AvgCommunicate_67038_Content_8 = {
    Text = "Die einzige schlechte Nachricht könnte die Geburt einer Welt sein, in der nur Miryam verletzt wird..."
  },
  AvgCommunicate_67038_Content_9 = {
    Text = "Das bedeutet nur, dass sie eine blinde Priesterin ist, die ihren eigenen Gott nicht versteht."
  },
  AvgCommunicate_67038_Option_11 = {
