  AvgCommunicate_67039_Content_1 = {
    Text = "Lieber Schutzherr, hast du mein neuestes Werk erhalten?"
  },
  AvgCommunicate_67039_Content_10 = {
    Text = "Dein plötzliches Lob bringt mich ganz in Verlegenheit..."
  },
  AvgCommunicate_67039_Content_11 = {
    Text = "Sei nicht schüchtern. Du warst schon immer meine Muse. Wenn du Zeit hast, könntest du mein Atelier besuchen?"
  },
  AvgCommunicate_67039_Content_12 = {
    Text = "Es gibt noch so viele Werke, die ich vollenden möchte, und ich muss deine Seele sorgfältig abbilden."
  },
  AvgCommunicate_67039_Content_13 = {
    Text = "Ich werde hier auf dich warten und auf weitere Inspiration hoffen."
  },
  AvgCommunicate_67039_Content_2 = {
    Text = "Das ist... ich, während ich schlafe?"
  },
  AvgCommunicate_67039_Content_3 = {
    Text = "In meiner Inspiration bist das du, wie du in einen wunderschönen Traum versinkst."
  },
  AvgCommunicate_67039_Content_4 = {
    Text = "Wähle zwischen blindem, falschem Glück und klarsichtigem, schmerzvollem Untergang."
  },
  AvgCommunicate_67039_Content_5 = {
    Text = "Dilemmas sind stets die Themen von Kunst und Philosophie."
  },
  AvgCommunicate_67039_Content_6 = {
    Text = "Kann ich nicht ein klares und wahrhaftiges Glück erlangen?"
