  AvgCommunicate_67040_Content_1 = {
    Text = "Hey, Süße, wie hast du unseren letzten zärtlichen Moment empfunden? Durchlebst du ihn jeden Tag aufs Neue?"
  },
  AvgCommunicate_67040_Content_10 = {
    Text = "Sprich, was hast du jetzt vor..."
  },
  AvgCommunicate_67040_Content_11 = {
    Text = "Sei nicht so angespannt, unsere Verbindung ist doch schon so stark geworden～"
  },
  AvgCommunicate_67040_Content_12 = {
    Text = "Vertrau mir, folge mir, und ich werde dich zu einer neuen Art von Glück führen."
  },
  AvgCommunicate_67040_Content_13 = {
    Text = "Möchtest du dieses Mal den Gebrauch von Kerzen und Peitschen persönlich erleben?"
  },
  AvgCommunicate_67040_Content_14 = {
    Text = "Ich werde dir alles Schritt für Schritt beibringen, mein Schatz."
