  AvgCommunicate_67040_Content_2 = {
    Text = "Welchen Moment?"
  },
  AvgCommunicate_67040_Content_3 = {
    Text = "Ich erinnere mich nicht."
  },
  AvgCommunicate_67040_Content_4 = {
    Text = "Was für ein herzloser Mensch, obwohl ich letztes Mal so sanft war～"
  },
  AvgCommunicate_67040_Content_5 = {
    Text = "Ich rate dir, auf deine Worte und Taten zu achten..."
  },
  AvgCommunicate_67040_Content_6 = {
    Text = "Hmph, dumm stellen bringt nichts. Ich habe bereits deine Konturen, deine Kurven und all deine Formen in Wachs festgehalten!"
  },
  AvgCommunicate_67040_Content_7 = {
    Text = "Ich würde es so gerne allen zeigen～"
