  AvgCommunicate_67041_Content_1 = {
    Text = "Mein Gebieter, habt Ihr mir gerade ein Zeichen gegeben, Euch zu kontaktieren?"
  },
  AvgCommunicate_67041_Content_10 = {
    Text = "Seufz, ich muss dir beibringen, wie man böse Mädchen in der Schule erkennt, und einige Vorsichtsmaßnahmen."
  },
  AvgCommunicate_67041_Content_11 = {
    Text = "Hör mir zu, verlasse sofort ihren Türeingang, so weit wie möglich, und sag später, dass ich dich weggerufen habe!"
  },
  AvgCommunicate_67041_Content_12 = {
    Text = "Aber ich habe Lady Pandia ein Versprechen gegeben. Ich kann mein Wort nicht brechen."
  },
  AvgCommunicate_67041_Content_13 = {
    Text = "Es ist schon in Ordnung, mein Herr. Es gibt noch genug Kraft in mir, um mich selbst zu beschützen!"
  },
  AvgCommunicate_67041_Content_14 = {
    Text = "Du, ich... Schon gut. Wenn du unbedingt dort stehen musst, denk daran, nicht ihr Zimmer zu betreten."
  },
  AvgCommunicate_67041_Content_15 = {
    Text = "Natürlich nicht! Ich würde niemals das Zimmer einer Dame betreten!"
  },
  AvgCommunicate_67041_Content_16 = {
    Text = "Egal was sie sagt, geh nicht hinein. Ruf mich, wenn etwas passiert. Und was auch immer du tust, riech nicht an ihren Kerzen!"
  },
  AvgCommunicate_67041_Content_17 = {
    Text = "Verstanden, mein Herr. Aber warum darf ich nicht an der Kerze riechen?"
  },
  AvgCommunicate_67041_Content_18 = {
    Text = "Frag nicht... Das sind die Tränen und das Blut, die ich dir erspart habe."
  },
  AvgCommunicate_67041_Content_2 = {
    Text = "Genau, warum stehst du vor Pandias Tür??"
  },
  AvgCommunicate_67041_Content_3 = {
    Text = "Ah, das ist eine Bitte von Lady Pandia. Sie sagte, sie hätte etwas Wichtiges zu erledigen, und bat mich, die Tür für sie zu bewachen."
  },
  AvgCommunicate_67041_Content_4 = {
    Text = "Etwas Wichtiges? Glaub ihr nicht! Ihre Geschichten... ach, vergiss es, du bist definitiv von ihr hereingelegt worden!"
  },
  AvgCommunicate_67041_Content_5 = {
    Text = "Hm? Aber ihr Ausdruck war gerade so feierlich, und sie hielt meine Hand so aufrichtig..."
  },
  AvgCommunicate_67041_Content_6 = {
    Text = "Hat sie auch noch deine Hand gehalten und gesagt, du seist der zuverlässigste und sanftmütigste Ritter, richtig?"
  },
  AvgCommunicate_67041_Content_7 = {
    Text = "Woher wisst Ihr das, mein Gebieter?!"
  },
  AvgCommunicate_67041_Content_8 = {
    Text = "Ogier, vertrau nicht den Worten einer bösen Frau! Du lässt dich viel zu leicht täuschen!"
  },
  AvgCommunicate_67041_Content_9 = {
    Text = "Nun, ich denke einfach, dass niemand etwas Böses im Sinn hat..."
  },
  AvgCommunicate_67041_Option_10 = {
    Text = "Ich sollte dir wohl besser beibringen, wie man böse Frauen in der Schule erkennt..."
  },
  AvgCommunicate_67041_Option_14 = {
    Text = "Schon gut..."
  },
