  AvgCommunicate_67043_Content_1 = {
    Text = "Nachdem ich so viel Zeit in Misaq verbracht habe, begann ich plötzlich, den Mond in der Wüste zu vermissen."
  },
  AvgCommunicate_67043_Content_10 = {
    Text = "Komm und schaffe neue Erinnerungen mit mir: zwischen Blumen, in der Wildnis, um das Meer und Täler zu sehen, Städte und das Land."
  },
  AvgCommunicate_67043_Content_11 = {
    Text = "Ich möchte mit dir an jedem schönen Ort wunderschöne Erinnerungen schaffen. Du kommst mit, oder?"
  },
  AvgCommunicate_67043_Content_2 = {
    Text = "Du hast also auch Heimweh?"
  },
  AvgCommunicate_67043_Content_3 = {
    Text = "Eher als Heimweh vermisse ich vielleicht einfach die Erinnerungen, die ich mit anderen geteilt habe, und diese intensiven Gefühle."
  },
  AvgCommunicate_67043_Content_4 = {
    Text = "Hätte nie erwartet, dass du so nostalgisch bist."
  },
  AvgCommunicate_67043_Content_5 = {
    Text = "Was? Denkt Ihr, ich bin sorglos und gefühllos? Nein, ich erinnere mich an jede Person, an jede warme und süße Erinnerung."
  },
  AvgCommunicate_67043_Content_6 = {
    Text = "Einschließlich deiner."
  },
  AvgCommunicate_67043_Content_7 = {
    Text = "Sollte ich mich geehrt oder neidisch fühlen?"
  },
  AvgCommunicate_67043_Content_8 = {
    Text = "Ich liebe es einfach, dich so aufgelöst zu sehen; das ist bezaubernd."
  },
  AvgCommunicate_67043_Content_9 = {
    Text = "Auch wenn die vergangenen Tage Nostalgie wecken, ist die Freude des heutigen Abends das Kostbarste."
  },
  AvgCommunicate_67043_Option_2 = {
    Text = "Du hast also auch Heimweh?"
  },
  AvgCommunicate_67043_Option_4 = {
    Text = "Hätte nie erwartet, dass du so nostalgisch bist."
  },
  AvgCommunicate_67043_Option_7 = {
