  },
  AvgCommunicate_67044_Content_1 = {
    Text = "Ich habe mir in letzter Zeit einige Dekorationen ausgedacht, um meine Sammlungen zu verschönern."
  },
  AvgCommunicate_67044_Content_10 = {
    Text = "Wenn möglich, akzeptiere bitte die Halsketten, die ich sorgfältig für dich ausgewählt habe. Sie sind diesmal kostenlose Geschenke."
  },
  AvgCommunicate_67044_Content_11 = {
    Text = "Wenn dir eine davon nach dem Anprobieren gefällt, sag mir unbedingt Bescheid."
  },
  AvgCommunicate_67044_Content_12 = {
    Text = "Auch wenn dein Haupt mir noch nicht gehört, allein dich damit zu sehen, reicht aus, um mich zu erfreuen."
  },
  AvgCommunicate_67044_Content_2 = {
    Text = "Es gibt ziemlich viele Stile zur Auswahl, und ich bin etwas unentschlossen. Ich wollte dich um Rat fragen."
  },
  AvgCommunicate_67044_Content_3 = {Text = "Sammlung?"},
  AvgCommunicate_67044_Content_4 = {
    Text = "Du meinst nicht..."
  },
  AvgCommunicate_67044_Content_5 = {
    Text = "Ah, natürlich, meine kostbaren Schädel."
  },
  AvgCommunicate_67044_Content_6 = {
    Text = "Ich habe viele Modezeitschriften gelesen, sowie Designs von Juweliergeschäften."
  },
  AvgCommunicate_67044_Content_7 = {
    Text = "Die bunten Halsketten haben jeweils ihre eigenen einzigartigen Merkmale, darunter sogar einige ausgefallene Halsband-Designs, was die Wahl wirklich schwer macht."
  },
  AvgCommunicate_67044_Content_8 = {
    Text = "Mm... Ich finde, deine Sammlung verdient die ausgefallenste Dekoration."
  },
  AvgCommunicate_67044_Content_9 = {
    Text = "Wirklich? Das macht mich so glücklich."
