  AvgCommunicate_67045_Content_1 = {
    Text = "Seufz, das Geschäft in meinem kleinen Laden lief in letzter Zeit schlecht; es ist lange her, dass ich einen Schädel gefunden habe, der mir gefällt."
  },
  AvgCommunicate_67045_Content_10 = {
    Text = "Wenn ihr euch zusammentut, um ein paar große Flüchtige zu jagen, schafft ihr vielleicht eine Legende von Stadträngern, die das Böse auslöschen."
  },
  AvgCommunicate_67045_Content_11 = {
    Text = "Ein guter Vorschlag, aber so ein cleverer Kerl lässt sich nicht so leicht täuschen."
  },
  AvgCommunicate_67045_Content_12 = {
    Text = "Apropos, sein eigenartiger Kopf wäre ein großartiges Sammlerstück, aber es gibt keine Gelegenheit für einen Deal — wie schade."
  },
  AvgCommunicate_67045_Content_13 = {
    Text = "Hoffnung, dass Ryker jetzt nicht niesen muss..."
  },
  AvgCommunicate_67045_Content_2 = {
    Text = "Mm... Schädel sind in der Tat seltene Funde."
  },
  AvgCommunicate_67045_Content_3 = {
    Text = "Also habe ich kürzlich eine Zusammenarbeit mit dem Prüfungsausschuss vereinbart. Ich helfe ihnen, Flüchtige aufzuspüren, und im Gegenzug versorgen sie mich heimlich mit den Köpfen von zum Tode Verurteilten."
  },
  AvgCommunicate_67045_Content_4 = {
    Text = "Ein lebender Mensch tauscht gegen den Schädel eines Toten; ein profitables Geschäft für beide Seiten."
  },
  AvgCommunicate_67045_Content_5 = {
    Text = "Hä? Hätte nie gedacht, dass der Prüfungsausschuss so eine Zusammenarbeit genehmigen würde."
  },
  AvgCommunicate_67045_Content_6 = {
    Text = "Klar, es ist keine offizielle Zusammenarbeit, aber es gibt überall schlaue Leute."
  },
  AvgCommunicate_67045_Content_7 = {
    Text = "Ich habe auch versucht, das Revier in Lentiniën zu kontaktieren, aber die scheinen diesem hundsköpfigen Detektiv mehr zu vertrauen."
  },
  AvgCommunicate_67045_Content_8 = {
    Text = "Da sich schon jemand die Geschäftsgelegenheit geschnappt hat, muss ich mich nach anderen Möglichkeiten umsehen."
  },
  AvgCommunicate_67045_Content_9 = {
    Text = "Mm... Allerdings glaube ich, dass Ryker sich nicht wirklich um diesen Deal schert."
  },
  AvgCommunicate_67045_Option_13 = {
    Text = "Hoffnung, dass Ryker jetzt nicht niesen muss..."
  },
  AvgCommunicate_67045_Option_2 = {
