  AvgCommunicate_67046_Content_1 = {
    Text = "Mein Herr! Die warmblütige Stute namens Schneeflocke im Stall wird gleich gebären!"
  },
  AvgCommunicate_67046_Content_10 = {
    Text = "Der Gedanke, an Ponys Wachstum von klein auf beteiligt zu sein, macht mich aufgeregt!"
  },
  AvgCommunicate_67046_Content_11 = {
    Text = "So werden die Pferde also in so jungem Alter aufgezogen?"
  },
  AvgCommunicate_67046_Content_12 = {
    Text = "Ein Pferd ist der engste Gefährte des Ritters! Je mehr Vertrauen zwischen ihnen besteht, desto besser."
  },
  AvgCommunicate_67046_Content_13 = {
    Text = "Ich habe mir immer gewünscht, ein Pferd zu besitzen, das ich von einem Fohlen aufgezogen habe!"
  },
  AvgCommunicate_67046_Content_14 = {
    Text = "Ich kann sehen, dass du dich wirklich darauf freust."
  },
  AvgCommunicate_67046_Content_15 = {
    Text = "Wenn ich dann Zeit habe, werde ich kommen und dir helfen."
  },
  AvgCommunicate_67046_Content_16 = {
    Text = "Ich bin auch neugierig, welches Muster das Pony haben wird."
  },
  AvgCommunicate_67046_Content_17 = {
    Text = "!! Ich werde gut vorbereitet sein!"
  },
  AvgCommunicate_67046_Content_2 = {
    Text = "Ich erinnere mich, dass der Hengst rein schwarz war. Ich frage mich, welche Farbe ihre Nachkommen haben—vielleicht schwarz und weiß?"
  },
  AvgCommunicate_67046_Content_3 = {
