  AvgCommunicate_67047_Content_10 = {
    Text = "Mit dir an ihrer Seite wird sie sich bestimmt wohler und sicherer fühlen."
  },
  AvgCommunicate_67047_Content_11 = {
    Text = "Soll ich bei ihr bleiben...? Ich verstehe."
  },
  AvgCommunicate_67047_Content_12 = {
    Text = "Dann überlasse ich es dir. Vielen herzlichen Dank, Schutzherr."
  },
  AvgCommunicate_67047_Content_2 = {
    Text = "Was ist los?"
  },
  AvgCommunicate_67047_Content_3 = {
    Text = "Könntest du Tinktur zu einigen Versammlungen mitnehmen, damit sie neue Freunde finden kann?"
  },
  AvgCommunicate_67047_Content_4 = {
    Text = "Seit unserer Wiedervereinigung klammert sie sich jeden Tag an mich, völlig abgeschottet von der Außenwelt."
  },
  AvgCommunicate_67047_Content_5 = {
    Text = "Obwohl ich unsere Wiedervereinigung sehr schätze, möchte ich sie nicht vollständig an meine Seite binden."
  },
  AvgCommunicate_67047_Content_6 = {
    Text = "Das ist nicht schwierig, aber hast du Tincts Gefühle bedacht?"
  },
  AvgCommunicate_67047_Content_7 = {
    Text = "Ich verstehe sie... Aber sie kann nicht meinetwegen alle anderen weiterhin ablehnen."
  },
  AvgCommunicate_67047_Content_8 = {
    Text = "Vielleicht musst du sie nicht so entschlossen von dir wegstoßen."
  },
  AvgCommunicate_67047_Content_9 = {
    Text = "Wie wäre es, wenn ich dich und Tinct zu einer Feier mitnehme? Ich kümmere mich um die Schutzmaßnahmen."
  },
  AvgCommunicate_67047_Option_2 = {
    Text = "Was ist los?"
  },
  AvgCommunicate_67047_Option_6 = {
