  },
  AvgCommunicate_67048_Content_1 = {
    Text = "Hüter, danke für deinen Vorschlag beim letzten Mal."
  },
  AvgCommunicate_67048_Content_10 = {
    Text = "Sieht so aus, als wäre ich diejenige, die sich verbessern muss, nicht meine kleine Schwester."
  },
  AvgCommunicate_67048_Content_2 = {
    Text = "Seit Tinct und ich auf dieser Feier waren, hat Tinct es lieben gelernt, sich mit neuen Freunden zu unterhalten."
  },
  AvgCommunicate_67048_Content_3 = {
    Text = "Gern geschehen. Es freut mich, euch alle glücklich zu sehen."
  },
  AvgCommunicate_67048_Content_4 = {
    Text = "Mm... Mir ist zum ersten Mal aufgefallen, wie sehr Tinct es genießt, Kontakte zu knüpfen, wenn keine Last auf ihr liegt."
  },
  AvgCommunicate_67048_Content_5 = {
    Text = "Obwohl sie jedes Mal immer noch in meiner Nähe bleibt und mich gelegentlich in Gespräche hineinzieht."
  },
  AvgCommunicate_67048_Content_6 = {
    Text = "Aber es ist so lange her, dass ich sie zuletzt so fröhlich jemand anderen angelächelt habe sehen."
  },
  AvgCommunicate_67048_Content_7 = {
    Text = "Das ist wunderbar."
  },
  AvgCommunicate_67048_Content_8 = {
    Text = "Seufz, verglichen mit ihrer Begeisterung tue ich mich mit diesen häufigen gesellschaftlichen Anlässen immer noch schwer."
  },
  AvgCommunicate_67048_Content_9 = {
    Text = "Nach jeder Feier muss ich mich eine Weile in meinem Panzer ausruhen, um mich zu erholen."
  },
  AvgCommunicate_67048_Option_3 = {
