  AvgCommunicate_67049_Content_1 = {
    Text = "Keeper, hast du nach mir gesucht?"
  },
  AvgCommunicate_67049_Content_10 = {
    Text = "Du versuchst offensichtlich wieder, Leute zu ozeanischen Opfern zu überreden!!"
  },
  AvgCommunicate_67049_Content_11 = {
    Text = "Natürlich nicht, das waren nur Unfälle. Für immer in ihrer Heimat ruhend, werden ihre Seelen Erlösung finden."
  },
  AvgCommunicate_67049_Content_12 = {
    Text = "Du hast die Maskerade komplett fallen gelassen! Aussetzen! Setz ihn sofort aus!!"
