    Text = "Du bist eingeladen, unser neues intelligentes Abfragesystem auszuprobieren. Bitte teile uns nach der Nutzung dein Feedback und deine Vorschläge mit."
  },
  AvgCommunicate_67057_Content_3 = {
    Text = "Du könntest zum Beispiel zu mir sagen: Wie ist das Wetter heute?"
  },
  AvgCommunicate_67057_Content_4 = {
    Text = "Wie ist das Wetter heute?"
  },
  AvgCommunicate_67057_Content_5 = {
    Text = "In Lentiniën wird es heute leichten Regen geben, der sich später aufklart, bei Temperaturen zwischen 18 und 25 Grad Celsius. Der Südwestwind weht mit Stärke 2 bis 3. Es wird empfohlen, beim Ausgehen einen Regenschirm mitzunehmen."
  },
  AvgCommunicate_67057_Content_6 = {
    Text = "So beeindruckend? Lass mich mal meinen aktuellen Kursplan überprüfen."
  },
  AvgCommunicate_67057_Content_7 = {
    Text = "Der organisierte Zeitplan wurde separat gesendet. Wir haben festgestellt, dass du drei nicht eingereichte Aufgaben hast. Bitte achte auf die Abgabefristen."
  },
  AvgCommunicate_67057_Content_8 = {
    Text = "Äh, wenn man vom Teufel spricht..."
