  AvgCommunicate_70486_Content_1 = {
    Text = "Ich habe gehört, dass..."
  },
  AvgCommunicate_70486_Content_10 = {
    Text = "Ramona wurde tatsächlich zum Schwarzen Pool gebracht, aber du weißt, das ist ein Ort, den du nicht betreten kannst..."
  },
  AvgCommunicate_70486_Content_11 = {
    Text = "Sei unbesorgt, ich werde Ramona vollständig unversehrt zurückbringen!"
  },
  AvgCommunicate_70486_Content_12 = {
    Text = "Danke, dass ihr mich informiert habt. Ich fürchte jedoch, dass ich euch diesmal enttäuschen muss."
  },
  AvgCommunicate_70486_Content_13 = {
    Text = "Bitte verstehe die Gefühle eines Vaters."
  },
  AvgCommunicate_70486_Content_14 = {
    Text = "Die Dinge, die ich in Zukunft tun werde, ich hoffe, du kannst mir verzeihen."
  },
  AvgCommunicate_70486_Content_15 = {
    Text = "Der Schwarze Pool ist jetzt extrem gefährlich; deine Seelenstärke kann im Schwarzen Pool nicht überleben!"
  },
  AvgCommunicate_70486_Content_16 = {
    Text = "Bitte handle nicht hastig, Professor Dexter!"
  },
  AvgCommunicate_70486_Content_17 = {
    Text = "Professor Dexter?"
  },
  AvgCommunicate_70486_Content_18 = {
    Text = "Professor Dexter?!..."
  },
  AvgCommunicate_70486_Content_2 = {
    Text = "Ramona, zum Schwarzen Pool gebracht?"
  },
  AvgCommunicate_70486_Content_3 = {
    Text = "Ich bin schuld, dass ich sie nicht beschützt habe..."
  },
  AvgCommunicate_70486_Content_4 = {
    Text = "Nicht deine Verantwortung. Kein Grund, sich selbst zu beschuldigen, Hüter."
  },
  AvgCommunicate_70486_Content_5 = {
    Text = "Während sie Dekan Czort eskortierte, traf sie Herbert......"
  },
  AvgCommunicate_70486_Content_6 = {
    Text = "Es ist kein Treffen, Hüter."
  },
  AvgCommunicate_70486_Content_7 = {
    Text = "Herbert ist hier für Ramona."
  },
  AvgCommunicate_70486_Content_8 = {
    Text = "Ich möchte nur wissen, ob sie zum Schwarzen Pool gebracht wurde."
  },
  AvgCommunicate_70486_Content_9 = {
    Text = "Ich möchte nichts verbergen, Professor Dexter."
  },
  AvgCommunicate_70486_Option_15 = {
    Text = "Bitte sei nicht impulsiv!"
  },
  AvgCommunicate_70486_Option_3 = {
    Text = "Ich bin schuld, dass ich sie nicht beschützt habe..."
  },
  AvgCommunicate_70486_Option_5 = {
    Text = "Während sie Dekan Czort eskortierte, traf sie Herbert......"
  },
  AvgCommunicate_70486_Option_9 = {Text = "Ja..."},
  AvgCommunicate_70487_Content_1 = {
    Text = "Wie läuft die Genesung dieses Schwächlings?"
  },
  AvgCommunicate_70487_Content_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_70487_Content_11 = {
    Text = "Ich mag sie nicht, noch mag ich dich. Aber ich verabscheue diesen selbstgerechten Schneeberg noch mehr, sowie die, die mich benutzen und verraten wollen."
  },
  AvgCommunicate_70487_Content_12 = {
    Text = "Das ist alles."
  },
  AvgCommunicate_70487_Content_2 = {
    Text = "Nachdem sie vom Schneeberg zurückgekehrt war, erhielt sie Heilung, und ihre Verletzungen heilten sehr gut."
  },
  AvgCommunicate_70487_Content_3 = {
    Text = "Ich habe von dem Schneeberg von einer anderen Version von dir gehört."
  },
  AvgCommunicate_70487_Content_4 = {
    Text = "Danke, Helot. Du warst es, der uns geholfen hat."
  },
  AvgCommunicate_70487_Content_5 = {
    Text = "Danke? Was für ein schwaches Wort."
  },
  AvgCommunicate_70487_Content_6 = {
    Text = "Ich suche nur die Macht des Schneeberges. Es hat nichts mit dir zu tun."
  },
  AvgCommunicate_70487_Content_7 = {
    Text = "Die Leben einer Gruppe Ameisen interessieren mich nicht."
  },
  AvgCommunicate_70487_Content_8 = {
    Text = "In den Schneebergen hattest du die Möglichkeit, eine andere Version von dir selbst zu töten, entweder die Kraft des Schneeberges allein zu verschlingen oder den Schneeberg uns verschlingen zu lassen."
  },
  AvgCommunicate_70487_Content_9 = {
    Text = "Aber du hast es nicht, richtig?"
  },
  AvgCommunicate_70487_Option_3 = {
    Text = "Danke, dass ihr mir von dem Schneeberg erzählt habt."
  },
  AvgCommunicate_70487_Option_8 = {
    Text = "Aber du hast dich entschieden, eine andere Version von dir selbst nicht zu töten."
  },
  AvgCommunicate_70488_Content_1 = {
    Text = "Kapitan, der Körper wird schwächer..."
  },
  AvgCommunicate_70488_Content_10 = {
    Text = "Hüter, ich werde mein Möglichstes tun, um dir zu helfen."
  },
  AvgCommunicate_70488_Content_11 = {
    Text = "Wenn sich die Gelegenheit bietet, rette bitte den Kapitän."
  },
  AvgCommunicate_70488_Content_12 = {
    Text = "Dies ist... mein Wunsch."
  },
  AvgCommunicate_70488_Content_2 = {
    Text = "Darf ich fragen, ob es eine Möglichkeit gibt, ihm zu helfen?"
  },
  AvgCommunicate_70488_Content_3 = {
    Text = "Das könnte schwierig sein, Celeste."
  },
  AvgCommunicate_70488_Content_4 = {
    Text = "Selbst für Ermittler ist die Verknüpfung mit Weckern eine enorme Belastung."
  },
  AvgCommunicate_70488_Content_5 = {
    Text = "Außerdem ist Kapitän Elton in dieser Hinsicht lediglich eine gewöhnliche Person."
  },
  AvgCommunicate_70488_Content_6 = {
    Text = "Dass er so lange eine Verbindung zu dir aufrechterhalten konnte, ist bereits ein Wunder."
  },
  AvgCommunicate_70488_Content_7 = {
    Text = "Aber bitte seien Sie unbesorgt, ich werde bestimmt einen Weg finden, Ihnen zu helfen."
  },
  AvgCommunicate_70488_Content_8 = {
    Text = "Was Miryam kann, kann Mythag sicherlich auch."
  },
  AvgCommunicate_70488_Content_9 = {
    Text = "Menschen wünschen sich Dinge von mir, aber ich bin machtlos, denjenigen um mich herum zu helfen..."
  },
  AvgCommunicate_70488_Option_3 = {
    Text = "Das könnte schwierig sein, aber Mythag wird sicherlich einen Weg finden."
  },
  AvgCommunicate_70489_Content_1 = {
    Text = "Es tut mir leid für die Unterbrechung, blinder Blick."
  },
  AvgCommunicate_70489_Content_10 = {
    Text = "Mein Kontakt zu dir basiert rein auf persönlichem Interesse."
  },
  AvgCommunicate_70489_Content_11 = {
    Text = "Nachdem ich die aktuellen Angelegenheiten geklärt habe, hoffe ich wirklich, eine Gelegenheit zu haben, Sie privat zu treffen."
  },
  AvgCommunicate_70489_Content_12 = {
    Text = "Um mit dir über deine Vergangenheit und deine Zukunft zu sprechen."
  },
  AvgCommunicate_70489_Content_13 = {
    Text = "Natürlich, vorausgesetzt, du kannst diese Ereignisse überstehen."
  },
  AvgCommunicate_70489_Content_14 = {
    Text = "Ich wünsche dir alles Gute, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgCommunicate_70489_Content_15 = {
    Text = "Meine Zukunft?"
  },
  AvgCommunicate_70489_Content_16 = {
    Text = "Was meinst du?"
  },
  AvgCommunicate_70489_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_70489_Content_18 = {
    Text = "Clementine?"
  },
  AvgCommunicate_70489_Content_2 = {
    Text = "Es bist du... Perfekte Timing. Ich habe noch viele Dinge, die ich dich fragen möchte."
  },
  AvgCommunicate_70489_Content_3 = {
    Text = "Was hast du uns im Arbeitslager angetan?"
  },
  AvgCommunicate_70489_Content_4 = {
    Text = "Wie ich sagte, einige Tricks in spezialisierten Bereichen."
  },
  AvgCommunicate_70489_Content_5 = {
    Text = "Es kann mir erlauben zu gehen und euch allen einen guten Schlaf zu gönnen."
  },
  AvgCommunicate_70489_Content_6 = {
    Text = "Du hast den Begriff \"Blindes Auge\" mehr als einmal erwähnt. Was bedeutet er wirklich?"
  },
  AvgCommunicate_70489_Content_7 = {
    Text = "Pssst, das ist gerade nichts, was du wissen solltest."
  },
  AvgCommunicate_70489_Content_8 = {
    Text = "Vertraue mir, du wirst es wissen — wenn die Zeit reif ist."
  },
  AvgCommunicate_70489_Content_9 = {
    Text = "Jedenfalls meine ich es nicht böse, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgCommunicate_70489_Option_15 = {
    Text = "Meine Zukunft?"
  },
  AvgCommunicate_70489_Option_2 = {
    Text = "Bist du... der Psychologe?!"
  },
  AvgCommunicate_70489_Option_3 = {
    Text = "Was hast du uns im Arbeitslager angetan?"
  },
  AvgCommunicate_70489_Option_6 = {
    Text = "Was bedeutet \"Blinder Blick\" genau?"
  },
  AvgCommunicate_70490_Content_1 = {
    Text = "Als der künstliche Körper sich selbst zerstörte, ließ ich Herbert ein kleines Stück Silber mit Informationen und Übertragungsfähigkeiten zurück."
  },
  AvgCommunicate_70490_Content_10 = {
    Text = "Genau gleich wie das Symbol, das du in deinem Traum gezeichnet hast."
  },
  AvgCommunicate_70490_Content_11 = {
    Text = "Was genau ist dieses Symbol?"
  },
  AvgCommunicate_70490_Content_12 = {
    Text = "Tempellicht-Kirche"
  },
  AvgCommunicate_70490_Content_13 = {
    Text = "Es sind eigentlich sie..."
  },
  AvgCommunicate_70490_Content_14 = {
    Text = "Die Bildhauer, Elwes ... die Erscheinung der Tempellicht-Kirche ist nicht neu."
  },
  AvgCommunicate_70490_Content_15 = {
    Text = "Mythags wahre Feinde nähern sich uns."
  },
  AvgCommunicate_70490_Content_16 = {
    Text = "Mach dich bereit, %player%."
  },
  AvgCommunicate_70490_Content_2 = {
    Text = "Dank Herbert's Gier konnte dieses kleine Gerät doch viele Informationen sammeln."
  },
  AvgCommunicate_70490_Content_3 = {
    Text = "So mächtig, Professor Puppe!"
  },
  AvgCommunicate_70490_Content_4 = {
    Text = "Es ist nur so, dass er nicht vorsichtig genug war."
  },
  AvgCommunicate_70490_Content_5 = {
    Text = "Ein selbsternannter Genie, dessen Arroganz ihn dazu bringt, seine Wachsamkeit zu verlieren."
  },
  AvgCommunicate_70490_Content_6 = {
    Text = "Hast du diesen Zug schon lange geplant?!"
  },
  AvgCommunicate_70490_Content_7 = {
    Text = "Selbst das Manipulieren künstlicher Körper ist ziemlich mühsam."
  },
  AvgCommunicate_70490_Content_8 = {
    Text = "Wenn ich nichts bekommen kann, kann ich mir ebenso gut nachmittags Tee in der Lounge gönnen."
  },
  AvgCommunicate_70490_Content_9 = {
    Text = "Zusammenfassend ist die wichtigste Information in den gesammelten Geheimdienstinformationen ein Symbol."
  },
  AvgCommunicate_70490_Option_11 = {
    Text = "Was genau ist dieses Symbol?"
  },
  AvgCommunicate_70490_Option_3 = {
    Text = "So mächtig, Professor Puppe!"
  },
  AvgCommunicate_70490_Option_6 = {
    Text = "Hast du diesen Zug schon lange geplant?!"
  },
  AvgCommunicate_70491_Content_1 = {
    Text = "Die erste Feldaufgabe nach der Annahme der Rolle des Hüters ist beendet."
  },
  AvgCommunicate_70491_Content_10 = {
    Text = "Ich habe nie erwartet, dass meine erste offizielle Feldmission damit zu tun haben würde."
  },
  AvgCommunicate_70491_Content_11 = {
    Text = "Weil du der Hüter bist."
  },
  AvgCommunicate_70491_Content_12 = {
    Text = "Viele sind gegangen, aber aufgrund von dir wurden mehr gerettet."
  },
  AvgCommunicate_70491_Content_13 = {
    Text = "Wir sind auf dem richtigen Weg."
  },
  AvgCommunicate_70491_Content_14 = {
    Text = "Du hast recht, Ramona."
  },
  AvgCommunicate_70491_Content_15 = {
    Text = "Mehr Menschen werden durch uns gerettet."
  },
  AvgCommunicate_70491_Content_16 = {
    Text = "Wir werden diesen Weg bis zum Ende gehen."
  },
  AvgCommunicate_70491_Content_17 = {
    Text = "Sicherlich!"
  },
  AvgCommunicate_70491_Content_2 = {
    Text = "Herzlichen Glückwunsch."
  },
  AvgCommunicate_70491_Content_3 = {
    Text = "Ich habe nie erwartet, dass meine erste offizielle Feldmission damit zu tun haben würde."
  },
  AvgCommunicate_70491_Content_4 = {
    Text = "Aber ungeachtet dessen, haben wir es geschafft."
  },
  AvgCommunicate_70491_Content_5 = {
    Text = "Wir sind auf dem richtigen Weg."
  },
  AvgCommunicate_70491_Content_6 = {
    Text = "Das ist korrekt, Hüter."
  },
  AvgCommunicate_70491_Content_7 = {
    Text = "Wir werden diesen Weg bis zum Ende gehen."
  },
  AvgCommunicate_70491_Content_8 = {
    Text = "Ich habe das Gefühl, dass ich nichts erfolgreich abgeschlossen habe, Ramona."
  },
  AvgCommunicate_70491_Content_9 = {
    Text = "Senior Anderson, Sarah, Aigis..."
  },
  AvgCommunicate_70491_Option_14 = {
    Text = "Du hast absolut recht..."
  },
  AvgCommunicate_70491_Option_3 = {
    Text = "Es gibt viele Bedauern, aber wir sind auf dem richtigen Weg."
  },
  AvgCommunicate_70491_Option_8 = {
    Text = "Das Problem ist vorübergehend gelöst, aber einige Bedauern können niemals behoben werden."
  },
  AvgCommunicate_70492_Content_1 = {
    Text = "Ich möchte kürzlich eine Gedenkveranstaltung abhalten, aber ich habe nicht genug lebende Fische und Boote."
  },
  AvgCommunicate_70492_Content_10 = {
    Text = "Da du über meine Vergangenheit Bescheid weißt, solltest du auch meine Antwort kennen."
  },
  AvgCommunicate_70492_Content_11 = {
    Text = "Wenn ich eine weitere Chance bekäme, würde ich immer noch tun, was ich einmal getan habe."
  },
  AvgCommunicate_70492_Content_12 = {
    Text = "Die Vergangenheit, die Gegenwart und die Zukunft. Der Hohe Priester von Lemuria bereut niemals."
  },
  AvgCommunicate_70492_Content_13 = {
    Text = "Ich... hatte nie eine andere Wahl, Hüter."
  },
  AvgCommunicate_70492_Content_2 = {
    Text = "Kann Mythag sich für eine Weile etwas leihen? Ich garantiere, als der Hohepriester von Lemuria wird es rechtzeitig zurückgegeben."
  },
  AvgCommunicate_70492_Content_3 = {
    Text = "Kein Problem. Ich werde dir helfen, mit der Schule zu kommunizieren, und das Schulkomitee sollte es genehmigen."
  },
  AvgCommunicate_70492_Content_4 = {
    Text = "Sind diese Gegenstände für deine Familie oder für Deborah?"
  },
  AvgCommunicate_70492_Content_5 = {
    Text = "...Weißt du alles?"
  },
  AvgCommunicate_70492_Content_6 = {
    Text = "Laut den Bräuchen von Lemuria würden Sie Ihren am meisten geschätzten Verstorbenen mit lebenden Fischen und Booten Grüße senden."
  },
  AvgCommunicate_70492_Content_7 = {
    Text = "Du kannst sie immer noch nicht vergessen. Du liebst sie immer noch tief."
  },
  AvgCommunicate_70492_Content_8 = {
    Text = "Also... bereust du es, Miryam?"
  },
  AvgCommunicate_70492_Content_9 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_70492_Option_3 = {
    Text = "Kein Problem."
  },
  AvgCommunicate_70492_Option_4 = {
    Text = "Ist es für deine Familie, oder ist es für Deborah vorbereitet?"
  },
  AvgCommunicate_70492_Option_8 = {
    Text = "Bereust du es?"
  },
  AvgCommunicate_70493_Content_1 = {
    Text = "Ich habe deinen Willen gelesen."
  },
  AvgCommunicate_70493_Content_10 = {
    Text = "Ich werde auch stolz deine Taten anderen erzählen, bis... der Tag kommt, an dem meine Erinnerung einer Auflösung unterzogen wird."
  },
  AvgCommunicate_70493_Content_11 = {
    Text = "Aber während ich mein Testament vortrage, überkommt mich in diesem Moment das Bedauern, das all meine Gedanken verzehrt."
  },
  AvgCommunicate_70493_Content_12 = {
    Text = "Du hast gesagt, du bist ein Feigling. Du hast gesagt, du würdest uns niemals verlassen wollen."
  },
  AvgCommunicate_70493_Content_13 = {
    Text = "Aber am Ende bist du immer noch diesen Weg gegangen."
  },
  AvgCommunicate_70493_Content_14 = {
    Text = "Vater ist fort. Du bist auch fort."
  },
  AvgCommunicate_70493_Content_15 = {
    Text = "Es macht mir nichts aus, die Lügen, die du erzählst. Ich wünschte, du könntest mich noch ein bisschen länger täuschen. Ein Jahr, einen Monat..."
  },
  AvgCommunicate_70493_Content_16 = {
    Text = "Auch wenn es nur für einen Tag ist, haben die unausgesprochenen Worte zumindest die Chance gesagt zu werden..."
  },
  AvgCommunicate_70493_Content_17 = {
    Text = "Ich habe wirklich Angst, %player%."
  },
  AvgCommunicate_70493_Content_18 = {
    Text = "Ich fürchte, dass ich eines Tages dein Gesicht und deinen Namen vergessen werde."
  },
  AvgCommunicate_70493_Content_19 = {
    Text = "Ich fürchte, dass du eines Tages völlig aus meinem Gedächtnis verschwinden wirst..."
  },
  AvgCommunicate_70493_Content_2 = {
    Text = "Ich habe versucht, diese Worte in einem tröstlichen Ton zu rezitieren, wie du es gewünscht hast."
  },
  AvgCommunicate_70493_Content_20 = {
    Text = "Aber du weißt, ich bin nicht der Typ Mensch, der leicht aufgibt."
  },
  AvgCommunicate_70493_Content_21 = {
    Text = "Ich kann es nicht glauben, dass du einfach so verschwinden würdest."
  },
  AvgCommunicate_70493_Content_22 = {
    Text = "Egal wie lange ich warte, ich werde hier sein, mich erinnernd. Bis zu dem Tag, an dem du aus dem Schwarzen Pool erwachst, diese Tür öffnest und zu diesem Campus zurückkehrst."
  },
  AvgCommunicate_70493_Content_23 = {
    Text = "Wenn die Zeit kommt, werde ich dir alles erzählen, was während deiner Abwesenheit passiert ist, sowie die unausgesprochenen Worte, eines nach dem anderen..."
  },
  AvgCommunicate_70493_Content_24 = {
    Text = "Ich weiß, dass du jetzt sehr müde sein musst, zu müde um zu antworten... Es ist in Ordnung, ruhe dich gut aus."
  },
  AvgCommunicate_70493_Content_25 = {
    Text = "Ich warte auf dich... %player%."
  },
  AvgCommunicate_70493_Content_3 = {
    Text = "Ich habe mein Bestes gegeben. Aber ich kann es nicht, %player%..."
  },
  AvgCommunicate_70493_Content_4 = {
    Text = "Das Schlüsselgrab ist voller Menschen; ich kann niemanden sehen."
  },
  AvgCommunicate_70493_Content_5 = {
    Text = "Die ganze Welt ist verstummt. Nur das Geräusch des Regens bleibt, nur du und ich."
  },
  AvgCommunicate_70493_Content_6 = {
    Text = "Als sich die Tür vor mir schloss und diese Worte Zeile für Zeile vor meinen Augen vorbeizogen, fühlte ich nur Bedauern."
  },
  AvgCommunicate_70493_Content_7 = {
    Text = "Es tut mir leid, diese Ideen der Ermittler in dir eingepflanzt zu haben, es tut mir leid, dir dieses Wissen über die Ermittlungen beigebracht zu haben, es tut mir leid, dich von Akut weggenommen zu haben..."
  },
  AvgCommunicate_70493_Content_8 = {
    Text = "Ich weiß, dass ich nicht so denken sollte."
  },
  AvgCommunicate_70493_Content_9 = {
    Text = "Ich bin ein Ermittler. Du hast unsere Welt vor der Auflösung gerettet. Ich sollte mich für dich erleichtert fühlen."
  },
  AvgCommunicate_70494_Content_1 = {
    Text = "Guten Tag, Hüter von Mythag."
  },
  AvgCommunicate_70494_Content_10 = {
    Text = "Ich habe gehört, dass Mythag einen herausragenden Hüter hervorgebracht hat."
  },
  AvgCommunicate_70494_Content_11 = {
    Text = "Ich sollte nicht eindringen, aber ich kann einfach meine Neugier nicht zügeln und möchte dich gerne persönlich sehen."
  },
  AvgCommunicate_70494_Content_12 = {
    Text = "Du hast mich nicht enttäuscht, %player%."
  },
  AvgCommunicate_70494_Content_13 = {
    Text = "Was genau hast du vor?"
  },
  AvgCommunicate_70494_Content_14 = {
    Text = "Wenn ich die Gelegenheit habe, würde ich dich gerne als Gast in mein Labor einladen."
  },
  AvgCommunicate_70494_Content_15 = {
    Text = "Ein Hüter, der unzählige Erwachte verknüpfen kann... Die Geheimnisse über dich faszinieren mich sehr."
  },
  AvgCommunicate_70494_Content_16 = {
    Text = "Wenn du die Mitglieder der Bildhauervereinigung bringst, um Mythag zu beichten, könnte die Zusammenarbeit einen Gedanken wert sein."
  },
  AvgCommunicate_70494_Content_17 = {
    Text = "Heh... Ich dachte, ich würde getadelt werden."
  },
  AvgCommunicate_70494_Content_18 = {
    Text = "Du bist interessanter, als ich mir vorgestellt habe."
  },
  AvgCommunicate_70494_Content_19 = {
    Text = "Die kommenden Tage sind lang, und in der Zukunft werden wir viele Gelegenheiten zur Kommunikation haben."
  },
  AvgCommunicate_70494_Content_2 = {
    Text = "Es bist du... Herbert Rosenthal..."
  },
  AvgCommunicate_70494_Content_20 = {
    Text = "Freu dich darauf, %player%."
  },
  AvgCommunicate_70494_Content_3 = {
    Text = "Oh, es scheint, jemand hat mich dir bereits vorgestellt."
  },
  AvgCommunicate_70494_Content_4 = {
    Text = "Es hat mir tatsächlich viel Mühe erspart."
  },
  AvgCommunicate_70494_Content_5 = {
    Text = "Silberkommunikation erfordert eine bidirektionale Verknüpfung. Wie hast du mich kontaktiert?"
  },
  AvgCommunicate_70494_Content_6 = {Text = "Hmm..."},
  AvgCommunicate_70494_Content_7 = {
    Text = "Für die Glücklichen, die an der Entwicklung teilnehmen dürfen, gibt es in der Silber-Kommunikationstechnologie keine Geheimnisse."
  },
  AvgCommunicate_70494_Content_8 = {
    Text = "Bist du der Entwickler von Silber Kommunikation?"
  },
  AvgCommunicate_70494_Content_9 = {
    Text = "Alte Geschichten können in Ruhe besprochen werden, wenn wir Zeit haben."
  },
  AvgCommunicate_70494_Option_13 = {
    Text = "Was genau hast du vor?"
  },
  AvgCommunicate_70494_Option_16 = {
    Text = "Es sei denn, du gestehst Mythag"
  },
  AvgCommunicate_70494_Option_2 = {
    Text = "Herbert Rosenthal..."
  },
  AvgCommunicate_70494_Option_5 = {
    Text = "Wie hast du mit mir Kontakt aufgenommen?"
  },
  AvgCommunicate_70495_Content_1 = {
    Text = "Andersons Reste wurden von der Bildhauervereinigung zerstört und lassen sich nicht zu einer vollständigen menschlichen Form zusammensetzen."
  },
  AvgCommunicate_70495_Content_10 = {
    Text = "Vielleicht werden wir eines Tages..."
  },
  AvgCommunicate_70495_Content_11 = {
    Text = "Wirst du Angst empfinden, Senior William?"
  },
  AvgCommunicate_70495_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_70495_Content_13 = {
    Text = "Vielleicht kann jemand Leben und Tod transcendieren, aber nicht ich."
  },
  AvgCommunicate_70495_Content_14 = {
    Text = "Ich habe die ganze Zeit Angst, %player%."
  },
  AvgCommunicate_70495_Content_15 = {
    Text = "Aber ich habe nie irgendwelche Spuren von Angst in dir gesehen."
  },
  AvgCommunicate_70495_Content_16 = {
    Text = "Weil ich keine Zeit habe. Weil die Auflösung direkt vor mir steht."
  },
  AvgCommunicate_70495_Content_17 = {
    Text = "Viele sind gestorben, doch ich lebe noch."
  },
  AvgCommunicate_70495_Content_18 = {
    Text = "Ob es Angst oder Erinnerung ist, der Ermittler von Mythag hat nicht das Recht, dafür anzuhalten."
  },
  AvgCommunicate_70495_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_70495_Content_2 = {
    Text = "Diese gewaltsam extrahierten Silber sind auch fast vollständig zerstört worden."
  },
  AvgCommunicate_70495_Content_20 = {
    Text = "Eine neue Aufgabe ist angekommen."
  },
  AvgCommunicate_70495_Content_21 = {
    Text = "Wir werden überleben, %player%. Bis zu dem Tag, an dem die Auflösung gelöst ist."
  },
  AvgCommunicate_70495_Content_3 = {
    Text = "Wir durchsuchen das Labor im Armenhaus und fanden nur das."
  },
  AvgCommunicate_70495_Content_4 = {
    Text = "Silberschlüssel, ID L-1463, gehört zu Ermittler Anderson – gehörte einst ihm."
  },
  AvgCommunicate_70495_Content_5 = {
    Text = "Was wird die Schule mit diesem silbernen Schlüssel machen...?"
  },
  AvgCommunicate_70495_Content_6 = {
    Text = "Wiederverwertung, lege in die <Schwarze Pfütze> zum Neugestalten und verteile dann an neue <Investigators> bei der nächsten <Schlüsselgrabzeremonie> im nächsten Jahr."
  },
  AvgCommunicate_70495_Content_7 = {
    Text = "Es wird den neuen Ermittler begleiten, ständig zu den gefährlichsten Orten unterwegs."
  },
  AvgCommunicate_70495_Content_8 = {
    Text = "Bis dieser Ermittler zurücktritt oder stirbt."
  },
  AvgCommunicate_70495_Content_9 = {
    Text = "Vielleicht werden wir eines Tages..."
  },
  AvgCommunicate_70495_Option_10 = {
    Text = "Wirst du Angst empfinden?"
  },
  AvgCommunicate_70495_Option_15 = {
    Text = "Ich habe deine Angst nie gespürt."
  },
  AvgCommunicate_70495_Option_5 = {
    Text = "Was wird die Schule mit diesem silbernen Schlüssel machen...?"
  },
  AvgCommunicate_70495_Option_9 = {
    Text = "Werden wir enden wie Anderson?"
  },
  AvgCommunicate_70496_Content_1 = {
    Text = "Das Ritual dieser Aram-Leute... ist wirklich erschreckend."
  },
  AvgCommunicate_70496_Content_10 = {
    Text = "Bin ich so eine Art Mensch?"
  },
  AvgCommunicate_70496_Content_11 = {
    Text = "Ich habe nur beiläufig gefragt, warum so angespannt?"
  },
  AvgCommunicate_70496_Content_12 = {
    Text = "Das zu tun, macht dich bei der Kartentisch zu einem offenen Buch. Deine mentale Stärke benötigt Verbesserung, Hüter."
  },
  AvgCommunicate_70496_Content_13 = {
    Text = "Kurz gesagt, die Geheimnisse dieser Wüste sind wahrscheinlich viel komplexer als wir angenommen haben."
  },
  AvgCommunicate_70496_Content_14 = {
    Text = "Die nachfolgende Untersuchung erfordert besondere Vorsicht."
  },
  AvgCommunicate_70496_Content_2 = {
    Text = "Ich dachte, du würdest die Einladung der Arlan-Frau annehmen."
  },
  AvgCommunicate_70496_Content_3 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_70496_Content_4 = {
    Text = "Welches Bild habe ich wirklich in deinem Herzen..."
  },
  AvgCommunicate_70496_Content_5 = {
    Text = "Ich habe nie erwartet, dass Ryker, der normalerweise so charmant ist, auch Dinge hat, die er nicht akzeptieren kann."
  },
  AvgCommunicate_70496_Content_6 = {
    Text = "Es gibt keine Geschichten mit Blumen und Wein, nur die primitivsten und wildesten Wünsche."
  },
  AvgCommunicate_70496_Content_7 = {
    Text = "Diese Art von Ritual gefällt mir in der Tat nicht."
  },
  AvgCommunicate_70496_Content_8 = {
    Text = "Sprechen wir darüber, du hast doch keine seltsamen Einladungen angenommen, oder?"
  },
  AvgCommunicate_70496_Content_9 = {
    Text = "Wann... natürlich nicht... wie könnte das sein!"
  },
  AvgCommunicate_70496_Option_2 = {
    Text = "Ich dachte, du würdest die Einladung dieser Aylan-Frau annehmen."
  },
  AvgCommunicate_70496_Option_5 = {
    Text = "Ich habe nicht erwartet, dass es Dinge gibt, die du ebenfalls nicht akzeptieren kannst."
  },
  AvgCommunicate_70496_Option_9 = {
    Text = "Wann... natürlich nicht... wie könnte das sein!"
  },
  AvgCommunicate_70497_Content_1 = {
    Text = "Hallo, Geheimnishüter {Male=Herr,Female=Frau}."
  },
  AvgCommunicate_70497_Content_2 = {
    Text = "Hattest du Spaß beim Spielen mit Juliettes Spielzeug?"
  },
  AvgCommunicate_70497_Content_3 = {
    Text = "Bist du... der Maulwurf?!"
  },
  AvgCommunicate_70497_Content_4 = {
    Text = "Ich dachte, du hättest früher herausgefunden, wer ich bin. So schade."
  },
  AvgCommunicate_70497_Content_5 = {
    Text = "Aber es ist in Ordnung; es ist schließlich nur das letzte Spiel."
  },
  AvgCommunicate_70497_Content_6 = {
    Text = "Jetzt steht das Spiel kurz vor dem Ende."
  },
  AvgCommunicate_70497_Content_7 = {
    Text = "Bevor die vorherbestimmte Zerstörung eintrifft, interessiert mich nur eines."
  },
  AvgCommunicate_70497_Content_8 = {
    Text = "Kann die ewige Wahrheit des Chaos, der mutige Hüter, von dem wir schamlos sprechen, Mythag, der mutige Retter, wirklich mit Tapferkeit konfrontiert werden?"
  },
  AvgCommunicate_70497_Option_3 = {
    Text = "Bist du... der Maulwurf?!"
  },
  AvgCommunicate_70498_Content_1 = {
    Text = "Ich bin kein törichter Händler, aber nach sorgfältiger Überlegung scheint es, dass ich einen Verlustdeal gemacht habe..."
  },
  AvgCommunicate_70498_Content_10 = {
    Text = "Immer vorsichtig bei Lügen zu sein, ist eine grundlegende Eigenschaft eines qualifizierten Geschäftsführers."
  },
  AvgCommunicate_70498_Content_11 = {
    Text = "Also... das war wirklich das wahre Gesicht von Frau Davendale?"
  },
  AvgCommunicate_70498_Content_12 = {
    Text = "Es gibt keine Kosten, die teurer sind als die Realität, kleiner Hüter."
  },
  AvgCommunicate_70498_Content_13 = {
    Text = "Vielen Dank, Lady Narzisse."
  },
  AvgCommunicate_70498_Content_14 = {
    Text = "Was ich gerade gesagt habe, war ein Scherz. Ich weiß, was es bedeutet, für jemanden wie dich, sein wahres Ich zu offenbaren."
  },
  AvgCommunicate_70498_Content_15 = {
    Text = "Dies ist ein wertvolles Geschenk, und ich werde es gut schätzen."
  },
  AvgCommunicate_70498_Content_16 = {
    Text = "Denk nicht, dass du mich einfach mit ein paar Worten abwimmeln kannst, Kleine."
  },
  AvgCommunicate_70498_Content_17 = {
    Text = "Im Gegenzug solltest du mir auch ein Geschenk geben, oder?"
  },
  AvgCommunicate_70498_Content_18 = {
    Text = "Wurde ich durchschaut...?"
  },
  AvgCommunicate_70498_Content_19 = {
    Text = "Frau Davendale, was wünschen Sie sich?"
  },
  AvgCommunicate_70498_Content_2 = {Text = "?"},
  AvgCommunicate_70498_Content_20 = {
    Text = "Da du meine wahre Form bereits gesehen hast, wann wirst du bereit sein, mir dein wahres Ich zu zeigen?"
  },
  AvgCommunicate_70498_Content_21 = {
    Text = "Mein wahres Ich? Was bedeutet das... Ich verstehe nicht ganz, Lady Narzisse."
  },
  AvgCommunicate_70498_Content_22 = {
    Text = "Es scheint, dass Mythag dir noch nichts gesagt hat..."
  },
  AvgCommunicate_70498_Content_23 = {
    Text = "Die Zeit ist noch nicht gekommen. Keine Sorgen."
  },
  AvgCommunicate_70498_Content_24 = {
    Text = "Denke an unser heutiges Geschäft, Kleines."
  },
  AvgCommunicate_70498_Content_25 = {
    Text = "Ich freue mich auf den Tag, an dem du dein wahres Gesicht offenbarst."
  },
  AvgCommunicate_70498_Content_3 = {
    Text = "Hast du nicht bereits den Kopf erhalten, den du gewünscht hast?"
  },
  AvgCommunicate_70498_Content_4 = {
    Text = "Diese lebendige graue Materie ist zu einem weiteren geschätzten Stück in deiner Sammlung geworden."
  },
  AvgCommunicate_70498_Content_5 = {
    Text = "In der Tat, es war ein schöner Kopf; dieser Tausch kann nicht als Verlust betrachtet werden."
  },
  AvgCommunicate_70498_Content_6 = {
    Text = "Jedoch ist der Preis, den ich gezahlt habe, noch immer ein bisschen zu hoch."
  },
  AvgCommunicate_70498_Content_7 = {
    Text = "Du hast mir nur einen Blick auf deine wahre Form gegeben..."
  },
  AvgCommunicate_70498_Content_8 = {
    Text = "Und ob du wirklich so aussiehst, ist schwer zu sagen."
  },
  AvgCommunicate_70498_Content_9 = {
    Text = "Hehe... Nicht schlecht, Kleine."
  },
  AvgCommunicate_70498_Option_11 = {
    Text = "Also... das war wirklich das wahre Gesicht von Frau Davendale?"
  },
  AvgCommunicate_70498_Option_13 = {
    Text = "Vielen Dank, Lady Narzisse."
  },
  AvgCommunicate_70498_Option_18 = {
    Text = "Wurde ich durchschaut...?"
  },
  AvgCommunicate_70498_Option_2 = {
    Text = "Haben wir nicht bereits den Kopf bekommen?"
  },
  AvgCommunicate_70498_Option_21 = {
    Text = "Mein wahres Ich? Was bedeutet das"
  },
  AvgCommunicate_70498_Option_7 = {
    Text = "Ich habe gerade einen flüchtigen Blick auf deine wahre Gestalt geworfen..."
  },
  AvgCommunicate_70499_Content_1 = {
    Text = "Indem sie Abweichler eliminiert, hat sie sich von den Zwängen Longbels und des Vertrags befreit. Ohne diese Hindernisse ist sie in nur wenigen Wochen zur rücksichtslosesten Jägerin in Londiniums Geschäftswelt geworden."
  },
  AvgCommunicate_70499_Content_10 = {
    Text = "Mach dir keine Sorgen, Professor Dexter. Wir werden dich beim nächsten Mal nicht solche gefährlichen Dinge tun lassen... Ich meine, wir werden versuchen, es nicht zu tun."
  },
  AvgCommunicate_70499_Content_11 = {
    Text = "Die Existenz, die in Sorels Bewusstsein verborgen ist, scheint \"N\" genannt zu werden. Weißt du etwas über ihn?"
  },
  AvgCommunicate_70499_Content_12 = {
    Text = "Nicht sehr klar. Klingt entweder nach einem Betrüger oder einem Verrückten, wahrscheinlich beides."
  },
  AvgCommunicate_70499_Content_13 = {
    Text = "Aber egal wie abscheulich, dieser Kerl hat wenigstens Geschmack. Man kann es aus seinem Gesang erkennen."
  },
  AvgCommunicate_70499_Content_14 = {
    Text = "Beim nächsten Mal, wenn sich eine Gelegenheit bietet, müssen wir uns besser kennenlernen. Vielleicht können wir sogar das ein oder andere Getränk teilen."
  },
  AvgCommunicate_70499_Content_15 = {
    Text = "...Natürlich, in einer sicheren Umgebung. Der alte Herr kann keinen Schreck mehr ertragen."
  },
  AvgCommunicate_70499_Content_2 = {
    Text = "Ich denke, es wird nicht lange dauern, bis das gesamte Land Londinium ihren Nachnamen trägt."
  },
  AvgCommunicate_70499_Content_3 = {
    Text = "Lady Sorel, was für eine faszinierende Person. Glücklicherweise steht Mythag auf ihrer Seite."
  },
  AvgCommunicate_70499_Content_4 = {
    Text = "Ich schulde diese Angelegenheit Ihrer Hilfe, Professor Dexter."
  },
  AvgCommunicate_70499_Content_5 = {
    Text = "Danke, dass ihr geholfen habt, den Verdächtigen herauszulocken; sonst hätte es viel länger gedauert, diese Angelegenheit zu klären."
  },
  AvgCommunicate_70499_Content_6 = {
    Text = "Einfach die Pflichten eines Gentlemans erfüllen."
  },
  AvgCommunicate_70499_Content_7 = {
    Text = "Der Vorschlag, den Ramona gemacht hat, kann von diesem alten Vater von mir nicht abgelehnt werden."
  },
  AvgCommunicate_70499_Content_8 = {
    Text = "Jedoch hoffe ich, dass du beim nächsten Mal schneller handeln kannst, falls so etwas wieder passiert."
  },
  AvgCommunicate_70499_Content_9 = {
    Text = "Warte nicht, bis das Messer von diesem Typ nur noch fünf Zentimeter von meinem Hals entfernt ist, um zu erscheinen; das ist wirklich erschreckend."
  },
  AvgCommunicate_70499_Option_10 = {
    Text = "Es wird kein nächstes Mal geben... ich werde mein Bestes tun."
  },
  AvgCommunicate_70499_Option_11 = {
    Text = "Wissen Sie über \"N\" Bescheid?"
  },
  AvgCommunicate_70499_Option_4 = {
    Text = "Danke, dass ihr geholfen habt, den Verdächtigen herauszulocken"
  },
  AvgCommunicate_70500_Content_1 = {
    Text = "Die Unterhaltung im Café war recht vergnüglich, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgCommunicate_70500_Content_10 = {
    Text = "Dann, wenn diese Situation erneut eintritt, würdest du immer noch das wahre Ich erschießen, um andere zu retten? Würdest du?"
  },
  AvgCommunicate_70500_Content_11 = {
    Text = "Hmm... natürlich."
  },
  AvgCommunicate_70500_Content_12 = {
    Text = "Sei unbesorgt, {Male=Mr.,Female=Miss} Schutzherr. Das Glück wird mir weiterhin hold sein."
  },
  AvgCommunicate_70500_Content_13 = {
    Text = "Zu diesem Zeitpunkt hatte meine Waffe definitiv keine Kugeln."
  },
  AvgCommunicate_70500_Content_14 = {Text = "70% nein."},
  AvgCommunicate_70500_Content_2 = {
    Text = "Es ist eine Ehre, die Vergangenheit eines Spielers zu witness."
  },
  AvgCommunicate_70500_Content_3 = {
    Text = "Mein Lieblingsteil ist, wenn der Spieler alles verliert und seine Seele von anderen gestohlen wird."
  },
  AvgCommunicate_70500_Content_4 = {
    Text = "Ha... Es gibt Siege und Niederlagen, so ist das Leben."
  },
  AvgCommunicate_70500_Content_5 = {
    Text = "Sieh, haben wir dieses Mal nicht einen Vorteil erlangt?"
  },
  AvgCommunicate_70500_Content_6 = {
    Text = "So war der Schuss, den du auf mich abgegeben hast, also auch ein Spiel?"
  },
  AvgCommunicate_70500_Content_7 = {
    Text = "Wie könnte das sein? Ich bin mir zu 70 % sicher über mein Urteil."
  },
  AvgCommunicate_70500_Content_8 = {
    Text = "Was ist mit den verbleibenden 30%?"
  },
  AvgCommunicate_70500_Content_9 = {
    Text = "Es gibt keine verbleibenden 30%. 70% entsprechen 100%."
  },
  AvgCommunicate_70500_Option_2 = {
    Text = "Es ist eine Ehre, die Vergangenheit eines Spielers zu witness."
  },
  AvgCommunicate_70500_Option_6 = {
    Text = "Also war der Schuss, der auf mich abgefeuert wurde, auch ein Risiko?"
  },
  AvgCommunicate_70500_Option_8 = {
    Text = "Was ist mit den verbleibenden 30%?"
  },
  AvgCommunicate_70501_Content_1 = {
    Text = "Sieht es gut aus?"
  },
  AvgCommunicate_70501_Content_10 = {
    Text = "Allerdings... die Geschichte, die diese Skulpturengruppe erzählt, ist ein wenig zu grausam."
  },
  AvgCommunicate_70501_Content_11 = {
    Text = "Du hast es verstanden, Schutzherr..."
  },
  AvgCommunicate_70501_Content_12 = {
    Text = "Alle Schöpfung ist grausam."
  },
  AvgCommunicate_70501_Content_13 = {
    Text = "Gerade in dieser Grausamkeit gewinnt die stille Kunst ein lebendiges Leben."
  },
  AvgCommunicate_70501_Content_14 = {
    Text = "Wenn ich es wäre, würde ich diesen kreativen Prozess ziemlich erschöpfend finden..."
  },
  AvgCommunicate_70501_Content_15 = {
    Text = "Aber du bist anders, Sanga. Ich verstehe deine Entscheidung."
  },
  AvgCommunicate_70501_Content_16 = {
    Text = "Werke wie „Frau Corals Tod\" verkörpern den Sinn, den du verfolgst."
  },
  AvgCommunicate_70501_Content_17 = {
    Text = "Ich freue mich darauf, dass die „Grausamkeit\" erneut in den Linien erblüht, die du schnitzt."
  },
  AvgCommunicate_70501_Content_18 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_70501_Content_19 = {
    Text = "Ich dachte, du würdest vorschlagen, meine Kunst „normaler\" zu machen, wie diese gewöhnlichen Individuen."
  },
  AvgCommunicate_70501_Content_2 = {
    Text = "Was... dein Gesicht?"
  },
  AvgCommunicate_70501_Content_20 = {
    Text = "Diese Worte bedeuten mir sehr viel... Danke, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgCommunicate_70501_Content_21 = {
    Text = "Als Gegenleistung verrate ich dir ein kleines Geheimnis: Wenn du einen Traum betrittst, stehe ich direkt neben dir."
  },
  AvgCommunicate_70501_Content_22 = {
    Text = "Ich habe deine aufgeschreckten Gesichtsausdrücke eingefangen. Lebhaft realistisch."
  },
  AvgCommunicate_70501_Content_23 = {
    Text = "Wenn du Zeit hast, komm und besuche meine kleine Ausstellungshalle~"
  },
  AvgCommunicate_70501_Content_24 = {
    Text = "Sanga! Ich gebe dir fünfzig Leo-Fänge, also bitte wirf diese Skulpturen weg..."
  },
  AvgCommunicate_70501_Content_25 = {
    Text = "Was du gesagt hast, ist lebendige und „grausame\" Kunst, nicht wahr, Schutzherr?"
  },
  AvgCommunicate_70501_Content_3 = {
    Text = "Natürlich die Skulptur, die du in deinem Traum gesehen hast."
  },
  AvgCommunicate_70501_Content_4 = {
    Text = "Die Linien des Körpers sind von Natur aus harmonisch, doch es fehlt ihnen die Stille und ewige Schönheit sowie Thema und Kreativität, was es schwierig macht, sie mit bildhauerischen Werken zu vergleichen."
  },
  AvgCommunicate_70501_Content_5 = {
    Text = "Diese Skulpturengruppe ist heutzutage selten zu sehen. Ich würde gerne deine Gedanken dazu erfahren..."
  },
  AvgCommunicate_70501_Content_6 = {
    Text = "Was... deine Skulptur?"
  },
  AvgCommunicate_70501_Content_7 = {
    Text = "Natürlich. Diese Skulpturengruppe bekommt heutzutage kaum noch jemand zu sehen, und ich möchte deine Meinung dazu wissen..."
  },
  AvgCommunicate_70501_Content_8 = {
    Text = "Das war die schönste Skulpturengruppe, die ich je gesehen habe."
  },
  AvgCommunicate_70501_Content_9 = {
    Text = "Obwohl offensichtlich statisch, stellen die Linien eine Dynamik und Lebendigkeit dar, die lebenden Wesen fehlt."
  },
  AvgCommunicate_70501_Option_14 = {
    Text = "Ich verstehe deine Wahl"
  },
  AvgCommunicate_70501_Option_2 = {
    Text = "Dein Gesicht?"
  },
  AvgCommunicate_70501_Option_24 = {Text = "Nein!!!"},
  AvgCommunicate_70501_Option_6 = {
    Text = "Deine Skulptur?"
  },
  AvgCommunicate_70501_Option_8 = {
    Text = "Schönheit... und Grausamkeit."
  },
  AvgCommunicate_70502_Content_1 = {
    Text = "Langweilig. Langweilig, langweilig, langweilig..."
  },
  AvgCommunicate_70502_Content_10 = {
    Text = "Londinium erlaubt keine Sklaverei, dieser barbarische Ort."
  },
  AvgCommunicate_70502_Content_11 = {
    Text = "Mir bleibt keine Wahl, als auf dich zu hören und sie im Labyrinth zu befehligen."
  },
  AvgCommunicate_70502_Content_12 = {
    Text = "Die Art, wie sie in der Arena kämpften, war genau so, wie ich es zuvor gesehen hatte!"
  },
  AvgCommunicate_70502_Content_13 = {
    Text = "So wird das Labyrinth für diesen Zweck genutzt..."
  },
  AvgCommunicate_70502_Content_14 = {
    Text = "Das stimmt, das stimmt! Wie faszinierend!"
  },
  AvgCommunicate_70502_Content_15 = {
    Text = "Komm schon, lass uns mal einen Blick darauf werfen! Das ist die höchste Ehre!"
  },
  AvgCommunicate_70502_Content_16 = {
    Text = "Es ist nicht unmöglich; mehr über die Geschichte zu lernen, ist keine schlechte Sache..."
  },
  AvgCommunicate_70502_Content_17 = {
    Text = "Uvhash wird wahrscheinlich wirklich deine Arena mögen. Warum nicht auch ihn einladen?"
  },
  AvgCommunicate_70502_Content_18 = {
    Text = "Auf keinen Fall! Haltet mir diesen Teufel vom Leib!!!"
  },
  AvgCommunicate_70502_Content_2 = {
    Text = "Jeden Tag in diesem gottverlassenen Ort festzusitzen, treibt mich in den Wahnsinn!"
  },
  AvgCommunicate_70502_Content_3 = {
    Text = "Ich habe mein Labyrinth neu aufgebaut, eine gesamte Arena, die nach meinen Erinnerungen konstruiert wurde!"
  },
  AvgCommunicate_70502_Content_4 = {
    Text = "Lass uns Spaß haben! Sofort!"
  },
  AvgCommunicate_70502_Content_5 = {
    Text = "Wann wirst du diesen Ton ändern, den du benutzt, um Sklaven zu befehlen...?"
  },
  AvgCommunicate_70502_Content_6 = {
    Text = "Hmph, was gibt es daran zu ändern?"
  },
  AvgCommunicate_70502_Content_7 = {
    Text = "Ich habe bereits zehntausend Mal nachgegeben! Jetzt befehle ich nur noch diesen Sklaven im Labyrinth."
  },
  AvgCommunicate_70502_Content_8 = {
    Text = "Hast du keine Angst, diese Dinge jetzt zu erinnern?"
  },
  AvgCommunicate_70502_Content_9 = {
    Text = "In der Tat. Was gibt es zu fürchten!"
  },
  AvgCommunicate_70502_Option_16 = {
    Text = "Dann werde ich auch Uvhash rufen."
  },
  AvgCommunicate_70502_Option_5 = {
    Text = "Wann wirst du deinen Ton ändern..."
  },
  AvgCommunicate_70502_Option_8 = {
    Text = "Hast du keine Angst, diese Dinge jetzt zu erinnern?"
  },
  AvgCommunicate_70503_Content_1 = {
    Text = "Der Vorfall, der in der Kirche stattfand... Wäre es nicht gewesen, wären mehr unschuldige Menschen verletzt worden..."
  },
  AvgCommunicate_70503_Content_10 = {
    Text = "Aber jetzt ist sie die aktuelle Anführerin der Tempellicht-Kirche."
  },
  AvgCommunicate_70503_Content_11 = {
    Text = "Was? Die Anführerin der Tempellicht-Kirche?!!!"
  },
  AvgCommunicate_70503_Content_12 = {
    Text = "In religiösen Kreisen ist die Tempellicht-Kirche die größte Feindin Ihrer Kirche ... Wie konnte Ihr Schüler nur ..."
  },
  AvgCommunicate_70503_Content_13 = {
    Text = "Eine lange Geschichte, Bote."
  },
  AvgCommunicate_70503_Content_14 = {
    Text = "Sie arbeitete einmal mit mir für die Sache des Vater Gottes und widmete alles, was wir hatten, dem Volk des Vater Gottes."
  },
  AvgCommunicate_70503_Content_15 = {
    Text = "Aber, wie du sehen kannst, ist es nicht so einfach für die Abtrünnigen, sich vom Vater Gott abzuwenden. Diese Gräueltaten und Vorurteile können nicht einfach mit ein wenig Segnen beseitigt werden."
  },
  AvgCommunicate_70503_Content_16 = {
    Text = "Weil sie aufgrund der Prüfungen, die ich durchgemacht habe, einen Weg eingeschlagen hat, von dem es schwierig sein würde, zurückzukehren."
  },
  AvgCommunicate_70503_Content_17 = {
    Text = "So ist es also..."
  },
  AvgCommunicate_70503_Content_18 = {
    Text = "Ich verstehe. Genau wie das, was zuvor in der Kirche passiert ist, diejenigen, die sich aufgrund deiner guten Taten nicht verändert haben, verursachten ihre Transformation..."
  },
  AvgCommunicate_70503_Content_19 = {
    Text = "Der Vater Gott lehrte uns einst, dass die Dinge in dieser Welt nicht immer schwarz und weiß sind. Gute Taten können manchmal auch ein Fehler sein."
  },
  AvgCommunicate_70503_Content_2 = {
    Text = "Im Namen der Kirche und der unschuldigen Überlebenden spreche ich dir, dem Blassen Boten, meinen aufrichtigen Dank aus."
  },
  AvgCommunicate_70503_Content_20 = {
    Text = "Ich habe alles den Opfern gewidmet, aber ich habe vergessen, dass mein Schüler auch einer von ihnen ist."
  },
  AvgCommunicate_70503_Content_21 = {
    Text = "Die Kirche und mein Glauben mögen vielen Menschen das Leben gerettet haben, aber sie konnten sie nicht retten."
  },
  AvgCommunicate_70503_Content_22 = {
    Text = "Ich bin kein qualifizierter Lehrer, Bote."
  },
  AvgCommunicate_70503_Content_23 = {
    Text = "Ich werde weiterhin den Weg des Vaters Gottes gehen. Aber ich frage mich, ob ich jemals die Chance haben werde, dieses Bedauern gegenüber diesem Schüler wieder gutzumachen..."
  },
  AvgCommunicate_70503_Content_3 = {
    Text = "Gern geschehen, Bischof Salvador. Es gehört alles zu meinen Pflichten."
  },
  AvgCommunicate_70503_Content_4 = {
    Text = "Bischof, bezüglich deiner Vergangenheit gibt es eine Frage, die ich dir stellen möchte..."
  },
  AvgCommunicate_70503_Content_5 = {
    Text = "Sprich ohne Vorbehalte, Gesandter."
  },
  AvgCommunicate_70503_Content_6 = {
    Text = "Meine Vergangenheit wird für jede Person unter dem Schutz der Vatergötter offen sein."
  },
  AvgCommunicate_70503_Content_7 = {
    Text = "Als ich mich mit dir verband, sah ich neben Sophia eine Frau, die ein Gespräch mit dir führte."
  },
  AvgCommunicate_70503_Content_8 = {
    Text = "Diese Erinnerung nimmt einen großen Teil deines Geistes ein... Seid ihr alle sehr damit vertraut?"
  },
  AvgCommunicate_70503_Content_9 = {
    Text = "In der Tat, sehr vertraut. Einst war sie meine herausragendste Schülerin."
  },
  AvgCommunicate_70503_Option_11 = {
    Text = "Die Anführerin der Tempellicht-Kirche?!"
  },
  AvgCommunicate_70503_Option_17 = {
    Text = "So ist es also..."
  },
  AvgCommunicate_70503_Option_3 = {
    Text = "Es ist alles, was ich tun sollte."
  },
  AvgCommunicate_70503_Option_7 = {
    Text = "Wer ist die letzte Frau, die in deiner Erinnerung erschien?"
  },
  AvgCommunicate_70504_Content_1 = {
    Text = "Hattest du last Nacht einen angenehmen Aufenthalt, lieber Gast?"
  },
  AvgCommunicate_70504_Content_10 = {
    Text = "Sei unbesorgt, ich habe eine Vereinbarung mit einem bestimmten Herrn getroffen und werde keine empörenden Maßnahmen ergreifen."
  },
  AvgCommunicate_70504_Content_11 = {
    Text = "Integrität ist sehr wichtig für einen Händler."
  },
  AvgCommunicate_70504_Content_12 = {
    Text = "Außerdem hast du nicht weniger Geheimnisse als ich, oder?"
  },
  AvgCommunicate_70504_Content_13 = {
    Text = "Was ist mein Geheimnis? Worauf bezieht es sich?"
  },
  AvgCommunicate_70504_Content_14 = {
    Text = "Jetzt ist nicht die Zeit. Aber sei versichert, der Handel mit dem neuen Geheimnis wird bald beginnen."
  },
  AvgCommunicate_70504_Content_15 = {
    Text = "Der Wind und der Schnee auf dem Weg sind wilder, als du dir vorstellen kannst."
  },
  AvgCommunicate_70504_Content_16 = {
    Text = "Solange Zeit ist, genieße die Wärme des Kamins, Kleines."
  },
  AvgCommunicate_70504_Content_2 = {
    Text = "Ein so warmes kleines Geschäft ist an stürmischen, schneereichen Tagen wirklich selten. Ich danke dir für deine Gastfreundschaft, Frau Davendale."
  },
  AvgCommunicate_70504_Content_3 = {
    Text = "Aber es scheint, dass dein Laden viele Geheimnisse verbirgt."
  },
  AvgCommunicate_70504_Content_4 = {
    Text = "Diese Sammlerstücke sind wahrscheinlich nicht so einfach, wie sie erscheinen."
  },
  AvgCommunicate_70504_Content_5 = {
    Text = "Sehr scharfe Beobachtung. Doch das Eindringen in die Geheimnisse anderer ist kein gentlemanhaftes Verhalten!"
  },
  AvgCommunicate_70504_Content_6 = {
    Text = "Es tut mir leid, Frau Narzisse."
  },
  AvgCommunicate_70504_Content_7 = {
    Text = "Wir sind an diesen unbekannten Ort für eine Ermittlung gekommen und müssen zunächst unsere Sicherheit gewährleisten."
  },
  AvgCommunicate_70504_Content_8 = {
    Text = "Ich hoffe, du kannst verstehen."
  },
  AvgCommunicate_70504_Content_9 = {
    Text = "Natürlich. Wenn man in einem fremden Haus rücksichtslos einschlafen könnte, dann ist die Ausbildung der Hüter in Mythag offensichtlich unzureichend."
  },
  AvgCommunicate_70504_Option_13 = {
    Text = "Mein Geheimnis?"
  },
  AvgCommunicate_70504_Option_2 = {
    Text = "Es scheinen viele Geheimnisse hier zu sein."
  },
  AvgCommunicate_70504_Option_6 = {
    Text = "Es tut mir leid, aber ich muss die Sicherheit der Operation gewährleisten."
  },
  AvgCommunicate_70505_Content_1 = {
    Text = "Miryam, die einst mein vertrauenswürdigster Hohepriester war."
  },
  AvgCommunicate_70505_Content_10 = {
    Text = "Ich trage die Verantwortung für die Seefahrer."
  },
  AvgCommunicate_70505_Content_11 = {
    Text = "Niemand hätte die Entwicklung der Situation vorhersehen können; das sollte nicht als Verbrechen bezeichnet werden."
  },
  AvgCommunicate_70505_Content_12 = {
    Text = "Was du getan hast, war die beste Entscheidung in diesem Moment."
  },
  AvgCommunicate_70505_Content_13 = {
    Text = "Es ist nicht deine Schuld, Tulu."
  },
  AvgCommunicate_70505_Content_14 = {
    Text = "Vielleicht. Aber du hast diese Angelegenheit persönlich gelöst."
  },
  AvgCommunicate_70505_Content_15 = {
    Text = "Niemand hätte den Verlauf der Ereignisse vorhersehen können."
  },
  AvgCommunicate_70505_Content_16 = {
    Text = "Auch wenn es Fehler gab, hast du sie korrigiert."
  },
  AvgCommunicate_70505_Content_17 = {
    Text = "Du hast deine Pflicht als König von Lemuria erfüllt, Tulu."
  },
  AvgCommunicate_70505_Content_18 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_70505_Content_19 = {
    Text = "Die tröstenden Worte sind etwas ungeschickt, aber ich akzeptiere sie."
  },
  AvgCommunicate_70505_Content_2 = {
    Text = "Sie und ich haben einmal eine kurze Blütezeit in Lemuria gebracht."
  },
  AvgCommunicate_70505_Content_20 = {
    Text = "Ich muss mich jetzt ausruhen."
  },
  AvgCommunicate_70505_Content_21 = {
    Text = "Zur rechten Zeit werde ich erwachen."
  },
  AvgCommunicate_70505_Content_22 = {
    Text = "Meine Pflicht liegt nicht nur in Lemuria, sondern auch in Mythag."
  },
  AvgCommunicate_70505_Content_3 = {
    Text = "Sie und die Menschen von Lemuria glauben alle daran, dass ich Lemuria das göttliche Reich der Herrlichkeit zurückbringen werde."
  },
  AvgCommunicate_70505_Content_4 = {
    Text = "Aber... das ist eine Lüge, oder?"
  },
  AvgCommunicate_70505_Content_5 = {
    Text = "Im Traum erhielt ich eine Offenbarung."
  },
  AvgCommunicate_70505_Content_6 = {
    Text = "Das Ende von Lemuria ist unausweichlich."
  },
  AvgCommunicate_70505_Content_7 = {
    Text = "Von Anfang an lebte Lemuria in Lügen."
  },
  AvgCommunicate_70505_Content_8 = {
    Text = "Ich band Lemuria und Miryam mit Lügen."
  },
  AvgCommunicate_70505_Content_9 = {
    Text = "Ich habe nie gedacht, dass diese Lüge viele Jahre später zu solchen Konsequenzen führen würde."
  },
  AvgCommunicate_70505_Option_11 = {
    Text = "Niemand hätte es vorhersehen können; das sollte nicht als Sünde bezeichnet werden."
  },
  AvgCommunicate_70505_Option_14 = {
    Text = "Das Problem wurde von deinen eigenen Händen gelöst."
  },
  AvgCommunicate_70505_Option_4 = {
    Text = "Aber... das ist eine Lüge, oder?"
  },
  AvgCommunicate_70506_Content_1 = {
    Text = "Dein Seil ist nicht sicher gebunden."
  },
  AvgCommunicate_70506_Content_10 = {
    Text = "Außerdem ist Töten nur ein Mittel, nicht das Ziel."
  },
  AvgCommunicate_70506_Content_11 = {
    Text = "Du solltest mehr über deine eigenen Angelegenheiten nachdenken."
  },
  AvgCommunicate_70506_Content_12 = {
    Text = "Was ich tun möchte, ist nicht dein Anliegen."
  },
  AvgCommunicate_70506_Content_13 = {
    Text = "Du hast einen Trumpf im Ärmel."
  },
  AvgCommunicate_70506_Content_14 = {
    Text = "Dieser Kurze... er wird Miryam sicher verrückt machen, haha."
  },
  AvgCommunicate_70506_Content_15 = {
    Text = "Gib dein Bestes, Hüter von Mythag."
  },
  AvgCommunicate_70506_Content_16 = {
    Text = "Ich bin neugierig, wie weit du meinen geschätzten hohen Priester treiben kannst."
  },
  AvgCommunicate_70506_Content_2 = {
    Text = "Sei vorsichtig, dass du nicht bemerkt wirst."
  },
  AvgCommunicate_70506_Content_3 = {
