  AvgCommunicate_70506_Content_5 = {
    Text = "Sehe ich aus wie jemand mit einem guten Herzen?"
  },
  AvgCommunicate_70506_Content_6 = {
    Text = "Du solltest mehr über deine eigenen Angelegenheiten nachdenken."
  },
  AvgCommunicate_70506_Content_7 = {
