  AvgCommunicate_70507_Content_1 = {
    Text = "Ich... fühle mich ein bisschen müde..."
  },
  AvgCommunicate_70507_Content_10 = {
    Text = "Der Schmerz in dir... wird ab diesem Punkt auch verschwinden."
  },
  AvgCommunicate_70507_Content_11 = {
    Text = "So nett, Mythag..."
  },
  AvgCommunicate_70507_Content_12 = {
    Text = "Hmm, ich will nicht nachdenken. Ich will an nichts mehr denken."
  },
  AvgCommunicate_70507_Content_13 = {
    Text = "Ich habe beschlossen, Hüter."
  },
  AvgCommunicate_70507_Content_14 = {
    Text = "Was hast du herausgefunden?"
  },
  AvgCommunicate_70507_Content_15 = {Text = "Nichts..."},
  AvgCommunicate_70507_Content_16 = {
    Text = "Der kleine Kuchen von Mythag, du wirst mich mitnehmen, um ihn zu probieren, oder?"
  },
  AvgCommunicate_70507_Content_17 = {
    Text = "Mach dir keine Sorgen, Murphy. Ich werde dich auf jeden Fall zurückbringen!"
  },
  AvgCommunicate_70507_Content_2 = {
    Text = "Murphy, hat sich die Situation wieder verschlechtert?!"
  },
  AvgCommunicate_70507_Content_3 = {
