  },
  AvgCommunicate_70507_Content_4 = {
    Text = "Ich habe Lust auf ein paar Cupcakes..."
  },
  AvgCommunicate_70507_Content_5 = {
    Text = "Einmal machte jemand mir jeden Tag kleine Kuchen, aber seit ich das Schiff bestiegen habe, gab es keine mehr."
  },
  AvgCommunicate_70507_Content_6 = {
    Text = "Miryam hat sich verändert. Goliath hat sich verändert. Diese Seefahrer haben sich ebenfalls verändert."
