  AvgCommunicate_70507_Content_7 = {
    Text = "Ich habe dich erst gerade kennengelernt, aber du bist die Einzigen, die mir helfen und an meiner Seite stehen werden..."
  },
  AvgCommunicate_70507_Content_8 = {
    Text = "Du solltest dich ausruhen und nicht über diese Dinge nachdenken, Murphy."
  },
  AvgCommunicate_70507_Content_9 = {
    Text = "Wenn du in Mythag ankommst, wird es alles, was du essen möchtest, im Überfluss geben."
  },
  AvgCommunicate_70507_Option_14 = {
