  AvgCommunicate_70507_Option_17 = {
    Text = "Sicherlich!"
  },
  AvgCommunicate_70507_Option_2 = {Text = "Murphy?!"},
  AvgCommunicate_70507_Option_8 = {
    Text = "Denk vorerst nicht an solche Dinge"
  },
  AvgCommunicate_70508_Content_1 = {
    Text = "Danke für die Angelegenheit bezüglich des Wachsmuseums."
  },
  AvgCommunicate_70508_Content_10 = {
    Text = "Herzlichen Glückwunsch, du hast diese Angelegenheit vollständig gelöst."
  },
  AvgCommunicate_70508_Content_11 = {
    Text = "Als du in der Schule warst, war deine Gesamtfähigkeit weniger ideal."
  },
  AvgCommunicate_70508_Content_12 = {
    Text = "Aber in diesen zwei Ereignissen hast du außergewöhnlich hervorragende Fähigkeiten gezeigt."
  },
  AvgCommunicate_70508_Content_13 = {
    Text = "Auch ohne ein einzigartiges Talent in Geisterkraft bist du immer noch ein herausragender Ermittler."
  },
  AvgCommunicate_70508_Content_14 = {
    Text = "Es ist ein Segen, mit einem solchen Kameraden zusammenzuarbeiten."
  },
  AvgCommunicate_70508_Content_15 = {
    Text = "Du auch, Senior William."
