  AvgCommunicate_70508_Content_8 = {
    Text = "Was ich gesagt habe, ist wahr!"
  },
  AvgCommunicate_70508_Content_9 = {
    Text = "Zusammenfassend."
  },
  AvgCommunicate_70508_Option_15 = {Text = "Ebenso"},
  AvgCommunicate_70508_Option_2 = {
