  },
  AvgCommunicate_70509_Content_1 = {Text = "Hüter..."},
  AvgCommunicate_70509_Content_10 = {
    Text = "Sie ist im Kampf. Kämpft endlos..."
  },
  AvgCommunicate_70509_Content_11 = {
    Text = "Die Kraft des Schneebergs hat denselben Ursprung wie wir. Sie sucht danach, uns zu verschlingen."
  },
  AvgCommunicate_70509_Content_12 = {
    Text = "Sie und ich standen auf einer Seite. Unsere Kräfte verschmolzen..."
  },
  AvgCommunicate_70509_Content_13 = {Text = "Und dann?"},
  AvgCommunicate_70509_Content_14 = {Text = "Dann..."},
  AvgCommunicate_70509_Content_15 = {
    Text = "Wir haben den Schneeberg verschlungen."
  },
  AvgCommunicate_70509_Content_16 = {Text = "!!!"},
  AvgCommunicate_70509_Content_17 = {
    Text = "Ich sagte, dass ich Ihn besiegen würde."
  },
  AvgCommunicate_70509_Content_18 = {
    Text = "Ein Krieger geht niemals von seinem Wort zurück. Du bist ein wahrer Krieger, Helot!"
  },
  AvgCommunicate_70509_Content_19 = {
    Text = "Ich werde bald zurück sein. Bitte bereite Lotan vor, Hüter."
  },
  AvgCommunicate_70509_Content_2 = {Text = "Helot?!"},
  AvgCommunicate_70509_Content_20 = {
    Text = "Ich habe die mächtige Wurzel eines Kriegers gefunden. Ich habe meinen Glauben gefunden."
  },
  AvgCommunicate_70509_Content_21 = {
    Text = "Ich bin dankbar für die Worte, die du einmal zu mir gesagt hast, und für die Dinge, die du für mich getan hast."
  },
  AvgCommunicate_70509_Content_22 = {
    Text = "Im Gegenzug werde ich sie die Macht vom Schneeberg erleben lassen."
