  AvgCommunicate_70509_Content_23 = {
    Text = "Deine Art, Dankbarkeit zu zeigen, ist ein wenig seltsam... Aber Lotan sollte sehr glücklich darüber sein."
  },
  AvgCommunicate_70509_Content_24 = {
    Text = "Kurz gesagt, willkommen zurück, Helot!"
  },
  AvgCommunicate_70509_Content_3 = {
    Text = "Ich sah das Eis und den Schnee von Elworth schmelzen, mit einem Löwenzahn, der dort aus dem Schneeberg wuchs..."
