  AvgCommunicate_70510_Content_14 = {Text = "Erica?!"},
  AvgCommunicate_70510_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_70510_Content_16 = {
    Text = "Es tut mir leid, Schutzherr. Das Geistunterdrückungsgerät hat gerade eine Fehlfunktion gehabt."
  },
  AvgCommunicate_70510_Content_17 = {
    Text = "Diese Persönlichkeit bleibt die gleiche, ein wenig verrückt und unberechenbar..."
  },
  AvgCommunicate_70510_Content_18 = {
    Text = "Geht es dir gut?"
  },
  AvgCommunicate_70510_Content_19 = {
    Text = "Danke für deine Sorge, Hüter."
  },
  AvgCommunicate_70510_Content_2 = {
    Text = "Erica? Gibt es heute eine weitere Testeinladung?"
  },
  AvgCommunicate_70510_Content_20 = {
    Text = "Professorin Doll hat unterstützende Überwachungs- und automatische Reparaturgeräte in mich eingebaut, und die Fehlfunktion wurde erfolgreich behoben."
  },
  AvgCommunicate_70510_Content_21 = {
    Text = "Es freut mich zu hören, dass es dir gut geht."
  },
  AvgCommunicate_70510_Content_22 = {
    Text = "Die Persönlichkeit hat eine Theorie der mechanischen Evolution erwähnt, die extrem und einseitig ist."
  },
  AvgCommunicate_70510_Content_23 = {
    Text = "In gewisser Weise kann dies als eine Art böser Glaube betrachtet werden."
  },
  AvgCommunicate_70510_Content_24 = {
    Text = "Die Persönlichkeit hat eine Theorie der mechanischen Evolution erwähnt, obwohl sie etwas extrem und einseitig war."
  },
  AvgCommunicate_70510_Content_25 = {
    Text = "Aber in gewisser Weise ist es tatsächlich ein Weg, der Auflösung entgegenzuwirken."
  },
  AvgCommunicate_70510_Content_26 = {
    Text = "Allerdings wird dies viele technische und ethische Fragen aufwerfen..."
  },
  AvgCommunicate_70510_Content_27 = {
    Text = "Es gibt keine entsprechenden Einträge in meiner Datenbank, daher kann ich keine hilfreichen Referenzmeinungen liefern."
  },
  AvgCommunicate_70510_Content_28 = {
    Text = "Ob dieser Ansatz gültig ist, muss von dir beurteilt werden, Schutzherr."
  },
  AvgCommunicate_70510_Content_3 = {
    Text = "Testeinladung... Man könnte es wohl so nennen."
  },
  AvgCommunicate_70510_Content_4 = {
    Text = "Aber nicht diese belanglosen kleinen Experimente."
  },
  AvgCommunicate_70510_Content_5 = {
    Text = "Sondern eine große Erfindung, die unsere Umstände wahrhaft verändern kann."
  },
  AvgCommunicate_70510_Content_6 = {
    Text = "Ihr habt gegen die schwarze Substanz gekämpft, doch in Wahrheit lag die Lösung die ganze Zeit direkt vor euch."
  },
  AvgCommunicate_70510_Content_7 = {
    Text = "Worüber redest du..."
