  AvgCommunicate_70511_Content_1 = {
    Text = "Herrscher... es gibt etwas, das ich Sie fragen möchte..."
  },
  AvgCommunicate_70511_Content_10 = {
    Text = "Wenn ich und die Prinzessin gleichzeitig in Gefahr geraten würden, wen würdest du zuerst retten?"
  },
  AvgCommunicate_70511_Content_11 = {
    Text = "Herr... Herrscher... das... ich..."
  },
  AvgCommunicate_70511_Content_12 = {
    Text = "Okay, okay... es ist meine Schuld, ich hätte dich nicht so aufziehen sollen."
  },
  AvgCommunicate_70511_Content_13 = {
    Text = "Ich weiß, du bist ein pflichtbewusster Ritter, der deinen Schwur auch in jeder Gefahr bewahrst."
  },
  AvgCommunicate_70511_Content_14 = {
    Text = "Die Erlebnisse in diesem Traum haben mir dabei geholfen, dich besser zu verstehen."
  },
  AvgCommunicate_70511_Content_15 = {
    Text = "Danke... Danke, Herrscher..."
  },
  AvgCommunicate_70511_Content_16 = {
    Text = "Ich trainiere jetzt jeden Tag. Ich werde ein qualifizierter Ritter, der in der Lage ist, meinen Herrn zu beschützen, und ich werde nie wieder zulassen, dass so etwas wie damals geschieht!"
  },
  AvgCommunicate_70511_Content_17 = {
    Text = "Also, mein Herr... kann ich wirklich nicht in der Schule Reitkünste üben..."
  },
  AvgCommunicate_70511_Content_18 = {Text = "Nein!"},
  AvgCommunicate_70511_Content_19 = {
    Text = "Allerdings gibt es eine neue Pferderennbahn, die gerade im Westbezirk eröffnet wurde... Wie wäre es, wenn ich dich dieses Wochenende dorthin mitnehme?"
  },
  AvgCommunicate_70511_Content_2 = {
    Text = "Ogier, auch wenn du dich normalerweise sehr gut schlägst, verbietet Missaga das Reiten innerhalb des Campusgeländes, geschweige denn das Üben von Sprintreitkünsten..."
  },
  AvgCommunicate_70511_Content_20 = {Text = "!!!"},
  AvgCommunicate_70511_Content_21 = {
    Text = "Danke, mein Herr!!!"
  },
  AvgCommunicate_70511_Content_3 = {
    Text = "Sie haben mich missverstanden, Herrscher! Ich wollte Sie bezüglich des Traums etwas fragen..."
  },
  AvgCommunicate_70511_Content_4 = {
    Text = "Bezieht sich das auf den „Traum\", den ich hatte?"
  },
  AvgCommunicate_70511_Content_5 = {
    Text = "Ja, Herrscher!"
  },
  AvgCommunicate_70511_Content_6 = {
    Text = "Ich möchte wissen, was Sie in diesem Traum tatsächlich gesehen haben."
  },
  AvgCommunicate_70511_Content_7 = {
    Text = "Ich sah eine Katastrophe, eine gütige Prinzessin und einen mutigen, standhaften kleinen Ritter."
  },
  AvgCommunicate_70511_Content_8 = {
    Text = "Ich habe auch eine Frage, die ich dir stellen möchte."
  },
  AvgCommunicate_70511_Content_9 = {
    Text = "Herrscher, bitte sprechen Sie."
  },
  AvgCommunicate_70511_Option_10 = {
