  },
  AvgCommunicate_70511_Option_13 = {
    Text = "Ich weiß, du bist ein pflichtbewusster Ritter"
  },
  AvgCommunicate_70511_Option_18 = {Text = "Nein!"},
  AvgCommunicate_70511_Option_2 = {
    Text = "Was das Reiten auf dem Schulhof angeht?"
  },
  AvgCommunicate_70511_Option_4 = {
    Text = "Über den „Traum“?"
  },
  AvgCommunicate_70512_Content_1 = {
    Text = "Seit Lengwashi ist es lange her, Geheimnisträger {Male=Herr,Female=Frau}."
  },
  AvgCommunicate_70512_Content_10 = {
    Text = "Der verfallende Zerfall dieser Welt ist etwas, das ihr verwöhnten Menschen niemals verstehen werdet."
  },
  AvgCommunicate_70512_Content_11 = {
    Text = "Der höchste Wille, das ursprüngliche Relikt, wird ultimativen Purifikation in die Welt bringen."
  },
  AvgCommunicate_70512_Content_12 = {
    Text = "Ich habe nicht die Absicht, Mythag ins Visier zu nehmen, aber Mythag blockiert den Weg zur Ankunft der Neuen Welt."
  },
  AvgCommunicate_70512_Content_13 = {
    Text = "Seid unbesorgt, {Male=Mr.,Female=Miss} Schutzherr, mein Herr wird Euch deswegen nicht verstoßen."
  },
  AvgCommunicate_70512_Content_14 = {
    Text = "Du wirst auch ein Mitglied der neuen Welt werden."
  },
  AvgCommunicate_70512_Content_15 = {
    Text = "Er wird dir all die brandneue Zukunft zeigen."
  },
  AvgCommunicate_70512_Content_16 = {
    Text = "In diesem Moment wird er deine aufrichtigen Geständnisse hören."
  },
  AvgCommunicate_70512_Content_17 = {
    Text = "Darauf kannst du dich verlassen, Juliette."
  },
  AvgCommunicate_70512_Content_18 = {
    Text = "Dein Meister wird keine Chance haben, zu erscheinen."
  },
  AvgCommunicate_70512_Content_19 = {
    Text = "Ich werde dich aufhalten. Auf jeden Fall!"
  },
  AvgCommunicate_70512_Content_2 = {
    Text = "Juliette... Was genau willst du erreichen, indem du Mythag eindringst?!"
  },
  AvgCommunicate_70512_Content_3 = {
    Text = "In Lemwashi habe ich dir das bereits gesagt."
  },
  AvgCommunicate_70512_Content_4 = {
    Text = "Unser Gott wird eine bessere Zukunft für die Welt schaffen."
  },
  AvgCommunicate_70512_Content_5 = {
    Text = "Erinnerst du dich, Hüter?"
  },
  AvgCommunicate_70512_Content_6 = {
    Text = "Natürlich werde ich diese wichtige Information nicht vergessen."
  },
  AvgCommunicate_70512_Content_7 = {
    Text = "Was hat das mit Mythag zu tun?"
  },
  AvgCommunicate_70512_Content_8 = {
    Text = "Ich erinnere mich nicht an die verführerischen Worte des Feindes."
  },
  AvgCommunicate_70512_Content_9 = {
    Text = "Ich habe viele hoffnungslos starrköpfige Menschen gesehen, und ich bin nicht überrascht."
  },
  AvgCommunicate_70512_Option_17 = {
    Text = "Ich werde dich aufhalten."
  },
  AvgCommunicate_70512_Option_2 = {
    Text = "Was möchtest du tun?!"
  },
  AvgCommunicate_70512_Option_6 = {
    Text = "Ich erinnere mich"
  },
  AvgCommunicate_70512_Option_8 = {
    Text = "Ich erinnere mich nicht an die hinterhältigen Worte des Feindes"
  },
  AvgCommunicate_70513_Content_1 = {
    Text = "Ich ging dem Klang der Flöte nach, die du gehört hast, während du bewusstlos warst."
  },
  AvgCommunicate_70513_Content_10 = {
    Text = "Ich weiß nicht, ob ich deinen Optimismus loben oder deine Ignoranz kritisieren soll."
  },
  AvgCommunicate_70513_Content_11 = {
    Text = "Was Tawil konkret erwähnt, ist normalerweise eine Katastrophe."
  },
  AvgCommunicate_70513_Content_12 = {
    Text = "Die schlimmste Art."
  },
  AvgCommunicate_70513_Content_13 = {
    Text = "Da es bereits geschehen ist... lass uns einen Moment zur Selbstberuhigung nehmen."
  },
  AvgCommunicate_70513_Content_14 = {
    Text = "Kurz gesagt, ich werde weiterhin diese Angelegenheit untersuchen."
  },
  AvgCommunicate_70513_Content_15 = {
    Text = "Es hat derzeit keine wesentlichen Auswirkungen auf dich, also gibt es keinen Grund, sich vorerst darum zu sorgen."
