  AvgCommunicate_70514_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} Schutzherr, der Verlag hat mir einen Brief geschickt."
  },
  AvgCommunicate_70514_Content_10 = {
    Text = "Es ist unter ihrem Schutz, dass ich unbeschwert in der Welt der Blumen und der Poesie wandern kann."
  },
  AvgCommunicate_70514_Content_11 = {
    Text = "Diese Schutzmaßnahmen und Schäden gehören jetzt alle der Vergangenheit an..."
  },
  AvgCommunicate_70514_Content_12 = {
    Text = "Hüter, danke, dass du mich dieses Mal nach Cité gebracht hast... Diese Reise ist mir sehr wichtig."
  },
  AvgCommunicate_70514_Content_13 = {
    Text = "Das ist korrekt. Alles aus deiner Vergangenheit mit Corrette liegt nun hinter dir."
  },
  AvgCommunicate_70514_Content_14 = {
    Text = "Schau nach vorne, Horla."
  },
  AvgCommunicate_70514_Content_15 = {
    Text = "In Ordnung, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgCommunicate_70514_Content_16 = {
    Text = "Diese Gedichtsammlung ist mein Abschied von der Vergangenheit."
  },
  AvgCommunicate_70514_Content_17 = {
    Text = "Ich werde Colette in ihrer Jugend erinnern. Ich werde Colette im Alter erinnern. Ich werde sie auch loslassen..."
  },
  AvgCommunicate_70514_Content_18 = {
    Text = "Es gibt neue Leben und neue Gedichte, die auf mich warten."
  },
  AvgCommunicate_70514_Content_2 = {
    Text = "Sie gratulierten mir und sagten, dass diese Sammlung von Gedichten hervorragende Ergebnisse erzielt hat."
  },
  AvgCommunicate_70514_Content_3 = {
    Text = "Herzlichen Glückwunsch, Horla!"
  },
  AvgCommunicate_70514_Content_4 = {
    Text = "Danke, Hüter."
