  AvgCommunicate_70514_Content_5 = {
    Text = "In der Vergangenheit war Colette für all diese Angelegenheiten verantwortlich."
  },
  AvgCommunicate_70514_Content_6 = {
    Text = "Schon immer war sie diejenige, die diesen Teil getragen hat."
  },
  AvgCommunicate_70514_Content_7 = {
    Text = "In meiner Erinnerung ist das das erste Mal, dass ich gesehen habe, dass du dich um den Verkauf sorgst."
