  AvgCommunicate_70515_Content_1 = {
    Text = "Ich habe mich gerade im Wachsfigurenkabinett umgesehen... Es ist wirklich ein Chaos."
  },
  AvgCommunicate_70515_Content_10 = {
    Text = "Um diesen verrückten Hunden aus dem Ausschuss zu entkommen, habe ich mein Spiel lange nicht gespielt..."
  },
  AvgCommunicate_70515_Content_11 = {
    Text = "Du könntest in Mythag zusammen mit Rogers überlegen, aufzugeben."
  },
  AvgCommunicate_70515_Content_12 = {
    Text = "Du solltest die Konsequenzen wissen, wenn du vom Ausschuss erwischt wirst."
  },
  AvgCommunicate_70515_Content_13 = {
    Text = "Dein Mund weiß sicherlich, wie man täuscht, Liebling."
  },
  AvgCommunicate_70515_Content_14 = {
    Text = "Aber, ich hatte viel Spaß, mit euch allen im Wachsfigurenkabinett zu spielen."
  },
  AvgCommunicate_70515_Content_15 = {
    Text = "Vielleicht werde ich ernsthaft darüber nachdenken."
  },
  AvgCommunicate_70515_Content_16 = {
    Text = "Vielleicht gibt es noch einen Tag des Wiedersehens. Ich freue mich darauf, {Male=Mr.,Female=Miss} Schutzherr～"
  },
  AvgCommunicate_70515_Content_2 = {
    Text = "Du weißt wirklich nicht, wie man schätzt!"
  },
  AvgCommunicate_70515_Content_3 = {Text = "Pandia?"},
  AvgCommunicate_70515_Content_4 = {
    Text = "Wohin sind du und Rogers gegangen?"
  },
  AvgCommunicate_70515_Content_5 = {
    Text = "Was, denkst du an die Peitsche von jemandem?"
  },
  AvgCommunicate_70515_Content_6 = {
