  AvgCommunicate_70516_Content_11 = {
    Text = "Hast du so wenig Vertrauen in deinen Partner?"
  },
  AvgCommunicate_70516_Content_12 = {
    Text = "Mach dir keine Sorgen, ich schließe mich dir an, nachdem ich hier drüben alles geregelt habe."
  },
  AvgCommunicate_70516_Content_13 = {
    Text = "Ihr Zustand ist gerade jetzt am gefährlichsten; Sie müssen vorsichtig sein, %player%..."
  },
  AvgCommunicate_70516_Content_2 = {
    Text = "Ramona?! Geht es dir gut?"
  },
  AvgCommunicate_70516_Content_3 = {
    Text = "Hmm, mir geht's gut."
  },
  AvgCommunicate_70516_Content_4 = {
    Text = "Ich bin gerade ein paar Mitgliedern des Ausschusses begegnet, und ich habe mich bereits darum gekümmert."
  },
  AvgCommunicate_70516_Content_5 = {
    Text = "Ich wollte herkommen und mich dir anschließen, aber ich sah eine Gruppe von Ausschussmitgliedern auf das Lehrgebäude zusteuern..."
  },
  AvgCommunicate_70516_Content_6 = {
    Text = "Viele Lehrer und Schüler sind dort im Unterricht; ich mache mir Sorgen, dass die Leute des Ausschusses ihnen schaden könnten."
  },
  AvgCommunicate_70516_Content_7 = {
    Text = "Ich muss sie an einen sicheren Ort eskortieren."
  },
  AvgCommunicate_70516_Content_8 = {
    Text = "Ich habe mich gerade mit Clementine konfrontiert; ich werde mich um die Angelegenheiten hier kümmern."
  },
  AvgCommunicate_70516_Content_9 = {
    Text = "Ich werde das Lehrgebäude dir überlassen."
  },
  AvgCommunicate_70516_Option_2 = {
    Text = "Ramona?! Geht es dir gut?"
  },
  AvgCommunicate_70516_Option_8 = {
    Text = "Pass auf dich auf, Ramona!"
  },
  AvgCommunicate_70517_Content_1 = {
    Text = "Öde. Pedantisch. Mangelnd an der Leidenschaft, die das Leben haben sollte..."
  },
  AvgCommunicate_70517_Content_10 = {
    Text = "Du, genau wie damals, kümmerst dich immer noch so sehr um die Regeln."
