  AvgCommunicate_70517_Content_11 = {
    Text = "Es ist in Ordnung, ich habe bereits die Schulaula gemietet."
  },
  AvgCommunicate_70517_Content_12 = {
    Text = "Die Halle mieten? Warum?"
  },
  AvgCommunicate_70517_Content_13 = {
    Text = "Weil der Mythag-Schulvorstand mit meiner Entscheidung, sie zu kaufen, nicht einverstanden war."
  },
  AvgCommunicate_70517_Content_14 = {
    Text = "Es scheint, dass Sie meine Frage missverstanden haben..."
  },
  AvgCommunicate_70517_Content_15 = {
    Text = "Es spielt keine Rolle. Morgen Abend werde ich ein Festmahl im Saal ausrichten."
  },
  AvgCommunicate_70517_Content_16 = {
    Text = "Ein leidenschaftliches, neuartiges und wirklich lebendiges Festmahl, erfüllt mit der Vitalität des Lebens, genau wie die in einem alten Schloss."
  },
  AvgCommunicate_70517_Content_17 = {
    Text = "Die Artikel, die vorbereitet werden müssen, sind jetzt vollständig bereit."
  },
  AvgCommunicate_70517_Content_18 = {
    Text = "Ich habe bereits die Hindernisse, die die Regeln darstellen, im Voraus umgangen. Niemand wird uns stören."
  },
  AvgCommunicate_70517_Content_19 = {
    Text = "Kannst du den Weg zur Halle finden, Hüter?"
  },
  AvgCommunicate_70517_Content_2 = {
    Text = "Worüber redest du..."
  },
  AvgCommunicate_70517_Content_3 = {
    Text = "Ich meine, wir haben seit Langem kein Festmahl gehalten."
  },
  AvgCommunicate_70517_Content_4 = {
    Text = "Gab es nicht letztes Wochenende ein Abendessen im Saal?"
  },
  AvgCommunicate_70517_Content_5 = {
    Text = "Eine Gruppe gut gekleideter Personen sitzt zusammen, hält einen höflichen sozialen Abstand, verhält sich höflich, ist jedoch immer darauf bedacht, die schmutzigen Gedanken in ihren Herzen zu verbergen..."
  },
  AvgCommunicate_70517_Content_6 = {
