  },
  AvgCommunicate_70517_Content_7 = {
    Text = "Du hast das wahre Festmahl in der alten Burg bereits gesehen, oder?"
  },
  AvgCommunicate_70517_Content_8 = {
    Text = "Madame Wanda, schließlich ist dies Londinium, nicht dein Schloss..."
  },
  AvgCommunicate_70517_Content_9 = {
