  AvgCommunicate_70518_Content_10 = {
    Text = "Ambitioniert... Ich mag diesen Titel."
  },
  AvgCommunicate_70518_Content_11 = {
    Text = "Keine Sorge. Ich habe bereits Anpassungen am Plan vorgenommen."
  },
  AvgCommunicate_70518_Content_12 = {
    Text = "Die Wiederbelebung des Perishiten beschränkt sich nicht auf die Eroberung der Macht des Seefahrers."
  },
  AvgCommunicate_70518_Content_13 = {
    Text = "Ich suche sie, weil ich über den nächsten Schritt in unserer Zusammenarbeit sprechen möchte."
  },
  AvgCommunicate_70518_Content_14 = {
    Text = "Die Ressourcen und Kräfte, über die Mythag verfügt, sind sowohl für sie als auch für mich von großem Nutzen."
  },
  AvgCommunicate_70518_Content_15 = {
    Text = "Laut gegen Mythag direkt vor mir zu intrigieren... ist das nicht ein bisschen unangemessen?"
  },
  AvgCommunicate_70518_Content_16 = {
    Text = "Es ist Zusammenarbeit. Schließlich, wenn die Kräfte des Seefahrers und des Perishiten genutzt werden können, wird deine Untersuchung viel reibungsloser verlaufen, oder?"
  },
  AvgCommunicate_70518_Content_17 = {
    Text = "Es klingt, als könnte etwas daran wahr sein..."
  },
  AvgCommunicate_70518_Content_18 = {
    Text = "Sehr gut, sehr aufschlussreich, Hüter."
  },
  AvgCommunicate_70518_Content_19 = {
    Text = "Mach dir keine Sorgen, sobald die Mission abgeschlossen ist, wirst du alles, was dir gehört, erhalten."
