  AvgCommunicate_70523_Content_1 = {
    Text = "Im Eilverfahren hatte ich nicht die Gelegenheit, euch die lokalen Bräuche und die Kultur vorzustellen."
  },
  AvgCommunicate_70523_Content_10 = {
    Text = "Wie ich bereits erwähnte, bin ich nur ein Bote, der die Lehren meines Herrn verkündet."
