  AvgCommunicate_70523_Content_11 = {
    Text = "Unser Gott wird eine bessere Zukunft für die Welt schaffen."
  },
  AvgCommunicate_70523_Content_12 = {
    Text = "Primitivgruppen wie die Aram sind ebenfalls Teil dieser Zukunft und bleiben unsere loyalsten Freunde."
  },
  AvgCommunicate_70523_Content_13 = {
    Text = "Natürlich verstehe ich auch die Zweifel des {Male=Mr.,Female=Miss} Schutzherrn."
  },
  AvgCommunicate_70523_Content_14 = {
    Text = "Ich glaube, solange wir ein wenig mehr Zeit zusammen verbringen, werden diese Zweifel von selbst verschwinden."
  },
  AvgCommunicate_70523_Content_15 = {
    Text = "Jeder ist einen langen Weg gegangen, bitte ruhe dich gut aus."
  },
  AvgCommunicate_70523_Content_16 = {
    Text = "Ich vertrete Lengwashi und heiße dich herzlich willkommen, Geheimnisträger {Male=Herr,Female=Frau}."
  },
  AvgCommunicate_70523_Content_2 = {
    Text = "Ich frage mich, ob {Male=Mr.,Female=Miss} Schutzherr irgendwelche Fragen an mich hat?"
