  AvgCommunicate_70523_Content_3 = {
    Text = "Ich bin ein wenig neugierig auf die Bräuche hier."
  },
  AvgCommunicate_70523_Content_4 = {
    Text = "Obwohl die Aram-Leute seit Generationen durch Viehzucht leben, fernab der Industriegesellschaft, sollten sie bitte nicht als unzivilisierte barbarische Stämme betrachtet werden."
  },
  AvgCommunicate_70523_Content_5 = {
    Text = "Es gibt keine Regeln hier; fühle dich frei, mit ihnen zu interagieren."
  },
  AvgCommunicate_70523_Content_6 = {
    Text = "Die Begeisterung der Aram-Leute, die bald jeder fühlen kann."
  },
  AvgCommunicate_70523_Content_7 = {
    Text = "Es ist ziemlich seltsam, dass jemand wie Juliette in einem so primitiven Stamm existiert, nicht wahr?"
  },
  AvgCommunicate_70523_Content_8 = {
    Text = "Von einem Traum gerufen, um Aran zu führen – diese Begründung wirkt zumindest etwas weit hergeholt."
