  },
  AvgCommunicate_70525_Option_6 = {
    Text = "Die nächste Arbeit hängt von dir ab!"
  },
  AvgCommunicate_70525_Option_9 = {
    Text = "Jenkin hat einige Gedanken zur Geschichte des Ewigen Nachtwächters..."
