  AvgCommunicate_70526_Content_10 = {
    Text = "Kurz gesagt, ich möchte eine größere Welt sehen."
  },
  AvgCommunicate_70526_Content_11 = {
    Text = "Lotan hat mich dreimal besiegt. Ich frage mich, was sonst, über Hass hinaus, jemandem so immense Macht verleihen kann."
