  },
  AvgCommunicate_70526_Option_7 = {
    Text = "Wohin gehst du?"
  },
  AvgCommunicate_70527_Content_1 = {
    Text = "Aurita zeigte Lily die Quallen, die sie großgezogen hatte."
  },
  AvgCommunicate_70527_Content_10 = {
    Text = "Weil sie ihren größten Wunsch erfüllt hat – dich ein glückliches Leben leben zu lassen."
  },
  AvgCommunicate_70527_Content_11 = {
    Text = "Lily möchte ihre Mutter so lächeln sehen."
  },
  AvgCommunicate_70527_Content_12 = {
    Text = "Um Mutter glücklich zu machen, wird Lily weiterhin fröhlich sein!"
  },
  AvgCommunicate_70527_Content_13 = {
    Text = "Das stimmt!"
  },
  AvgCommunicate_70527_Content_14 = {
    Text = "Möchte Lily weiterhin die U-Bahn nehmen? Wenn ja, kann ich sie jetzt sofort dorthin bringen."
  },
  AvgCommunicate_70527_Content_15 = {
    Text = "Wirklich?! Danke, Meister!"
  },
  AvgCommunicate_70527_Content_2 = {
    Text = "Jenkin nahm Lily mit, um den Uhrturm zu besteigen."
  },
  AvgCommunicate_70527_Content_3 = {
    Text = "Schwester Ramona hat Lily eine große Menge köstlicher Nahrung gebracht..."
  },
  AvgCommunicate_70527_Content_4 = {
    Text = "Lily, wie fühlst du dich jetzt? Geht es dir besser?"
  },
  AvgCommunicate_70527_Content_5 = {Text = "...Okay!"},
  AvgCommunicate_70527_Content_6 = {
    Text = "Lily träumte letzte Nacht, sie träumte von ihrer Mutter..."
  },
  AvgCommunicate_70527_Content_7 = {
    Text = "Die Mutter sagt, sie sieht mir zu."
  },
  AvgCommunicate_70527_Content_8 = {
    Text = "Mich glücklich zu sehen, macht auch Mutter glücklich."
  },
  AvgCommunicate_70527_Content_9 = {
    Text = "Die Mutter lächelt. Lily hat ihre Mutter so lange nicht mehr lächeln gesehen."
  },
  AvgCommunicate_70527_Option_10 = {
    Text = "Weil sie ihren Wunsch erfüllt hat"
  },
  AvgCommunicate_70527_Option_14 = {
    Text = "Willst du immer noch die U-Bahn nehmen?"
  },
  AvgCommunicate_70527_Option_4 = {
    Text = "Lily, wie fühlst du dich jetzt?"
  },
  AvgCommunicate_70528_Content_1 = {
    Text = "Während dieser Zeit seit meiner Rückkehr habe ich auch einige neue Möglichkeiten erkundet."
  },
  AvgCommunicate_70528_Content_10 = {
    Text = "Überlebe, Hüter... finde mit Ramona einen Weg, gegen die Auflösung zu kämpfen."
  },
  AvgCommunicate_70528_Content_11 = {
    Text = "Wenn es etwas gibt, das du möchtest, dass ich tue, lass es mich einfach wissen."
  },
  AvgCommunicate_70528_Content_12 = {
    Text = "Lass diese Welt nicht so werden wie meine."
  },
  AvgCommunicate_70528_Content_13 = {
    Text = "Das ist meine einzige Hoffnung, und nur du kannst es wahr werden lassen."
  },
  AvgCommunicate_70528_Content_2 = {
    Text = "Ohne Ausnahme sind all diese Entscheidungen falsch."
  },
  AvgCommunicate_70528_Content_3 = {
    Text = "Du bist auf dem einzigen richtigen Weg, Hüter."
  },
  AvgCommunicate_70528_Content_4 = {
    Text = "Danke für deine harte Arbeit, Ramona..."
  },
  AvgCommunicate_70528_Content_5 = {
    Text = "Hat sich die Situation auf deiner Seite jetzt verbessert?"
  },
  AvgCommunicate_70528_Content_6 = {
    Text = "Immer noch das gleiche... Alles ist in Auflösung versunken, das einzige verbleibende Refugium."
  },
  AvgCommunicate_70528_Content_7 = {
    Text = "Lehrer Alistair pflegt diesen Ort, und sein Zustand ist auch nicht gut..."
  },
  AvgCommunicate_70528_Content_8 = {
    Text = "Ramona... gibt es etwas, das ich für dich tun kann?"
  },
  AvgCommunicate_70528_Content_9 = {
    Text = "Es ist alles in Ordnung. Wir haben uns bereits daran gewöhnt."
  },
  AvgCommunicate_70528_Option_4 = {
    Text = "Danke für deine harte Arbeit, Ramona..."
  },
  AvgCommunicate_70528_Option_8 = {
    Text = "Gibt es etwas, das ich für dich tun kann?"
  },
  AvgCommunicate_70529_Content_1 = {
    Text = "Hallo, Schutzherr {Male=Mr.,Female=Miss}."
  },
  AvgCommunicate_70529_Content_10 = {
    Text = "Natürlich. Genau in diesem Moment hat sich der Zustand eines Patienten plötzlich verschlechtert, und ich muss mich sofort darum kümmern."
  },
  AvgCommunicate_70529_Content_11 = {
    Text = "Danke, dass ihr Lily nach Hause gebracht habt. Die Lounge und Erfrischungen sind für alle vorbereitet."
  },
  AvgCommunicate_70529_Content_12 = {
    Text = "Willkommen bei Rai Sanatorium, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgCommunicate_70529_Content_2 = {
    Text = "Über die Empfehlung von Frau Davendale hat mir Misag deine Kontaktdaten gegeben."
  },
  AvgCommunicate_70529_Content_3 = {
    Text = "Darf ich fragen, wo ihr alle mit Lily seid?"
  },
  AvgCommunicate_70529_Content_4 = {
    Text = "Wir sind an der Fowler-Stahlbrücke angekommen und werden bald das Sanatorium erreichen."
  },
  AvgCommunicate_70529_Content_5 = {
    Text = "Hat Lily auf dieser Reise Schwierigkeiten für alle verursacht?"
  },
  AvgCommunicate_70529_Content_6 = {
    Text = "Bitte mach dir keine Sorgen; Lily war die ganze Zeit über sehr gehorsam."
  },
  AvgCommunicate_70529_Content_7 = {
    Text = "Frau Francis, bezüglich des Sanatoriums würde ich gerne..."
  },
  AvgCommunicate_70529_Content_8 = {
    Text = "Entschuldigung, Hüter. Der Zustand eines Kranken hat sich plötzlich verschlechtert, ich muss mich sofort darum kümmern."
  },
  AvgCommunicate_70529_Content_9 = {
    Text = "Dann treffen wir uns im Sanatorium?"
  },
  AvgCommunicate_70529_Option_4 = {
    Text = "Es ist schon fast hier."
  },
  AvgCommunicate_70529_Option_6 = {
    Text = "Lily ist sehr gehorsam."
  },
  AvgCommunicate_70529_Option_7 = {
    Text = "Frage Francis nach den Abweichungen im Sanatorium"
  },
  AvgCommunicate_70529_Option_9 = {
    Text = "Erdulden für jetzt, um ihre Wachsamkeit nicht zu erhöhen."
  },
  AvgCommunicate_70530_Content_1 = {
    Text = "Mein kostbarer Samen wurde abgelehnt... Das ist wirklich traurig, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgCommunicate_70530_Content_10 = {
    Text = "Je wertvoller etwas ist, desto mehr sollte es mit einer feierlichen Zeremonie empfangen werden."
  },
  AvgCommunicate_70530_Content_11 = {
    Text = "Dieser kostbarste Same wird früher oder später dir gehören."
  },
  AvgCommunicate_70530_Content_12 = {
    Text = "Mach dir keine Sorgen, Hüter. Dieser Tag wird nicht lange auf sich warten lassen."
  },
  AvgCommunicate_70530_Content_2 = {
    Text = "Thais, das war nicht, was ich meinte..."
  },
  AvgCommunicate_70530_Content_3 = {
    Text = "Oh? Was bedeutet der Hüter dann?"
  },
  AvgCommunicate_70530_Content_4 = {Text = "Ich..."},
  AvgCommunicate_70530_Content_5 = {
    Text = "Es tut mir leid, aber die Situation damals war einfach zu hastig. Ich hatte keine Zeit zu denken..."
  },
  AvgCommunicate_70530_Content_6 = {
    Text = "Was ist, wenn die Situation nicht dringend ist?"
  },
  AvgCommunicate_70530_Content_7 = {Text = "Ich..."},
  AvgCommunicate_70530_Content_8 = {
    Text = "Alright, alright, ich werde dich nicht mehr ärgern."
  },
  AvgCommunicate_70530_Content_9 = {
    Text = "Ich verstehe, Hüter."
  },
  AvgCommunicate_70530_Option_2 = {
    Text = "Thais, das war nicht, was ich meinte..."
  },
  AvgCommunicate_70530_Option_5 = {
    Text = "Es tut mir leid, aber die Situation damals war einfach zu hastig..."
