  AvgCommunicate_70531_Content_10 = {
    Text = "Willkommen in Mythag."
  },
  AvgCommunicate_70531_Content_11 = {
    Text = "...Hannah kam gerade, um mich zu sehen."
  },
  AvgCommunicate_70531_Content_12 = {
    Text = "Jenkins Erwachen der Schöpfung wurde erfolgreich abgeschlossen."
  },
  AvgCommunicate_70531_Content_13 = {Text = "!!!"},
  AvgCommunicate_70531_Content_14 = {
    Text = "Lass uns gehen und unseren kleinen Helden treffen."
  },
  AvgCommunicate_70531_Content_2 = {
    Text = "Wie Fortschritte macht Jenkins Erwachen?"
  },
  AvgCommunicate_70531_Content_3 = {
    Text = "Die Materialbibliothek der Schule hat die benötigten Gegenstände für ihren Körper vorbereitet, und der Prozess zur Schaffung des Awakener ist derzeit im Gange."
  },
  AvgCommunicate_70531_Content_4 = {
    Text = "Bald werden wir sie wiedersehen können!"
  },
  AvgCommunicate_70531_Content_5 = {
    Text = "Ausgezeichnet! Ausgezeichnet..."
  },
  AvgCommunicate_70531_Content_6 = {
    Text = "Vielen Dank, Hüter. Vielen Dank an euch alle..."
  },
  AvgCommunicate_70531_Content_7 = {
    Text = "Du und Jenkin habt uns gerettet."
  },
  AvgCommunicate_70531_Content_8 = {
    Text = "Sie starb, um Mythag zu retten; das ist, was wir tun müssen."
  },
  AvgCommunicate_70531_Content_9 = {
    Text = "Das Schulkomitee hat diskutiert und genehmigt, sodass ihr beiden euch keine Sorgen mehr machen müsst, zurückgelassen zu werden."
  },
  AvgCommunicate_70531_Option_11 = {
