  AvgCommunicate_70532_Content_1 = {Text = "Hüter!"},
  AvgCommunicate_70532_Content_2 = {
    Text = "Wann werden wir wieder filmen!"
  },
  AvgCommunicate_70532_Content_3 = {
    Text = "Was, bist du süchtig nach dem Applaus geworden?"
  },
  AvgCommunicate_70532_Content_4 = {
    Text = "Es liegt nicht daran, dass ich süchtig bin; es ist, dass diese Stadt uns braucht!"
  },
  AvgCommunicate_70532_Content_5 = {
    Text = "Diese Stadt ist voller Hungernder, die die Nachtwanderer und ihre Assistenten brauchen!"
  },
  AvgCommunicate_70532_Content_6 = {
    Text = "Ich werde Doll fragen, ob ich die Kamera wieder ausleihen kann."
  },
  AvgCommunicate_70532_Content_7 = {
    Text = "Übrigens, hast du regelmäßig an den Alphabetisierungskursen teilgenommen? Wie viele Tippfehler hast du gemacht!"
  },
  AvgCommunicate_70532_Content_8 = {
    Text = "Kümmere dich um deine eigenen Angelegenheiten, Westside-Typ!"
