  AvgCommunicate_70533_Content_1 = {
    Text = "Hüter, Hüter!"
  },
  AvgCommunicate_70533_Content_10 = {
    Text = "Aber warum erinnert sich Aurita nicht an sie?"
  },
  AvgCommunicate_70533_Content_11 = {
    Text = "Welpe, Pony, kleine Qualle... Sie waren einst alle Freunde von Aurita."
  },
  AvgCommunicate_70533_Content_12 = {
    Text = "Später mussten sie an einen fernen Ort gehen."
  },
  AvgCommunicate_70533_Content_13 = {
    Text = "Sie hatten Angst, Aurita Schmerzen zuzufügen, also löschten sie Auritas Erinnerungen an sie aus."
  },
  AvgCommunicate_70533_Content_14 = {
    Text = "Aber sie wollten immer noch an Auritas Seite bleiben, also ließen sie ihre Körper zurück."
  },
  AvgCommunicate_70533_Content_15 = {
    Text = "Diese Körper wurden zu kleinen Tonpuppen und im Wasserpalast von Aurita zurückgelassen."
  },
  AvgCommunicate_70533_Content_16 = {
    Text = "...Sie haben sich immer um Aurita gekümmert und sie begleitet, und das hat sich nie geändert."
  },
  AvgCommunicate_70533_Content_17 = {
    Text = "Es scheint, als würde ich es verstehen, und doch fühlt es sich auch so an, als würde ich es nicht..."
  },
  AvgCommunicate_70533_Content_18 = {
    Text = "Aber Aurita weiß es! Die im Wasserpalast sind alles gute Freunde von Aurita."
  },
  AvgCommunicate_70533_Content_19 = {
    Text = "Aurita wird gut auf sie aufpassen und jeden Tag mit ihnen spielen!"
  },
  AvgCommunicate_70533_Content_2 = {
    Text = "Weißt du, was sich im Wasserpalast von Aurita befindet?"
  },
  AvgCommunicate_70533_Content_3 = {
    Text = "Was denkt Aurita, dass das ist?"
  },
  AvgCommunicate_70533_Content_4 = {
    Text = "Hmm... Aurita kann sich nicht erinnern..."
  },
  AvgCommunicate_70533_Content_5 = {
    Text = "Es fühlt sich vertraut an, wie... wie..."
  },
  AvgCommunicate_70533_Content_6 = {Text = "Freund..."},
  AvgCommunicate_70533_Content_7 = {
    Text = "Aurita liebt Freunde am meisten, aber warum erinnert sich Aurita nicht an sie?"
  },
  AvgCommunicate_70533_Content_8 = {
    Text = "Das sind alles Freunde von Aurita."
  },
  AvgCommunicate_70533_Content_9 = {
    Text = "Freund? Aurita liebt Freunde am meisten!"
  },
  AvgCommunicate_70533_Option_11 = {
    Text = "Erzähle Aurita ihre Geschichte"
  },
  AvgCommunicate_70533_Option_3 = {
    Text = "Was denkt Aurita?"
  },
  AvgCommunicate_70533_Option_8 = {
    Text = "Das sind alles Auritas Freunde."
  },
  AvgCommunicate_72037_Content_1 = {
    Text = "Gestern träumte ich von meiner Kindheit und von vielen Menschen aus Limorias Vergangenheit."
  },
  AvgCommunicate_72037_Content_10 = {
    Text = "Nichts entgeht deinem Blick."
  },
  AvgCommunicate_72037_Content_11 = {
    Text = "Das Gefühl, das im Traum nachhallte, war besonders vertraut und wohlbekannt. Yu dachte zunächst, es käme von Noah."
  },
  AvgCommunicate_72037_Content_12 = {
    Text = "Erst später stellte sich heraus, dass das Vertrauteste für mich über die langen Jahre hinweg nicht länger eine Person war, sondern ein kaltes, totes Objekt."
  },
  AvgCommunicate_72037_Content_13 = {Text = "Tulu..."},
  AvgCommunicate_72037_Content_14 = {
    Text = "<Yellow:Zeig keine Sympathie, ich war seit dem Moment, als ich die Krone aufsetzte, bereit.>"
  },
  AvgCommunicate_72037_Content_15 = {
    Text = "Der König von Lemuria benötigt niemanden, der für ihn Tränen vergießt."
  },
  AvgCommunicate_72037_Content_16 = {
    Text = "Also... König von Lemuria, bist du daran interessiert, dieses Reisbonbon erneut zu probieren? Ich denke, der Koch aus Mythag sollte in der Lage sein, es bis zu einem gewissen Grad nachzustellen."
  },
  AvgCommunicate_72037_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_72037_Content_18 = {
    Text = "Hmm, du bist wirklich rücksichtsvoll."
  },
  AvgCommunicate_72037_Content_19 = {
    Text = "Nun gut, betrachte es als dein Tribut."
  },
  AvgCommunicate_72037_Content_2 = {
    Text = "Das sind die Erinnerungen, über die ich nie gern gesprochen habe, aber, im Traum von gestern, warst du es, richtig?"
  },
  AvgCommunicate_72037_Content_3 = {
    Text = "?! Wie hast du das gewusst?"
  },
  AvgCommunicate_72037_Content_4 = {
    Text = "Die Zeit, die ich im Traum verbrachte, übersteigt die in der gewöhnlichen Welt bei Weitem; zweifelst du an der Wahrnehmung jemandes, der in einem Traum lebt?"
  },
  AvgCommunicate_72037_Content_5 = {
    Text = "Neben Prophezeiungen habe ich manchmal Träume wie gewöhnliche Menschen, aber keiner dieser Träume ist so lebhaft und kontinuierlich wie der Traum von gestern..."
  },
  AvgCommunicate_72037_Content_6 = {
    Text = "So, als säße jemand neben Yu und würde die vergangenen Ereignisse noch einmal mit ihm durchleben."
  },
  AvgCommunicate_72037_Content_7 = {
    Text = "Dieses Gefühl, nicht einsam zu sein... es ist ziemlich schön."
  },
  AvgCommunicate_72037_Content_8 = {
    Text = "Ich bin in der Tat immer an deiner Seite gewesen."
  },
  AvgCommunicate_72037_Content_9 = {
    Text = "Lass mich raten, du musst die Krone besitzen, oder?"
  },
  AvgCommunicate_72037_Option_10 = {Text = "Ja"},
  AvgCommunicate_72037_Option_13 = {Text = "Tulu..."},
  AvgCommunicate_72037_Option_16 = {Text = "Dann ..."},
  AvgCommunicate_72037_Option_3 = {Text = "?!"},
  AvgCommunicate_72037_Option_8 = {
    Text = "Ich bin in der Tat immer an deiner Seite gewesen."
  },
  AvgCommunicate_80100_Content_1 = {
    Text = "%player%, wenn es dir passt, kannst du zu einem psychologischen Test kommen?"
  },
  AvgCommunicate_80100_Content_10 = {
    Text = "Ramona, Lotan, Ogier... wenn ich allein bin, schweben ihre Figuren immer in meinem Geist."
  },
  AvgCommunicate_80100_Content_11 = {
    Text = "Keine Notwendigkeit, allein festzuhalten. Egal welche Probleme und Verwirrungen du hast, du kannst es mir sagen."
  },
  AvgCommunicate_80100_Content_12 = {
    Text = "Ich habe sogar heißen Tee und Snacks für dich vorbereitet, damit wir in Ruhe plaudern können."
  },
  AvgCommunicate_80100_Content_13 = {
    Text = "...Ich gehe jetzt dorthin."
  },
  AvgCommunicate_80100_Content_2 = {
    Text = "...Psychologischer Test?"
  },
  AvgCommunicate_80100_Content_3 = {
    Text = "Es ist ganz einfach, zeichne einfach ein Haus, einen Baum und eine Person auf ein leeres Blatt Papier."
  },
  AvgCommunicate_80100_Content_4 = {
    Text = "Glaub mir, es wird nicht zu viel deiner Zeit in Anspruch nehmen."
  },
  AvgCommunicate_80100_Content_5 = {
    Text = "...Aber ich habe das Gefühl, dass mein Geist ziemlich gesund ist."
  },
  AvgCommunicate_80100_Content_6 = {
    Text = "Der ultimative Zweck des Tests ist nicht die Beurteilung der Gesundheit, sondern die Beobachtung potenzieller psychologischer Probleme."
  },
  AvgCommunicate_80100_Content_7 = {
    Text = "\"%player%, nachdem du hierher gekommen bist, fühlst du dich einsam? Vermisst du die Freunde aus dieser Welt?\""
  },
  AvgCommunicate_80100_Content_8 = {
    Text = "Diese Einsamkeit und Isolation werden tief in deinem Herzen verborgen sein und mit der Zeit weiter gären, was unbekannte Auswirkungen hervorrufen kann."
  },
  AvgCommunicate_80100_Content_9 = {
    Text = "Vielleicht hast du recht, ich vermisse sie..."
  },
  AvgCommunicate_80100_Option_13 = {
    Text = "...Ich gehe jetzt dorthin."
  },
  AvgCommunicate_80100_Option_2 = {
    Text = "...Psychologischer Test?"
  },
  AvgCommunicate_80100_Option_5 = {
    Text = "...Aber ich habe das Gefühl, dass mein Geist ziemlich gesund ist."
  },
  AvgCommunicate_80100_Option_9 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_80101_Content_1 = {
    Text = "Ich habe gehört, dass du dich in letzter Zeit niedergeschlagen fühlst; wenn es dir nichts ausmacht, kannst du dich für eine Konsultation an mich wenden."
  },
  AvgCommunicate_80101_Content_10 = {
    Text = "Ah, allein darüber zu sprechen, lässt mein silbernes Herz nonstop zittern..."
  },
  AvgCommunicate_80101_Content_11 = {
    Text = "\"%player%, ich kann es kaum erwarten, in dein Herz einzutauchen und deine Erinnerungen zu schmecken.\""
  },
  AvgCommunicate_80101_Content_12 = {
    Text = "Dann wirst du enttäuscht sein. Ich bin bereits gegangen."
  },
  AvgCommunicate_80101_Content_13 = {
    Text = "Ich weiß. Einer meiner Patienten hat mir eine Nachricht geschickt, um mich über diese Angelegenheit zu informieren."
  },
  AvgCommunicate_80101_Content_14 = {
    Text = "Sie hat sogar aufmerksam deinen aktuellen Standort angehängt, also..."
  },
  AvgCommunicate_80101_Content_15 = {
    Text = "Ich werde bald da sein."
  },
  AvgCommunicate_80101_Content_2 = {
    Text = "Keine Notwendigkeit, anzugeben, Hüter. Vorschläge von Fachleuten können dir helfen, deinen Stress schneller anzupassen."
  },
  AvgCommunicate_80101_Content_3 = {
    Text = "Wie konntest du das wissen...?"
  },
  AvgCommunicate_80101_Content_4 = {Text = "Geheimnis~"},
  AvgCommunicate_80101_Content_5 = {
    Text = "Was ist also deine Antwort?"
  },
  AvgCommunicate_80101_Content_6 = {
    Text = "Ich verspreche, dass ich diesmal keine andere Anleitung geben werde."
  },
  AvgCommunicate_80101_Content_7 = {
    Text = "Du hast das letzte Mal dasselbe gesagt und das Mal davor..."
  },
  AvgCommunicate_80101_Content_8 = {
    Text = "Das ist nicht meine Schuld, sondern dass Ihr Bewusstsein mit angenehmen Erinnerungen gefüllt ist."
  },
  AvgCommunicate_80101_Content_9 = {
    Text = "Diese Erinnerungen übertreffen bei weitem den Schmerz, den eine gewöhnliche Person erdulden kann, und tragen die Aura jener großen Existenz, die die höchste Süße darstellt."
  },
  AvgCommunicate_80101_Option_12 = {
    Text = "...Dann wirst du enttäuscht sein"
  },
  AvgCommunicate_80101_Option_3 = {
    Text = "Wie konntest du das wissen...?"
  },
  AvgCommunicate_80101_Option_7 = {
    Text = "Du hast das letzte Mal dasselbe gesagt und das Mal davor..."
  },
  AvgCommunicate_80102_Content_1 = {
    Text = "%player%, wenn es dir nichts ausmacht, darf ich dann deine psychologische Behandlung übernehmen?"
  },
  AvgCommunicate_80102_Content_10 = {
    Text = "Aber ich werde keine übertriebenen Maßnahmen ergreifen. Glaub mir."
  },
  AvgCommunicate_80102_Content_11 = {
    Text = "......Wirklich?"
  },
  AvgCommunicate_80102_Content_12 = {
    Text = "Natürlich. Immerhin bin ich nur ein Psychologe."
  },
  AvgCommunicate_80102_Content_2 = {
    Text = "Ich glaube, du benötigst einen eigenen Psychologen."
  },
  AvgCommunicate_80102_Content_3 = {
    Text = "......Ich glaube nicht, dass das nötig ist."
  },
  AvgCommunicate_80102_Content_4 = {
    Text = "Nein, als einziger Geheimnisträger ist deine Existenz an sich bereits von Bedeutung."
  },
  AvgCommunicate_80102_Content_5 = {
    Text = "Ich möchte dir nur mit meiner professionellen Fähigkeit helfen."
  },
  AvgCommunicate_80102_Content_6 = {
    Text = "Es ist wirklich so? Warum habe ich das Gefühl, dass du ein anderes Ziel verfolgst..."
  },
  AvgCommunicate_80102_Content_7 = {
    Text = "Zum Beispiel, um meine Erinnerungen unter dem Vorwand des eigenen Psychologen zu erkunden."
  },
  AvgCommunicate_80102_Content_8 = {
    Text = "<Yellow:Ah, wurde ich entdeckt? Dann gibt es wohl nichts, was man dagegen tun kann.>"
  },
  AvgCommunicate_80102_Content_9 = {
    Text = "Ich bin tatsächlich äußerst an deinen Erinnerungen interessiert. Insbesondere nachdem du von dieser anderen Welt berichtet hast."
  },
  AvgCommunicate_80102_Option_11 = {
