  AvgCommunicate_80104_Content_16 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_17 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_18 = {
    Text = "Heh, ich weiß, dass du immer noch hier bist. Aber das ist in Ordnung, wir haben noch viel Zeit."
  },
  AvgCommunicate_80104_Content_2 = {
    Text = "Das ist ein handschriftlich kopierter, redigierter Bericht über die Insektenarten, ohne Probleme mit Leckagen, fühlen Sie sich frei, ihn zu behalten."
  },
  AvgCommunicate_80104_Content_3 = {
