  AvgCommunicate_81323_Content_1 = {
    Text = "Mein Wohltäter, wann wirst du mir das neue Arbeitsbuch übergeben?"
  },
  AvgCommunicate_81323_Content_10 = {
    Text = "Ich verstehe, hat der Wohltäter dann andere Lehrer, die in diesen zwei Fächern bewandert sind, die du empfehlen kannst?"
  },
  AvgCommunicate_81323_Content_11 = {
    Text = "Wenn unbedingt nötig, kann ich einige andere Bücher lesen und versuchen, mir selbst etwas beizubringen."
  },
  AvgCommunicate_81323_Content_12 = {
    Text = "Es gibt... es gibt, aber ihr Temperament ist nicht sehr gut."
  },
  AvgCommunicate_81323_Content_13 = {
    Text = "Es ist in Ordnung, ich habe keine Angst."
  },
  AvgCommunicate_81323_Content_14 = {
    Text = "Ich habe Angst! Nun, wenn ich Winkle suche... äh, sie würde wohl zuerst verrückt werden."
  },
  AvgCommunicate_81323_Content_15 = {
    Text = "Verrückt? Hat dieser Meister Winkle irgendeine Art von Krankheit?"
  },
  AvgCommunicate_81323_Content_16 = {
    Text = "Nein... ich kann nicht sagen, dass es nicht so ist, ah ah ah! Kurz gesagt, lassen Sie mich Ihnen zuerst eine Wahrheit des Lernens beibringen!"
  },
  AvgCommunicate_81323_Content_17 = {
    Text = "In Ordnung, Wohltäter, ich höre zu."
  },
  AvgCommunicate_81323_Content_18 = {
    Text = "Das heißt, stelle keine Fragen zu allem!!!"
  },
  AvgCommunicate_81323_Content_19 = {
    Text = "Warum passiert das wieder? Wohltäter, ich verstehe es nicht ganz. Wenn ich nicht klar nachfrage, wie kann ich dann gründlich lernen..."
  },
  AvgCommunicate_81323_Content_2 = {
    Text = "Und bezüglich der letzten beiden Bücher habe ich sie gründlich gelesen und insgesamt 107 Fragen notiert; ich hoffe, der Wohltäter kann in seiner Freizeit etwas Anleitung geben."
  },
  AvgCommunicate_81323_Content_20 = {
    Text = "Bist du nicht müde! Mit einem so fleißigen Geist, der in das Meer des Wissens eintritt, wirst du in allem, was du tust, Erfolg haben..."
  },
  AvgCommunicate_81323_Content_21 = {
    Text = "Danke, Wohltäter. Die Freiheit zu haben, das zu lernen, was mich interessiert, ist wirklich eine kostbare und freudige Angelegenheit."
  },
  AvgCommunicate_81323_Content_22 = {
    Text = "Es ist in Ordnung, eine Pause zu machen, wenn man wirklich schläfrig ist; wie könnte man müde sein?"
  },
  AvgCommunicate_81323_Content_23 = {
    Text = "Also, wann kann mein Wohltäter mich dem neuen Lehrer vorstellen? Ich werde mein Bestes geben, um nicht zu neugierig zu sein."
  },
  AvgCommunicate_81323_Content_24 = {
    Text = "Ähm... wie wäre es, wenn ich 97 Fragen stelle?"
  },
  AvgCommunicate_81323_Content_3 = {
    Text = "Ich habe einen Fehler gemacht"
  },
  AvgCommunicate_81323_Content_4 = {
    Text = "Ichlag ganz falsch"
  },
  AvgCommunicate_81323_Content_6 = {
    Text = "Ich hätte deine Hausaufgaben nicht für dich machen sollen; man sollte seine eigenen Angelegenheiten regeln..."
  },
  AvgCommunicate_81323_Content_7 = {
    Text = "Bitte hör auf, mich zu fragen! Wenn das so weitergeht, werde ich nachts Albträume haben!"
  },
  AvgCommunicate_81323_Content_8 = {
    Text = "Ah... entschuldigung, ich hätte nicht gedacht, dass mein Eindringen meinen Wohltäter so sehr stören würde; ich bin wirklich zu stumpf."
  },
  AvgCommunicate_81323_Content_9 = {
    Text = "Nein, gar nicht, vielleicht bin ich einfach nicht dafür gemacht, ein Lehrer zu sein..."
  },
  AvgCommunicate_81323_Option_12 = {
    Text = "Es gibt... es gibt."
  },
  AvgCommunicate_81323_Option_14 = {
    Text = "Ich habe Angst!"
  },
  AvgCommunicate_81323_Option_16 = {
    Text = "Nein... ich kann nicht sagen, dass es nicht so ist..."
  },
  AvgCommunicate_81323_Option_18 = {
    Text = "Das heißt, stelle keine Fragen zu allem!!!"
  },
  AvgCommunicate_81323_Option_20 = {
    Text = "Bist du nicht müde!"
  },
  AvgCommunicate_81323_Option_3 = {
    Text = "Ich habe mich geirrt"
