  AvgCommunicate_81324_Content_1 = {
    Text = "Mein Wohltäter, ich habe neue Fragen, seit ich in letzter Zeit gelesen habe."
  },
  AvgCommunicate_81324_Content_10 = {
    Text = "Sagst du... es hängt von den Gedanken während des Tuns ab?"
  },
  AvgCommunicate_81324_Content_11 = {
    Text = "Das ist richtig, denk mal darüber nach, als ich dich bat, diese beiden Aufgaben zu schreiben, wollte ich dich dann kostenlos ausbeuten oder hoffte ich, dass du eine Lerngelegenheit gewinnst?"
  },
  AvgCommunicate_81324_Content_12 = {
    Text = "Ich weiß nicht."
  },
  AvgCommunicate_81324_Content_13 = {
    Text = "Wie könnte dies unbekannt sein? Natürlich, es ist, um dir zu helfen, Wissen besser zu lernen!"
  },
  AvgCommunicate_81324_Content_14 = {
    Text = "So ist es also. Ich habe missverstanden; ich dachte, der Wohltäter wollte nur, dass ich dir bei deinen Hausaufgaben helfe."
  },
  AvgCommunicate_81324_Content_16 = {
    Text = "Hust, hust... Nun, lass uns noch einmal nachdenken. Wenn wir eine Handlung mit einer Person als Endziel durchführen und einander aufrichtig berücksichtigen, kann das als moralisch bezeichnet werden."
  },
  AvgCommunicate_81324_Content_17 = {
    Text = "Wenn du Menschen als reine Werkzeuge behandelst, ist das sicherlich unmoralisch."
  },
  AvgCommunicate_81324_Content_18 = {
    Text = "Ich denke, ich verstehe es, es ist wie das Verwenden einer Laterne, um mich und Polyx wie Werkzeuge für ein Opfer zu behandeln, ohne wirklich unsere Gefühle zu berücksichtigen. Das ist unmoralisch."
  },
  AvgCommunicate_81324_Content_19 = {
    Text = "Das stimmt, das stimmt, deine Einsicht ist großartig!"
  },
  AvgCommunicate_81324_Content_2 = {
    Text = "Du hast zuvor gesagt, dass Aufgaben dazu dienen, dein Wissen zu testen und zu verfeinern; solange das Wissen beherrscht wird, ist es nicht nötig, an der Vollständigkeit der Aufgabe festzuhalten."
  },
  AvgCommunicate_81324_Content_20 = {
    Text = "Ich verstehe, Wohltäter, du bist wirklich eine moralische Person! Dann bitte, Wohltäter, gib mir noch ein paar Aufträge, ich werde sie sorgfältig erledigen und zurückkommen, um zu konsultieren!"
  },
  AvgCommunicate_81324_Content_21 = {
    Text = "Wohltäter?"
  },
  AvgCommunicate_81324_Content_22 = {
    Text = "Das, ich habe plötzlich etwas zu erledigen. Du solltest direkt zu Puppe wegen der Hausaufgaben gehen!"
  },
  AvgCommunicate_81324_Content_3 = {
    Text = "Ähm... es scheint, als hätte ich so etwas schon einmal gesagt."
  },
  AvgCommunicate_81324_Content_4 = {
    Text = "Aber die letzten Bücher, die ich gelesen habe, erwähnen, dass es unethisch erscheint, andere für sich arbeiten zu lassen."
  },
  AvgCommunicate_81324_Content_6 = {
    Text = "Dann, wie beurteilst du, ob diese Angelegenheit moralisch ist?"
  },
  AvgCommunicate_81324_Content_7 = {
    Text = "Uh... zu dieser Angelegenheit solltest du sie dialektisch betrachten."
  },
  AvgCommunicate_81324_Content_8 = {
    Text = "Wir können nicht mit Sicherheit ja oder nein sagen."
  },
  AvgCommunicate_81324_Content_9 = {
    Text = "Wenn du etwas beurteilst, kannst du nicht nur das Ergebnis betrachten, sondern musst auch den Zweck hinter der Handlung in Betracht ziehen."
  },
  AvgCommunicate_81324_Option_11 = {Text = "Ja. Genau!"},
  AvgCommunicate_81324_Option_13 = {
    Text = "Wie könnte dies unbekannt sein?"
  },
  AvgCommunicate_81324_Option_19 = {
