  AvgCommunicate_81325_Content_1 = {
    Text = "Was für eine magische Box, Wohltäter, wird diese wirklich nicht durch irgendeine Art von Magie oder Ritualanordnung betrieben?"
  },
  AvgCommunicate_81325_Content_10 = {
    Text = "Das ist nicht der Fall, es ist nur so, dass diese beiden Themen derzeit auch entwickelt werden, und viele Wissenschaftler werden diese Studien erweitern und vertiefen, wodurch neues Wissen entsteht."
  },
  AvgCommunicate_81325_Content_11 = {
    Text = "Wenn du diese blühende Disziplin als dein Lernziel nimmst, solltest du natürlich lernen, bis du alt wirst."
  },
  AvgCommunicate_81325_Content_12 = {
    Text = "So ist es also, Wissen, das sich weiterhin entwickelt... wahrhaft großartig."
  },
  AvgCommunicate_81325_Content_13 = {
    Text = "Wenn wir die Schriften der Laterne studieren, können wir kein einziges Wort ändern; alle Inhalte sind gesichert, wiederholt und bleiben unverändert."
  },
  AvgCommunicate_81325_Content_14 = {
    Text = "Aber jedes Mal, wenn ich die Schriften studiere, fühle ich mich, als wäre ich in einer Kiste und würde einen Blick auf das Ende werfen."
  },
  AvgCommunicate_81325_Content_15 = {
    Text = "In der Tat entspricht nur das ständig wachsende Wissen der wahren Essenz des Lebens!"
  },
  AvgCommunicate_81325_Content_16 = {
    Text = "Plötzlich fühlte ich Transzendenz..."
  },
  AvgCommunicate_81325_Content_17 = {
    Text = "Wenn wir davon sprechen, habe ich eine hervorragende Lerngelegenheit, die ich dir großzügig kostenlos anbieten kann."
  },
  AvgCommunicate_81325_Content_18 = {
    Text = "Wirklich, Wohltäter! Meine Dankbarkeit kennt keine Worte."
  },
  AvgCommunicate_81325_Content_19 = {
    Text = "Natürlich ist es wahr, dieses Üben und die Wartungsprinzipien der Silbertechnologie, zusammen mit diesem verpflichtenden Handbuch für die Psychologiestrategien von Ermittlern, welches möchtest du zuerst schreiben..."
  },
  AvgCommunicate_81325_Content_2 = {
    Text = "Nein, das ist reine Silberchiptechnologie, und um Sie daran zu erinnern, der Kommunikator ist teuer, also schlage ich vor, dass Sie ihn nicht achtlos auseinandernehmen."
  },
  AvgCommunicate_81325_Content_20 = {
    Text = "Ah nein, welches sollte ich zuerst lernen?"
  },
  AvgCommunicate_81325_Content_3 = {
    Text = "Ah, wie schade... wie hat der Wohltäter gewusst, dass ich es gerade auseinandernehmen wollte? Ist das Gedankenlesen?"
