  AvgCommunicate_81325_Content_5 = {
    Text = "Psychologie muss ein weiteres tiefgründiges Wissen sein; bedauerlicherweise ist mein Verständnis in der Tat karg..."
  },
  AvgCommunicate_81325_Content_6 = {
    Text = "Mein Wohltäter, wie lange dauert es, diese Technologie des silbernen Chips und Psychologie zu lernen?"
