  AvgCommunicate_84107_Content_1 = {
    Text = "Wann endet diese Ferienpause?"
  },
  AvgCommunicate_84107_Content_10 = {
    Text = "Erst durch die Summe dieser Faktoren und eine sorgfältige Abwägung von Vor- und Nachteilen lässt sich die effizienteste und vernünftigste Route planen."
  },
  AvgCommunicate_84107_Content_11 = {
    Text = "......Verstanden. Es scheint, dass jeder Job seine eigene Bedeutung hat."
  },
  AvgCommunicate_84107_Content_12 = {
    Text = "Ja, da ich die Wahl getroffen habe, muss ich auch die Verantwortung dafür übernehmen."
  },
  AvgCommunicate_84107_Content_13 = {
    Text = "Ab sofort werde ich jeden Abend eine Patrouille durchführen, um sicherzustellen, dass während der Ferien keine Zwischenfälle am Institut stattfinden."
  },
  AvgCommunicate_84107_Content_14 = {
    Text = "Hüter des Geheimnisses, dann lass uns hier erstmal Schluss machen. Ich muss zur Arbeit gehen."
  },
  AvgCommunicate_84107_Content_2 = {
    Text = "...Die Ferien haben doch erst begonnen, oder?"
  },
  AvgCommunicate_84107_Content_4 = {
    Text = "Ich bereite mich nur auf das vor, was danach kommt."
  },
  AvgCommunicate_84107_Content_5 = {
    Text = "Der Campusplan wurde aktualisiert, die Uhr wurde kalibriert und die Flaggen sowie Flaggenmasten wurden gereinigt."
  },
  AvgCommunicate_84107_Content_6 = {
    Text = "Auch an den folgenden Tagen werde ich die Wartung fortsetzen, um sicherzustellen, dass wir jederzeit loslegen können."
  },
  AvgCommunicate_84107_Content_7 = {
    Text = "...Nur der Mittagsverkehr an der Kommandantur – braucht das wirklich so viel Vorbereitung?"
  },
  AvgCommunicate_84107_Content_8 = {
    Text = "Natürlich. Welche Kantine am beliebtesten ist, in welcher Fakultät die meisten Studenten sind und welche Studenten priorisiert in die Kantine gehen möchten, all das beeinflusst die Planung der gesamten Route."
  },
  AvgCommunicate_84107_Content_9 = {
    Text = "Welche Blumenbeete wurden von neu hinzugekommenen streunenden Katzen zu ihrem Zuhause gemacht, welcher Bereich wurde von Schülern zu einem neuen Pfad ausgetreten, welche Straße muss saniert werden..."
  },
  AvgCommunicate_84107_Option_11 = {
    Text = "......Verstanden."
  },
  AvgCommunicate_84107_Option_2 = {
    Text = "...Die Ferien haben doch gerade erst begonnen, oder?"
  },
  AvgCommunicate_84107_Option_7 = {
    Text = "Nur der Mittagsverkehr an der Kommandanturschule..."
  },
  AvgCommunicate_84108_Content_1 = {
    Text = "Schutzherr, es tut mir aufrichtig leid wegen des letzten Vorfalls."
  },
  AvgCommunicate_84108_Content_10 = {
    Text = "Aber hier ist schließlich nicht das Meer, also habe ich Anpassungen an die jeweilige Situation vorgenommen."
  },
  AvgCommunicate_84108_Content_11 = {
    Text = "Die sogenannte Anpassung wird doch nicht einfach dich und mich zusammenfesseln, oder..."
  },
  AvgCommunicate_84108_Content_12 = {
    Text = "Doch. Auf diese Weise kannst du es sofort bemerken und eingreifen, falls mir etwas zustößt."
  },
  AvgCommunicate_84108_Content_13 = {
    Text = "......Kann ich ablehnen?"
  },
  AvgCommunicate_84108_Content_14 = {
    Text = "Du kannst sicherlich ablehnen."
  },
  AvgCommunicate_84108_Content_15 = {
    Text = "Aber ich bin bereits vor der Tür angekommen."
  },
  AvgCommunicate_84108_Content_2 = {
    Text = "......Meinst du den Vorfall mit dem Elmsfeuer, das durch die Schlaflosigkeit verursacht wurde?"
  },
  AvgCommunicate_84108_Content_3 = {
    Text = "Obwohl Schmelzen·Puppe mich rechtzeitig bewusstlos geschlagen hat, fühle ich mich dennoch schuldig."
  },
  AvgCommunicate_84108_Content_4 = {
    Text = "Ich habe lange darüber nachgedacht und fand, dass ich bestraft werden muss."
  },
  AvgCommunicate_84108_Content_5 = {
    Text = "Das ist nicht nötig. Der letzte Vorfall hatte keine ernsthaften Konsequenzen."
  },
  AvgCommunicate_84108_Content_6 = {
    Text = "Nein, wenn man etwas falsch macht, muss man bestraft werden. Das ist die Regel."
  },
  AvgCommunicate_84108_Content_7 = {
    Text = "Ich habe mich auf einer Seite selbst mit Handschellen gefesselt, und die andere Seite erfordert deine Mitwirkung."
  },
  AvgCommunicate_84108_Content_8 = {
    Text = "Meine Kooperation?"
  },
  AvgCommunicate_84108_Content_9 = {
    Text = "Normalerweise werden Straftäter auf dem Schiff an den Beinen gefesselt und mehrere Stunden der Sonne auf dem Deck ausgesetzt."
  },
  AvgCommunicate_84108_Option_11 = {
    Text = "Die sogenannte Anpassung wird doch nicht..."
  },
  AvgCommunicate_84108_Option_13 = {
    Text = "......Kann ich ablehnen?"
  },
  AvgCommunicate_84108_Option_2 = {
    Text = "Du meinst..."
  },
  AvgCommunicate_84108_Option_5 = {
    Text = "Das ist nicht nötig."
  },
  AvgCommunicate_84108_Option_8 = {
    Text = "Meine Kooperation?"
  },
  AvgCommunicate_84109_Content_1 = {
    Text = "Hüter, danke."
  },
  AvgCommunicate_84109_Content_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_84109_Content_11 = {
    Text = "Eigentlich..."
  },
  AvgCommunicate_84109_Content_12 = {
    Text = "Eigentlich? Warum stotterst du plötzlich beim Sprechen, das ist nicht wie du."
  },
  AvgCommunicate_84109_Content_13 = {
    Text = "Eigentlich musst du das maritime Museum nicht besuchen; ein wenig \"entspannen\" sollte ausreichen."
  },
  AvgCommunicate_84109_Content_14 = {
    Text = "Obwohl ich nicht verstehe, was du mit normaler \"Entspannung\" meinst, fühle ich mich ruhig, wenn ich bei dir bin."
  },
  AvgCommunicate_84109_Content_15 = {
    Text = "Es fühlt sich an, als wäre man in einer ruhigen See, ohne Stürme, und ohne auf Stürme zu treffen, einfach dem Kurs folgend, können wir unser Ziel sicher erreichen."
  },
  AvgCommunicate_84109_Content_16 = {
    Text = "......Obwohl dieses Bild schwer zu verstehen ist, verstehe ich grob, was du meinst."
  },
  AvgCommunicate_84109_Content_17 = {
    Text = "In der Zukunft können wir verschiedene Orte erkunden. Diese Welt ist riesig, jenseits der Ozeane gibt es viele schöne Landschaften."
  },
  AvgCommunicate_84109_Content_18 = {
    Text = "......Ich verstehe. Ich werde es versuchen."
  },
  AvgCommunicate_84109_Content_19 = {
    Text = "Sieh... die wunderschöne Landschaft, die sich vom Ozean unterscheidet."
  },
  AvgCommunicate_84109_Content_2 = {
    Text = "Warum plötzlich Dankbarkeit zeigen?"
  },
  AvgCommunicate_84109_Content_3 = {
    Text = "Auf dieser Reise zum Londoner Maritimen Museum habe ich viel gelernt."
  },
  AvgCommunicate_84109_Content_4 = {
    Text = "Die ausgestellten maritimen Uhren, handgezeichneten Seekarten und Fragmente von Navigationsprotokollen tragen alle zur Verbesserung der Navigationsfähigkeiten bei."
  },
  AvgCommunicate_84109_Content_5 = {
    Text = "Ich werde all das bei der nächsten Fahrt nutzen, um sicherzustellen, dass alle sicher in den Hafen zurückkehren."
  },
  AvgCommunicate_84109_Content_6 = {
    Text = "Ich erinnere mich, dass der Zweck, an diesem Tag zum Londoner Maritimen Museum zu gehen, war, um „sich zu entspannen“..."
  },
  AvgCommunicate_84109_Content_7 = {
    Text = "Vergiss es, solange du glücklich bist."
  },
  AvgCommunicate_84109_Content_8 = {
    Text = "Ja, ich bin sehr glücklich, und ich hoffe, in Zukunft oft mit dir rauszugehen und mich zu entspannen."
  },
  AvgCommunicate_84109_Content_9 = {
    Text = "Kein Problem, ich werde nachsehen, welche maritimen Museen in London ich besuchen kann."
  },
  AvgCommunicate_84109_Option_12 = {
    Text = "Eigentlich?"
  },
  AvgCommunicate_84109_Option_16 = {
    Text = "......Was für eine komplexe Metapher"
  },
  AvgCommunicate_84109_Option_2 = {
    Text = "Warum plötzlich Dankbarkeit zeigen?"
  },
  AvgCommunicate_84109_Option_6 = {Text = "...?"},
  AvgCommunicate_84109_Option_9 = {
    Text = "Kein Problem"
  },
  AvgCommunicate_84110_Content_1 = {
    Text = "Könntest du mir im Voraus die nächste Charge Koffein-Vorräte schicken, Hüter?"
  },
  AvgCommunicate_84110_Content_10 = {
    Text = "Warte, wie könnte es noch absurder werden!"
  },
  AvgCommunicate_84110_Content_11 = {
    Text = "Wo ist Winkle jetzt?"
  },
  AvgCommunicate_84110_Content_12 = {
    Text = "Hier führe ich Experimente an dem Leitungsgerät durch, um zu testen, ob die Energie von @2<AvgCommunicateConfuseColor.Light> in Lichtenergie umgewandelt werden kann."
  },
  AvgCommunicate_84110_Content_13 = {
    Text = "Warum weigerst du dich nicht?"
  },
  AvgCommunicate_84110_Content_14 = {
    Text = "Warum verweigern? Passagieren zu dienen ist eine meiner Pflichten."
  },
  AvgCommunicate_84110_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_84110_Content_16 = {
    Text = "Ich gehe jetzt hinüber. Du hältst das Zwinkern für mich."
  },
  AvgCommunicate_84110_Content_17 = {
    Text = "Erhalten, geschworen, deinen Befehl zu erfüllen."
  },
  AvgCommunicate_84110_Content_2 = {
    Text = "Wurden auch eure Vorräte von Winkle genommen?"
  },
  AvgCommunicate_84110_Content_3 = {
    Text = "Genauer gesagt, es wurde nicht „genommen“, sondern ich gab es diesem Passagier."
  },
  AvgCommunicate_84110_Content_4 = {
    Text = "......Schon wieder mit dem Grund \"Ich werde beim nächsten Mal mitreisen\"?"
  },
  AvgCommunicate_84110_Content_5 = {
    Text = "Ich erfülle nur meine Pflichten. Den Passagieren zu dienen, gehört ebenfalls zu meinen Verantwortlichkeiten."
  },
  AvgCommunicate_84110_Content_6 = {
    Text = "......Die Anfrage für Nachschub wurde genehmigt. Dies ist das letzte Mal."
  },
  AvgCommunicate_84110_Content_7 = {
    Text = "Übrigens, versucht Winkle immer noch, das @2 aus deiner Brust zu extrahieren?"
  },
  AvgCommunicate_84110_Content_8 = {
    Text = "Nicht mehr; dieser Passagier hat die Art und Weise, wie Forschung durchgeführt wird, verändert."
  },
  AvgCommunicate_84110_Content_9 = {
    Text = "Zum Beispiel, die Intensität von @2<AvgCommunicateConfuseColor.Light> mit einem Impulsstrommeter zu testen, die Spektrallinien von @2<AvgCommunicateConfuseColor.Light> mit einem Prisma zu scannen, eine menschliche Testplattform zu nutzen, um die Verbindung von @2<AvgCommunicateConfuseColor.Light> mit Nervenfasern zu überprüfen..."
  },
  AvgCommunicate_84110_Option_10 = {
    Text = "Warte, wie könnte es noch absurder werden!"
  },
  AvgCommunicate_84110_Option_13 = {
    Text = "Warum weigerst du dich nicht?"
  },
  AvgCommunicate_84110_Option_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgCommunicate_84110_Option_2 = {
    Text = "Wurden auch eure Vorräte von Winkle genommen?"
  },
  AvgCommunicate_84110_Option_4 = {
    Text = "Wieder liegt es daran..."
  },
  AvgCommunicate_84110_Option_6 = {
    Text = "Lieferanforderung wurde genehmigt..."
  },
  AvgCommunicate_94500_Content_1 = {
    Text = "Dank deiner Einführung, nachdem ich Lord Ogier getroffen habe, stellte er uns weiteren Freunden vor."
  },
  AvgCommunicate_94500_Content_10 = {
    Text = "Herr Ogier erwähnte ebenfalls, dass das Training der Ritter noch komplizierter und mühsamer ist als dies; es scheint, dass, wie in den Büchern beschrieben, jeder Ritter tatsächlich eine Person ist, die Respekt verdient."
  },
  AvgCommunicate_94500_Content_11 = {
    Text = "Stimmt, Ogier ist tatsächlich der fleißigste unter allen Erwachten in der Ausbildung!"
  },
  AvgCommunicate_94500_Content_12 = {
    Text = "Wir haben auch entdeckt, dass selbst mit einer Behinderung, Ausbilder Alva dasselbe Training wie wir macht."
  },
  AvgCommunicate_94500_Content_13 = {
    Text = "Ursprünglich dachten wir, dass Ausbilder Alva auch eine Ritterin ist, aber sie sagte, sie sei früher Soldatin gewesen. Ich weiß nicht, welche Art von Beruf ein Soldat ist, aber er muss ebenso respektabel sein wie der eines Ritters."
  },
  AvgCommunicate_94500_Content_14 = {
    Text = "Soldaten sind diejenigen, die für das Land kämpfen, was auch als eine Art Ritter angesehen werden kann; im Vergleich zu den strengen moralischen Kodizes von Rittern repräsentieren die Taten der Soldaten jedoch nicht unbedingt Gerechtigkeit."
  },
  AvgCommunicate_94500_Content_15 = {
    Text = "Alva erkannte dies erst, nachdem sie die Armee verlassen hatte; vielleicht ist das Leben jetzt komfortabler für sie."
  },
  AvgCommunicate_94500_Content_16 = {
    Text = "Ich verstehe, was du meinst, ist, dass ein Ritter nicht Macht repräsentiert, sondern einen Geist der Gerechtigkeit; wie Ausbilder Alva und gerechte Menschen wie du alle die Seele eines Ritters besitzen."
  },
  AvgCommunicate_94500_Content_18 = {
    Text = "Obwohl du sehr gut gesprochen hast, fühlt es sich ziemlich peinlich an..."
  },
  AvgCommunicate_94500_Content_2 = {
    Text = "Das sind gute Nachrichten; ich freue mich wirklich für dich."
  },
  AvgCommunicate_94500_Content_3 = {
    Text = "Wir haben bereits viele Erwachte getroffen, und tatsächlich, wie Sie sagten, sind die meisten von ihnen freundliche Menschen."
  },
  AvgCommunicate_94500_Content_4 = {
    Text = "Ich fühle mich beschämt, wenn ich daran zurückdenke, als ich hierher kam; ich hegte oft misstrauische Zweifel gegenüber anderen."
  },
  AvgCommunicate_94500_Content_5 = {
    Text = "Eigentlich ist es nicht zu schlecht, denn es gibt viele Menschen, die Vorsicht verdienen..."
  },
  AvgCommunicate_94500_Content_6 = {
    Text = "Jetzt bin ich mit Castor zusammen und besuche zusammen mit Lord Ogier Instructeur Alvas Trainingskurs"
  },
  AvgCommunicate_94500_Content_7 = {
    Text = "Die Kampfhaltung von Herrn Ogier ist wirklich beeindruckend, aber er selbst scheint mit Lob unbehaglich zu sein; was für eine bescheidene Person."
  },
  AvgCommunicate_94500_Content_8 = {
    Text = "Ha ha, Ogier ist einfach schüchtern, sprich ganz normal mit ihm."
  },
  AvgCommunicate_94500_Content_9 = {
    Text = "Es stellte sich heraus, dass Castor und ich im Kirchenkampftraining nie ausgebildet wurden; ein solches hartes Training ist wirklich schwer, doch Lord Ogier sagt, er macht das jeden Tag; was für eine große Ausdauer."
  },
  AvgCommunicate_94500_Option_11 = {
    Text = "Stimmt, Ogier ist tatsächlich der fleißigste unter allen Erwachten in der Ausbildung!"
  },
  AvgCommunicate_94500_Option_14 = {
    Text = "Ich schätze..."
  },
  AvgCommunicate_94500_Option_2 = {
    Text = "Das sind gute Nachrichten; ich freue mich wirklich für dich."
  },
  AvgCommunicate_94500_Option_5 = {
    Text = "Eigentlich ist es nicht zu schlecht, denn es gibt viele Menschen, die Vorsicht verdienen..."
  },
  AvgCommunicate_94500_Option_8 = {
    Text = "Ogier ist einfach leicht schüchtern."
  },
  AvgCommunicate_94501_Content_1 = {
    Text = "Ehrenwerter Herr, danke, dass Sie einen Unterschlupf für mich und Castor vorbereitet haben."
  },
  AvgCommunicate_94501_Content_10 = {
    Text = "Dieser Typ Castor mochte es, sich fünfmal am Tag frisch zu machen, aber nachdem ich ihn gestoppt habe, wurde es zu dreimal am Tag."
  },
  AvgCommunicate_94501_Content_12 = {
    Text = "Dein Gesicht zu oft zu waschen verursacht Schaden!!"
  },
  AvgCommunicate_94501_Content_13 = {
    Text = "Aber habt ihr diese Dinge vorher noch nie benutzt? Ich hätte nicht gedacht, dass die Tempellicht-Kirche so geizig ist."
  },
  AvgCommunicate_94501_Content_14 = {
    Text = "In der Tat nicht, aber nicht, weil die Kirche geizig ist, sondern als der Sohn sind wir immer angehalten worden, Wünsche zu zügeln und uns auf die Praxis zu konzentrieren."
  },
  AvgCommunicate_94501_Content_15 = {
    Text = "Wir hatten kaum jemals Kontakt mit diesen technologischen Produkten, und es gibt viele Regeln in Bezug auf unser tägliches Leben und unsere Mahlzeiten."
  },
  AvgCommunicate_94501_Content_16 = {
    Text = "Obwohl die Kleidung und das Essen im Allgemeinen luxuriös sind, kann man nur zu den Mahlzeiten essen, und man muss den Schlafsaal verlassen, sobald es Zeit zum Aufstehen ist."
  },
  AvgCommunicate_94501_Content_17 = {
    Text = "Als Kind stellte ich oft vor, wann ich aufhören könnte, früh aufzuwachen und den ganzen Tag essen zu können, was ich wollte."
  },
  AvgCommunicate_94501_Content_18 = {
    Text = "In diesen Tagen habe ich immer wieder ein junges Mädchen gesehen, das am Nachmittag mit Essen vorbeigeht; es scheint, als wäre das Leben, von dem ich hier geträumt habe, bereits zur Routine geworden."
  },
  AvgCommunicate_94501_Content_19 = {
    Text = "Ah, wahrscheinlich ist Murphy losgegangen, um die kleinen Kuchen zu holen... in der Tat scheint dein Leben wirklich mühselig zu sein."
  },
  AvgCommunicate_94501_Content_2 = {
    Text = "Ich habe gehört, dass Castor gesagt hat, dass im Haus speziell ein Bett hinzugefügt wurde, also wusste ich, dass es dein Werk sein muss."
  },
  AvgCommunicate_94501_Content_20 = {
    Text = "Alles ist vergangen, diese Fehler und Verzerrungen werden in der Vergangenheit bleiben. Wir werden den richtigen Weg mit einem brandneuen Aspekt einschlagen, bitte seid Zeugen."
  },
  AvgCommunicate_94501_Content_21 = {
    Text = "Sehr freundlich von euch, aber wenn es Probleme gibt, könnt ihr gerne zu mir kommen. Mit eurer Einstellung seid ihr schon um Längen besser als manch anderer Erwachte!"
  },
  AvgCommunicate_94501_Content_3 = {
    Text = "Wir haben uns seit unserer Kindheit daran gewöhnt, im Palast zusammen zu leben, und es beunruhigt uns immer noch zu hören, dass die Schlafräume hier ein Zimmer pro Person erfordern."
  },
  AvgCommunicate_94501_Content_4 = {
    Text = "Während du jetzt gründlich für uns nachdachtest, wird mir klar, dass Lady Thais' Vorschlag, damals Zuflucht bei dir zu suchen, richtig war."
  },
  AvgCommunicate_94501_Content_5 = {
    Text = "Ha, es ist nichts, seid ihr alle zufrieden, seit ihr hier seid?"
  },
  AvgCommunicate_94501_Content_6 = {
    Text = "Dank deiner Fürsorge ist alles gut. Obwohl der Palast hier so klein ist wie das Zimmer einer Magd, ist er vollständig eingerichtet und nach der Anpassung fühlt es sich ziemlich warm an."
  },
  AvgCommunicate_94501_Content_7 = {
    Text = "Ahaha, ist das so, dann ist das gut, das ist gut..."
  },
  AvgCommunicate_94501_Content_8 = {
    Text = "Wir haben langsam gelernt, ohne bedient zu werden zu leben; du brauchst dir keine Sorgen um uns zu machen. Tatsächlich ist das etwas, von dem wir beide seit Jahren träumen."
  },
  AvgCommunicate_94501_Content_9 = {
    Text = "Besonders der in dem Zimmer bereitgestellte Gesichtsreiniger ist wirklich magisch. Nach der Anwendung gemäß der Anleitung bildet es viele wolkenartige Blasen, und der Geschmack dieser Zahnpasta ist ebenfalls sehr erfrischend."
  },
  AvgCommunicate_94501_Option_19 = {
    Text = "Ah, wahrscheinlich ist Murphy losgegangen, um die kleinen Kuchen zu holen..."
  },
  AvgCommunicate_94501_Option_21 = {
    Text = "Zu höflich."
  },
  AvgCommunicate_94501_Option_5 = {
    Text = "Keine Sorgen, keine Sorgen."
  },
  AvgCommunicate_94501_Option_7 = {
    Text = "Ahaha, ist das so, dann ist das gut, das ist gut..."
  },
  AvgCommunicate_94502_Content_1 = {
    Text = "Ich entschuldige mich für die Störung, aber könntest du uns bitte eine kurze Einführung geben..."
  },
  AvgCommunicate_94502_Content_10 = {
    Text = "Oh! Es sollten Ogier und Lotan sein."
  },
  AvgCommunicate_94502_Content_11 = {
    Text = "Ogier... Ich habe diesen Namen notiert, dieses jugendliche Auftreten ist aufrecht und heldenhaft, es lässt unsere Herzen schneller schlagen. Castor und ich wollten zunächst einen Schritt vorwärts machen, aber sie gingen schnell vorbei und verschwanden."
  },
  AvgCommunicate_94502_Content_12 = {
    Text = "Nachdem wir ins Studentenheim zurückgekehrt waren, wälzten wir uns im Bett und wollten wirklich diesen Ritter treffen, wussten aber nicht, wie wir anfangen sollten, also baten wir um deine Einführung, in der Hoffnung, dass du dir die Zeit und Mühe nehmen könntest, unser Treffen zu ermöglichen."
  },
  AvgCommunicate_94502_Content_13 = {
    Text = "Ich verstehe; tatsächlich musst du nicht so höflich sein. Ogier ist ein sehr warmherziger Mensch; solange du sprichst, wird er sich sehr freuen, Freundschaft mit dir zu schließen."
  },
  AvgCommunicate_94502_Content_14 = {
    Text = "Wahrlich bewundernswert als echter Ritter, diese Großzügigkeit ist lobenswert, bereit, uns zu akzeptieren, die wir einst Feinde waren."
  },
  AvgCommunicate_94502_Content_15 = {
    Text = "Nein, nein, das hat nichts mit Großzügigkeit zu tun! So machen normale Menschen Freunde!"
  },
  AvgCommunicate_94502_Content_16 = {
    Text = "Obwohl nicht jeder Erwachte ein normaler Mensch ist ... aber die meisten hier sind dennoch sehr freundlich. Ihr könnt euch also ruhig normal mit ihnen austauschen."
  },
  AvgCommunicate_94502_Content_17 = {
    Text = "Es tut mir leid, könntest du mich bitte aufklären, was... normale Kommunikation ist?"
  },
  AvgCommunicate_94502_Content_19 = {
    Text = "Ich verstehe, lass mich dir das Geheimnis erzählen, wie man Freunde gewinnt!"
  },
  AvgCommunicate_94502_Content_2 = {
    Text = "Seit du vorgeschlagen hast, dass wir mehr Freunde finden, haben Castor und ich oft in belebten Orten herumgehangen."
  },
  AvgCommunicate_94502_Content_20 = {
    Text = "Das ist die Initiative! Aufrichtigkeit und Initiative sind die bewegendsten Dinge!"
  },
  AvgCommunicate_94502_Content_21 = {
    Text = "Erinnere dich, du könntest abgelehnt oder betrogen werden, aber das ist das Problem derjenigen, die dir schaden; zweifle niemals daran, dass Aufrichtigkeit falsch ist."
  },
  AvgCommunicate_94502_Content_22 = {
    Text = "Trainiere ein starkes Herz und erlebe dann mutig Freundschaft!"
  },
  AvgCommunicate_94502_Content_23 = {
    Text = "Ihre Weisheit hat mich immer geehrt und bewundert; ich werde wirklich über Ihre Lehren nachdenken, Ihnen aufrichtig danken, mein Leitstern."
  },
  AvgCommunicate_94502_Content_3 = {
    Text = "Wanderst du?"
  },
  AvgCommunicate_94502_Content_4 = {
    Text = "Das ist richtig, wir sitzen oft ruhig im Restaurant oder auf dem Platz, beobachten die vorbeiziehende Menge und versuchen, niemanden zu stören."
  },
  AvgCommunicate_94502_Content_6 = {
    Text = "Uh, obwohl deine Absichten gut sind, wird es nicht dazu beitragen, Freunde zu machen, nur hier zu sitzen!"
  },
  AvgCommunicate_94502_Content_7 = {
    Text = "So ist das also! Wir waren durch die Etikette eingeschränkt, aber ich hätte nicht gedacht, dass hier ein echter Ritter ist!"
  },
  AvgCommunicate_94502_Content_8 = {
    Text = "Du hast vielleicht von Castor gehört, dass wir beide immer die Geschichten von Rittern bewundert haben."
  },
  AvgCommunicate_94502_Content_9 = {
    Text = "An diesem Tag auf dem Platz sahen wir einen jungen Mann mit einem langen Speer, der die Speerkunst der Ritter mit einer Dame diskutierte."
  },
  AvgCommunicate_94502_Option_10 = {
    Text = "Oh! Es sollten Ogier und Lotan sein."
  },
  AvgCommunicate_94502_Option_13 = {
    Text = "Eigentlich musst du nicht so höflich sein."
  },
  AvgCommunicate_94502_Option_15 = {
    Text = "Das hat nichts mit Sentimentalität zu tun!"
  },
  AvgCommunicate_94502_Option_3 = {
    Text = "Wanderst du?"
  },
  AvgCommunicate_95003_Content_1 = {
    Text = "Hey, Kleiner, hast du Zeit?"
  },
  AvgCommunicate_95003_Content_10 = {
    Text = "\"... Wenn die Sterne sich ausrichten, wird das Heilige Kind aus dem Schoß der Göttlichen Mutter geboren.\""
  },
  AvgCommunicate_95003_Content_11 = {
    Text = "\"... Obwohl wir keine Rituale oder Opfer mehr vollziehen, hoffe ich, dass diese Informationen dich in irgendeiner Weise inspirieren können.\""
  },
  AvgCommunicate_95003_Content_12 = {
    Text = "\"... Wenn ich Zeit habe, würde ich gerne mit dir über unseren Säuglingskönig und Retter sprechen...\""
  },
  AvgCommunicate_95003_Content_13 = {
    Text = "......Jetzt weiß ich, wer es ist."
  },
  AvgCommunicate_95003_Content_14 = {
    Text = "......Ich hätte daran denken sollen."
  },
  AvgCommunicate_95003_Content_15 = {
    Text = "Es scheint, dass dieser kleine Kerl jemanden kennt?"
  },
  AvgCommunicate_95003_Content_16 = {
    Text = "Das ist richtig... überlass es mir, mich darum zu kümmern."
  },
  AvgCommunicate_95003_Content_17 = {
    Text = "Das nächste Mal, wenn du so einen Brief siehst, antworte bitte nicht und informiere mich sofort!"
  },
  AvgCommunicate_95003_Content_2 = {
    Text = "Ist etwas nicht in Ordnung?"
  },
  AvgCommunicate_95003_Content_3 = {
    Text = "Ich hätte nie gedacht, dass nach diesem Tag tatsächlich einige Briefe ankommen würden."
  },
  AvgCommunicate_95003_Content_4 = {
    Text = "Schließe die aus, die auf den ersten Blick so falsch sind, überraschenderweise gibt es ein paar echte darunter."
  },
  AvgCommunicate_95003_Content_5 = {
    Text = "Ich kann nicht glauben, dass jemand tatsächlich darauf hereingefallen ist!"
  },
  AvgCommunicate_95003_Content_6 = {
    Text = "Doch es gibt einen Brief, der ziemlich seltsam ist; der Absender ist innerhalb von Mythag."
  },
  AvgCommunicate_95003_Content_7 = {
    Text = "Was! Wir müssen sofort das Sicherheitsbüro benachrichtigen."
  },
  AvgCommunicate_95003_Content_8 = {
    Text = "Beeil dich nicht; nur um auf Nummer sicher zu gehen, lass mich dir zuerst die wichtigsten Punkte erzählen."
  },
  AvgCommunicate_95003_Content_9 = {
    Text = "\"... Früher wählten wir geeignete Säuglinge aus, die die Aufgaben der Göttlichen Mutter übernehmen sollten.\""
  },
  AvgCommunicate_95003_Option_13 = {
    Text = "......Jetzt weiß ich, wer es ist."
  },
  AvgCommunicate_95003_Option_14 = {
    Text = "......Ich hätte daran denken sollen."
  },
  AvgCommunicate_95004_Content_1 = {
    Text = "Lange nicht gesehen, mein kleiner Hüter."
  },
  AvgCommunicate_95004_Content_10 = {
    Text = "So etwas ist gewiss seltsam!!!"
  },
  AvgCommunicate_95004_Content_11 = {
    Text = "Ha ha, genau wie ich dachte."
  },
  AvgCommunicate_95004_Content_12 = {
    Text = "Wh-was ist das Gleiche?"
  },
  AvgCommunicate_95004_Content_13 = {
    Text = "Ich habe Ismael gewettet, dass der Kleine schockiert wäre, dies zu sehen."
  },
  AvgCommunicate_95004_Content_14 = {
    Text = "Es scheint, dass ich gewonnen habe"
  },
  AvgCommunicate_95004_Content_15 = {
    Text = "......Kannst du mir sagen, wer diesen Abschnitt geschrieben hat?"
  },
  AvgCommunicate_95004_Content_16 = {
    Text = "Obwohl ich etwas Ähnliches schreiben kann."
  },
  AvgCommunicate_95004_Content_17 = {
    Text = "Doch die obige Aussage wurde tatsächlich von Ismael angefordert."
  },
  AvgCommunicate_95004_Content_18 = {
    Text = "......Sehr gut, es scheint, dass beide die Täter sind."
  },
  AvgCommunicate_95004_Content_19 = {Text = "Uh, uh..."},
  AvgCommunicate_95004_Content_2 = {
    Text = "Es ist eine Weile her, seit wir uns das letzte Mal getroffen haben, ich frage mich, ob es dir gut geht."
  },
  AvgCommunicate_95004_Content_20 = {
    Text = "Hey, Kleiner?"
  },
  AvgCommunicate_95004_Content_21 = {
    Text = "Hey, Kleiner? Immer noch hier?"
  },
  AvgCommunicate_95004_Content_22 = {
    Text = "Nicht verfügbar, bitte hinterlassen Sie eine Nachricht."
  },
  AvgCommunicate_95004_Content_23 = {
    Text = "Entschuldigung, Entschuldigung, kleines Wesen, sei nicht böse."
  },
  AvgCommunicate_95004_Content_24 = {
